INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1402, 0, 6, 'zhTW', '今天我會給你一個漢堡作為星期二那天的報酬。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1402 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1402, 0, 7, 'zhTW', '這都是他們的錯，愚蠢的聯盟軍隊。居然在我的農場背後修建他們的哨塔。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1405 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1405, 0, 0, 'zhTW', '你能不能施捨一些硬幣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1405 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1405, 0, 1, 'zhTW', '幫幫我這個窮人吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1405 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1405, 0, 2, 'zhTW', '擦一件裝甲只收一個銅板咯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1410 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1410, 0, 0, 'zhTW', '別想活著逃走！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1410 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1410, 0, 1, 'zhTW', '我會先要你的能量，再要你的命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1410 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1410, 0, 2, 'zhTW', '別讓他們跑了！殺了他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1410 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1410, 0, 3, 'zhTW', '你知道得太多了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1410 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1410, 0, 4, 'zhTW', '為了凱爾薩斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1410 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1410, 0, 5, 'zhTW', '一個都別讓他們逃跑了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1416 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1416, 0, 0, 'zhTW', '跟著我吧，聖騎士。我製造馬飾比我喝矮人烈酒要快。嗯……烈酒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1416 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1416, 1, 0, 'zhTW', '嗯，這能應該就行了。來吧，回到商店，完成我們的交易！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1426 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1426, 0, 0, 'zhTW', '有更多的骨頭可以啃啦……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1426 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1426, 0, 1, 'zhTW', '啊啊啊……新鮮的肉！');
