INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1443, 0, 0, 'zhTW', '我必須摧毀這些惡魔的工具！為了部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1493 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 0, 'zhTW', '你上次給我帶來不少樂子哪……出來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1493 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 1, 'zhTW', '斯莫特！嘿，斯莫特！出來玩玩吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1493 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 2, 'zhTW', '我可不想整天陪著這座雕像玩。過來較量較量吧！');
