INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 4, 'zhTW', '我保證這次我不會殺死你的船員，哈哈！但是我的兄弟可能會吃了他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1493 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 5, 'zhTW', '你一艘船都沒有了嗎？你的勇氣去哪裡了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1493 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 6, 'zhTW', '斯莫特！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1493 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1493, 0, 7, 'zhTW', '斯莫特，你不想戰鬥嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1494 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1494, 0, 0, 'zhTW', '嗯……我聞到食物的味道了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1497 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1497, 0, 0, 'zhTW', '從箱子裡拿一根誘靈蠟燭，$n。');
