INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1717, 0, 0, 'zhTW', '我要碾碎你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1719 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1719, 0, 0, 'zhTW', '突然之間，到處都是那幫傢伙了。');
