INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1719, 0, 3, 'zhTW', '我要去幹什麼來著？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1719 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1719, 0, 4, 'zhTW', '這到底怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1754 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1754, 0, 0, 'zhTW', '我要一個人靜一靜，請離開吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1754 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1754, 1, 0, 'zhTW', '你來啦，西部荒野那邊有什麼訊息嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1754 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1754, 2, 0, 'zhTW', '嗯，可能就是那個愛管閒事的肖爾，我要去看看能找到些什麼。回頭再聯絡吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1754 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1754, 3, 0, 'zhTW', '啊，非常感謝。當我料理好這件小事之後就去圖書館。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1755 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1755, 0, 0, 'zhTW', '範克里夫告訴我計劃正在進行中。但是他也聽說有一些人正在四處打探相關的訊息。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1755 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1755, 1, 0, 'zhTW', '迪菲亞兄弟會必勝！沒有人能阻止我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1756 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1756, 0, 0, 'zhTW', '遵命，長官！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1756 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1756, 1, 0, 'zhTW', '當然，他在圖書館等您。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1763 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1763, 0, 0, 'zhTW', '把這些東西搬到船上去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1763 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1763, 0, 1, 'zhTW', '誰說要休息？想都別想！趕快去幹活，你們這些蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1802 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1802, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 0, 0, 'zhTW', '你不會到達森林邊緣的，弗丁。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 1, 0, 'zhTW', '你讓我失望了，泰蘭。原本我設計了一個規劃……一個重要的計劃。啊，你骯髒的血統最終表露出來只是個時間問題。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 2, 0, 'zhTW', '就像他們說的：有其父必有其子。你就跟提里奧一樣軟弱……或許比他更軟弱。我只希望我派出的刺客能順利結束他令人同情的一生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 3, 0, 'zhTW', '大十字軍命令我毀掉了你和你新交的朋友，泰蘭，但是你要知道：我做這事兒純屬個人興趣，跟職責和義務無關。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 4, 0, 'zhTW', '大檢察官伊斯利恩呼叫他的衛兵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 5, 0, 'zhTW', '弗丁，該結束了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 6, 0, 'zhTW', '夠了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 7, 0, 'zhTW', '大檢察官伊斯利恩笑了起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 1840 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (1840, 8, 0, 'zhTW', '你真的認為自己能打敗我嗎？你的朋友很快就會隨你去的，泰蘭。');
