INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2597, 0, 0, 'zhTW', '我想你應該是帶來了什麼好訊息吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2599 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2599, 0, 0, 'zhTW', '一切正在按照計劃進行著，法庫雷斯特公爵。我向你保證，這只是時間問題。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2610 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2610, 0, 0, 'zhTW', '所有參與作戰的人都各就各位！納迦來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2610 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2610, 1, 0, 'zhTW', '只要我們現在能控制住他們，那就肯定能搞明白這件事情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2619 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2619, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2643 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2643, 0, 0, 'zhTW', '%s變得憤怒了！');
