INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 0, 0, 'zhTW', '那麼就儘快開始吧。我們在這裡待得越久，亡靈重回希爾斯布萊德作惡的可能性就越大。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 1, 0, 'zhTW', '好了，我們要在這兒真刀真槍地幹一場。準備好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 2, 0, 'zhTW', '替我斷後！我要看看在這些垃圾裡能找到什麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 3, 0, 'zhTW', '%s開始翻找藥劑師的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 4, 0, 'zhTW', '我猜奎艾會認為這個很重要。她應該對這些東西相當熟悉——雖然她不是這方面的專家，但也算得上是知識淵博。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 5, 0, 'zhTW', '好，讓我們趕快離開這裡吧！你們繼續跑。我要停一下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 6, 0, 'zhTW', '%s把她的包交給了奎艾。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 7, 0, 'zhTW', '我們成功了！奎艾，我們成功了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2713 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2713, 8, 0, 'zhTW', '你可以攻擊我，但是你依然無法阻止我回到奎艾那裡去。');
