INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2733, 0, 0, 'zhTW', '你聽好了，在我殺死你之後，你的身體將為我所用，$r。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2733 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2733, 0, 1, 'zhTW', '你無法阻止被遺忘者，$r。黑暗女王將會讓你感受到痛苦和恐懼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2748 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2748, 0, 0, 'zhTW', '誰膽敢喚醒阿扎達斯？誰膽敢觸怒造物之神？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2748 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2748, 1, 0, 'zhTW', '醒來吧！我的奴僕！保護圓盤！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2748 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2748, 2, 0, 'zhTW', '兄弟們，到我這兒來！為創世者而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2748 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2748, 3, 0, 'zhTW', '魯莽的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2755 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2755, 0, 0, 'zhTW', '什麼？$n，你做得很好，但……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2755 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2755, 1, 0, 'zhTW', '你為什麼這樣急於召喚了我？我還沒恢復我所有的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2755 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2755, 2, 0, 'zhTW', '不過沒關係。你真是個笨蛋，居然幫助了我，現在是該讓你付出代價的時候了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2763 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2763, 0, 0, 'zhTW', '住手！愚蠢的$c，我們不能讓你召喚密斯萊爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2764 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2764, 0, 0, 'zhTW', '拿下那裡！枯須狗頭人必勝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2764 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2764, 0, 1, 'zhTW', '站直了，弟兄們！不要怕！我們這裡有大個的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2765 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2765, 0, 0, 'zhTW', '不！快走開！我們絕對不能失敗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2765 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2765, 0, 1, 'zhTW', '站直了，弟兄們！不要怕！我們這裡有大個的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2765 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2765, 0, 2, 'zhTW', '你會被碾成粉末的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 0, 0, 'zhTW', '好了，$n。跟我到那個洞裡去一趟，我會試著把符石的能量注入到護目鏡上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 1, 0, 'zhTW', '我第一天來這裡的時候就發現了這個洞穴。我相信這塊石頭裡的能量對我們大有用處。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 2, 0, 'zhTW', '我要開始將石頭中的能量提取出來。$n，你的工作就是保護我。這個地方是被詛咒過的……相信我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 3, 0, 'zhTW', '%s開始在石頭前修補護目鏡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 4, 0, 'zhTW', '趕快！只有幹掉這些東西，我才能完成我的工作！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 5, 0, 'zhTW', '快完成了！再給我一點點時間！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 6, 0, 'zhTW', '我完成了！我把石頭的能量注入了護目鏡！咱們趕快從這裡出去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 7, 0, 'zhTW', '呼……終於可以離開那個陰暗的洞穴了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 8, 0, 'zhTW', '%s把護目鏡交給了德拉克里格博士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2768 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2768, 9, 0, 'zhTW', '德拉克里格博士將會給你進一步的指示，$n。很感謝你的幫助！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 2775 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2775, 0, 0, 'zhTW', '沒有什麼可以阻止我們的！你死定了！');
