INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2917, 0, 0, 'zhTW', '好吧，$n，讓我們去找找看我到底把那神秘的化石留在哪裡了。跟著我！');
