INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2917, 1, 0, 'zhTW', '我到底把那個神秘的化石放在哪裡了？啊，也許在那上面……');
