INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (2917, 3, 0, 'zhTW', '這裡沒有那塊神秘的化石……啊，但是有《荊棘谷的青山》的手抄本。多好的一本書啊！');
