INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3644, 2, 0, 'zhTW', '我的愛人，你恨我嗎？我在萬般無奈之下摧毀了你的軀殼，因為只有這樣才能讓你從痛苦中永久地解脫。');
