INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3843, 2, 0, 'zhTW', '但是，即使是這經過數千年的分離才換來的重逢也是如此短暫……我和這個世界的聯結正在逐漸減弱，我正在慢慢地離開它……離開你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 3843 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3843, 3, 0, 'zhTW', '再見了，塞瑞利恩，我的愛人。我們終能再見……');
