INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3843, 4, 0, 'zhTW', '%s柔和的聲音在薄霧中輕輕迴響，“我永遠愛你……”');
