INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3849, 0, 0, 'zhTW', '終於從這個骯髒的房間逃了出來！讓我帶你到院子裡去……');
