INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3849, 3, 0, 'zhTW', '希望你能解決掉阿魯高。我必須趕快回到哈德瑞克那裡。');
