INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3946, 0, 0, 'zhTW', '女神啊，我同伴的數量正在不斷地減少，我的力量很快就不足以阻止費伍德森林的惡魔了。');
