INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3946, 2, 0, 'zhTW', '什麼……這是什麼？這就是女神對我祈禱的回應？艾露恩賜予我一件武器，一把鐮刀，去打敗那些惡魔！');
