INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (3946, 3, 0, 'zhTW', '我失敗了……我最終還是失敗了……我愧對我的同胞……狼人肆虐，而女神賜予我的鐮刀也丟失了。');
