INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4419, 2, 0, 'zhTW', '短程加速賽的冠軍是……地精車隊！幹得好，兄弟們！');
