INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4421, 0, 0, 'zhTW', '討厭的傢伙。我會給你些顏色看看的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4421 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4421, 1, 0, 'zhTW', '下一個是誰？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4421 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4421, 2, 0, 'zhTW', '你們這些自不量力的傢伙會為侵犯我們的領地付出代價的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4421 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4421, 2, 1, 'zhTW', '我們的新盟友會為我們復仇的！');
