DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 0, 0, 'zhTW', '似乎我們遇到麻煩了。打起精神來，他們來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 1, 0, 'zhTW', '刺客……最好在他們找到我們之前快點離開這裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 2, 0, 'zhTW', '小心！我感到附近有邪惡的存在……亡靈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 3, 0, 'zhTW', '我們繼續前進吧，否則會碰到更多想要我命的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 4, 0, 'zhTW', '又是這三個？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 5, 0, 'zhTW', '這次我會把你徹底幹掉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 6, 0, 'zhTW', '幹得好！我應該可以自己離開這裡了。記著到梣谷的梅伊瑟娜崗哨去和淨化者德爾格倫談談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4484 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4484, 7, 0, 'zhTW', '我們必須趕快行動。奧伯丁離這裡不遠，但是有很多敵人潛伏在森林裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 0, 0, 'zhTW', '喔，喔！終於出來了。不過接下來還有危險，所以要保持警惕。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 1, 0, 'zhTW', '那上面就是卡爾加·刺肋的住處。那個該死的又幹又癟的老太婆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 2, 0, 'zhTW', '救命！快幫我把這$n搞定！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 3, 0, 'zhTW', '這個溝裡就有藍葉薯！它們可都是唾手可得的金子啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 4, 0, 'zhTW', '這裡到處都潛伏著危險。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 5, 0, 'zhTW', '我不明白這些愚蠢的動物是怎麼在這種地方生存的……聞起來真臭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 6, 0, 'zhTW', '我想我看到了一條可以走出這片荊棘林的路。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 7, 0, 'zhTW', '能走出這條臭溝真好，儘管出去了也好不了多少。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 8, 0, 'zhTW', '終於！我終於能走出這個地方了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 9, 0, 'zhTW', '我想在回到棘齒城之前休息一下。謝謝你的幫助！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4508 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4508, 10, 0, 'zhTW', '好了，現在我要起身去棘齒城了！祝你好運！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4509 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4509, 0, 0, 'zhTW', '在大災變時，亞米薩蘭正在大陸崩裂的邊界，幾乎沒有什麼倖存者逃過那次劫難。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4509 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4509, 1, 0, 'zhTW', '埃瑟裡克斯來到我們面前，他聲稱能把我們從痛苦中解救出來。他給我們施了魔法，讓我們免受傷害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4509 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4509, 2, 0, 'zhTW', '當震動停下來的時候，他的真實目的暴露出來了。我們都被困住了，而他在慢慢地汲取我們的能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4509 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4509, 3, 0, 'zhTW', '曾經有數百人被他的法術困住。現在只有一小部分還被囚禁著。他有時也會和我們交談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4509 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4509, 4, 0, 'zhTW', '他擔心他的法力會減弱，那塊寶貴的靈魂寶石也會消失和死亡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4509 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4509, 5, 0, 'zhTW', '他的副官，伊克魯德·瑪格蘇爾有一本書，裡面也許記載著其它靈魂寶石的所在地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4514 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4514, 0, 0, 'zhTW', '%s變得怒不可遏！');
