INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4966, 0, 0, 'zhTW', '為什麼我們不現在解決呢，亨德爾？普勞德摩爾女士將會很樂意在塔裡接見你的。');
