INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4966, 2, 0, 'zhTW', '真對不起，我花了這麼多時間才到這裡。我希望普勞德摩爾女士現在就能接見我。');
