INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4979, 2, 3, 'zhTW', '我很久沒讀到過這麼好笑的東西啦。你是來逗我開心的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 0, 0, 'zhTW', '你……你要幹什麼？離我遠一點……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 1, 0, 'zhTW', '我發誓，我沒有偷你的任何東西！我的東西你可以隨便拿，但是請快點離開！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 2, 0, 'zhTW', '我……好吧，我也許從旅店裡拿了一些東西……但是為什麼食人魔要關心這個？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 3, 0, 'zhTW', '不要過來，食人魔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 4, 0, 'zhTW', '我對你的這些火並不瞭解……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 5, 0, 'zhTW', '那是什麼？你聽到什麼了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 6, 0, 'zhTW', '%s被箭射中了胸膛，搖搖晃晃地向後退了幾步。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 7, 0, 'zhTW', '啊……哈蘭，我沒有想到……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4980 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4980, 8, 0, 'zhTW', '今天一定是你幸運的一天。好吧，我會說的。先讓我一個人呆一會。瞧，你還不相信我，但它……哦，天哪……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 0, 0, 'zhTW', '我注意到島那邊有一些火光。還有一個人。讓我們去那邊看看，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 1, 0, 'zhTW', '那是帕瓦爾·雷瑟。讓我們過去看看他會說什麼，如何？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 2, 0, 'zhTW', '和我們講講你對樹蔭旅店的事情有什麼瞭解，放心，我不會打你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 3, 0, 'zhTW', '看看這裡，如果你不告訴我有關那次火災的事情的話——');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 4, 0, 'zhTW', '該死！你最好不要死在我手上！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 5, 0, 'zhTW', '雷瑟，你在幹什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 4983 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (4983, 6, 0, 'zhTW', '好像是掛了，你最好回去告訴克羅格這裡發生了什麼。');
