INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5046, 0, 0, 'zhTW', '帕瓦爾·雷瑟！終於找到你了。你現在和食人魔混在一起了？不要害怕，即便是背叛者也會得到寬恕。');
