DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 0, 0, 'zhTW', '愛德華，泰勒爾出來。準備接受你們的第一輪挑戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 1, 0, 'zhTW', '利斯塔，把戰俘帶過來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 2, 0, 'zhTW', '看來你們應付第一輪還是非常輕鬆的嘛。讓我們看看你是怎樣對付第二輪測試的。利斯塔，把巫妖王的爪牙帶上來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 3, 0, 'zhTW', '利斯塔，召喚亡靈俘虜。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 4, 0, 'zhTW', '年輕的戰士，面對你們最後一輪挑戰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 5, 0, 'zhTW', '利斯塔，衝啊……憎惡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5661 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5661, 6, 0, 'zhTW', '幹得很好。現在站到旁邊去，讓其他的兄弟來試試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 0, 'zhTW', '你們最好現在就能證明自己不是個廢物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 1, 'zhTW', '好了，你這堆可憐的爛骨頭。讓我們看看你有什麼本事。攻擊你的對手，我說停的時候你才能停止。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 2, 'zhTW', '你那也叫作戰？如果那也叫戰鬥，那我就是戰神了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 3, 'zhTW', '木頭和稻草會顯示出憐憫之心，但巫妖王不會！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 4, 'zhTW', '劍不是工具，它是你的延伸。我希望你們能做得更好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 5, 'zhTW', '停！你們把這個叫做戰鬥？真可憐！現在用心去戰鬥，好吧，你們其實已經沒那東西了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 6, 'zhTW', '你們是死了，但不是被埋了。現在讓我看看你們的實力吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 7, 'zhTW', '你們不再是只為了自己而戰鬥，蠢貨！你們現在是為希爾瓦娜斯女王而戰，所以快點表現出你們的價值來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5662 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5662, 0, 8, 'zhTW', '你們知道自己看起來有多爛嗎？這是我見過的最可笑的戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 0, 0, 'zhTW', '瑟裡莎，把這個交給蘭克斯特神父。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 1, 0, 'zhTW', '謝謝你，我的寶貝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 2, 0, 'zhTW', '和我告訴你的一樣棒，是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 2, 1, 'zhTW', '我不是告訴你新的控制技術會成功的嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 2, 2, 'zhTW', '你覺得我的新玩具怎麼樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 2, 3, 'zhTW', '你喜歡我的寵物嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 2, 4, 'zhTW', '她難道不是最讓人驚奇的小東西嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 3, 0, 'zhTW', '一點點小魔法，她當然非常關心這些……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 3, 1, 'zhTW', '每個人都有弱點，關鍵是如何要找到它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 3, 2, 'zhTW', '摧毀她的精神對我來說很容易。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 3, 3, 'zhTW', '經過努力，我發現大腦中有這樣一個特定的部位，如果你將其切除或者施加特定的刺激，就可以使得該生物變得更加溫順。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 3, 4, 'zhTW', '你不是想要讓我把所有的秘密都告訴你吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5696 AND `GroupID` = 3 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5696, 3, 5, 'zhTW', '一個小小的儀式就夠你受的了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5697 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5697, 0, 0, 'zhTW', '遵命，大人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5697 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5697, 1, 0, 'zhTW', '我的主人阿博納斯大人讓我把這個交給你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5697 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5697, 2, 0, 'zhTW', '大人，這是蘭克斯特神父給您的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 0, 'zhTW', '妙極了，傑勒德，你們超越了自己，再來一次。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 1, 'zhTW', '傑勒德，你給我留下了深刻的印象。我原本以為你只會誇誇其談，但事實證明我錯了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 2, 'zhTW', '我不同意你用鍊金術去解決這些問題，但我對結果感到滿意。你幹得很好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 3, 'zhTW', '傑勒德，你有訓練她的場地嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 4, 'zhTW', '這絕對是一個令人驚訝的發現。我很想看看你失敗了的那些試驗品。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 6, 'zhTW', '很好，傑勒德。接下來，你要負責培養出更多這樣的生物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 7, 'zhTW', '你的寵物很不錯，傑勒德，但我想她需要一個帶著鈴鐺的項圈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5698 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5698, 0, 8, 'zhTW', '太不可思議了。這裡面到底有什麼訣竅？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5699 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5699, 0, 0, 'zhTW', '我從來沒見過這樣的情況。一個生物居然能夠在沒有失去自己意識的情況下被控制。你對她作了什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5699 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5699, 0, 1, 'zhTW', '真讓人感到驚訝！你是怎麼實現恆定控制的呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5699 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5699, 0, 2, 'zhTW', '傑勒德，我不贊成你的試驗，但是我承認結果是令人印象深刻的。你到底對她作了什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5699 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5699, 0, 3, 'zhTW', '她保留了她的知識和語言能力，同時還能為你出色地完成任務。你到底做了些什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5699 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5699, 0, 4, 'zhTW', '真是讓人驚訝，傑勒德。你是怎麼辦到的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5699 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5699, 0, 5, 'zhTW', '真令人驚訝。你在控制她，但她還能保持自己的意識。你是怎麼做到的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 0, 'zhTW', '不知道我能不能找到《魔法和能量的守則》這本書。啊哈，在這裡，它怎麼會在這裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 1, 'zhTW', '非常有趣。但如果確實是這樣的話，那我的理論就是錯誤的。我要重新去讀另一部分，看看我究竟錯過了什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 2, 'zhTW', '《不可思議的魔法流動及它是如何影響這個世界的》，瑪吉諾·仲馬著。我在一直尋找這本書。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 3, 'zhTW', '如果這個理論是正確的，那我就得做很多研究了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 4, 'zhTW', '啊，在這裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 5, 'zhTW', '看來我真的需要一個更好的圖書分類系統了。啊，就是這本！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 6, 'zhTW', '但這個肯定不對。我把那本大書放哪裡去了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 7, 'zhTW', '《卡德加的魔法日記，第八卷》，我要的是這一本。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 8, 'zhTW', '哈，《達拉然大法師的神秘咒術》，太棒了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 9, 'zhTW', '不知道我能不能找到《魔法和能量的守則》這本書。啊哈，在這裡，它怎麼會在這裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 10, 'zhTW', '《魔法致病學》，不對不對。《魔法矩陣》，也不對。啊，就是這個，《魔法神秘學》。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 11, 'zhTW', '這就是我要尋找的魔法書。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 12, 'zhTW', '沒錯。嗯，這本書參考了另外一本書的內容。看來我還要去找那一本書。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 13 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 13, 'zhTW', '這一本不是很有用。讓我看一下另外一本。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 14 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 14, 'zhTW', '那就是我想要知道的東西。現在我要知道書中的哪個章節討論的是魔法流量的變化問題。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 15 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 15, 'zhTW', '看來我對於能量的理解是正確的。讓我們去看看另一本書講了些什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5700 AND `GroupID` = 0 AND `ID` = 16 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5700, 0, 16, 'zhTW', '從頭再來一遍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 0, 0, 'zhTW', '如果你在這裡，那就表明你已經準備好去研究召喚惡魔的方法了。我們將從最低階的生物召喚開始，然後再慢慢進階。讓我們開始吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 1, 0, 'zhTW', '最容易召喚的是小鬼。你的能力也許已經遠遠超過召喚小鬼的水平，但是我們為了保證召喚教學的完整性，所以還是從召喚它開始吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 2, 0, 'zhTW', '這些邪惡的小傢伙就是小鬼。它很小而且很瘦弱，顯然是不能做為肉盾使用的，而它的威力也不大。這種召喚生物最好是在多人組隊的時候作為支援力量使用。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 3, 0, 'zhTW', '現在你已經瞭解了小鬼的特性，那麼讓我們繼續研究下一種你可以召喚的生物：虛空行者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 4, 0, 'zhTW', '這種惡魔被稱為虛空行者。它的力量和耐力都非常驚人，可以出色地勝任防禦任務。首先控制它來攻擊你的敵人，這樣就能保證你在有肉盾保護的情況下安全地使用法術和技能。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 5, 0, 'zhTW', '如果你還沒有看見過虛空行者，那你一定要去看看。這種生物看上去就極具氣勢，而且在戰場上也能發揮很強的作用。接下來，讓我們看看所有男性學員都在熱切期盼的召喚生物：魅魔。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 6, 0, 'zhTW', '好了。除了和前面那兩種召喚生物的外形有著明顯的差異之外，魅魔的攻擊能力也非常可觀。然而，她的防禦力很差，所有很難作為肉盾來使用。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 7, 0, 'zhTW', '努力學習，總有一天你們也可以召喚魅魔的，但現在我們要繼續課程了，下一講是地獄獵犬。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 8, 0, 'zhTW', '現在你們看到的就是地獄獵犬。這種生物擁有法力燃燒等多種技能，這些技能在對付施法型的敵人時是十分有用的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 9, 0, 'zhTW', '當遇見施法者的時候，這種惡魔是你最好的朋友。現在，讓我們進行一下講的課程。這種召喚生物主要被用來幫助你更快地旅行。它就是地獄戰馬，有時也被稱為夢魘。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 10, 0, 'zhTW', '我懷疑你已經看過很多次這個生物了。這些惡魔馬能讓你的旅行速度加快，只要你召喚出它們來，就可以把它們當作自己的坐騎。但是地獄戰馬是非常難以馴服的，所以在嘗試之前，你最好確定自己準備充足。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5702 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5702, 11, 0, 'zhTW', '所有的召喚生物都介紹完畢了。召喚課程已經結束。新的課程將會很快開始，如果你要想要得到進一步的提高，那就請不要走遠，先在周圍轉轉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5709 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5709, 0, 0, 'zhTW', '絕不能讓邪惡力量侵襲這個世界！來吧，孩子們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5710 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5710, 0, 0, 'zhTW', '防禦結界被摧毀了！醒來吧，阿塔萊！醒來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5710 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5710, 1, 0, 'zhTW', '加入我們吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5710 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5710, 2, 0, 'zhTW', '奪靈者來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5710 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5710, 3, 0, 'zhTW', '哈卡會重生的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5710 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5710, 4, 0, 'zhTW', '哈卡會重生的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5721 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5721, 0, 0, 'zhTW', '回去！不要喚醒沉睡者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5721 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5721, 1, 0, 'zhTW', '你不知道你幹了什麼！我們要為了你的利益而毀滅你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 0, 0, 'zhTW', '嗯，看來基佛需要一個新的專案。如果那個笨蛋阿博納斯繼續從基佛手裡搶專案，基佛肯定會對他有意見的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 1, 0, 'zhTW', '嗯，搞定了。現在讓基佛試試看。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 2, 0, 'zhTW', '%s強行把液體灌進了那個疲憊不堪的人的口中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 3, 0, 'zhTW', '%s戳了戳那隻小蛤蟆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 4, 0, 'zhTW', '不是基佛想要的結果。基佛可能加了太多的地根草。我們來看一下第二份藥水是不是基佛所需要的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 5, 0, 'zhTW', '%s給蛤蟆餵了一些奇怪的液體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 6, 0, 'zhTW', '%s失望地戳了戳那隻小松鼠。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 7, 0, 'zhTW', '好吧，失敗了。這種生物太小了。讓我們看看基佛的第三批藥劑效果如何。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 8, 0, 'zhTW', '%s給松鼠餵了一些粘粘的液體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 9, 0, 'zhTW', '%s戳了戳那隻野兔。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 10, 0, 'zhTW', '基佛對這個結果不太滿意。也許如果基佛嘗試一下大劑量的話，效果會好一些。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 11, 0, 'zhTW', '%s抓住野兔，把那瓶液體全數灌入野兔腹中，然後把它塞回籠子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 12, 0, 'zhTW', '這是什麼？基佛要的是一隻綿羊？基佛想要一件強力的武器，但他現在得到的就是這隻綿羊。基佛非常失望。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 13, 0, 'zhTW', '%s反覆地戳那隻綿羊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5734 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5734, 14, 0, 'zhTW', '基佛很高興。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5888 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5888, 0, 0, 'zhTW', '願安寧和耐心永遠與你同在，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5901 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5901, 0, 0, 'zhTW', '水之精靈，我讚美你，還有我想請你幫個忙。你聽到$n的請求了，而我相信$g他的:她的用意是高尚的。你願意幫助我們嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5901 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5901, 1, 0, 'zhTW', '謝謝你，偉大的精靈。謝謝你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5907 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5907, 0, 0, 'zhTW', '當然，奧克拉。但是不要離家太遠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 0, 'zhTW', '我很渴。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 1, 'zhTW', '托爾塔肯定很擔心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 2, 'zhTW', '我們還要走更遠嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 3, 'zhTW', '還沒到嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 4, 'zhTW', '沙子灌進鞋裡了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 5, 'zhTW', '要走多遠？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 6, 'zhTW', '你能揹我走一段嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 0, 7, 'zhTW', '你聽說過食人魔、地精和深淵領主的故事嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 1, 0, 'zhTW', '我親愛的托爾塔！我終於回來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 2, 0, 'zhTW', '親愛的托爾塔，在別離那麼長時間之後我們終於再次相見了。我們之間的愛還會更加熱烈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 5955 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (5955, 3, 0, 'zhTW', '好吧，托爾塔。你要什麼我就給你找什麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6015 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6015, 0, 0, 'zhTW', '你知不知道我在這裡等了很久？晚飯在哪裡？那麼晚了還沒有晚飯的影子？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6015 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6015, 1, 0, 'zhTW', '少廢話，我肚子餓了！現在去海里給我找點吃的來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6015 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6015, 2, 0, 'zhTW', '這次不要再迷路了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6026 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6026, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6109 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6109, 0, 0, 'zhTW', '來吧，小傢伙們。面對我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6119 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6119, 0, 0, 'zhTW', '太可怕了！好吧，也許它只是需要被清理一下？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6169 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6169, 1, 0, 'zhTW', '上帝保佑！$n！我們完成了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6172 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6172, 0, 0, 'zhTW', '感謝你，親愛的$C，你救了我的命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6176 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6176, 0, 0, 'zhTW', '集中精神，$n。我馬上要開始召喚儀式了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6176 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6176, 1, 0, 'zhTW', '%s開始吟唱召喚法術……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6177 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6177, 0, 0, 'zhTW', '感謝你，親愛的$C，你救了我的命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6182 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6182, 0, 0, 'zhTW', '到房子那邊去！無論如何都要緊跟著我！那裡有槍和彈藥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 6182 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6182, 1, 0, 'zhTW', '幹得好！');
