INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (6222, 0, 2, 'zhTW', '這些蠢貨……他們源源不斷地湧來。死吧，蠢貨！死！');
