INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (8421, 0, 0, 'zhTW', '笨蛋，如果我拿我兄弟脆弱的感情開玩笑，他會被送去急救的。');
