INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (8421, 1, 0, 'zhTW', '我輕鬆地讓你從暮光之錘的那群笨蛋手裡得到了最後一塊蘇塔拉之石。');
