INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9816, 3, 0, 'zhTW', '哈！哈！哈！謝謝你們這些笨蛋放了我。現在讓我吃掉你們的肉來報答你們吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9818 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
