DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9818 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9818, 1, 0, 'zhTW', '%s開始召喚黑手恐法師！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9997 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9997, 0, 0, 'zhTW', '林格！你沒事了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9997 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9997, 1, 0, 'zhTW', '林格？快醒醒！不要擔心，我會照顧你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 0, 0, 'zhTW', '嗯，我不知道自己還能撐多久……我感到有些乏力……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 0, 1, 'zhTW', '記住，如果我迷糊了，就抽我的耳光。如果我暈厥的話，就用這個水壺。現在，我們走吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 1, 0, 'zhTW', '熱……我受不了了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 1, 1, 'zhTW', '你……能不能揹我一程？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 1, 2, 'zhTW', '啊啊啊啊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 1, 3, 'zhTW', '我有些不適……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 2, 0, 'zhTW', '我……我這是在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 2, 1, 'zhTW', '我現在感覺好些了，謝謝你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 2, 2, 'zhTW', '嗯，繼續！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 2, 3, 'zhTW', '我感覺怎麼樣？簡直溼透了，謝謝你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 3, 0, 'zhTW', '斯普拉格！我簡直不敢相信自己居然能活著回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 4, 0, 'zhTW', '啊……有點暈……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 5, 0, 'zhTW', '%s昏倒在地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 6, 0, 'zhTW', '%s停留了幾秒後，站了起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 7, 0, 'zhTW', '額。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 9999 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (9999, 8, 0, 'zhTW', '%s過了好一會兒後消失了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10000 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10000, 0, 0, 'zhTW', '我改變主意了，我忠實的僕人。你不必把犯人帶到我的書房了，我要在這兒解決掉他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10000 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10000, 1, 0, 'zhTW', '你和你那些可憐的夥伴會發現驅逐我和我的兒子比那些可憐的肯瑞託更有成就感了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10000 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10000, 2, 0, 'zhTW', '如果你不用你的劍和我主人敵人的知識來服侍我主人的話……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10000 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10000, 3, 0, 'zhTW', '你的枯骨將作為一個見證——一個人愚蠢到膽敢入侵我的領地會有什麼後果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10096 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10096, 0, 0, 'zhTW', '索瑞森的臣民將在秩序競技場中看著你死去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10096 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10096, 1, 0, 'zhTW', '釋放你的怒火吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10096 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10096, 2, 0, 'zhTW', '但是真正的懲戒還在後面呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10096 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10096, 3, 0, 'zhTW', '很好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10096 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10096, 4, 0, 'zhTW', '你因為反對黑鐵王國的罪行而被宣判死罪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10096 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10096, 5, 0, 'zhTW', '哈！我敢打賭你以為自己能獲勝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 0, 0, 'zhTW', '很好……看起來好像這些愛管閒事的小人物來得正是時候。歡迎，凡人！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 1, 0, 'zhTW', '我的孩子，讓他們的鮮血在地板上一滴也不要留下了。享受他們的靈魂大餐吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 2, 0, 'zhTW', '蠢貨……殺死穿那件衣服的人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 3, 0, 'zhTW', '難以置信！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 4, 0, 'zhTW', '你的努力都是白費心機。沒有什麼會阻止我們的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 5, 0, 'zhTW', '孩子，別推我的手！我將用你的獸皮裝飾我的靴子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 6, 0, 'zhTW', '使用冰凍噴吐，你這蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 7, 0, 'zhTW', '這不可能！！！雷德，解決掉這些傢伙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 8, 0, 'zhTW', '酋長會除掉你的，凡人。做好準備吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 9, 0, 'zhTW', '嚐嚐我的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 10, 0, 'zhTW', '你的勝利不會長久。聯盟和部落的日子都不長了！下次我們見面就是最後一次了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 11, 0, 'zhTW', '凡人戰敗了！黑石軍團的新時代即將來臨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 12, 0, 'zhTW', '在這個世界中，時間是你的敵人，但是它是我的戰友。這段你自以為在你掌握之中的時光實際上是你的主宰。因此我會說……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 13, 0, 'zhTW', '讓遊戲開始吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10162 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10162, 14, 0, 'zhTW', '啊……英雄們。你們都會堅持不懈的，是不是？你們這群凡人想要與我的力量相抗衡——那麼你們就要付出代價。現在他將為我而戰……他的任務就是幹掉你們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10181 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10181, 0, 0, 'zhTW', '%s跪了下來，並從地上撿起了項鍊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10181 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10181, 1, 0, 'zhTW', 'Belore……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10181 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10181, 2, 0, 'zhTW', '%s低頭看著地上的項鍊。女王帶著悲傷的神情吟唱了一段咒語，召喚出上層精靈的靈魂。整個房間中都回響著辛多雷那久遠的歌聲……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10184 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10184, 0, 0, 'zhTW', '真是走運。通常我必須離開窩才能找到食物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10184 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10184, 1, 0, 'zhTW', '要明白你的處境，凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10184 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10184, 2, 0, 'zhTW', '這毫無意義的行動讓我很厭煩。我會從上空把你們都燒成灰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10184 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10184, 3, 0, 'zhTW', '看起來需要再給你一次教訓，凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10184 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10184, 4, 0, 'zhTW', '%s深深地吸了一口氣……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10220 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10220, 0, 0, 'zhTW', '%s發出悽慘的低嘯，轟然倒地。黑石塔大廳中緊接著傳來令人毛骨悚然的咆哮聲。看來有什麼生物受到了刺激，變得異常憤怒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 0, 'zhTW', '比修知道寶藏被藏在哪兒了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 1, 'zhTW', '哇！*咳**咳*我要戒菸！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 2, 'zhTW', '問問基布雷爾關於寶藏的事情！哇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 3, 'zhTW', '他們都去了黑石塔，但是跟比修一樣……沒有人活著回來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 4, 'zhTW', '奧普斯想要一些科爾戈的黃金……和一些蟲子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 5, 'zhTW', '基布雷爾正在接受地精工程學協會的調查。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 6, 'zhTW', '比修失敗了！啊！*咳嗽*');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10262 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10262, 0, 7, 'zhTW', '龍控制著獸人！？不會吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10300 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10300, 0, 0, 'zhTW', '記住，我需要你的幫助來正確進行吟唱。我在我們前進的路上會請你幫好幾次忙，所以請準備好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10300 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10300, 1, 0, 'zhTW', '這藍色的亮光……真奇怪。你認為它意味著什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10300 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10300, 2, 0, 'zhTW', '我們找到它了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10300 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (10300, 2, 1, 'zhTW', '請在我吟唱的時候點亮這個。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 10300 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
