INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11466, 0, 0, 'zhTW', '惡魔逃走了，我們必須趕緊抓住他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11469 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11469, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11486 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11486, 0, 0, 'zhTW', '誰敢破壞埃雷薩拉斯的聖潔？懦夫，面對我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11489 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11489, 0, 0, 'zhTW', '你不屬於這裡！先祖，起來對抗這些入侵者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11489 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11489, 1, 0, 'zhTW', '先祖馬靈在一聲巨大的雷鳴中掙脫了它的束縛。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11491 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11491, 0, 0, 'zhTW', '終於……在他的詛咒之握中……解脫了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11496 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11496, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11501 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11501, 0, 0, 'zhTW', '別向我挑戰，矮小的傢伙！現在我是國王啦，永遠都是！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 0, 0, 'zhTW', '拉格納羅斯，炎魔之王！他比這個世界本身還要古老，在他面前屈服吧！在你們的末日面前屈服吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 1, 0, 'zhTW', '你為什麼要喚醒我，埃克索圖斯，為什麼要打擾我？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 2, 0, 'zhTW', '是因為這些入侵者，我的主人！他們闖入了您的聖殿，想要竊取您的秘密！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 3, 0, 'zhTW', '蠢貨！你讓這些不值一提的蟲子進入了這個神聖的地方？現在你還將他們引到了我這裡來？你太讓我失望了，埃克索圖斯，你太讓我失望了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 4, 0, 'zhTW', '現在輪到你們了！你們愚蠢地追尋拉格納羅斯的力量，現在你們即將親眼見到它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 5, 0, 'zhTW', '出現吧，我的奴僕！保衛你們的主人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 6, 0, 'zhTW', '你們不是烈焰之王的敵人！出現吧，火焰的奴僕！你們的主人在召喚你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 7, 0, 'zhTW', '讓火焰淨化一切吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 8, 0, 'zhTW', '嚐嚐薩弗隆的火焰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 9, 0, 'zhTW', '死吧，你這卑鄙的傢伙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11502 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11502, 10, 0, 'zhTW', '死吧，你這卑鄙的傢伙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11582 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11582, 0, 0, 'zhTW', '瞧，不要召喚這樣的東西。它如此脆弱，用棒敲擊就能使它粉身碎骨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11582 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11582, 0, 1, 'zhTW', '嗯，這東西看起來做成風鈴更合適。做好筆記，學生們……衝鋒廝殺時你們可不能召喚出這樣的玩意兒來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11582 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11582, 0, 2, 'zhTW', '這個比上一個稍微好那麼一點。但是它的骨架結構還是很脆弱。你能召喚出這樣的東西，證明你還是在不斷進步的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11582 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11582, 0, 3, 'zhTW', '看看這東西不牢靠的結構。你一定要念完咒語，否則你就只能召喚出這樣的東西來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11582 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11582, 0, 4, 'zhTW', '噢，這東西簡直毫無用處。讓我再試一次。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 0, 0, 'zhTW', '幹得好，我的手下。凡人的勇氣開始消退了！現在，讓我們看看他們如何應對黑石塔的真正主人的力量！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 0, 1, 'zhTW', '死亡騎士們……到這兒來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 0, 2, 'zhTW', '燃燒吧！你們這些悲慘的傢伙！燃燒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 1, 0, 'zhTW', '不可能！出現吧，我的僕人！再次為你們的主人效力！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 2, 0, 'zhTW', '沒用的$n！你的朋友不久之後就會去找你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 3, 0, 'zhTW', '這不可能！我是這裡的主人！你們這些凡人對於我來說一無是處！聽到了沒有？一無是處！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 4, 0, 'zhTW', '你們也是法師？小心別玩火自焚……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 5, 0, 'zhTW', '戰士們，我知道你們可以更加勇猛！讓我們見識一下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 6, 0, 'zhTW', '德魯伊和你們愚蠢的變形法術。讓我們看看有什麼事情會發生吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 7, 0, 'zhTW', '牧師們！如果你們要繼續這麼治療的話，那我們就來玩點有趣的東西吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 8, 0, 'zhTW', '聖騎士……聽說你們有無數條命。讓我看看到底是怎麼樣的吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 9, 0, 'zhTW', '薩滿祭司，讓我看看你們的圖騰到底是幹什麼用的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 10, 0, 'zhTW', '術士們，不要隨便去嘗試那些你們根本不理解的法術。看到後果了吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 11, 0, 'zhTW', '獵人們，還有你們那些討厭的玩具槍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 12, 0, 'zhTW', '潛行者？不要躲躲藏藏了，勇敢地面對我吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11583 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11583, 13, 0, 'zhTW', '死亡騎士們……到這兒來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11596 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11596, 0, 0, 'zhTW', '啊……科多獸令人驚奇的聲音。我喜歡它們震動地表的方式……幫我照看這些野獸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11596 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11596, 0, 1, 'zhTW', '嗨，小心那頭科多獸！你最好在我寄予你信任之前看好這頭野獸！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11596 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11596, 0, 2, 'zhTW', '那隻科多獸真美。等等，我的眼鏡在哪兒？也許你該幫我照看這頭野獸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11625 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11625, 0, 0, 'zhTW', '真遺憾又走了一位顧客，不過我們還有人可騙。我們過段時間還會再回來的，拜拜！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11625 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11625, 1, 0, 'zhTW', '我們想僱傭一些保鏢來保護基澤爾頓車隊。我們就停在科爾考爾半人馬村北邊考米特小屋東邊的路上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11626 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11626, 0, 0, 'zhTW', '基澤爾頓車隊就要開拔了！我們很快就會回來，可是如果你等不及就去考米特小屋找我們，我們會在那兒開一個小時的店。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11626 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11626, 1, 0, 'zhTW', '這是裡格·基澤爾頓僱傭的護送到瑪諾洛克集會所的車隊。我在葬影村東邊的路上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11672 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11672, 0, 0, 'zhTW', '%s在主人遇到危險時是不會選擇死亡的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11677 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11677, 0, 0, 'zhTW', '斯尼維爾在此！冷齒礦洞是斯尼維爾的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11680 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11680, 0, 0, 'zhTW', '不要穿過黑鐵矮人的地盤，$C。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11711 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11711, 0, 0, 'zhTW', '停……聽到了嗎？前方，西邊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11711 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11711, 1, 0, 'zhTW', '我的箭用完了。如果他們還有更多的話，朋友我想你得親自去取箭了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11711 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11711, 2, 0, 'zhTW', '讚美月神！我不知道沒有你的話我能不能活下來，朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11711 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11711, 3, 0, 'zhTW', '我的腿現在好多了，藥物正在慢慢起效。請原諒，我必須馬上向上級彙報這兒的情況。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11711 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11711, 4, 0, 'zhTW', '請同在梣谷邁斯特拉崗哨的哨兵奧奈雅談談，你會為你這幾天的英勇行為得到嘉獎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11747 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11747, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11793 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11793, 0, 0, 'zhTW', '這裡什麼也不能有！你必須被摧毀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11793 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11793, 0, 1, 'zhTW', '你不屬於這裡！你的身體將成為我造物的養料！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 0, 'zhTW', '殺死你簡直是易如反掌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 1, 'zhTW', '巨魔的魔精是最好的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 2, 'zhTW', '你的頭骨將用於裝飾我們的祭壇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 3, 'zhTW', '我要把你的魔精抽乾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 4, 'zhTW', '嚐嚐巫毒的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 5, 'zhTW', '我渴望戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11830 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11830, 0, 6, 'zhTW', '你很快就會沒命了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 0, 'zhTW', '殺死你簡直是易如反掌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 1, 'zhTW', '巨魔的魔精是最好的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 2, 'zhTW', '你的頭骨將用於裝飾我們的祭壇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 3, 'zhTW', '我要把你的魔精抽乾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 4, 'zhTW', '嚐嚐巫毒的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 5, 'zhTW', '我渴望戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11831 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11831, 0, 6, 'zhTW', '你很快就會沒命了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 0, 0, 'zhTW', '我們會根據你收集的碎片找出夢魘的源頭，$n。那樣我們就能開啟一條裂縫，把伊蘭尼庫斯從翡翠夢境中拉出來。要堅強，$C。我們將要邀請夢魘的化身進入我們的世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 1, 1, 'zhTW', '月神湖上空將出現一道裂縫。做好準備吧，$n。伊蘭尼庫斯的入侵會給整個世界帶來混亂和戰爭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 2, 2, 'zhTW', '他會不擇手段地摧毀瑪法里奧的肉身。我們絕不能讓此事發生……我們必須在泰蘭妲到達之前控制住那頭野獸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 3, 3, 'zhTW', '保衛永夜港，英雄……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 4 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 4, 4, 'zhTW', '你這惡魔！嚐嚐塞納留斯的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 5 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 5, 5, 'zhTW', '你算錯了一招，野獸。你不曾料到我們會在瑪法里奧的身邊召喚你吧？伊蘭尼庫斯，你的救贖就要來臨了。你將得到淨化——墮落之源將被清除。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 6 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 6, 6, 'zhTW', '快，$n！我們必須儘快找地方躲起來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 7 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 7, 7, 'zhTW', '勇士，請保護我們的人民吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 8 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 8, 8, 'zhTW', '沒問題，伊蘭尼庫斯。你要保重。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 9 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 9, 9, 'zhTW', '英雄，讓我們離開永夜港吧。來小樹林找我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 10 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 10, 10, 'zhTW', '來吧，$n。湖泊就在拐彎處。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 11 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 11, 11, 'zhTW', '靠近我，$n。我會保護你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 12 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 12, 12, 'zhTW', '瑪法里奧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 13 AND `ID` = 13 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 13, 13, 'zhTW', '瑪法里奧，夢魘裡到處是屍體。究竟發生了什麼事？是什麼造成了這樣的暴行？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 14 AND `ID` = 14 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 14, 14, 'zhTW', '瑪法里奧，我跟你有相同的感覺。黑暗的歲月即將降臨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 15 AND `ID` = 15 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 15, 15, 'zhTW', '瑪法里奧，你離開得太久了。艾澤拉斯的和平是如此的脆弱。我的父親怎麼樣了？你的兄弟呢？你有什麼訊息嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 16 AND `ID` = 16 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 16, 16, 'zhTW', '老朋友，再見了……再見……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11832 AND `GroupID` = 17 AND `ID` = 17 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11832, 17, 17, 'zhTW', '凡人，讓我們回到樹林去吧。');
