INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11901, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 0, 0, 'zhTW', '雷矛的渣滓！在我的要塞？！殺光他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 1, 0, 'zhTW', '你們想要把霜狼的將軍引出他的要塞？可笑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 2, 0, 'zhTW', '雷矛的渣滓們，如果你們真的有這麼大膽的話，就來我的堡壘中挑戰我吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 3, 0, 'zhTW', '我想你的進攻因為寒冷減弱了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 3, 1, 'zhTW', '你會在今天見到你的祖先的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 3, 2, 'zhTW', '如果你不自動離開奧特蘭克山谷，霜狼會強迫你離開的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 3, 3, 'zhTW', '你不能擊敗霜狼部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 3, 4, 'zhTW', '你不是部落的力量的對手！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11946 AND `GroupID` = 3 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11946, 3, 5, 'zhTW', '不留活口！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11947 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11947, 0, 0, 'zhTW', '去死吧！你們別想在奧特蘭克山谷站住腳！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11947 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11947, 1, 0, 'zhTW', '我永遠不會被你那點伎倆算計到，蠢貨！如果你想要一戰的話，那就到我的地盤來挑戰我吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11947 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11947, 2, 0, 'zhTW', '準備發動攻擊！為部落而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 0, 0, 'zhTW', '雷矛士兵，你們的將軍受到攻擊！我需要援助！快！快！殺死這些卑鄙的霜狼氏族的成員。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 1, 0, 'zhTW', '你們永遠無法將我趕出我的工事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 1, 1, 'zhTW', '為什麼你們不再試驗一次你們那些低賤的手段，娘娘腔？！你們是不是一群懦夫？？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 0, 'zhTW', '不留俘虜！把這些異教徒都殺光！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 1, 'zhTW', '你的攻擊太微弱了！去找些兔子練習一下，當你強壯些後再回來找我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 2, 'zhTW', '我們一定會完成使命的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 3, 'zhTW', '你這樣的烏合之眾是不可能打倒我的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 4, 'zhTW', '聯盟會勝利的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 5, 'zhTW', '雷矛一族不會對任何人俯首稱臣的，特別是部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 2 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 2, 6, 'zhTW', '這是你的最高水平了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11948 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11948, 3, 0, 'zhTW', '不留俘虜！把這些異教徒都殺光！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11949 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11949, 0, 0, 'zhTW', '去死吧，渣滓！聯盟會獲得勝利的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11949 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11949, 1, 0, 'zhTW', '可惡的霜狼懦夫！如果你們想要一戰的話，就放馬，不，放狼過來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11949 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11949, 2, 0, 'zhTW', '把這些渣滓趕出奧特蘭克！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11980 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11980, 0, 0, 'zhTW', '沒錯，遊戲就快要結束了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11980 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11980, 1, 0, 'zhTW', '消滅他們！一個不留！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11980 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11980, 2, 0, 'zhTW', '愚蠢的凡人，竟敢冒犯我！別以為我會放過你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11980 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11980, 3, 0, 'zhTW', '伊利丹大人，賜予我飛翔的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11981 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11981, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 11982 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (11982, 0, 0, 'zhTW', '%s變得極為狂暴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12017 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12017, 0, 0, 'zhTW', '你怎麼進來的？你們這種生物不能進來！我要毀滅你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12017 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12017, 1, 0, 'zhTW', '你們很聰明，凡人——但是我不會那麼輕易地離開我的聖地！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 0, 0, 'zhTW', '可笑的凡人！在烈焰之子面前灰飛煙滅吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 1, 0, 'zhTW', '守護符文被摧毀了！兄弟們，殺掉這些入侵者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 2, 0, 'zhTW', '塵歸塵，土歸土！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 3, 0, 'zhTW', '是因為這些入侵者，我的主人！他們闖入了您的聖殿，想要竊取您的秘密！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 4, 0, 'zhTW', '不……不可能！等一下……我投降！我投降！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 5, 0, 'zhTW', '拉格納羅斯，炎魔之王！他比這個世界本身還要古老，在他面前屈服吧！在你們的末日面前屈服吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12018 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12018, 6, 0, 'zhTW', '是因為這些入侵者，我的主人！他們闖入了您的聖殿，想要竊取您的秘密！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12046 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12046, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12056 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12056, 0, 0, 'zhTW', '%s為拉格納羅斯做最後一次服務……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 8, 0, 'zhTW', '已經很多年了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 9, 0, 'zhTW', '誰在女神的祭壇搗亂？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 12, 0, 'zhTW', 'Enu thora serador。這是一片神聖之地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 13, 0, 'zhTW', '我們會給你看……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 14, 0, 'zhTW', '朝上看，Thara dormil dorah……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 15, 0, 'zhTW', '這寶石曾允許與月神本人進行直接溝通。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 16, 0, 'zhTW', '月神透過寶石傳達著她無盡的智慧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 17, 0, 'zhTW', '寶石需要得到保護，於是我們就向女神求助。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 18, 0, 'zhTW', '很快，我們眼前浮現出一種生物的幻象……它有貓頭鷹的羽毛，同時也有熊的意志和力量……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 19, 0, 'zhTW', '就在那天我們得到了梟獸。兇猛的守衛，女神派梟獸保護她所有的神聖之地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 21, 0, 'zhTW', '但是現在，梟獸已經變得更加兇猛，而且由於失去了女神的指引，它們很迷茫……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 22, 0, 'zhTW', '它們毫無目的地遊蕩……但是很多梟獸又回到了它們曾經發誓要保護的神聖之地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 23, 0, 'zhTW', '梟獸天生具有魔力；這種力量是由女神賜予他們的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 24, 0, 'zhTW', '你要知道，無論身處何地，他們都會受他人委託，保護著某種重要的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 25, 0, 'zhTW', '記住我們向你展示的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12116 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12116, 26, 0, 'zhTW', '再見。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12121 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12121, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12122 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12122, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 0, 0, 'zhTW', '你做了什麼，伊森利恩？你從前為名譽而戰，為了人民的幸福而戰……而現在……你殺死了我的孩子……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 1, 0, 'zhTW', '伊森利恩，你的靈魂將痛苦地燃燒著！聖光會賦予我力量對抗這個惡魔的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 2, 0, 'zhTW', '看著我，膽小鬼。面對你從前也曾擁有的信念和力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 3, 0, 'zhTW', '像他這樣的人還有成千上萬，一個倒下，另一個就會立即成為他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 4, 0, 'zhTW', '提里奧·弗丁單膝跪地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 5, 0, 'zhTW', '看看他們對我的孩子做了什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 6, 0, 'zhTW', '我無所事事地坐得太久了，迷霧籠罩著我……這令人很不舒服。我在哀嘆著要發生的……即將發生的事。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 7, 0, 'zhTW', '你會死得其所，泰蘭。一個新的秩序在這一天誕生——一個致力於消滅世間所有邪惡的勢力。惡魔可不能永遠藏匿於政治和笑話後面。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12126 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12126, 8, 0, 'zhTW', '我發誓……我發誓……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12136 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12136, 0, 0, 'zhTW', '飛往格羅姆高的飛艇已經靠港了！要去荊棘谷的就趕快啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12152 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12152, 20, 0, 'zhTW', 'Anu duoline。Nu sharola yenudoly。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12238 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12238, 0, 0, 'zhTW', '自由了！自由了！終於擺脫了束縛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12277 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12277, 0, 0, 'zhTW', '謝謝你，$n。現在讓我們離開這兒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12277 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12277, 1, 0, 'zhTW', '我們成功了！再次感謝你！我先走了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12277 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12277, 2, 0, 'zhTW', '嗨，霍恩尼茲！我回來了！有些好心人幫我脫離了困境。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12277 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12277, 3, 0, 'zhTW', '我們不得不把瑪洛迪半人馬從我們的合作伙伴列表中劃掉。他們太難共事了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12277 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12277, 4, 0, 'zhTW', '好吧，我要到吉爾吉斯村去了。他們不像瑪洛迪半人馬一樣蠢，而且他們更加通情達理。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12337 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12337, 0, 0, 'zhTW', '我感到前方有危險。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12337 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12337, 0, 1, 'zhTW', '要是我遇難的話，拿著我的揹包。一定要將它送到大將軍手上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 12337 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12337, 0, 2, 'zhTW', '我的背部痛死了。');
