INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (12717, 3, 0, 'zhTW', '現在我們必須等待。納迦很快就會意識到我們幹了些什麼。');
