INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (13601, 0, 0, 'zhTW', '我的！我的！我的！吉茲洛克是這片領域的統治者！你不能暴露我的存在！');
