INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (13716, 1, 0, 'zhTW', '我以我詛咒形態漂泊於世間太久了，現在你解救了我……你的行為不會白費的。');
