INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14324, 0, 0, 'zhTW', '國王死了——哦，召喚狡猾的米茲勒，他知道接下來該怎麼做。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14325 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14325, 0, 0, 'zhTW', '沒有人能打敗我，沒有人敢威脅國王！死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14325 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14325, 1, 0, 'zhTW', '幫我粉碎這些微不足道的傢伙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14325 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14325, 2, 0, 'zhTW', '%s開始反擊，展開報復！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14325 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14325, 3, 0, 'zhTW', '嘿，芬古斯說誰是戀豺狼人癖？！把囚犯交給國王吧，他們攜帶著武器，對國王來說是個威脅。我倒要看看當我把芬古斯打趴下的時候他還敢說什麼！哈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14325 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14325, 4, 0, 'zhTW', '好吧，芬古斯，你什麼意思？！你敢叫我戀豺狼人癖，看我一錘打得你找不到北！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14326 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14326, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14338 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14338, 0, 0, 'zhTW', '$n，我會讓我所有的盟友朋友都知道你今天救了我的命。給你——我需要輕裝上路，請你幫忙收下我的裁縫和製革物品！再次感謝你——再見！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14351 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14351, 0, 0, 'zhTW', '不！把鞣酸放進籃子裡，不然還會得到棒槌的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14353 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14353, 0, 0, 'zhTW', '哦不！國王死啦！呃……向新國王致敬！啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14353 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14353, 1, 0, 'zhTW', '他真的死了。你成了新國王……嗯，就是你！戈多克是你的啦，國王！你應該跟我談談，瞭解這兒的一切！我是……我是他的助手！是的，這就是我為什麼被稱為狡猾的傢伙的原因！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14354 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14354, 0, 0, 'zhTW', '想要鑰匙的話，就來追我吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14354 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14354, 1, 0, 'zhTW', '如果你敢的話就來追我吧！我會毫不猶豫地奔跑的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14354 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14354, 2, 0, 'zhTW', '為什麼你想要傷害我！？我們可以成為朋友的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14354 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14354, 3, 0, 'zhTW', '死？！你把普希林弄哭啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14354 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14354, 4, 0, 'zhTW', '跟我的小朋友問聲好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14362 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14362, 0, 0, 'zhTW', '荊棘幼崽開始成長！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14362 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14362, 1, 0, 'zhTW', '荊棘幼崽繼續成長！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14362 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14362, 2, 0, 'zhTW', '荊棘幼崽成長為完全體！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14368 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14368, 0, 0, 'zhTW', '我很懷疑他有什麼話可說，陌生人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14368 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14368, 1, 0, 'zhTW', '我個人並不在意他。王子從未如此對待過他領地中的高等精靈。唉，我還沒資格質疑王子。不過至少,他並沒有立即把溫薩魯斯燒成灰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14368 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14368, 2, 0, 'zhTW', '我們再也不想得到什麼關注啦，陌生人。回到那些讓你來找失蹤的管理員的傢伙那兒去吧，告訴他們什麼都找不到。然後回到我這兒來，我會告訴你一個失傳的秘密。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14383 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14383, 0, 0, 'zhTW', '哦親愛的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14383 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14383, 1, 0, 'zhTW', '%s嘆了一口氣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14383 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14383, 2, 0, 'zhTW', '《奧法師的食譜》不見了，這是個陷阱！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14383 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14383, 3, 0, 'zhTW', '《迦羅娜：潛行與詭計研究》必須被放回原處。');
