INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14386, 0, 0, 'zhTW', '%s感覺到了你的存在，開啟了一個虛空傳送門。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14392 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14392, 0, 0, 'zhTW', '奈法利安被殺了！奧格瑪的人民，為$N和他的盟友對黑龍軍團的戰鬥而鞠躬！這一次行動讓黑龍軍團受到重創，而且這次行動會讓他們的父親：死亡之翼感受到痛苦和哀傷的折磨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14392 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14392, 1, 0, 'zhTW', '為$N的成就感到振奮吧！為他激動的呼喊而陶醉吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14454 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14454, 0, 0, 'zhTW', '%s和他的侵略軍隊出現在希利蘇斯西北部的狂亂大火中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14454 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14454, 1, 0, 'zhTW', '%s令狂風席捲大地，怒吼之聲也從西北傳來。');
