INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14454, 2, 0, 'zhTW', '%s匿身於虛空，他的怒吼仍在你耳邊迴響。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14457 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14457, 0, 0, 'zhTW', '這片冰凍之地將迎來痛楚。到我這邊來，凡人，讓我給你一個快速和痛苦的死亡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14457 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14457, 1, 0, 'zhTW', '如果你們都是這麼怯懦，那我征服這個大地將會容易得多。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14457 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14457, 2, 0, 'zhTW', '當我從深淵歸來，你們都將付出沉痛的代價。');
