INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14461, 0, 0, 'zhTW', '聽從我的號令，烈焰的子民，讓我來燒掉這片不潔之地！');
