INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14461, 1, 0, 'zhTW', '所謂的“英雄”在哪兒？都不敢出來玩玩，嗯？');
