DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14750 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14750, 0, 0, 'zhTW', '%s完全被烈焰吞噬了，他的雙眼射出了瘋狂的光芒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14821 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14821, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14823 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14823, 0, 0, 'zhTW', '每個人都還玩得開心吧？棒極了！歡迎來到暗月馬戲團，艾澤拉斯最盛大的展覽！當你在尼比蓋爾的珍奇館購物時記得跟亞布和他的朋友談談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14823 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14823, 0, 1, 'zhTW', '我們回來啦，感覺棒極了！暗月馬戲團的朋友們，今兒是你們的幸運日！不要吝惜你的錢財，我們出售的都是來自世界各地的稀罕之物。無論你年方几何，無論你是貧窮還是富有，都能在暗月馬戲團上買到稱心如意的東西！請記得將你們的暗夜集市獎券交給吉瓦斯·格里加特，挑選一份豐厚的獎品！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14823 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14823, 0, 2, 'zhTW', '來啊，大家都來啊。歡迎來到暗月馬戲團！不要害羞。到蘭拉這裡購買來自遙遠大陸的奇特東西。如果你是個擁有暗月卡片的幸運兒，那麼就去找薩杜斯·帕雷教授吧。渴了？餓了？你很幸運！你可以從塞蘭妮亞和斯塔姆那裡獲得讓你倍感清新的食物和水。我建議你去嚐嚐暗月特殊儲備那裡的熱辣烤翅，絕對不容錯過！如果你想要了解自己的未來，那麼快點去找塞格談談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14823 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14823, 0, 3, 'zhTW', '歡迎所有人來到暗月馬戲團，世界上最盛大的事件！我們擁有……可口的美食、烈性飲料、異地的神器、尋寶書、豐厚的獎品和無盡的刺激！別忘記將你的暗月馬戲團獎券交給吉瓦斯·格里加特！只需要5張獎券你就可以領取一份艾澤拉斯最豐厚的獎品。每個人都是贏家！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14834 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14834, 0, 0, 'zhTW', '驕傲會將你送上絕路。來吧，凡人！品嚐奪靈者的憤怒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14834 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14834, 1, 0, 'zhTW', '凡人，逃跑是無濟於事的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14834 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14834, 2, 0, 'zhTW', '你膽敢踏足哈卡的聖地？哈卡的屬下們，摧毀這些異教徒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 14834 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (14834, 3, 0, 'zhTW', '哈卡的僕從，聽從主人的召喚！聖潔的神廟已經受到威脅。神聖的土地已經被入侵者佔領！誓死保護血神祭壇，殺死所有的入侵者！');
