INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15341, 0, 0, 'zhTW', '我們復仇的時刻到了！讓敵人的內心被黑暗吞噬吧！');
