INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15341, 1, 0, 'zhTW', '我們不用再呆在這座石牆裡面了！我們很快就能報仇了！在我們的怒火面前，就連那些龍也會戰慄！');
