INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15341, 2, 0, 'zhTW', '讓敵人膽戰心驚吧！讓他們在恐懼中死去！');
