INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15341, 3, 0, 'zhTW', '鹿盔將會嗚咽著哀求我饒他一命，就像他那懦弱的兒子一樣！一千年來的屈辱會在今天洗清！');
