INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15341, 4, 0, 'zhTW', '範達爾！你的死期到了！藏到翡翠夢境裡去吧，祈禱我們永遠都找不到你！');
