INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15341, 12, 0, 'zhTW', '很快你就會知道多管閒事的後果了，凡人……我的主人很快就能恢復力量……當他站起來的時候，就是你的世界毀滅的時候。');
