INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15362, 1, 0, 'zhTW', '要保持鎮定，勇士。我知道你來這裡的目的，我也知道你要尋找的東西。伊蘭尼庫斯不會輕易交出碎片的。他的心靈被某種力量扭曲了，那力量正是你想要打敗的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15362 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15362, 2, 0, 'zhTW', '你真的很吃驚嗎？是不是很難相信上古之神的力量居然能穿越翡翠夢境？這是真的——伊蘭尼庫斯，夢境之暴君，已經向我們發起挑戰了。隨他而來的，是毀滅的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15362 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15362, 3, 0, 'zhTW', '你要明白，伊蘭尼庫斯無非是想離開翡翠夢境，進入艾澤拉斯。一旦他得以脫身，他一定會瘋狂地摧毀我的肉身。但是，這也是獲取節杖碎片的惟一方法。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15362 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15362, 4, 0, 'zhTW', '勇士，你會將他帶回這個世界的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15367 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15367, 0, 0, 'zhTW', '來吧！你的朋友不會為你哀悼太久的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15369 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15369, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15370 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15370, 0, 0, 'zhTW', '%s凝視著$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15371 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15371, 0, 0, 'zhTW', '散開，$c！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15371 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15371, 0, 1, 'zhTW', '走開，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15371 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15371, 1, 0, 'zhTW', '不要找茬，公民！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15378 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15378, 0, 0, 'zhTW', '還有一個辦法……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15378 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15378, 1, 0, 'zhTW', '阿納克洛斯，我們會擊退他們的。我發誓會支援你完成這項任務。當你動手封印這股毀滅的力量時，千萬不要出錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15378 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15378, 2, 0, 'zhTW', '渺小的凡人，在無盡的噩夢中沉睡吧。讓噩夢吞噬你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15378 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15378, 3, 0, 'zhTW', '%s看了一眼她的同胞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15379 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15379, 0, 0, 'zhTW', '範達爾，記住我的話：別讓悲痛動搖了你的信念。你的思想……將把你引入黑暗，暗夜精靈。誤入歧途的復仇是不能被赦免的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15379 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15379, 1, 0, 'zhTW', '暗夜精靈，不要忘記今天犧牲的人們。這些野獸讓我們蒙受了巨大的損失。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15379 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15379, 2, 0, 'zhTW', '雅立史卓莎，賦予我堅定的信念，讓我擊退敵人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15380 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15380, 0, 0, 'zhTW', '阿納克洛斯，聲東擊西的戰術能讓你和年輕的德魯伊有足夠的時間來封印大門。不要猶豫。現在，讓我們看看它們如何對付這些混亂的魔法。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15380 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15380, 1, 0, 'zhTW', '讓他們感受藍龍的憤怒吧！願瑪裡苟斯庇護我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15380 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15380, 2, 0, 'zhTW', '%s心照不宣地點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 0, 0, 'zhTW', '我們必須趕快，否則就一切都太晚了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 1, 0, 'zhTW', '鹿盔！我們走吧！準備好你的魔法！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 2, 0, 'zhTW', '靠近些……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 3, 0, 'zhTW', '時間之沙將停止流動，但只有片刻的時間！我現在要召喚屏障。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 4, 0, 'zhTW', '鹿盔，趕快完成施法！我沒法讓節界雕文繼續維持原位了！召喚自然的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 5, 0, 'zhTW', '鹿盔，結……結束了。我們勝利了。雖然我們為此付出了慘痛的代價。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 6, 0, 'zhTW', '還有一件事要解決……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 7, 0, 'zhTW', '在我離開之前，鹿盔，我還要再送一件東西給你。如果有一天，因為某些原因，你必須進入這座被詛咒的堡壘，就在神聖的銅鑼上使用流沙節杖。屏障上的魔法將被驅散，而安其拉的恐怖氣息也將再次傳遍世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 8, 0, 'zhTW', '鹿盔，你要去哪兒？為了自尊和高傲，你就要切斷我們的聯絡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 9, 0, 'zhTW', '凡人，現在你已經知道一切了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 10, 0, 'zhTW', '%s將流沙節杖交給了範達爾·鹿盔。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 11, 0, 'zhTW', '%s失望地搖著頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15381 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15381, 12, 0, 'zhTW', '%s蹲下身去撿起被摔碎的節杖碎片。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 0, 0, 'zhTW', '我的軍隊不足以抵抗安其拉的部隊。我們無法走到足夠近的地方，啟動你那寶貴的魔法屏障。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 1, 0, 'zhTW', '完成了。你來帶路吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 2, 0, 'zhTW', '遠古的神靈，指引我……從沉睡中甦醒吧！醒來，封印這片被詛咒的地方！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 3, 0, 'zhTW', '在我的人民目睹並經歷了那場暴行之後，你還指望我能挑起這個沉重的負擔？很明顯，你瘋了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 4, 0, 'zhTW', '我不想再跟希利蘇斯、其拉蟲人和該死的龍類有任何關係了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 5, 0, 'zhTW', '虛假的勝利無法告慰我兒子的靈魂。我會把他找回來的。儘管這或許需要數千年，但是我會把他找回的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 6, 0, 'zhTW', '%s雙腿一軟，筋疲力盡地跪倒在地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15382 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15382, 7, 0, 'zhTW', '%s將流沙節杖扔向魔法屏障，節杖頓時碎裂開來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15387 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15387, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15402 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15402, 0, 0, 'zhTW', '這麼……黑暗的……能量！這怎麼可能？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15420 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15420, 0, 0, 'zhTW', '好吧。讓我們看看你說的是什麼，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15420 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15420, 1, 0, 'zhTW', '這是什麼詭計，$r？如果你想要偷襲我的話，就來試試看吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15420 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15420, 2, 0, 'zhTW', '你的這些奧術聖殿真的……很有意思，凱丹尼斯先生。我對你今天給予我的資訊表示感激。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15471 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15471, 0, 0, 'zhTW', '它們來了。儘量別被它們幹掉，新兵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15471 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15471, 1, 0, 'zhTW', '拉賈克斯，還記得我說過要殺光其它蟲子之後再幹掉你麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15481 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15481, 0, 0, 'zhTW', '我遺憾的向你說再見了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 0, 0, 'zhTW', '可憐的凡人……你都不知道自己在幹什麼！主人的願望已經達成。月光林地和瑪法里奧都會被摧毀的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 1, 1, 'zhTW', '%s露出陰險的笑容。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 2, 2, 'zhTW', '小子，你當然沒法跟你的父親相比。要是我高興的話，我會一爪要了你的命。讓怒風來挑戰我，你就趁早躲到一邊去吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 3, 3, 'zhTW', '救贖？大膽！只有我的神能救贖我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 4 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 4, 4, 'zhTW', '%s瘋狂地咆哮起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 5 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 5, 5, 'zhTW', '出來吧，夢魘的僕從們！摧毀這世界！不留活口……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 6 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 6, 6, 'zhTW', '你們的救世主在哪兒？面對我的攻擊，你還能支撐多久？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 7 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 7, 7, 'zhTW', '雷姆洛斯，我不費吹灰之力就能了結他們。住手吧，愚蠢的傢伙。把這個德魯伊交給我來對付，我會很快結束戰鬥的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 8 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 8, 8, 'zhTW', '打敗了我的手下？來跟我打打看吧，凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 9 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 9, 9, 'zhTW', '燃燒起來了！疼痛……灼熱……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 10 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 10, 10, 'zhTW', '為什麼？為什麼……會發生這種事？泰蘭妲，你在哪兒？當我在月神面前倒下時，你在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 11 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 11, 11, 'zhTW', '我……我感到……我再次感受到月神的觸控……她在對我微笑……是的……我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15491 AND `GroupID` = 12 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15491, 12, 12, 'zhTW', '%s跪倒在地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15509 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15509, 0, 0, 'zhTW', '%s變得極為狂暴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15509 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15509, 1, 0, 'zhTW', '%s變得狂暴不已！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15516 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
