INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15552, 0, 0, 'zhTW', '不跟你的老朋友打個招呼嗎，納裡安。你在等誰呢？');
