INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15552, 2, 0, 'zhTW', '所以……你以為你能愚弄我？艾澤拉斯最偉大的犯罪大師？');
