DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 0, 0, 'zhTW', '時機成熟了！古爾丹，命令你的術士們加倍努力！用不了多久，傳送門就會開啟，你的部落將在這個富饒而毫無防備的世界中所向披靡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 1, 0, 'zhTW', '古爾丹說得不錯！我們應該一起回去把這個訊息告訴我們的弟兄們！從黑暗之門撤退！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 2, 0, 'zhTW', '勇士們！我的護盾正在減弱！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 3, 0, 'zhTW', '我的能量必須集中在傳送門上！我沒有時間來增強護盾了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 4, 0, 'zhTW', '護盾快要消失了！我的一切努力隨時都有可能付之東流！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 5, 0, 'zhTW', '不！我詛咒這具脆弱的軀體！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 6, 0, 'zhTW', '感謝你們的幫助，勇士們。古爾丹的部落將會像蝗蟲一樣席捲這個世界，我精心準備的計劃也總算沒有白費。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15608 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15608, 7, 0, 'zhTW', '部落的獸人們！這個入口將是通向全新命運的道路！艾澤拉斯就在你的面前，等待著你們去佔領。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15625 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15625, 0, 0, 'zhTW', '來吧，$n。看看夢魘給你帶來了什麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15625 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15625, 1, 0, 'zhTW', '夢魘是不可抵擋的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15625 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15625, 2, 0, 'zhTW', '%s奪走$n的最後一絲氣息，吞噬了他們的靈魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15628 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15628, 0, 0, 'zhTW', '我已經迷失很久了……夢魘令我完全墮落……現在……你們……你們拯救了我。是你們將我從夢魘的魔爪下解放出來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15628 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15628, 1, 1, 'zhTW', '但是……瑪法里奧、塞納留斯、伊瑟拉……他們還在堅持。他們需要我。我必須馬上返回翡翠夢境。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15628 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15628, 2, 2, 'zhTW', '我的女王，我不值得你親自祈禱。你是光明的天使，希望的化身。請讓我返回那個古老的洞穴，這樣或許我就可以回到翡翠夢境。跟瑪法里奧一樣，我也有心愛的她……她在等著我……我必須回到她身邊……保護她……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15628 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15628, 3, 3, 'zhTW', '英雄……我有你要找的東西。願它能再次為淨化邪惡的力量而效勞。雷姆洛斯，請確保我們的勇士得到綠龍軍團保管的碎片。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15629 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15629, 0, 0, 'zhTW', '%s品嚐著亡者的痛苦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15633 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15633, 0, 0, 'zhTW', '伊蘭尼庫斯，尋求赦免吧。一切都會得到寬恕的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15633 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15633, 1, 1, 'zhTW', '伊蘭尼庫斯，你的罪行會被赦免的。艾露恩永遠愛著你。掙脫禁錮著你的束縛吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15633 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15633, 2, 2, 'zhTW', '上古之神的束縛沒有絲毫減弱的跡象。他完全被他們黑暗的思想所控制……我……我不能……不能引導……幫幫我，艾露恩……');
