INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15956, 1, 2, 'zhTW', '去哪裡？做什麼？太多的選擇，可這一切都會在痛苦與死亡中終結。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15956 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15956, 1, 3, 'zhTW', '我該先吃誰呢？真是難以選擇。每一個聞起來都這麼鮮美……');
