DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 0, 0, 'zhTW', '大軍幾乎已經整裝待發，隨時可以從後方突襲敵人，陛下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 1, 0, 'zhTW', '如此真誠地為服侍我是一件好事。不久，所有人都會為服侍巫妖王，最後，只要你不步履蹣跚，你就會得到回報。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 2, 0, 'zhTW', '是的，主人，他們的最終末日馬上即將降臨了……這是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 3, 0, 'zhTW', '你的安全措施已失效，看著他直接終止吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 4, 0, 'zhTW', '如您所願，主人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 5, 0, 'zhTW', '不！！！詛咒你，入侵者，詛咒你！巫妖王的軍團一定會殺死你的。你逃避不了必然的命運……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 6, 0, 'zhTW', '誰敢侵犯聖所的神聖？所有入侵這裡的人都註定要被警告。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 6, 1, 'zhTW', '蠢貨！你們以為勝券在握了嗎？你們只不過是離地獄更近了一步而已。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 6 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 6, 2, 'zhTW', '這場遊戲已經讓我覺得無聊了。繼續吧，到我這裡來，我會親自毀滅你們的靈魂！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 6 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (15990, 6, 3, 'zhTW', '看來你們還不知道自己將面臨怎樣的恐怖？看來你們根本一無所知！納克薩瑪斯的霜寒之心正等待著你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 15990 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
