INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16128, 3, 0, 'zhTW', '我們勇敢的夥伴們深入泰坦之城奧杜爾，擊敗了觀察者奧爾加隆，泰坦派來的使者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16128 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16128, 4, 0, 'zhTW', '奧爾加隆前來決定我們這個世界的命運。');
