INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16128, 5, 0, 'zhTW', '他發現，在這個世界中，人們並不接受泰坦設計的藍圖。在這個世界中，並非一切都按照計劃完美執行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16128 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16128, 6, 0, 'zhTW', '冷酷的邏輯推論出：我們的世界不值得拯救。但是，它並沒有考慮到自由意志的力量。我們每一個人都有責任證明，這是一個值得拯救的世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16128 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16128, 7, 0, 'zhTW', '因為我們的生命……是值得延續的生命。');
