INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 3, 0, 'zhTW', '沒錯，我的兒子非常強大……但我也有自己的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16524 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 3, 1, 'zhTW', '我不是某個可笑的小丑，我是聶拉斯·埃蘭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16524 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 4, 0, 'zhTW', '你們應該不會不讓一個可憐的老人喝點東西吧？不，不，當然不會。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16524 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 5, 0, 'zhTW', '還沒完！我還有幾招沒有用呢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16524 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 6, 0, 'zhTW', '我要結束這場噩夢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16524 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 6, 1, 'zhTW', '不要再煩我了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16524 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16524, 7, 0, 'zhTW', '你們浪費了我太多的時間……讓這場遊戲結束吧！');
