INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16544, 0, 0, 'zhTW', '回頭吧，在你還有機會回頭的時候……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16544 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16544, 0, 1, 'zhTW', '圖書館的秘密是我們的，是我們自己的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16544 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16544, 0, 2, 'zhTW', '這個地方的秘密不是你這種人可以接觸的！');
