DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16544 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16544, 1, 2, 'zhTW', '不是我們的成員，就休想踏足這座塔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16544 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
