DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16550 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16550, 0, 0, 'zhTW', '七塊阿塔瑪水晶在上！發現其他倖存者了！沙娜安，是你嗎？真高興可以再次看到你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16550 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16550, 1, 0, 'zhTW', '情況怎麼樣？毫無疑問……嗞嗞……這通訊裝置行不行啊？我代表……嗞嗞……碧藍崗哨……問好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16550 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16550, 2, 0, 'zhTW', '根據訊號來源，我們判斷你是在……飛船墜毀點的東南方。穿過晶水河……嗞嗞嗞嗞。抱歉，干擾實在太大了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16577 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16577, 0, 0, 'zhTW', '兄弟姐妹們，我曾去過理想中的樂土。我感受過令人心生敬畏的強大力量。那種被賜福的感覺緊緊環繞，我竟然產生了步入神靈夢境的錯覺。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16577 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16577, 1, 0, 'zhTW', '置身天堂時，你會感覺自己被來回牽扯著，在虛空間飄蕩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16577 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16577, 2, 0, 'zhTW', '看！原始的魔法能量從大地裂痕中噴湧而出，奧術能量的藤蔓照亮了漆黑的天空。跪下從這些裂縫中汲取魔法能量，就像從溪流或是水井中飲水那樣。採集來自天堂的藤蔓，就像從樹上採摘蘋果那樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16578 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16578, 0, 0, 'zhTW', '瑪提克，快說下去。那是什麼？感覺怎麼樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16578 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16578, 1, 0, 'zhTW', '但是怎麼樣才能……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16578 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16578, 2, 0, 'zhTW', '%s劇烈地喘息起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16584 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16584, 0, 0, 'zhTW', '扎著馬尾巴辮的地精小姑娘工作起來都比你們這些苦工努力！！給我快一點！快一點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16585 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16585, 0, 0, 'zhTW', '你們的食物好了。過來拿吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16585 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16585, 1, 0, 'zhTW', '要是我再聽說你們這些差勁的傢伙向納茲格雷爾抱怨的話，那麼下次我就會用你們中的一個來做菜……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16587 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16587, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 0, 0, 'zhTW', '那時，我和其他士兵就在榮耀之路上巡邏，這是我們日常的職責之一。我們派了偵察兵去前面察看情況，以防發生任何危險狀況。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 1, 0, 'zhTW', '果然，偵察兵急匆匆地跑了回來，說榮耀之路的另一端有一些獸人出沒。他們尚未發現我們，因此我們決定立即將這一訊息通傳到榮耀堡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 2, 0, 'zhTW', '巨大的紅色混蛋！比我看到過的任何獸人都要大。肌肉有這麼大，獠牙一直到這兒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 3, 0, 'zhTW', '%s點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 4, 0, 'zhTW', '邪獸人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 5, 0, 'zhTW', '我不知道，士兵。我——不——知道……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 6, 0, 'zhTW', '但那還不是最糟糕的。我們還沒來得及撤退，他們就發現了我們，並且發起了進攻。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16589 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16589, 7, 0, 'zhTW', '那天我失去了許多最棒的士兵……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16590 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16590, 0, 0, 'zhTW', '要不是我的胃在咕咕叫，我才不會碰這些給犯人吃的……食物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16590 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16590, 0, 1, 'zhTW', '我是不是嚐到了肉桂？還是肉豆蔻？不管是什麼，有一件事是肯定的——沒有人會像你那樣烹驢肉的，曲奇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16590 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16590, 1, 0, 'zhTW', '什麼樣的獸人？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16590 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16590, 2, 0, 'zhTW', '你指的是……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16590 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16590, 3, 0, 'zhTW', '但是怎麼會這樣，頭兒？詛咒不是已經被消除了嗎……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16593 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16593, 1, 0, 'zhTW', '為了卡加斯！為了勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16593 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16593, 1, 1, 'zhTW', 'Gakarah ma！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16593 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16593, 1, 2, 'zhTW', 'Lok\'narash！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16593 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
