INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16808, 3, 0, 'zhTW', '聯盟竟敢深入我的堡壘？把榮耀堡的戰俘帶出來，讓劊子手們待命！他們會為這次入侵付出生命的代價！');
