INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16808, 4, 0, 'zhTW', '索爾的那個冒牌部落膽敢深入我的堡壘？把索爾瑪的戰俘帶出來，讓劊子手們待命！他們會為這次入侵付出生命的代價！');
