DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 0, 0, 'zhTW', '女士們，先生們，歡迎觀看今晚的演出！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 1, 0, 'zhTW', '今晚，我們將見證人類靈魂深處的信念。一位迷失的小女孩，在忠誠的夥伴們的幫助下尋找回家的路！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 2, 0, 'zhTW', '但是……一個邪惡的老巫婆正在追趕著她！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 3, 0, 'zhTW', '她能逃脫魔掌嗎？她能平安回家嗎？只有時間才能回答這些問題。現在——演出開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 4, 0, 'zhTW', '女士們，先生們，晚上好！歡迎觀看今晚的演出！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 5, 0, 'zhTW', '今晚，一切都變得虛虛實實，真偽難辨；今晚，你們的眼睛將欺騙你們的心靈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 6, 0, 'zhTW', '比如說，這位老奶奶正在等待她的孫女……顯然，頭髮斑白的慈祥老奶奶沒有什麼威脅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 7, 0, 'zhTW', '但是我不能說得太多！你們必須自己看清隱藏在偽裝下面的真相！現在——演出開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 8, 0, 'zhTW', '女士們，先生們，歡迎觀看今晚的演出！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 9, 0, 'zhTW', '今晚，我們將看到一段受到百般阻撓的愛情！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 10, 0, 'zhTW', '但是，大家知道，並非所有的愛情故事都有完滿的結局。有些時候，愛情就像荊棘一樣危險！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16812 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16812, 11, 0, 'zhTW', '耳聞為虛眼見為實，當兩個彼此相愛的人在今晚見面時，又將會上演什麼樣的悲劇？大家拭目以待吧！現在——演出開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16819 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16819, 0, 0, 'zhTW', '歡迎來到榮耀堡，$n。你能來真是太好了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16819 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16819, 1, 0, 'zhTW', '墮落與腐化的盛宴已經不復存在了！瑪瑟裡頓在$n和$g他:她的夥伴們面前倒下了！它的滅亡見證了聯盟力量的偉大！一個深淵領主被消滅了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16819 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16819, 2, 0, 'zhTW', '兄弟們，姐妹們！敵人的末日降臨了！我們必須打擊剩餘的邪獸人！把他們像蟲子那樣消滅掉！在洛薩之子的庇護下繼續戰鬥吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16822 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16822, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16846 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16846, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16847 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16847, 0, 0, 'zhTW', '我的……力量……正在恢復！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16847 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16847, 0, 1, 'zhTW', '你治癒了我！讓我們的敵人嚐嚐失敗的滋味吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16847 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16847, 0, 2, 'zhTW', '你幫我恢復了健康！我欠你個人情，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16871 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16871, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16876 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16876, 0, 0, 'zhTW', '%s變得不穩定起來，並開始瓦解！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16878 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16878, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16880 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16880, 0, 0, 'zhTW', '%s開始慢慢變壯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16916 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16916, 0, 0, 'zhTW', '可憐可憐我吧！我必須馬上吃點東西……一塊魔力水晶……一塊碎片……任何東西都行！我實在無法忍受這種痛苦了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16924 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16924, 0, 0, 'zhTW', '告訴我們！你們的首領躲在哪裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16924 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16924, 1, 0, 'zhTW', '不開口就別想得到任何東西，你這渣滓！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16938 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16938, 0, 0, 'zhTW', '結束我的痛苦吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16938 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16938, 0, 1, 'zhTW', '原諒我……我別無選擇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16943 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16943, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16964 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16964, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 0, 'zhTW', '%s嗚咽著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 1, 'zhTW', '%s憤怒地握緊了拳頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 2, 'zhTW', '我們不能再離開房子了！戰鬥不會停止的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 3, 'zhTW', '山上的墓地填滿的速度比我們挖的都快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 4, 'zhTW', '我們還能回家嗎');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 5, 'zhTW', '我今天埋葬了我的兒子，塔爾沃斯……上週埋葬了我的妻子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 6, 'zhTW', '他們說下一次攻擊很快就來了，沒人能倖免。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 7, 'zhTW', '耐奧祖永不放棄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 8, 'zhTW', '托爾貝爾一人無法阻止獸人的聯合軍團，我們完了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16976 AND `GroupID` = 0 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16976, 0, 9, 'zhTW', '我們需要答案，中尉！我們有權知道真相。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16978 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16978, 0, 0, 'zhTW', '大家都冷靜下來！我們正在盡力控制局勢。獸人是無情的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16980 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16980, 0, 0, 'zhTW', '入侵者闖入了內室。加緊毀掉那條綠龍！留下龍筋龍骨用來複生！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16980 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16980, 1, 0, 'zhTW', '聯盟和部落很快就將被我們瓦解，之後，艾澤拉斯大陸也必然被天災大軍征服。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16992 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16992, 0, 0, 'zhTW', '%s變得強壯了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16993 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16993, 0, 0, 'zhTW', '謝謝你願意伸出援手，現在讓我們離開這裡，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16993 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16993, 1, 0, 'zhTW', '看！他們在跟蹤我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16993 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16993, 2, 0, 'zhTW', '請讓我休息一會，我已經非常累了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16993 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16993, 3, 0, 'zhTW', '你聽見什麼了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16993 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16993, 4, 0, 'zhTW', '終於到了獵鷹崗哨！現在，我的……？天哪！我的揹包找不到了！這可怎麼辦……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 16993 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (16993, 5, 0, 'zhTW', '你休想阻止我到達獵鷹崗哨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17007 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17007, 0, 0, 'zhTW', '我必須馬上見到主人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17007 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17007, 0, 1, 'zhTW', '主人在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17007 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17007, 0, 2, 'zhTW', '主人去哪兒了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17007 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17007, 0, 3, 'zhTW', '我們為什麼不能和主人對話？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17008 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17008, 0, 0, 'zhTW', '安靜！大地的崩潰很快就要來臨了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17008 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17008, 1, 0, 'zhTW', '親眼看看黑暗主宰那勢不可擋的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17008 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17008, 2, 0, 'zhTW', '有了他所賜予的力量，我會夷平這片土地，並重新鑄造它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17008 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17008, 3, 0, 'zhTW', '看！大地在我們面前破碎了！看那些流動的能量！它會讓我們的軍隊更加強大……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17008 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17008, 4, 0, 'zhTW', '我們再也不會缺乏足夠的力量了！我拯救了我們的未來！享受我的榮耀吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17008 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17008, 5, 0, 'zhTW', '結……束……了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17023 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17023, 0, 0, 'zhTW', '古爾丹說得不錯！我們應該一起回去把這個訊息告訴我們的弟兄們！從黑暗之門撤退！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 0, 0, 'zhTW', '不要停下來！如果你敢有哪怕一秒鐘放下鋤頭的念頭，我保證會讓你明白什麼叫死去活來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 0, 1, 'zhTW', '挖快點，可憐蟲！不要逼我對你下狠手！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 0, 2, 'zhTW', '再快點，蠢貨！如果我們找不到主人想要的阿塔瑪水晶，他不會高興的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 1, 0, 'zhTW', '你膽敢妨礙主人的計劃？你會付出代價的，愚蠢的凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 1, 1, 'zhTW', '消滅這些入侵者，骯髒的殘冠氏族！如果你們不服從我的命令，我會讓你們嚐到無盡的痛苦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 1, 2, 'zhTW', '去吧，你們這些可憐蟲！讓那些蠢貨們知道藐視主人的下場！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17058 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17058, 1, 3, 'zhTW', '不要妄想逃跑，可憐的破碎者！不消滅這些入侵者，我就讓你們生不如死！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17071 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17071, 0, 0, 'zhTW', '這真是個好訊息！你的努力拯救了我們，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 0, 'zhTW', '<哭泣> 我討厭墓地。太多人死去了。還有我親愛的魯哈娜……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 1, 'zhTW', '為什麼活下來的是我而不是你？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 2, 'zhTW', '安息吧，我的愛，我的心，我的魯哈娜。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 3, 'zhTW', '我永遠都不會忘記你，我的愛人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 4, 'zhTW', '如果讓我找到導致墜毀的元兇……！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 5, 'zhTW', '我們永遠都不會分開。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 6, 'zhTW', '為什麼，魯哈娜？為什麼？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 7, 'zhTW', '我非常想念你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 8, 'zhTW', '你會一直在我身邊的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 9, 'zhTW', '%s輕聲地哭泣著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 10, 'zhTW', '%s低下了頭嘆了口氣，非常疲倦的樣子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 11, 'zhTW', '%s悲痛地放聲大哭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17073 AND `GroupID` = 0 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17073, 0, 12, 'zhTW', '%s默默地凝視著他面前的墓碑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17077 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17077, 0, 0, 'zhTW', '%s抬起頭，似乎在聽著什麼東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17077 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17077, 1, 0, 'zhTW', '%s發出的嚎叫在北邊的山脈中迴響，提醒你跟著它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17085 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17085, 0, 0, 'zhTW', '亞維魯的魔法……仍然控制著我。你必須與我戰鬥，凡人。這是唯一可以解除那個魔法的辦法！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17085 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17085, 1, 0, 'zhTW', '亞維魯的魔法失效了！我又自由了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17086 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17086, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17117 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17117, 0, 0, 'zhTW', '%s呻吟著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17117 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17117, 1, 0, 'zhTW', '%s坐了起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17117 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17117, 2, 0, 'zhTW', '我……我在哪裡？這……這是什麼地方？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17117 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17117, 3, 0, 'zhTW', '以艾露恩之光的名義！艾瑞達人！你們這群被詛咒的惡魔，你們對我做了什麼？我並不是獨身一人，我們會像以前那樣和你們戰鬥到底！我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17117 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17117, 4, 0, 'zhTW', '%s昏了過去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17119 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17119, 0, 0, 'zhTW', '我想我可以自己回蕨牆村。他們把貨物放在了塔頂，多加小心！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17123 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17123, 0, 0, 'zhTW', '你好，$n。是什麼風把你吹到這裡來的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17156 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17156, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17188 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17188, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17214 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17214, 0, 0, 'zhTW', '現在把藥膏塗在她的傷口上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17214 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17214, 1, 0, 'zhTW', '看上去這藥膏沒有起作用。真遺憾……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17214 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17214, 2, 0, 'zhTW', '腐蝕者……但是……我們不是艾瑞達人！她必須明白這一點！如果還有其他類似她的生物，我們必須找到他們，給他們解釋……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17215 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17215, 0, 0, 'zhTW', '可能還有個解決辦法，到這邊來，$n。我會向你解釋我需要什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17215 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17215, 1, 0, 'zhTW', '這個應該有作用……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17215 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17215, 2, 0, 'zhTW', '醒來吧，小傢伙。從睡眠中醒來吧……你現在安全了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17225 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17225, 0, 0, 'zhTW', '一個遠古的生物在遠處被喚醒了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17225 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17225, 1, 0, 'zhTW', '愚蠢的傢伙！我會很快終結你們的痛苦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17225 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17225, 2, 0, 'zhTW', '可憐的渣滓。我要騰空而起，讓你嚐嚐毀滅的滋味！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17225 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17225, 3, 0, 'zhTW', '夠了！我要落下來把你們打得粉碎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17225 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17225, 3, 1, 'zhTW', '沒用的蟲子！讓你們見識一下我的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17225 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17225, 4, 0, 'zhTW', '%s深深地吸了一口氣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17226 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17226, 0, 0, 'zhTW', '好，我們走吧。我知道有個完美的地點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17226 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17226, 1, 0, 'zhTW', '我迫不及待地想嚐嚐這瓶酒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17226 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17226, 2, 0, 'zhTW', '發生……了……什麼事？把這隻貓從我身邊拿開！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17226 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17226, 3, 0, 'zhTW', '薇拉·火語飛快地竄開，努力從咪咪那裡逃走。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17230 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17230, 0, 0, 'zhTW', '咪咪用飢餓的眼神看著薇拉·火語。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17233 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17233, 0, 0, 'zhTW', '感謝你專程來紀念我。你找回了這個印記——雖然它並沒有什麼實際的意義，但是仍然讓我心裡感到很溫暖。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17233 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17233, 1, 0, 'zhTW', '請起身吧，我的朋友。拿著這份祝福，它是聖光力量的象徵，也可以時刻提醒我們，那些逝去的英雄其實一直活在我們的心中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17233 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17233, 2, 0, 'zhTW', '謝謝你，朋友。這一天我永遠都不會忘懷！我想在這裡待一會兒。請回到營地去找高階牧師瑪多妮爾，她一定對我們剛才遇到的事情很感興趣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17233 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17233, 3, 0, 'zhTW', '我只希望他能看到聖光，用他的力量來恢復曾經美麗的奎爾薩拉斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17238 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17238, 0, 0, 'zhTW', '可以開始了嗎，我的朋友？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17238 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17238, 1, 0, 'zhTW', '這個區域到處都是天災軍團的爪牙，你最好準備一下，免得手忙腳亂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17238 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17238, 2, 0, 'zhTW', '小心！我們受到攻擊了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17240 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17240, 0, 0, 'zhTW', '嘿，曲奇！今天晚餐咱們吃了什麼？不要告訴我是雞肉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17240 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17240, 1, 0, 'zhTW', '是不是啊？這麼棒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17240 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17240, 2, 0, 'zhTW', '我恨你，曲奇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17241 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17241, 0, 0, 'zhTW', '阿達曼特，你能看下這塊石板，順便試著翻譯一下上面的符文嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17241 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17241, 1, 0, 'zhTW', '謝謝你，阿達曼特。我想我知道誰最適合這項工作。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 0, 0, 'zhTW', '當然！沒問題，親愛的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 1, 0, 'zhTW', '嗯，讓我看看那塊石板。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 2, 0, 'zhTW', '%s慢慢地讀著石板，用他們的母語讀著那些文字。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 3, 0, 'zhTW', '天哪……納迦督軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 4, 0, 'zhTW', '嗯，你不會喜歡這個訊息的，小姑娘。這塊石板是納迦的交流工具。他們的首領督軍斯雷提茲命令他的納迦們用武力來搶奪這塊島嶼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 5, 0, 'zhTW', '看上去他得到了納沙塔爾的增援！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17242 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17242, 6, 0, 'zhTW', '我們必須得乾點什麼了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 0, 0, 'zhTW', '是的，主人。一切都在按照計劃進行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 1, 0, 'zhTW', '%s把貝殼舉起來放在耳邊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 2, 0, 'zhTW', '去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 3, 0, 'zhTW', '怎麼回事？你幾乎破壞了我的偽裝，白痴！我告訴你把羅盤和航海地圖放在一個安全的地方，而不是放在一個給任何傻瓜都可以發現的地方。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 4, 0, 'zhTW', '主人不遺餘力地探查有關艾克索達所在之處的資訊。你可能會破壞整個行動，包括我們在艾克索達安插的間諜！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 5, 0, 'zhTW', '放鬆點？你知道凱爾薩斯會對那些讓他失望的傢伙做些什麼嗎，吉茲爾？無盡的痛苦……不要把這事情搞砸了，白痴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 6, 0, 'zhTW', '我們的秘血島斥候已經定位到了我們的聯絡人。那個笨蛋維倫很快就會處於毫無防備的狀態，讓我們有充足的時間發動進攻！現在，在我把你蒸發掉之前離開我的視線……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17243 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17243, 7, 0, 'zhTW', '%s拾起納迦的旗幟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17246 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17246, 0, 0, 'zhTW', '呀，將軍。讓我考慮一下……啊……有了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17246 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17246, 1, 0, 'zhTW', '我計劃給大家烹製澆著美味肉汁、還有一點點杉德爾船長特製配方的鮮嫩多汁的烤豬排。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17246 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17246, 2, 0, 'zhTW', '而且我們有從暴風城空運過來的乳酪蛋糕作為餐後甜品。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17246 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17246, 3, 0, 'zhTW', '是不是啊？這麼棒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17246 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17246, 4, 0, 'zhTW', '還是雞肉……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17257 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17257, 0, 0, 'zhTW', '可悲的螻蟻，放了我！也許我可以讓你死得痛快點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17257 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17257, 0, 1, 'zhTW', '寄生蟲！吸血鬼！痛飲我的鮮血吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 17257 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17257, 0, 2, 'zhTW', '伊利丹是個傲慢的蠢貨。我要毀滅他重新統治外域。');
