INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17534, 3, 0, 'zhTW', '啊，好刀子！這就是你的鞘子；你刺了進去，讓我死了吧！');
