INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (17535, 3, 0, 'zhTW', '啊，託託，我們必須找到回家的路！那位老巫師是我們唯一的希望了！稻草人、獅子，還有鐵皮人，你們能不能——呀，有人來了！');
