INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18063, 5, 0, 'zhTW', '我恨他的所作所為。我恨他，因為他把負擔都留給了我。但是現在……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18063 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18063, 6, 0, 'zhTW', '你讓我看到了我可能永遠都不會知道的真相。你和你的朋友們給我帶來了無價的禮物：救贖。索爾，瑪格漢的救世主，你讓我感到了前所未有的榮耀……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18063 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18063, 7, 0, 'zhTW', '在今天，我心中的重擔終於可以放下了。我的內心充滿著自豪。我有生以來第一次可以驕傲地說出我的名字，終於可以釋放我心中的憤怒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18063 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18063, 8, 0, 'zhTW', '我是加爾魯什·地獄咆哮，格羅姆之子，瑪格漢的酋長！讓地獄咆哮的戰鬥怒吼給予你們勇氣和力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18063 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18063, 9, 0, 'zhTW', '謝謝你，杜隆坦之子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 1, 0, 'zhTW', '真沒勁！穆戈爾更厲害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 2, 0, 'zhTW', '穆戈爾沒有印象！瑟克拉加斯是由空氣和暗影組成的！像被壓扁的獸人一樣軟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 3, 0, 'zhTW', '現在你將面對真正的冠軍！我會給你一個逃跑的機會，小傢伙。在穆戈爾把你殺死之前逃跑吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 4, 0, 'zhTW', '沒有機會了！現在你要付出代價了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 5, 0, 'zhTW', '我發怒了！你把穆戈爾打疼了！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18069 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18069, 6, 0, 'zhTW', '什麼！？不可能！！你要和穆戈爾戰鬥了！穆戈爾殺啊！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18075 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18075, 0, 0, 'zhTW', '%s笑了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18075 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18075, 1, 0, 'zhTW', '在我意料之中。我知道你會來這裡，而且我看到你把強大的地獄咆哮也帶來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18075 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18075, 2, 0, 'zhTW', '他的血是我的，你們整個卑賤的種族都是我的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18075 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18075, 3, 0, 'zhTW', '勇敢的嘗試，但是毫無意義。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18075 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18075, 4, 0, 'zhTW', '%s笑了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18075 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18075, 5, 0, 'zhTW', '這個孩子相信他能夠挽救你，但他不知道是什麼在你的靈魂中燃燒。你心裡很清楚，你我都是一樣的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18076 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18076, 0, 0, 'zhTW', '不！不！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18076 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18076, 1, 0, 'zhTW', '索爾……血液的詛咒已經消失。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18076 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18076, 2, 0, 'zhTW', '由於血之詛咒被消除，格羅姆的眼睛變得暗淡了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18076 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18076, 3, 0, 'zhTW', '惡魔的火焰不再灼燒著我的軀體。我……解放了自己。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18094 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18094, 0, 0, 'zhTW', '我想我看到了有人進入了穀倉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18094 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18094, 1, 0, 'zhTW', '有東西激怒了那匹馬，讓我們去看看！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18094 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18094, 2, 0, 'zhTW', '索爾被困在了教堂裡，他現在逃不掉了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18094 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18094, 3, 0, 'zhTW', '他在這兒，阻止他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 0, 0, 'zhTW', '索爾！出來面對你的命運吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 1, 0, 'zhTW', '夠了。我要把你們全部消滅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 2, 0, 'zhTW', '你……不存在了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 3, 0, 'zhTW', '別高興得太早！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 3, 1, 'zhTW', '盡力掙扎吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 4, 0, 'zhTW', '不！主人……不會……高興的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 4, 1, 'zhTW', '索爾仍將是個奴隸。塔蕾莎會死去。你失敗了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 5, 0, 'zhTW', '別高興得太早！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 5, 1, 'zhTW', '盡力掙扎吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18096 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18096, 6, 0, 'zhTW', '不！主人……不會……高興的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18098 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18098, 0, 0, 'zhTW', '%s仔細地讀著通緝佈告。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18103 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18103, 0, 0, 'zhTW', '遵守銀月城的法律。違法者將被消滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18103 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18103, 0, 1, 'zhTW', '維護銀月城的秩序。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18103 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18103, 0, 2, 'zhTW', '快樂源於秩序，公民。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18103 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18103, 0, 3, 'zhTW', '要堅強起來。凱爾薩斯——錯誤——洛瑟瑪會指引你們走向力量和光明！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18103 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18103, 0, 4, 'zhTW', '不要破壞城市的寧靜。必須維護和平。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18105 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18105, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18117 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18117, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18119 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18119, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 0, 0, 'zhTW', '我等你好久了，孩子。靠近一點，我的眼睛已經不像以前那麼好使了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 1, 0, 'zhTW', '是的，你的一舉一動就像我的兒子那樣。你有著他那寬厚的肩膀——啊，還有你母親那犀利的目光。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 2, 0, 'zhTW', '不用懷疑，你是杜隆坦的後代……我的孫子。德拉卡在和你父親離開我們的世界前告訴我她有了孩子，但是我從沒有想到他們可以生存下來……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 3, 0, 'zhTW', '索爾？你只是過去是一個奴隸，孫子！你再也不會是奴隸了！當我最後一次看到杜隆坦的時候，他把還沒出生的兒子的名字都想好了……他是……那麼的自豪……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 4, 0, 'zhTW', '%s擦去了眼淚。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 5, 0, 'zhTW', '古伊爾。你是古伊爾，杜隆坦之子——真正的霜狼氏族的酋長。今天，我的孫兒——你是我心中最大的歡樂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 6, 0, 'zhTW', '我看到你拿著毀滅之錘。我們偉大的英雄們都倒下了嗎，孫子？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 7, 0, 'zhTW', '格羅瑪什怎麼了？地獄咆哮怎麼了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 8, 0, 'zhTW', '天哪！二十年以來，我們只知道是格羅姆第一個喝下詛咒之杯內的東西，把詛咒帶給了我們的人民……那是他兒子加爾魯什唯一知道的事實。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18141 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18141, 9, 0, 'zhTW', '孫子，你會……你會把你所告訴我的關於他父親的一切都告訴加爾魯什嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18146 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18146, 0, 0, 'zhTW', '%s略微地歪了下頭，向衛兵表示問候。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18146 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18146, 1, 0, 'zhTW', '%s朝衛兵們生硬地鞠了一躬，他板著臉，心中十分不情願。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18146 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18146, 2, 0, 'zhTW', '%s的目光掃過一個個衛兵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18146 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18146, 3, 0, 'zhTW', '%s俯視著那窄小的遊俠練習場，作出一副謙遜的笑容。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18166 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18166, 0, 0, 'zhTW', '不要用太多問題來麻煩阿達爾，$r。這個生物的意志是讓我們的城市遠離傷害的關鍵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18166 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18166, 1, 0, 'zhTW', '帶我們的客人去撒塔斯城裡走走吧？路過貧民窟的時候小心你的錢包。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18168 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18168, 0, 0, 'zhTW', '我為你們感到可悲，小傢伙們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18168 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18168, 0, 1, 'zhTW', '很快就會結束了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18168 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18168, 1, 0, 'zhTW', '怎麼可能？啊，這真是個殘酷的世界……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18168 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18168, 2, 0, 'zhTW', '搞定你了，對不對？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18202 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18202, 0, 0, 'zhTW', '想跑？沒門！消滅他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18206 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18206, 0, 0, 'zhTW', '何時才能結束這種痛苦啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18206 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18206, 0, 1, 'zhTW', '救救我！請救救我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18206 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18206, 0, 2, 'zhTW', '你怎麼能就這麼把我留在這裡？');
