INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18209, 4, 0, 'zhTW', '前面就是去塔拉的路。我們在前面的岔道分開，他們肯定會派更多人來追擊我們的。希望我們當中有人能活著回到塔拉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18210 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
