INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18210, 3, 0, 'zhTW', '冰霜震擊！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18210 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18210, 4, 0, 'zhTW', '最好我們現在就分開，以免他們派更多人來追擊我們。希望我們之間有人可以成功回到加爾魯什那裡。保重，陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18211 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18211, 0, 0, 'zhTW', '不要讓他們跑了！先殺掉那個強壯的傢伙！');
