INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18230, 0, 2, 'zhTW', '唉唷。他們告訴我這些水晶可以完美運轉！這幫奸商！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18230 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18230, 0, 3, 'zhTW', '要是我抓住你，我會把你的零件都給分解掉，所以你最好……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18230 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18230, 0, 4, 'zhTW', '過來，你這個小……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18230 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18230, 0, 5, 'zhTW', '不要擋著攝政王的路！我說真的！');
