DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18296 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18296, 0, 0, 'zhTW', '哇！看看他的肌肉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18296 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18296, 0, 1, 'zhTW', '我真想變得像鬥士那樣！');
