DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 0, 0, 'zhTW', '我的兄弟姐妹們，聽我說。我們必須開始關注自身的生存了。雖然我們在一場災難中勉強倖存了下來，但是我擔心下一場災難會把我們徹底摧毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 1, 0, 'zhTW', '你們看不到眼前正在發生些什麼事情嗎？睜開你們的眼睛，一切都明明白白展現在你們眼前。我們的新同盟是什麼？為什麼我們背叛了過去的盟友，卻要與所有生命的大敵親密相處？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 2, 0, 'zhTW', '你把她當作朋友？你真是個蠢貨。這個“黑暗女王”不是希爾瓦娜斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 3, 0, 'zhTW', '血？還有這些獸人，這些見風使舵的傢伙？他們會幫我們嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 4, 0, 'zhTW', '魔導師們是叛徒！他們已經註定了我們的毀滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 5, 0, 'zhTW', '我們竭盡全力掙扎奮鬥，為的是求得生存的機會，而不是給自己帶來真正的毀滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 6, 0, 'zhTW', '如果我們作為一個整體來抗爭，就不可能被忽視了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18303 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18303, 7, 0, 'zhTW', '我們會報復聯盟！我們永遠也不會忘記，永遠也不會原諒他們！');
