INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18331, 0, 3, 'zhTW', '你離家太遠了，陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18337 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18337, 0, 0, 'zhTW', '應該沒問題了。如果你還需要我的話，召喚我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18341 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18341, 0, 0, 'zhTW', '我要……吞噬你的靈魂。');
