INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18341, 3, 0, 'zhTW', '%s變成了一個靈體生物……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18344 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18344, 0, 0, 'zhTW', '這是怎麼回事？請原諒，但是我沒有料到會有人來拜訪。正如你們看到的，我們現在有別的事情要忙。不過沒關係，作為一個熱情的主人，我會用自己的方式招待你們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18344 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18344, 1, 0, 'zhTW', '我們還沒有互相作自我介紹呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18344 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18344, 1, 1, 'zhTW', '一場史詩般的戰鬥，多麼激動人心啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18344 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18344, 1, 2, 'zhTW', '我多麼渴望能有一次真正的冒險！');
