INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18401, 0, 0, 'zhTW', '靠近點……再靠近點……看看虛空給我們帶來了什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18402 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18402, 0, 0, 'zhTW', '我要把這個挑戰者撕成碎片！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18405 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18405, 0, 0, 'zhTW', '不希望一切代價保護植物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18407 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18407, 0, 0, 'zhTW', '那些該死的食人魔。他們應該被推到虛空裡。有人能從這些野人手裡拯救我們嗎？這已經是最近第五次綁架了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18407 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18407, 1, 0, 'zhTW', '那已經是我們所能提供的最好的獎勵了。希望有人會接受那個任務。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18417 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18417, 0, 0, 'zhTW', '我不能那麼慷慨地……與你分享資訊。你必須向我證明，你與我有著共同的敵人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18417 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18417, 1, 0, 'zhTW', '這本書將賜予我無盡的力量……我會變得……無堅不摧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18417 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18417, 2, 0, 'zhTW', '不……你必須把這東西從我這裡拿走，$n！我感覺到它的黑暗力量已經開始動搖我的意志了！用它來消滅瓦雷迪斯吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18428 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18428, 0, 0, 'zhTW', '食人魔，去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18428 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18428, 0, 1, 'zhTW', '太感謝你了，英雄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18428 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18428, 0, 2, 'zhTW', '總有一天，一個英雄將會挺身而出，讓獸人重獲昔日的榮耀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18428 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18428, 0, 3, 'zhTW', '靈魂與你同在，$r！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18428 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18428, 0, 4, 'zhTW', '謝謝你，$R！你為瑪格漢所做的一切，我們都將銘記在心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18445 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18445, 0, 0, 'zhTW', '謝謝你！你救了我多少次了？三次？我已經把你當親人看待了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18447 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18447, 0, 0, 'zhTW', '威脅結束了！是$n解救了我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 0, 0, 'zhTW', '進入鮮血競技場吧，$n。戰鬥就要開始了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 1, 0, 'zhTW', '戰鬥即將開始！$n對兇猛的裂蹄牛——斷蹄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 2, 0, 'zhTW', '$n打敗了斷蹄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 3, 0, 'zhTW', '戰鬥馬上開始！無情的暗血雙子對陣$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 4, 0, 'zhTW', '難以置信！$n擊敗了暗血兄弟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 5, 0, 'zhTW', '為從刀鋒山來的裂石之王洛卡達爾歡呼吧！$n正在為$g他的:她的生命而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 6, 0, 'zhTW', '$n又一次勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 7, 0, 'zhTW', '來自未知世界的強者，瑟克拉加斯！$n能否在虛空能量的衝擊下倖存呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 8, 0, 'zhTW', '$n又一次勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 9, 0, 'zhTW', '這是我們最為期待的時刻！戰槌勇士要開始他本週在鮮血競技場的第一場表演了！$n會不會像這位勇士的其他對手那樣被輕鬆打敗呢？我們拭目以待……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 10, 0, 'zhTW', '$n又一次勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 11, 0, 'zhTW', '穆戈爾向你挑戰。你必須同意！進入競技場，準備戰鬥吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18471 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18471, 12, 0, 'zhTW', '$n打敗了戰槌英雄穆戈爾！大家為$N而歡呼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 0, 0, 'zhTW', '我有自己的—呱嘎—寵物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 1, 0, 'zhTW', '嗯……該我行動了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 1, 1, 'zhTW', '不錯的寵物，哈哈……呱呱嘎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 1, 2, 'zhTW', '不錯的寵物，但是有武器就—嘎嘎—不太好了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 2, 0, 'zhTW', '對，生命是短暫的，嘎嘎呱！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 2, 1, 'zhTW', '嗯……你自由了。呱！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18472 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18472, 3, 0, 'zhTW', '啊……沒有了生命，沒有了痛苦。嘎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 0, 0, 'zhTW', '呱嘎！寶貝，對，強大的寶貝！力量，無窮的力量。呱嘎嘎！寶貝中的力量！嘎嘎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 1, 0, 'zhTW', '嗯，你們想跟艾吉斯開戰？呱嘎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 1, 1, 'zhTW', '艾吉斯殺了你們，呱嘎嘎！殺了你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 1, 2, 'zhTW', '咕呱——嘎！休想逃走！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 2, 0, 'zhTW', '死吧！嘎！別想動我的寶貝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 2, 1, 'zhTW', '嗯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 3, 0, 'zhTW', '艾吉斯不會……呱嘎……不會死………');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18473 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18473, 4, 0, 'zhTW', '%s開始引導奧術能量……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18475 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18475, 0, 0, 'zhTW', '出來，小傢伙們！穆格高克要跟你們玩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18475 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18475, 1, 0, 'zhTW', '穆格高克一點都不疼，鴉人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18475 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18475, 2, 0, 'zhTW', '很好！鴉人滾！穆格高克找到了一個新朋友！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18481 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18481, 0, 0, 'zhTW', '沉默突然籠罩著整個撒塔斯城。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18481 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18481, 1, 0, 'zhTW', '%s的思想似乎侵入了你的心靈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18481 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18481, 2, 0, 'zhTW', '凱爾薩斯·逐日者被$n和$g他:她的夥伴們打敗了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18481 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18481, 3, 0, 'zhTW', '現在，攻擊風暴要塞內的殘餘血精靈的時刻已經來臨了。拿起武器！讓阿達爾的戰歌激勵你們吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 0, 'zhTW', '他是誰？他看上去很面熟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 1, 'zhTW', '傳言是真的？他真的有蓋亞安祖母的血統嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 2, 'zhTW', '真的是杜隆坦的兒子？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 3, 'zhTW', '他是來領導我們的嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 4, 'zhTW', '我從未在一個獸人身上感到如此強大的力量。他是……凡人嗎……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 5, 'zhTW', '他拿著毀滅戰錘！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 6, 'zhTW', '我有生以來第一次感到如此安全。我並不認識你，陌生人，但是我知道，如果你要我放棄我的生命，我會毫不猶豫地為你這麼做。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18489 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18489, 0, 7, 'zhTW', '杜隆坦之子……加拉達和蓋亞安的孫子……向我們的酋長鞠躬吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18493 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18493, 0, 0, 'zhTW', '噓！靈魂正在沉睡！');
