INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18528, 0, 0, 'zhTW', '%s一言不發，心中權衡著要做出怎樣的抉擇。站在他旁邊的沙塔爾軍隊鴉雀無聲，空氣中瀰漫著緊張的氣氛……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18528 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18528, 1, 0, 'zhTW', '%s開始引導聖光的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18533 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18533, 0, 0, 'zhTW', '天空之翼，我會把你從你對我詛咒的身體裡釋放出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18538 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18538, 0, 0, 'zhTW', '聖光想讓它迷失的孩子回來，索克雷薩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18538 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18538, 1, 0, 'zhTW', '我願以我自己作為交換。如果你把凱蘭恩從你的黑暗枷鎖中釋放的話，你會得到奧爾多的高階女祭司伊沙娜作為你的囚犯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18554 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18554, 0, 0, 'zhTW', '你闖進我的家門來威脅我？我可不認為你能如願。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18554 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18554, 1, 0, 'zhTW', '一切都進展得非常順利，我的大人。塞納里奧樹林的小型樣本測試非常成功。與此同時，第二個炸彈正在下面的院子裡新增燃料。還有，我已經派了個信使去圖雷姆把剩餘的部分帶回這裡了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18554 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18554, 2, 0, 'zhTW', '你滿意了吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18554 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18554, 3, 0, 'zhTW', '我向您保證，我們不會失敗，我的主人。我親自監視著工程的每一步，而且最終的密碼掌握在我自己手中。一天以內，我就會讓炸彈在周圍那些討厭的傢伙身邊引爆的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18588 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18588, 0, 0, 'zhTW', '我選擇第三項：殺了你！');
