DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18668 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18668, 0, 0, 'zhTW', '不，你錯了！我們才是遭到背叛的人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18668 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18668, 1, 0, 'zhTW', '她曾經是銀月城的遊俠將軍，現在也會是我們忠誠的盟友！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18668 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18668, 2, 0, 'zhTW', '流血是真實的。我們只能相信自己！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18668 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18668, 3, 0, 'zhTW', '你稱我們是叛徒嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18669 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18669, 0, 0, 'zhTW', '什麼時候連矮人都變成了我們的朋友？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18669 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18669, 1, 0, 'zhTW', '沒有魔法，我們要怎麼生存？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18669 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18669, 2, 0, 'zhTW', '一派胡言。回到你的森林裡去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 0, 0, 'zhTW', '你這個蠢貨！王子的爪牙就是那些被遺忘者，就是我們現在的同盟！而且他現在已經背叛了我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 1, 0, 'zhTW', '死亡之痕橫穿過我們的土地！它每天都在生長。就像以前那樣，我們對魔法的需要使得我們脆弱，同樣也把我們帶向毀滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 2, 0, 'zhTW', '但是那代價呢？你完全被矇蔽了。我們都完全被矇蔽了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 3, 0, 'zhTW', '不，不是野蠻人！這是道德。我們毫無節制的行為會最終摧毀我們，進而摧毀我們所努力構建的一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 4, 0, 'zhTW', '我們站在毀滅的邊緣。我們必須重新考慮這輕率的行動計劃。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 5, 0, 'zhTW', '讓所有人聽到你們的聲音！現在是時候團結起來拯救我們的人民了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 6, 0, 'zhTW', '洛瑟瑪必須聽到我們的呼聲！我們不能再沉默下去了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 7, 0, 'zhTW', '洛瑟瑪重建的銀月城真是我們的驕傲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18671 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18671, 8, 0, 'zhTW', '英明的魔導師將會指引我們走向繁榮的未來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18683 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18683, 0, 0, 'zhTW', '我會把你的靈魂送到無盡虛空！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18683 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18683, 0, 1, 'zhTW', '讓我黑暗吞噬你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18683 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18683, 0, 2, 'zhTW', '在虛空裡，沒人能聽到你的哭號！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18688 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 0, 0, 'zhTW', '先祖們保佑著你，善良的人……');
