INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 0, 4, 'zhTW', '它為你而來……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18688 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 1, 0, 'zhTW', '靈魂的召喚……我被吞噬了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18688 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 1, 1, 'zhTW', '我控制不了……它在拉我進去……虛空在擴大……');
