INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 1, 5, 'zhTW', '到底是怎麼了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18688 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 1, 6, 'zhTW', '這是什麼騙局？我……啊……');
