INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18688, 1, 7, 'zhTW', '我們會怎麼樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18698 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18698, 0, 0, 'zhTW', '發現入侵者！立即終結威脅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18702 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18702, 0, 0, 'zhTW', '你竟敢來這兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18702 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18702, 0, 1, 'zhTW', '外人禁止入內！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18702 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18702, 0, 2, 'zhTW', '這裡是聖地！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18705 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18705, 0, 0, 'zhTW', '%s暈倒了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18708 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18708, 0, 0, 'zhTW', '%s從空氣中吸取能量……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18723 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18723, 0, 0, 'zhTW', '我相信只要你們給我一點時間，我就能向你們解釋發生了什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18723 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18723, 1, 0, 'zhTW', '法術應該會抹去剛才他們剛剛和我們一起發生的事。他們應該記住的是，如果沒有干預時間，現實會是什麼走向。做得好，索爾會繼續踏上尋找他的命運以及塔蕾莎的道路了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18723 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18723, 2, 0, 'zhTW', '她的命運真讓人遺憾。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18724 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18724, 0, 0, 'zhTW', '人類在我們最黑暗的時刻拋棄了我們！他們的王子親自領導了對我們領土的襲擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18724 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18724, 1, 0, 'zhTW', '看看這座神奇的城市！這就是魔法本身。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18724 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18724, 2, 0, 'zhTW', '你會讓我們像野蠻人那樣生活的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18725 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18725, 0, 0, 'zhTW', '當你準備飛往敦霍爾德時，請告訴我，我會帶你去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 0, 0, 'zhTW', '我仍然清晰地記得上次戰爭敗北的恥辱。我等待復仇的機會已經等得太久了。現在，軍團的陰影將籠罩這個世界，你們徹底毀滅的日子……已經不遠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 1, 0, 'zhTW', '軍團將會征服一切！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 1, 1, 'zhTW', '所有的凡人都將滅亡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 2, 0, 'zhTW', '所有的生命都將被根除！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 2, 1, 'zhTW', '我要把你們生吞活剝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 3, 0, 'zhTW', '可笑的凡人，你們只是延遲了不可避免的命運。一個惡魔倒下去，十個惡魔會站起來。這就是卡扎克的意志……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 3, 1, 'zhTW', '可笑的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 3, 2, 'zhTW', '宇宙將獲得新生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 4, 0, 'zhTW', '軍團……永遠不會……失敗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18728 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18728, 5, 0, 'zhTW', '%s進入狂暴狀態！');
