INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18896, 46, 0, 'zhTW', '儘管他們看上去很野蠻，但這些用鐵縫合起來的可怕生物其實是非常聰明的工程師和鑄造匠。');
