INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18927, 0, 0, 'zhTW', '傳說強大的年獸沉睡在月光林地的月神湖底，每年只會醒來一次。不過那也只是個傳說。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18927 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18927, 0, 1, 'zhTW', '你看過煙花嗎？現在是一年當中買菸花放的最佳季節！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18927 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (18927, 0, 2, 'zhTW', '月光林地的德魯伊正在舉辦隆重的慶典，慶祝春節的到來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 18927 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
