INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19178, 8, 8, 'zhTW', '每年的這個時候，煙林牧場的地精們總是會出售一些非常棒的糖果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19178 AND `GroupID` = 8 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19178, 8, 9, 'zhTW', '冬天爺爺會把每個人的禮物放在奧格瑪的樹下，我在想今年他會給我什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19181 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19181, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19188 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19188, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19191 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19191, 0, 0, 'zhTW', '多傲慢啊！多自大啊！你覺得你可以在我的門口打敗我嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19191 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19191, 1, 0, 'zhTW', '主人，我失敗了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19196 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19196, 0, 0, 'zhTW', '我感覺到了真正的戰爭氣息。水果販已經得到了食人魔的援助，我也必須叫來我的援兵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19196 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19196, 1, 0, 'zhTW', '水果商人！你的小車仍然擋著我們的路。我再給你一個小時，把它從我們的地盤挪開。不要再考驗我們的耐心！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 0, 0, 'zhTW', '朋友，我很榮幸來迎接你今日駕臨神殿。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 1, 0, 'zhTW', '對於我這個聖光的卑微僕從，阿達爾從來不會隱瞞任何知識。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 2, 0, 'zhTW', '我的神聖使命要求我必須將這些真理分享給所有應該知曉它的人們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 3, 0, 'zhTW', '這讓我得知，我們每個人的心中都有聖光……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 4, 0, 'zhTW', '……這是一份禮物，一份賜予所有自然生靈的禮物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 5, 0, 'zhTW', '剛開始的時候，聖光以某種微妙的感覺昭示著它的教義。人們很容易忽視這種感覺，但是聖光依然指引著他們探索真理，並促使他們常行善事。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 6, 0, 'zhTW', '真誠、仁慈、寬恕、奉獻。這些都是聖光結出的碩果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 7, 0, 'zhTW', '聖光祝福那些接受感召的人們，這種賜福可能是有形的，也可能是無形的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 8, 0, 'zhTW', '隨著個人信念的逐漸強化，他對聖光之力的駕馭就會愈發純熟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 9, 0, 'zhTW', '經過時間的歷練，越是服從聖光指引的人，就越能觸及到聖光的聲息，越能駕馭聖光的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 10, 0, 'zhTW', '聖光最忠實的追隨者們擁有無上的治癒與祝福之力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 11, 0, 'zhTW', '悲哀的是，那些徘徊的死者蔑視聖光。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 12, 0, 'zhTW', '聖光拋棄了那些執迷不悟的愚者，留給他們的是無盡的黑暗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 13, 0, 'zhTW', '在沒有聖光的地方，絕望、厭惡和憤怒橫行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 14, 0, 'zhTW', '我們出生在一個危險的時代，黑暗的力量誓要讓我們走向毀滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 15, 0, 'zhTW', '是在聖光之下尋找自我的時候了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 16, 0, 'zhTW', '聆聽我的話語，感受存在於你們體內的聖光吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 17, 0, 'zhTW', '擁抱你體內的聖光吧，我的朋友們！將所有的黑暗拒之門外……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19216 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19216, 18, 0, 'zhTW', '我們必須忍耐這些痛苦的時期，總有一天我們會找到屬於自己的勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 0, 0, 'zhTW', '哦，還有一場表演？太好了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 1, 0, 'zhTW', '%s深深嘆了口氣，瞟了薩根一眼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 2, 0, 'zhTW', '我會把我的朋友，薩根，變成某種令人吃驚的東西！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 3, 0, 'zhTW', '那麼，我的下一個戲法……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 4, 0, 'zhTW', '一個簡單而好笑的笑話。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 5, 0, 'zhTW', '感謝大家的觀看！如果你們明天能帶上一些零錢來看錶演的話，我會非常感激的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19217 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19217, 6, 0, 'zhTW', '看，我會噴火！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19218 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19218, 0, 0, 'zhTW', '我斷定你們會痛苦地死去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19218 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19218, 1, 0, 'zhTW', '你的戰術有漏洞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19218 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19218, 1, 1, 'zhTW', '啊，這是唯一符合邏輯的結果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19218 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19218, 2, 0, 'zhTW', '三思而後行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19218 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19218, 2, 1, 'zhTW', '如果我的切割沒有出錯……你們應該離死不遠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19218 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19218, 3, 0, 'zhTW', '一個意料之外的……偶然。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19219 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19219, 0, 0, 'zhTW', '你們應該趁早逃走的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19219 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19219, 1, 0, 'zhTW', '來呀，用你最厲害的招數！我照單全收！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19219 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19219, 2, 0, 'zhTW', '你以為你們能打傷我？你以為我會怕你？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19219 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19219, 3, 0, 'zhTW', '我可警告過你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19219 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19219, 3, 1, 'zhTW', '哇，我真厲害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19219 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19219, 4, 0, 'zhTW', '啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 0, 0, 'zhTW', '我們的時間非常緊迫。你們休想添亂！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 1, 0, 'zhTW', '我正在尋找一個夥伴……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 2, 0, 'zhTW', '是叫人幫忙的時候了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 3, 0, 'zhTW', '我喜歡自己動手……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 4, 0, 'zhTW', '一點小麻煩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 4, 1, 'zhTW', '你好像輸了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 5, 0, 'zhTW', '計劃……要繼續下去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19220 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19220, 6, 0, 'zhTW', '計劃……要繼續下去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 0, 0, 'zhTW', '不要把自己的生命看得太有價值。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 1, 0, 'zhTW', '我不是孤身一人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 2, 0, 'zhTW', '你們能受得了這高溫嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 2, 1, 'zhTW', '永遠別再回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 3, 0, 'zhTW', '永遠別再回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 3, 1, 'zhTW', '永遠別再回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19221 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19221, 4, 0, 'zhTW', '永遠別再回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19223 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19223, 0, 0, 'zhTW', '我要是發誓說我有更多蘋果就好了。葛羅克！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19223 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19223, 1, 0, 'zhTW', '那些可憐的獸人在叫喊什麼？誰去看看怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 0, 0, 'zhTW', '嘿！嘿，$r！我有個東西簡直是給你量身定做的！你看到過提克巴朗嗎？偷你東西的可怕生物。你所需要的就是我的防盜符咒，保證可以嚇走所有的提克巴朗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 0, 1, 'zhTW', '看這裡，$c！我這裡有樣東西給你，你絕對需要。是塊肥皂，是的……而且系在一根繩子上！我沒有要冒犯的意思，$G先生:甜心，但是我相信你知道我在說什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 0, 2, 'zhTW', '過來，$r。你不想讓你自己在地下城裡受到傷害吧，對嗎？努力工作，為了什麼？一些毫無價值的飾品？不，你所需要的就是一個我製作的護身符。保證有用！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 1, 0, 'zhTW', '你看上去很疲憊，$c。我有東西給你。這些護身符，它們可以幫你跳躍障礙物和遊過河流，就像那是你與生俱來的能力一樣。它們讓你吃的食物充滿能量，讓你的傷口在眨眼間就能癒合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 1, 1, 'zhTW', '嘿！嘿，$r！我有個東西簡直是給你量身定做的！你看到過提克巴朗嗎？偷你東西的可怕生物。你所需要的就是我的防盜符咒，保證可以嚇走所有的提克巴朗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 1, 2, 'zhTW', '看這裡，$c！我這裡有樣東西給你，你絕對需要。是塊肥皂，是的……而且系在一根繩子上！我沒有要冒犯的意思，$G先生:甜心，但是我相信你知道我在說什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 2, 0, 'zhTW', '你看上去很憂愁。是不是某些特殊的人讓你如此低落，嗯？不用擔心，不用擔心。從我這裡買一枚勳章吧，他們永遠都不會再成為你的問題了，$g夥計:小姐！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 2, 1, 'zhTW', '多棒的護身符啊！難以置信的古董！那些新來的珠寶工匠們從未嘗試過的、格里伏塔的神秘物品！買下這些魔法護身符，提升你的能力吧！很便宜的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19227 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19227, 2, 2, 'zhTW', '到處都有危險，不是嗎？知道你需要什麼嗎？保護。我可以幫你挑戰死亡！把這塊非凡的石頭戴在脖子上，看，如果你可以在靈魂世界找到自己，那麼你就能復活！只不過需要一個跑向屍體的過程，然後你就重生了，一個嶄新的你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 0, 'zhTW', '大家好！離下個笑話還有多久？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 1, 'zhTW', '我剛從鐵爐堡飛過來，小子！我坐騎的翅膀都快累斷了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 2, 'zhTW', '嘿，朋友們，夠了夠了……那是我第一次。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 3, 'zhTW', '謝謝你到這兒來看我！希望你已經準備好享受這個時刻了，我早就迫不及待了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 4, 'zhTW', '哇！這些掌聲都是獻給我的？感謝你們的到來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 5, 'zhTW', '這群人看上去不錯。連女矮人都颳了鬍子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 0, 6, 'zhTW', '你準備好開懷大笑了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 1, 0, 'zhTW', '我遇到過的牛頭人都非常美……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 2, 0, 'zhTW', '味！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 3, 0, 'zhTW', '我上週在閃金鎮。你去過那裡嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 4, 0, 'zhTW', '那鎮子真小，我讓一個小孩給我畫張地圖。結果他畫在了迪菲亞通緝令的背面……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 5, 0, 'zhTW', '還是一比一的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 6, 0, 'zhTW', '演出時間！我把這叫做“愚蠢的牛頭人”！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 7, 0, 'zhTW', '喜劇演員清了清喉嚨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 8, 0, 'zhTW', '喜劇演員扮成了一個牛頭人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 9, 0, 'zhTW', '我有個好問題，為什麼西瓜裡面有水？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 10, 0, 'zhTW', '因為它們是在春天種植的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 11, 0, 'zhTW', '怎麼和女人打交道？我的意思是她們就像是……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 12, 0, 'zhTW', '喜劇演員扮成了一個女性人類。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 13, 0, 'zhTW', '地精們更糟！他們一直在說一些……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 14, 0, 'zhTW', '喜劇演員扮成了一個地精。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 15, 0, 'zhTW', '當雷象坐在你家圍欄上的時候，你該怎麼辦？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 16, 0, 'zhTW', '去弄個新圍欄！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 17, 0, 'zhTW', '要是我知道會這樣，我就該穿上我的[大笑長靴]。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 17 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 17, 1, 'zhTW', '顯然我和你的人民是敵對的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 17 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 17, 2, 'zhTW', '哇！這裡的笑聲好像從來沒停過，是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 17 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 17, 3, 'zhTW', '能給我個增益魔法嗎？我快死在這裡了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 17 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 17, 4, 'zhTW', '哈哈哈！這些笑話真是太棒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 18, 0, 'zhTW', '嘿！嘿！嘿！這不是醉鬼拉里克嗎……他媽媽太胖了，她不僅上了《今日食人魔》的封面……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 19, 0, 'zhTW', '還上了封底！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 20, 0, 'zhTW', '地精們曾經是非常值得尊敬的種族……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 21, 0, 'zhTW', '有一天我看到有人沿著大街邊走邊叫，“一旦你變成地精，你就只能租房子住了！”');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 22, 0, 'zhTW', '我愛血精靈女人。特別是當她們說這些話題的時候……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 23, 0, 'zhTW', '喜劇演員扮成了一個血精靈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 24, 0, 'zhTW', '那些血精靈認為他們離控制這個世界只有一步之遙……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 25, 0, 'zhTW', '看上去更像千里之外！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 26, 0, 'zhTW', '最後一個模仿。有點難度，但是你們能猜出是誰嗎……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 27, 0, 'zhTW', '喜劇演員扮成了一個獸人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 28, 0, 'zhTW', '現在表演結束了，有人可以帶我去刷血色修道院嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 28 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 28, 1, 'zhTW', '謝謝！別忘記給服務生小費！晚安。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 28 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 28, 2, 'zhTW', '好吧，是時間取下這些可笑的肌肉了。大家晚安！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 28 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 28, 3, 'zhTW', '已經結束了？真不錯。路上小心，晚安。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 28 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 28, 4, 'zhTW', '感謝大家！繼續鼓掌，那裡有隻蒼蠅，你們中一定要有人把它拍下來！晚安！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 29, 0, 'zhTW', '多少狗頭人換一根蠟燭？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 30, 0, 'zhTW', '不許搶走我的蠟燭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 31, 0, 'zhTW', '閃金鎮旅店為他們的湖畔景觀房做廣告……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 32, 0, 'zhTW', '結果我看到有個魚人在我的窗邊游泳。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 33, 0, 'zhTW', '你有沒有注意到那些可愛的獸人孩子看上去全都長得一個樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 34, 0, 'zhTW', '他們長大之後就不可愛了，真是糟糕。貧瘠之地的成人禮上大概會執行“爬上大樹再狠狠地摔下來”這樣的儀式。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 35 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 35, 0, 'zhTW', '我聽說地精們可以實現願望……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 36 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 36, 0, 'zhTW', '我的願望就是讓他們走遠點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 37 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 37, 0, 'zhTW', '看這是誰啊，醉鬼拉里克……他的媽媽太胖了，連龍都不要吃她……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 38 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 38, 0, 'zhTW', '因為他們不知道該把剩下的肉放在哪裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 39 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 39, 0, 'zhTW', '我和我的妻子一起快樂地生活了二十三年……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 40 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 40, 0, 'zhTW', '然後我們相遇了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 41 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 41, 0, 'zhTW', '你把壞的迴旋標叫做什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 42 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 42, 0, 'zhTW', '一根棍子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 43 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 43, 0, 'zhTW', '這個地精告訴牛頭人說，他去過熔火之心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 44 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 44, 0, 'zhTW', '牛頭人說，“真是吹牛。”');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 45 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 45, 0, 'zhTW', '只能招募你的家畜作為同盟是多麼令人失望啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 46 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 46, 0, 'zhTW', '我有一條狗，但我不會把劍給它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 47 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 47, 0, 'zhTW', '通常你不能相信地精……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 48 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 48, 0, 'zhTW', '我在開玩笑嗎？如果你和地精們做生意，你最好給錢包裝上個鐵套子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 49 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 49, 0, 'zhTW', '只有我這麼覺得嗎？部落簡直是我們可以找到的最難看的敵人？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19228 AND `GroupID` = 50 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19228, 50, 0, 'zhTW', '你們不要感到失落，我的意思是血精靈是多麼迷人啊。都是翻譯的錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19255 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19255, 0, 0, 'zhTW', '是的，我們有麻煩了。我想那是顯而易見的。但問題是，我們要怎麼辦？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19255 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19255, 0, 1, 'zhTW', '習慣就好，姑娘們。像我一樣關心這些悲慘的倖存者吧。歡迎來到地獄火半島，你的新家。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19255 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19255, 0, 2, 'zhTW', '都長長腦子吧，在你們認識到一頭衝進燃燒軍團的小隊是自殺行為之前，我還要送多少具屍體回你們的家？還有，不要在我面前用力晃你們的大腦袋，好像你們明白我在說什麼似的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19255 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19255, 0, 3, 'zhTW', '我不想對你們說謊，士兵們。我們被打得屁滾尿流！有沒有像獸人那樣帶種的，站出來去做點什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19270 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19270, 0, 0, 'zhTW', '要是你想要大笑一場，就去天涯旅店吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19271 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19271, 0, 0, 'zhTW', '感謝大家光臨。現在請鼓掌歡迎撒塔斯城最棒的——派瑞·加奈爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19271 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19271, 1, 0, 'zhTW', '派瑞·加奈爾！多棒的表演！酒館是通宵營業的，所以請待在這盡情享受吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19273 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19273, 0, 0, 'zhTW', '去和空軍指揮官布拉克談談，$n。他會給你配備一隻武裝飛龍。對了，祝你好運！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19283 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19283, 0, 0, 'zhTW', '請不要視而不見……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19283 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19283, 0, 1, 'zhTW', '施捨個銅幣吧，$G先生:女士？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19283 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19283, 0, 2, 'zhTW', '嘿，$G先生:女士，可憐可憐我吧，我還有五個孩子等著吃飯呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19283 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19283, 0, 3, 'zhTW', '請施捨一點銅幣吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19294 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19294, 0, 0, 'zhTW', '到山上來，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19294 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19294, 1, 0, 'zhTW', '我有個主意。讓我們把這塊碎片種到地上，看看會發生什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19294 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19294, 2, 0, 'zhTW', '水晶碎片中散發出的邪惡光芒引來了一隻巨人，快點消滅它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19308 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19308, 0, 0, 'zhTW', '這場戰爭——不要錯誤地認為它是除了戰爭以外的什麼東西——是不會自動獲勝的。如果我們不盡全力來為這塊破碎世界的每一寸土地戰鬥，我們就會失去一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19308 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19308, 0, 1, 'zhTW', '在我們開始嚴肅對待之前，還有多少士兵要死在這裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19308 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19308, 0, 2, 'zhTW', '你們覺得這些惡魔會跟我們公平地交戰嗎？它們比獸人更野蠻，比亡靈更狡猾。千萬不要試圖以普通的戰爭標準來評判燃燒軍團。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19317 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19317, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19346 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19346, 0, 0, 'zhTW', '學者尼度門，我有一事相求。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19346 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19346, 1, 0, 'zhTW', '我們剛派了另一隊新手隊伍進駐了納格蘭。你能為他們祈禱平安嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19346 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19346, 2, 0, 'zhTW', '願我們的願望能夠實現。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19354 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19354, 0, 0, 'zhTW', '讓這些可憐的破碎者累到吐血吧，伊利達雷！要是這個被遺棄的地方有任何值錢的東西，我們會找到它的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19354 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19354, 0, 1, 'zhTW', '不要讓這些可憐蟲有一點點喘息的時間！如果這裡真的有一顆阿塔瑪水晶的話，那麼我們會找到它的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19354 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19354, 0, 2, 'zhTW', '看緊這些破碎者人渣！已經有很多從我們這裡逃走了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19354 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19354, 0, 3, 'zhTW', '我們必須找到主人想要的東西！只許成功，不許失敗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19362 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19362, 0, 0, 'zhTW', '要是給我看到誰偷懶，我就把他們綁在投石器上，丟到黑暗神殿去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19362 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19362, 0, 1, 'zhTW', '無論什麼時候，你們這些苦工要是想休息的話，那邊的墳地等著你們呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 0, 0, 'zhTW', '當然，我的朋友。請問有什麼可以效勞的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 1, 0, 'zhTW', '一個高貴的請求。這是一種榮譽，艾羅塞姆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 2, 0, 'zhTW', '我的朋友們，請與我一起謙卑地向聖光祈禱。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 3, 0, 'zhTW', '我們信奉的聖光，我們懇求你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 4, 0, 'zhTW', '在我們與黑暗的鬥爭中，我們派出了我們的孩子衝鋒陷陣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 5, 0, 'zhTW', '請為他們祝福，請保護他們吧，請賜予他們成功，凌駕於那些想傷害我們的人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 6, 0, 'zhTW', '我們乞求你繼續保佑我們古老的家園。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 7, 0, 'zhTW', '願我們能以一顆包容的心來看待那些精靈訪客。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19378 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19378, 8, 0, 'zhTW', '以納魯的名義，願我們的願望能夠實現。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19380 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19380, 0, 0, 'zhTW', '快磨斧子，說你呢！我要它鋒利到可以劈風斷水！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19380 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19380, 1, 0, 'zhTW', '要是你不適合修理工作的話，我們就要考慮你是否適合用來做菜了。幹活去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19383 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19383, 0, 0, 'zhTW', '我不懂你在說什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19383 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19383, 1, 0, 'zhTW', '請不要打我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19394 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19394, 0, 0, 'zhTW', '布隆！嗨，布隆！打我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19394 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19394, 1, 0, 'zhTW', '不，拳頭太弱了。用錘子敲我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19394 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19394, 2, 0, 'zhTW', '快點，你這個娘娘腔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19394 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19394, 3, 0, 'zhTW', '……太棒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19395 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19395, 0, 0, 'zhTW', '%s眨著眼，露出很困惑的表情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19395 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19395, 1, 0, 'zhTW', '什麼，用我的拳頭？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19395 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19395, 2, 0, 'zhTW', '我……不覺得這是個好主意，笨蛋。你可能會受傷……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19395 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19395, 3, 0, 'zhTW', '呃……笨蛋？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19412 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19412, 0, 0, 'zhTW', '一股冷風吹過你的臉頰，溫和的蜂鳴聲在大廳中環繞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19419 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19419, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19438 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19438, 0, 0, 'zhTW', '我的魔法能使我們回到索爾死之前。但是注意，我控制時間的能力是有限的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19438 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19438, 1, 0, 'zhTW', '我使時間又一次倒流。如果你不能阻止索爾死亡，那麼一切都將失去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19440 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19440, 0, 0, 'zhTW', '你被%s發現了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19442 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19442, 0, 0, 'zhTW', '%s召喚出他的座狼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19442 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19442, 1, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19453 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19453, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19456 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19456, 0, 0, 'zhTW', '你折騰得還不夠嗎？你非要把我從沉睡中驚醒嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19456 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19456, 1, 0, 'zhTW', '暴力就能解決一切嗎？該做的事，我都做完了。我辜負了我的族人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19466 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19466, 0, 0, 'zhTW', '閉嘴，你這混蛋！不要用那種語調和聖光的女祭司說話！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19466 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19466, 1, 0, 'zhTW', '連你都必須承認你從背叛者那得來的資訊是過時的，而且是不可靠的。我們應該有計劃地進攻這些法力熔爐，並儘可能收集一切情報。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19467 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19467, 0, 0, 'zhTW', '恕我直言，阿達爾派我來這裡是為了調查凱爾薩斯的行動，而不是發動一次全力進攻。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19467 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19467, 1, 0, 'zhTW', '魔導師會很高興知道我對薩拉斯語很熟悉的。別擺出一副謙恭的模樣，我不吃你這套。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19467 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19467, 2, 0, 'zhTW', '話過三句必跑題……我們應當把注意力放在這些法力熔爐上。我們需要知道敵人正在用它們做什麼，以及為什麼要這麼做。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19468 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19468, 0, 0, 'zhTW', '你瞧，甜心。我們沒有人想要直接進攻風暴要塞，但要是機會就在眼前，為何不去拿下呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19468 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19468, 1, 0, 'zhTW', '……又來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19468 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19468, 2, 0, 'zhTW', '老大終於發話了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19469 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19469, 0, 0, 'zhTW', '我身邊這些傢伙都是白痴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19469 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19469, 1, 0, 'zhTW', '我們是非常開誠佈公的！你忘了我們中的許多人都曾經是凱爾薩斯最信任的手下嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19475 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19475, 0, 0, 'zhTW', '一切進展順利，瓦菲雷。你不是要去做些產品示範之類的事情嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19480 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19480, 0, 0, 'zhTW', '什麼……我變成了什麼？啊……啊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19493 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19493, 0, 0, 'zhTW', '我告訴過你，當那個愚蠢的精靈回來了再召喚我！這算什麼？不過也沒關係了，你不會困住我太久的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19516 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 0, 0, 'zhTW', '警報！消滅入侵者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19516 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 1, 0, 'zhTW', '目標已終結。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19516 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 1, 1, 'zhTW', '入侵生命體已經停止運轉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19516 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 1, 2, 'zhTW', '威脅已排除。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19516 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 2, 0, 'zhTW', '系統……關閉……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19516 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 3, 0, 'zhTW', '備用方案啟動……');
