INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19516, 3, 1, 'zhTW', '計算力量引數……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19523 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
