INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19523, 1, 0, 'zhTW', '如果你對我好，我就讓你活下來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19523 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19523, 2, 0, 'zhTW', '我們餓了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19523 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19523, 3, 0, 'zhTW', '你留在這裡，我去殺別人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19523 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19523, 4, 0, 'zhTW', '我們先殺別人吧！');
