INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19523, 8, 0, 'zhTW', '嘿！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19523 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19523, 9, 0, 'zhTW', '我們殺了他的朋友吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 0, 0, 'zhTW', '你為什麼就不能讓我來說話？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 1, 0, 'zhTW', '不，我們不會讓你活下來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 2, 0, 'zhTW', '你總是餓。所以我們才這麼胖！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 3, 0, 'zhTW', '你在幹什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 4, 0, 'zhTW', '這一點都不有趣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 5, 0, 'zhTW', '你急什麼，白痴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 5, 1, 'zhTW', '那是因為我出了好大的力氣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 6, 0, 'zhTW', '你這蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 7, 0, 'zhTW', '煩了？他都快死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19524 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 8, 0, 'zhTW', '我累了。你去殺下一個！');
