INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19524, 9, 0, 'zhTW', '那是因為我出了好大的力氣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19527 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19527, 0, 0, 'zhTW', '%s吸收了本次攻擊的火焰能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19527 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19527, 1, 0, 'zhTW', '%s吸收了本次攻擊的奧術能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19527 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19527, 2, 0, 'zhTW', '%s吸收了本次攻擊的冰霜能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19527 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19527, 3, 0, 'zhTW', '%s吸收了本次攻擊的神聖能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19527 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19527, 4, 0, 'zhTW', '%s吸收了本次攻擊的自然能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19527 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19527, 5, 0, 'zhTW', '%s吸收了本次攻擊的暗影能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19533 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19533, 0, 0, 'zhTW', '一個商人，也許吧？你要補給的話只需要找我就好。我的價格十分合理，朋友。要知道，這些物品是很難搞到的，你就不要關心來源了好不好？總之，你會在這裡找到你想要的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19534 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19534, 0, 0, 'zhTW', '這個地方的生物非常強壯，旅行者。如果你想活下去的話，應該帶好充足的彈藥。你很幸運——我這裡有大量的箭矢、子彈和投擲武器。如果你考慮一下週圍的環境，我的價格還是非常合理的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19535 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19535, 0, 0, 'zhTW', '啊，又一個強大的旅行者。虛空很危險，你會需要最強力的法術來任你支配。我這裡有各種上好的材料，普通的和珍稀的都有。來吧，買點吧，你不會遺憾的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19541 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19541, 0, 0, 'zhTW', '好訊息是，我們周圍都是有著多餘機械部件的鄰居。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19541 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19541, 0, 1, 'zhTW', '也許我應該召集其他人，在這次變動後向那裡出發？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19541 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19541, 0, 2, 'zhTW', '唔，奧術殲滅者非常厲害，我懷疑維勒老爹是否知道他在懸賞什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19541 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19541, 0, 3, 'zhTW', '上次有人妄想獲得靈巖巨人的賞金，最後那個愚蠢的冒險者被踩成了照片。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19541 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19541, 0, 4, 'zhTW', '靈巖巨人？！那東西一腳就能把你踩扁！不用了，謝謝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19543 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19543, 0, 0, 'zhTW', '我不知道我在想什麼，竟然沒拿劍就出去了。如果我看到它在這裡，我就會帶上它了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19544 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19544, 0, 0, 'zhTW', '我不能不穿披風出去。我希望它在這裡……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19544 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19544, 1, 0, 'zhTW', '在這裡！我發誓我上次沒有把它放在這裡……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19545 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19545, 0, 0, 'zhTW', '喲！那是我的幸運帽。我一直在到處找它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19546 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19546, 0, 0, 'zhTW', '沒有一個好的睡前故事，我就睡不著。現在我肯定可以睡個好覺了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19554 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19554, 0, 0, 'zhTW', '你只會加速本就不可避免的事情，到時候，一切都會被吞噬！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19554 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19554, 1, 0, 'zhTW', '時間只對凡人有意義，迪門修斯是無限的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 0, 0, 'zhTW', '戰鼓的回聲從遠處傳來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 1, 0, 'zhTW', '我終於……回家了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 2, 0, 'zhTW', '地獄咆哮！天啊！德雷克塔爾，他簡直就是格羅姆再世。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 3, 0, 'zhTW', '我很抱歉我沒能及時趕來，年輕的地獄咆哮。我有很多關於你父親的事情要告訴你，但首先，你必須告訴我可以在哪裡找到祖母。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 4, 0, 'zhTW', '感謝你，加爾魯什。在我拜訪祖母之後，我會找你好好談談的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 5, 0, 'zhTW', '祖母……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 6, 0, 'zhTW', '祖母……我是不是……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 7, 0, 'zhTW', '他們……沒有，祖母。他們在我出生後不久就被殺害了。我從來都沒有見過他們。我是作為一個奴隸長大的。我這個名字的意思，就是“奴隸”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 8, 0, 'zhTW', '我一直夢到這個場景，祖母。奧格瑞姆跟我說過很多關於他們的故事和他們在德拉諾的冒險經歷。他是我最好的老師和最親密的朋友，祖母。他像個英雄般地死去了……他們都像英雄般地死去了，榮耀的戰歌為他們奏響。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 9, 0, 'zhTW', '他們的死充滿榮耀，祖母。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 10, 0, 'zhTW', '我們最偉大的英雄去世了。那就是拯救我們全族的格羅姆……我和他並肩而戰，最後他打倒了瑪諾洛斯，永遠地終結了我們的詛咒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 11, 0, 'zhTW', '告訴他？祖母，他父親的死讓我們都從血之詛咒中解脫了。我什麼都不會告訴他。我會讓他親眼看看！讓他和那些置疑格羅姆決心的傢伙看看，格羅姆為整個獸人氏族做過些什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 12, 0, 'zhTW', '請原諒，祖母。我很快就回來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 13, 0, 'zhTW', '加爾魯什，地獄咆哮之子，你的父親是我們最偉大的英雄。請允許我為你展示一下，你父親為了讓我們免受惡魔的控制而做出的犧牲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 14, 0, 'zhTW', '靈魂們，賜予我力量吧！從我的靈魂中抽出那些舊日的傷痛，讓所有人都看看！讓這個孩子瞭解他的父親！讓這些人認識他們的救世主！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 15, 0, 'zhTW', '%s把手放在加爾魯什的肩上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 16, 0, 'zhTW', '你沒必要感謝我，加爾魯什。你的父親和我是兄弟。我會為你和瑪格漢氏族做任何事。現在，我得回祖母身邊去了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19556 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19556, 17, 0, 'zhTW', '我回來了，祖母。加爾魯什找回了他的信心和鬥志。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19558 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19558, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19579 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19579, 0, 0, 'zhTW', '喲！那是我的幸運帽。我一直在到處找它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19580 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19580, 0, 0, 'zhTW', '我不能不穿披風出去。我希望它在這裡……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19580 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19580, 1, 0, 'zhTW', '在這裡！我發誓我上次沒有把它放在這裡……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19606 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19606, 0, 0, 'zhTW', '誰過來給葛雷克讀下這張通緝令。葛雷克不識字！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19606 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19606, 1, 0, 'zhTW', '葛雷克醉了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19606 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19606, 2, 0, 'zhTW', '葛雷克試試！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19606 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19606, 3, 0, 'zhTW', '這油對葛雷克沒什麼用處！你覺得葛雷克看起來像什麼？穿著長袍的弱者？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 0, 0, 'zhTW', '一隻臭鼬！啊…………！不要碰我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 1, 0, 'zhTW', '把它弄走！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 2, 0, 'zhTW', '給我們看看你的戲法，拉文德維爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 3, 0, 'zhTW', '讓我離開這裡！夥計們……人呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 4, 0, 'zhTW', '哦，他待你真好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 5, 0, 'zhTW', '你不是一直跟我們說要冷靜的嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 6, 0, 'zhTW', '真是太精彩了！好吧，夥計們，我們去喝點什麼吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 7, 0, 'zhTW', '我的眉毛！你燒焦了我的眉毛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19610 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19610, 8, 0, 'zhTW', '不要擔心。這是個進步！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 0, 0, 'zhTW', '魔法，能量，我的人民陷入其中不能自拔……自從太陽之井被摧毀之後就是如此。歡迎來到未來。真遺憾，你們無法阻止什麼。沒有人可以阻止我了！Selama ashal’anore！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 1, 0, 'zhTW', '卡波妮婭會很快解決你們的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 2, 0, 'zhTW', '幹得不錯。看來你們有能力挑戰我的首席技師，塔隆尼庫斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 3, 0, 'zhTW', '讓我們來看看你們如何面對褻瀆者薩拉德雷！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 4, 0, 'zhTW', '你們擊敗了我最強大的顧問……但是沒有人能戰勝鮮血之錘。出來吧，薩古納爾男爵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 5, 0, 'zhTW', '你們看，我的個人收藏中有許多武器……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 6, 0, 'zhTW', '也許我確實低估了你們。雖然讓你們同時面對我的四位顧問顯得有些不公平，但是我的人民從來都沒有得到過公平的待遇。我只是在以牙還牙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 7, 0, 'zhTW', '唉，有些時候，有些事情，必須得親自解決才行。Balamore shanal！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 8, 0, 'zhTW', '我的心血是不會被你們輕易浪費的！我精心謀劃的未來是不會被你們輕易破壞的！感受我真正的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 9, 0, 'zhTW', '去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 9 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 9, 1, 'zhTW', '你用生命作賭注，而且你輸了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 9 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 9, 2, 'zhTW', '小孩子的把戲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 10, 0, 'zhTW', '聽我號令！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 10 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 10, 1, 'zhTW', '屈服於我的意志吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 11, 0, 'zhTW', '如果世界變得上下顛倒，你們會怎麼辦呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 11 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 11, 1, 'zhTW', '站不住腳了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 12, 0, 'zhTW', '%s開始施放炎爆術！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 12 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 12, 1, 'zhTW', '以太陽之名！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 13, 0, 'zhTW', '為了……奎爾……薩拉斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19622 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19622, 14, 0, 'zhTW', '%s開始施放炎爆術！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19632 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19632, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19635 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19635, 0, 0, 'zhTW', '我愛早晨虛空的味道。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19635 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19635, 1, 0, 'zhTW', '聞上去就像……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19635 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19635, 2, 0, 'zhTW', '……勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19647 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19647, 0, 0, 'zhTW', '%s挑釁地咆哮著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19647 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19647, 1, 0, 'zhTW', '不，老朋友。你解放了我們所有人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19664 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19664, 0, 0, 'zhTW', '喝一口啤酒，吃一口我的鬆餅，真是人生的一大享受啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19664 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19664, 1, 0, 'zhTW', '哈哈，多麼美味啊。賣鬆餅啦！來這裡買新鮮的鬆餅吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19664 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19664, 2, 0, 'zhTW', '我有鬆餅。到我這裡來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19664 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19664, 2, 1, 'zhTW', '沒錯，我是鬆餅人。你知道為什麼嗎？因為我賣鬆餅啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19666 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19666, 0, 0, 'zhTW', '永遠不要低估其他虛靈的貪婪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19666 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19666, 1, 0, 'zhTW', '好啊！好啊！表現得真好……我不能勸你為我工作，我能嗎？不，我想我手下的那些屠夫會影響到你的簽約。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19666 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19666, 2, 0, 'zhTW', '沙赫恩，你的計劃是不錯。要不是出了點差池，你應該能僥倖成功的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19666 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19666, 3, 0, 'zhTW', '永遠不要低估其他虛靈的貪婪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 0, 0, 'zhTW', '這不會花費太久的。當我清理這些虛空收集者的時候保護我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 1, 0, 'zhTW', '難以置信！讓我們繼續，好吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 2, 0, 'zhTW', '看看這能量濃度，沙法爾註定要大獲全勝！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 3, 0, 'zhTW', '應該可以……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 4, 0, 'zhTW', '額，現在。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 5, 0, 'zhTW', '啊在那兒，跟我來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 6, 0, 'zhTW', '啊，怪物太多了。在我工作的時候保護我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 7, 0, 'zhTW', '我們在這裡幹什麼？我以為你說這裡很安全？這都是第三次攻擊了！我想如果我們能從這裡逃出去，我會從你的獎勵里扣掉一些。現在不要再傻傻站在這裡了，摧毀他們，不要讓我看到更多的收集者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 8, 0, 'zhTW', '我們已經快到出口了。我允許你休息30秒，然後我們就出去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 9, 0, 'zhTW', '準備好出發了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 10, 0, 'zhTW', '好吧，休息時間結束，走吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 11, 0, 'zhTW', '啊真的嗎？會是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 12, 0, 'zhTW', '你知道，他是對的。我得拿著自己的那條線……不像他以後還有用！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 13, 0, 'zhTW', '謝謝，祝你好運！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 20, 0, 'zhTW', '%s在檢查他的身體是否完好無損。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 21, 0, 'zhTW', '你做到了！幹得好，$r。現在，如果你不介意的話，我要把其他人都叫進來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 22, 0, 'zhTW', '%s熟練地操作著控制面板。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19671 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19671, 23, 0, 'zhTW', '不要浪費時間了！帶上一切東西到下層去，然後傳送到風暴尖塔。快快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 0, 0, 'zhTW', '跟我來，陌生人。這不會耽誤你太長時間的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 1, 0, 'zhTW', '撒塔斯城曾經是德萊尼人在這個世界的首都。它的意思是“聖光的居所”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 2, 0, 'zhTW', '當燃燒軍團誘使獸人和德萊尼人反目成仇時，激烈的戰鬥就在這裡爆發了。儘管德萊尼人浴血奮戰，但最後，城市還是淪陷了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 3, 0, 'zhTW', '整座城市只剩下廢墟和黑暗……直到沙塔爾來臨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 4, 0, 'zhTW', '我們去貧民窟走走吧。我要提醒你，作為外域唯一的避風港，撒塔斯城吸引了成群的難民，無論是現在的戰爭所致，還是以往的戰爭所致。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 5, 0, 'zhTW', '沙塔爾，或者說“生於聖光”，這個詞是指來到外域和燃燒軍團的惡魔們作戰的納魯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 6, 0, 'zhTW', '他們慕名來到撒塔斯城的廢墟，一小群德萊尼傳教士利用那裡的一座廢棄神廟傳授著他們的教義。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 7, 0, 'zhTW', '被稱為奧爾多的那些傳教士們，因為納魯迴歸和重建即將開始的傳言而迅速恢復了生命力。廢棄的神廟如今變成了治療傷者的醫務室。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 8, 0, 'zhTW', '然而好景不長，這座城市再次遭受了攻擊。這次，發動進攻的是伊利丹的軍隊。伊利丹的同盟凱爾薩斯·逐日者派出了一大群血精靈來毀滅這座城市。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 9, 0, 'zhTW', '當時一大群血精靈跨過了這座橋，奧爾多的主教和守備官們築起了人牆，保衛聖光廣場。就在這時，意想不到的事情發生了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 10, 0, 'zhTW', '血精靈們在城市守衛面前放下了武器。他們的首領，一個被稱為沃雷塔爾的血精靈長者，衝進了聖光廣場，要求和阿達爾對話。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 11, 0, 'zhTW', '當納魯走近他時，沃雷塔爾跪在他的面前，說道：“我在我的夢境裡看到過您，納魯。您是我的族群唯一的生存希望。我和我的部下願意為您效勞。”');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 12, 0, 'zhTW', '沃雷塔爾和他的追隨者們的變節是凱爾薩斯有史以來所遭受到的最嚴重的損失。他們不是一群普通的血精靈，凱爾薩斯手下很多最睿智、最強大的學者和魔導師也被沃雷塔爾的影響力動搖了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 13, 0, 'zhTW', '納魯接受了這些叛節的血精靈，他們被稱為占星者。他們住在上面的平臺，只有他們的追隨者才被允許踏足那裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 14, 0, 'zhTW', '奧爾多是聖光的追隨者，寬恕和救贖是他們的信條。然而，他們卻很難忘記血精靈在凱爾薩斯命令之下的所作所為。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 15, 0, 'zhTW', '許多傳教士曾經被那些如今發誓效忠納魯的魔導師們殺死。他們對於和舊日的敵人同住在一座城市裡面感到非常不悅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 16, 0, 'zhTW', '奧爾多最神聖的廟宇和它周圍的小建築坐落在上面的廣場上。作為一個神聖的場所，只有他們的追隨者才被允許進入那裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 17, 0, 'zhTW', '對撒塔斯城的進攻持續著，但是城市並沒有淪陷，就像你看到的那樣。相反，那個名叫克希利的納魯領導了一次成功的反擊，一直打到了伊利丹的家門口——影月谷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 18, 0, 'zhTW', '在奧爾多和占星者的協助下，他不斷對伊利丹的軍隊發動著攻勢。然而這兩股勢力並沒有冰釋前嫌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 19, 0, 'zhTW', '他們爭先恐後地想要為納魯效勞，想要在納魯那裡獲得更多的榮耀。可是睿智的阿達爾卻能讓這兩個氏族維繫著微妙的平衡。每一天，雙方的軍隊都聚集在這裡，等待由阿達爾選擇要派遣誰前往影月谷參戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 20, 0, 'zhTW', '卡德加應該準備好再次見你了。記住，如果你準備為沙塔爾效力，你很可能不得不與奧爾多或是占星者結盟。同樣，對任何一方示好都會引起另外一方的敵意。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19685 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19685, 21, 0, 'zhTW', '祝你好運，陌生人，歡迎來到撒塔斯城。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 0, 0, 'zhTW', '你們還有大約五秒可活。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 1, 0, 'zhTW', '精確的角度和速度……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 1, 1, 'zhTW', '沒什麼技術含量，但是很有效。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 2, 0, 'zhTW', '預料之中的結果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 2, 1, 'zhTW', '一切都在按計劃進行！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 3, 0, 'zhTW', '我的計算居然沒有……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19710 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19710, 4, 0, 'zhTW', '%s陰險地舉起戰錘……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19720 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19720, 0, 0, 'zhTW', '該好好給你上上家教課了，小$g子:姑娘！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19720 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19720, 1, 0, 'zhTW', '在我數到“3”之前，滾出這裡，否則小心我放狗咬你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19720 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19720, 2, 0, 'zhTW', '好吧，我們投降！不要傷害我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19720 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19720, 3, 0, 'zhTW', '好吧，我們投降！不要傷害我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19720 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19720, 4, 0, 'zhTW', '是時候去見你的造物主了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19720 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19720, 5, 0, 'zhTW', '好吧，我們投降！不要傷害我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 0, 0, 'zhTW', '準備好具化間，新的同盟很快就會加入我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 1, 0, 'zhTW', '我們的同盟到了！開啟具化間！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 2, 0, 'zhTW', '現在，向傳送器進發。鑄魔營地：天罰等著你的到來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 3, 0, 'zhTW', '準備接受無盡的折磨吧，凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 3, 1, 'zhTW', '什麼？！是誰膽敢給燃燒軍團惹麻煩？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 3, 2, 'zhTW', '我要把你從表皮到骨髓都完全烤熟，我一定會很喜歡那滋味！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 3, 3, 'zhTW', '什麼都無法阻止你的末日！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 3, 4, 'zhTW', '你膽敢襲擊我？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 3 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 3, 5, 'zhTW', '你膽敢冒犯我！我要慢慢地將你折磨至死！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19747 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19747, 4, 0, 'zhTW', '放狗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19763 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19763, 0, 0, 'zhTW', '感謝你的仁慈，晚飯時間快到了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19764 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19764, 0, 0, 'zhTW', '我以為我死定了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19766 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19766, 0, 0, 'zhTW', '我不知道是被邪獸人吃掉更糟呢，還是為拉澤克拉茲工作更糟？不管怎麼樣，還是謝謝你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19827 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19827, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19830 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19830, 0, 0, 'zhTW', '你不會是認真的吧！我們的人手已經嚴重不足，都快要不能維持法力熔爐的正常運作了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19830 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19830, 1, 0, 'zhTW', '遵命，主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19831 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19831, 0, 0, 'zhTW', '阿爾杜尼斯，我們要你派增援去法力熔爐：杜隆。這不是請求，而是命令。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19831 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19831, 1, 0, 'zhTW', '照我的吩咐做。法力熔爐：杜隆受到魔法生物的嚴重襲擊，局勢已然失控了。如果你們不按指示隨意胡來，將受到最嚴厲的懲罰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19831 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19831, 2, 0, 'zhTW', '大人！');
