INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19831, 4, 0, 'zhTW', '你給我確保一切正常，阿爾杜尼斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19832 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19832, 0, 0, 'zhTW', '哦不，那是什麼？快用再造機甲X6000保護我們！！！');
