DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19926 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19926, 0, 0, 'zhTW', '我似乎選擇了個錯誤的日子來戒除法力吸取……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19932 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19932, 0, 0, 'zhTW', '一些非常非常煩人的事情。它們越來越頻繁地穿越時間流了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19932 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19932, 1, 0, 'zhTW', '諾薩莉，我不是在談論某個想要透過微調過去來提升他現世地位的貪婪巫師。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19932 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19932, 2, 0, 'zhTW', '親愛的，這些傢伙並不是想給他們自己搞到暴風城彩票的幸運數字這麼簡單。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19932 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19932, 3, 0, 'zhTW', '對不起，諾薩莉，我最近有點急躁。這些生物正企圖改變時間流。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19932 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19932, 4, 0, 'zhTW', '你還記得上次發生同樣的事嗎？希望主人不需要被捲入此事。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19932 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19932, 5, 0, 'zhTW', '當然不。我們不能把自己捲入危險中去。主人不在的情況下，我們都要確保時間流完整無缺。艾澤拉斯的英雄們和冒險者們估計馬上就要來了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19933 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19933, 0, 0, 'zhTW', '太迷人了。這是什麼，安多爾姆？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19933 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19933, 1, 0, 'zhTW', '唔，他們正在破壞時間流嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19933 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19933, 2, 0, 'zhTW', '我很討厭你用那種態度和我說話。我和你在任何方面都是平等，兄弟。記住下次當你困在時間漩渦裡的時候，不要哭著求我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19933 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19933, 3, 0, 'zhTW', '我們應該這樣希望嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 19933 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (19933, 4, 0, 'zhTW', '%s點了點頭。');
