DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20098 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20098, 0, 0, 'zhTW', '我在這裡，爸爸。你睡了一整天了。你一定是太累了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20100 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20100, 0, 0, 'zhTW', '這……這是夢嗎？秘藍島，秘血島，贊加沼澤，影月……甚至是祖阿曼……傑恩！傑恩你在哪裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20100 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20100, 1, 0, 'zhTW', '啊，太好了。那一切只是場夢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20101 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20101, 0, 0, 'zhTW', '虛空之風為我們帶來了什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 0, 0, 'zhTW', '在春節期間，我們應該花時間來尋找我們的長者，思考他們的智慧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 0, 1, 'zhTW', '傳說月光林地的月神湖水下沉睡著一頭年獸，一年只出水一次。不過那只是個傳說而已。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 0, 2, 'zhTW', '你看到煙火了嗎？這是一年中購買菸火的最好時刻。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 0, 3, 'zhTW', '永夜港的德魯伊們正在月光林地舉辦一個隆重的春節慶祝活動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 6, 0, 'zhTW', '我們待會再玩“不給糖果就惡作劇”的遊戲吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 6, 1, 'zhTW', '肯·定·有什麼辦法能趁這節日的時候發上一筆！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 6 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 6, 2, 'zhTW', '旅店老闆們居然免費發糖，真是瘋了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 6 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 6, 3, 'zhTW', '為了聯盟！等等……為了部落！等等，我是哪邊的來著……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 8, 0, 'zhTW', '那些漂亮的聖誕帽是哪裡來的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 8 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 8, 1, 'zhTW', '啊，冬幕歡樂製造器。下一次我們該想點什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 8 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 8, 2, 'zhTW', '每年的這個時候，煙林牧場的地精們總是會出售一些非常棒的糖果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20102 AND `GroupID` = 8 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20102, 8, 3, 'zhTW', '啊，冬幕歡樂製造器。下一次我們該想點什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 0, 0, 'zhTW', '你好，$n。我會帶你遊覽時光之穴。請跟緊我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 1, 0, 'zhTW', '我們不知道時光之穴是否一直都允許凡人進入。確切的說，我們不可能知道這一點，因為時光之王在永遠地運動著，用他認為恰當的方式來改變我們的時間流。也許你現在所看到的東西，明天就不存在了。你也可能會在昨天醒來，然後對這個地方沒有絲毫的印象。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 2, 0, 'zhTW', '這很奇怪，我知道……大部分凡人無法真正理解他們在這裡看到的東西，他們所看到往往無法和他們的理解聯絡起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 3, 0, 'zhTW', '請跟著我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 4, 0, 'zhTW', '在這裡只有兩條真理：首先，時間是混亂的，永遠在不停地變化，並且可以完全改變。第二，感覺並不代表真實。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 5, 0, 'zhTW', '作為時間的管理者，我們看管和照顧著諾茲多姆的領地。主人目前不在這裡，這就意味著他正在嘗試著劇烈地改變時間程序。主人向來不理會凡人的閒事，除了糾正其他人對時間的改變。他是非常反對這種行為的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 6, 0, 'zhTW', '對於普通的時間維護工作，時光守護者的力量是足夠的。我們可以處理大部分普通的干擾。舉個小例子來說，比如某些無賴法師們試圖改變過去的一些東西來提升他們現在的身份和財富之類的事情，不在話下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 7, 0, 'zhTW', '你看到的這些隧道被稱為時間流。它們的數量是無窮的。當前在你們的現實中存在的那個就是主人所認為的“麻煩點”。這些麻煩點也許有著完全不同的內容，但是它們通常都有著相同的原因。它們的存在是同樣的時間干擾所產生的結果，當你進入其中的一個麻煩點去冒險時，要牢記這一點……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 8, 0, 'zhTW', '這個時間流目前正處於極度的混亂中！我們派了一些人在裡面努力恢復秩序。我所能告訴你的一點資訊就是，索爾的自由正在危難中。一個被稱為永恆之龍的邪惡組織正在嘗試阻止他的逃脫。我擔心如果沒有來自外界的幫助，一切都將無可挽回。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 9, 0, 'zhTW', '關於這個時間流，我們只得到了很少的一點情報。薩艾特已經被派遣進去了。從和他的通訊中，我們獲知的情報是永恆之龍再次嘗試改變時間。很可能他們的目標是破壞黑暗之門的開啟？希望不是這樣……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 10, 0, 'zhTW', '這個時間流在塌縮後實現了重組，迴歸於往昔的斯坦索姆。什麼樣的事件正在其中上演呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 11, 0, 'zhTW', '時間流目前是按照“小災難”至“大災難”的順序排列著的。注意它們全部都是“災難”，這意味著任何一個時間流的毀滅都會終結你們的世界，沒有區別。我們把它們這樣分類，只是為了讓那些被派到這裡來的英雄們和冒險者們知道自己的能力適合處理哪個時間流中的事務。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 12, 0, 'zhTW', '這個時間流通向海加爾山，我們只知道這些。永恆之龍不顧一切地阻止我們的介入，因此我們對其它的事情絲毫沒有頭緒，凡人。索莉多米正在嘗試著突破時間流的防守，但是迄今都沒有成功。你或許是我們突破和解決這個衝突的唯一希望。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20129 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20129, 13, 0, 'zhTW', '我們的時間正處在危險的邊緣，$n。如果運氣這種東西確實存在的話，我祝你好運。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20132 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20132, 0, 0, 'zhTW', '真是可笑。這就是前來消滅我的“強大的奧爾多軍隊”嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20132 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20132, 1, 0, 'zhTW', '好吧，讓我們結束這一切吧。不管怎樣，在我們開始之前，我想讓你見一個人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20132 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20132, 2, 0, 'zhTW', '幹掉這些狗東西，凱蘭恩！提升你在燃燒軍團的地位吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20132 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20132, 3, 0, 'zhTW', '你在等什麼？解決他們，年輕人。燃燒你的仇恨吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20132 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20132, 4, 0, 'zhTW', '你這個愚蠢的老巫婆……你們兩個都是我的囊中之物，我為什麼還要跟你做交易？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20132 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20132, 5, 0, 'zhTW', '哦，天哪！這太令人作嘔了，看來我不得不親自把你們全部解決掉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20138 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20138, 0, 0, 'zhTW', '你永遠也別想得到我的阿塔瑪水晶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20138 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20138, 0, 1, 'zhTW', '我要用阿塔瑪水晶的力量幹掉你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20138 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20138, 0, 2, 'zhTW', '阿塔瑪水晶是我的了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20140 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20140, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20159 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20159, 0, 0, 'zhTW', '如果你覺得我會這麼輕易背叛我的朋友，那你就大錯特錯了！來吧，你這個無賴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20159 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20159, 1, 0, 'zhTW', '請饒我一命！我會告訴你埃雷利恩的秘密。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20201 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20201, 0, 0, 'zhTW', '不要再往前走了，凡人。你們的力量還遠遠無法對抗永恆龍軍團。過來，讓我幫助你們一把。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20209 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20209, 0, 0, 'zhTW', '警告！%s的緊急停機程式已經啟動。停機將在兩分鐘內完成。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20209 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20209, 1, 0, 'zhTW', '將在一分鐘後完成緊急停機。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20209 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20209, 2, 0, 'zhTW', '將在三十秒後緊急停機。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20209 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20209, 3, 0, 'zhTW', '將在十秒後緊急停機。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20209 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20209, 4, 0, 'zhTW', '緊急停機已完成。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20209 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20209, 5, 0, 'zhTW', '法力熔爐停機中斷。恢復法力熔爐運作。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20218 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20218, 0, 0, 'zhTW', '中斷緊急停機！凱爾薩斯大人若是知道了，我們必定人頭不保！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20218 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20218, 0, 1, 'zhTW', '馬上停下來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20218 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20218, 0, 2, 'zhTW', '納魯的緊急停機程式會讓法力熔爐永久停止運轉的！必須阻止它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20221 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20221, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20227 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20227, 0, 0, 'zhTW', '看上去該把你從籠子裡放出來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20227 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20227, 1, 0, 'zhTW', '現在，把中和劑放上去……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20227 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20227, 2, 0, 'zhTW', '成功了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20234 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20234, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20239 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20239, 0, 0, 'zhTW', '隨著中和劑與湖水混合起來，被水晶對映的湖面開始變得清澈了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20242 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20242, 0, 0, 'zhTW', '最上乘的走私貨就在這裡，$n。我的貨物都是居家旅行殺人滅口的好東西。避開了地精的稅收和納魯的禁令——星界財團會滿足你方方面面的購物需求！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20243 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20243, 0, 0, 'zhTW', '%s的機械心臟開始輕微地跳動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20279 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20279, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20280 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20280, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 0, 0, 'zhTW', '讓我們以輕鬆輕快的步伐前進。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 1, 0, 'zhTW', '我們會從第一個能量塔開始，一直往前。記住，讓他們離我遠點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 2, 0, 'zhTW', '我已經把這個塔架修好了。下一個。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 3, 0, 'zhTW', '好的，二號塔架下。現在是匯流閥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 4, 0, 'zhTW', '必須那樣做，機器馬上要爆炸了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 4, 1, 'zhTW', '好吧，讓我們離開這兒吧。！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 5, 0, 'zhTW', '謝謝, $N！沒有你我做不到。你會讓加魯斯知道嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20281 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20281, 6, 0, 'zhTW', '讓他們滾遠點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 0, 0, 'zhTW', '愚蠢的小傢伙！我打！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 0, 1, 'zhTW', '我抓狂了。我要抽你的臉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 0, 2, 'zhTW', '啊！！！我要幹掉$r！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 1, 0, 'zhTW', '弱小的$r……你是一個……可怕的$g國王:女王。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 1, 1, 'zhTW', '啊……我……死了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 1, 2, 'zhTW', '我要去……奧格瑞拉了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 1, 3, 'zhTW', '$G國王:女王陛下，你覺得……世上真的有個……奧格瑞拉嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20334 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 1, 4, 'zhTW', '偉大的$g國王:女王陛下，殺了我吧……我很榮幸。');
