INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20334, 1, 5, 'zhTW', '$g國王:女王$n陛下，我現在死了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20342 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20342, 0, 0, 'zhTW', '什麼事，納特？');
