INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20342, 2, 0, 'zhTW', '你那根笛子裡裝著什麼，納特？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20342 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20342, 2, 1, 'zhTW', '納特，這是我聽過的最可笑的夢了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20342 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20342, 2, 2, 'zhTW', '這不可能！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 0, 0, 'zhTW', '哈爾……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 1, 0, 'zhTW', '昨晚我又做了那個夢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 2, 0, 'zhTW', '那個夢……那個瘋狂的夢。記得嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 3, 0, 'zhTW', '塔倫米爾被某種瘋狂的亡靈力量毀滅了，而且永遠地變成了南海鎮的敵人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 4, 0, 'zhTW', '你能想象這件事嗎，哈爾？你能嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 5, 0, 'zhTW', '那是個成千上萬的人們都從天上看著我們的地方……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 6, 0, 'zhTW', '我們就像他們的傀儡——我們不管做什麼都是為了讓他們開心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 7, 0, 'zhTW', '有時候，甚至在我清醒的時候，我都覺得他們正監視著我們。也許他們現在正監視著我們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 8, 0, 'zhTW', '然後我夢到一座長著大樹的山，一群精靈們到處跑來跑去……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 9, 0, 'zhTW', '不知道從哪裡冒出來的一個300尺高的惡魔或者什麼東西走了過來，開始爬樹……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 10, 0, 'zhTW', '聽起來很瘋狂吧？更瘋狂的還在後面呢。那個巨大的惡魔被一群飄在空中的小光球給炸死了……哦，我在夢中是一個女精靈……對……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 11, 0, 'zhTW', '在這個夢裡，我是這個世界中的釣魚大師。我搬到了一個名叫卡林多的地方……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 12, 0, 'zhTW', '從世界各地來的人們走到我面前對我表示敬意……在我這裡學習釣魚。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 13, 0, 'zhTW', '我就像什麼釣魚之神那樣……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 14, 0, 'zhTW', '還有一個非常可怕的夢……國王的兒子，阿爾薩斯……他和烏瑟爾一起對抗邪惡……*納特擦了擦他的額頭*');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 15, 0, 'zhTW', '不幸的是，阿爾薩斯被邪惡吞噬了，最終變成了邪惡本身……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 16, 0, 'zhTW', '他假裝好意地回到了國王身邊，拔出佩劍，跑向國王，對著國王就這麼……你知道……咔嚓一聲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 17, 0, 'zhTW', '我根本不能相信這個……你知道那兩個大嘴巴的惡棍，弗洛爾和提古勒嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 18, 0, 'zhTW', '在那個夢裡，他們不知透過什麼手段，發明了一種叫做冰淇淋的東西，還用草莓來調味……好吧，長話短說，他們最後變得十分富裕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 19, 0, 'zhTW', '還不夠瘋狂麼？我還夢到他們退出冰淇淋生意，變成了冒險家……他們周遊了全世界，隨後消失在什麼傳送門裡。我隨即就醒了，出了一身冷汗……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 20, 0, 'zhTW', '我還夢到敦霍爾德，布萊克摩爾那個的獸人奴隸逃跑了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 21, 0, 'zhTW', '他最終摧毀了整個城堡，救出了所有被我們關在營地的獸人。他成為了獸人的國王……酋長之類的什麼東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20344 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20344, 22, 0, 'zhTW', '太瘋狂了，不是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 0, 0, 'zhTW', '小聲點。周圍有陌生人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 1, 0, 'zhTW', '兄弟姐妹們，今天我把你們召集到這裡，是為了討論洛丹倫的命運。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 2, 0, 'zhTW', '我聽說發生了一些事情……一些不應該發生的事情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 3, 0, 'zhTW', '死者復生……亡靈，在北裂境那片冰冷的大陸。整個城市突然消失得無影無蹤。我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 4, 0, 'zhTW', '我聽說北裂境已經淪陷了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 5, 0, 'zhTW', '我們必須隨時準備好。我曾經面對過這些亡靈。他們是殘忍的殺人機器，毫無同情和憐憫。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 6, 0, 'zhTW', '建議？我建議我們現在就準備起來。為亡靈可能對我們的愛人、家人和朋友展開的屠殺準備起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 7, 0, 'zhTW', '就是這個……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 8, 0, 'zhTW', '我得到這個東西已經有十年了。自從黑石塔……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 9, 0, 'zhTW', '我把它從一個獸人軍官……一個黑暗的施法者的遺體上拿了下來……這是從他們的家鄉帶來的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 10, 0, 'zhTW', '不要太靠近了。我曾經把手放在上面……就那麼一次。那天的記憶至今仍然在我腦海裡浮現。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 11, 0, 'zhTW', '我猜想這個東西是暗影的實體化身……黑暗的表象。它是一塊虛空的領域。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 12, 0, 'zhTW', '不，老朋友，這很有關係。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 13, 0, 'zhTW', '讓我來問你們一個問題，兄弟姐妹們：善可以離開惡而存在嗎？光明可以離開黑暗而存在嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 14, 0, 'zhTW', '如果答案是否定的，那麼這很可能就是它存在的原因，這個東西的另一個極端是否也必然存在呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 15, 0, 'zhTW', '你們能否想象聖光的實體會對亡靈造成什麼樣的破壞？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 16, 0, 'zhTW', '它吞噬了聖光！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 17, 0, 'zhTW', '以聖光的名義！真的是這樣嗎？這就是我們所需要的東西嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 18, 0, 'zhTW', '我必須知道……我會知道的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 19, 0, 'zhTW', '太……太……太漂亮了。當我碰到它的時候，我感覺到……聖光在我體內流過，我覺得它……它治癒了我的靈魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 20, 0, 'zhTW', '讓我們再也不要提起今天這件事情。我們有太多的敵人。他們不需要知道我們手中有這麼一件寶貝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 21, 0, 'zhTW', '我看到了……我從這塊神聖的水晶中看到了……我們會鑄造一件武器。這件武器中包含著我們每個人的力量……當它面對亡靈時，它會釋放出這種力量，毀滅它們。這把武器所到之處，留下的只有灰燼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 22, 0, 'zhTW', '%s放低了他的聲音。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 23, 0, 'zhTW', '驚訝的聲音傳遍了整個房間。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 25, 0, 'zhTW', '%s開啟了箱子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 26, 0, 'zhTW', '%s從他的右臂上脫下了手套，在大家面前露出了他那扭曲的手。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 27, 0, 'zhTW', '%s搖了搖頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 28, 0, 'zhTW', '眾人震驚了片刻，隨即是一片沉默。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 29, 0, 'zhTW', '%s伸出手去觸控光明水晶。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20345 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20345, 30, 0, 'zhTW', '%s把水晶放回了箱子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20346 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20346, 0, 0, 'zhTW', '我不知道這個邪惡的東西會跟亡靈有什麼關係。我們必須摧毀它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20346 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20346, 1, 0, 'zhTW', '一派胡言，莫格萊尼！這東西必須被摧毀掉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20346 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20346, 2, 0, 'zhTW', '你的手！傷口癒合了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20346 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20346, 3, 0, 'zhTW', '灰燼使者……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20347 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20347, 0, 0, 'zhTW', '以聖光的名義！這是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20347 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20347, 1, 0, 'zhTW', '灰燼使者……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20348 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20348, 0, 0, 'zhTW', '它……它在變亮？它的顏色……正在改變。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20348 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20348, 1, 0, 'zhTW', '灰燼使者……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20349 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20349, 0, 0, 'zhTW', '是的，我也和他們交手過。我們的王國還沒有準備好抵擋這種進攻。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20349 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20349, 1, 0, 'zhTW', '這不可能！');
