INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20350, 0, 0, 'zhTW', '小聲點，赫爾庫拉。周圍都是陌生人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20350 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20350, 1, 0, 'zhTW', '通靈術。它叫通靈術。沒錯，我把它和我的力量結合在了一起。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20350 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20350, 2, 0, 'zhTW', '這和你無關，赫爾庫拉，你既不是肯瑞託的一員也不是一個通靈師。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20350 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20350, 3, 0, 'zhTW', '但是老實說，我對肯瑞託的想法一點也不感興趣！他們是群蠢貨，一群沉迷在他們古老腐朽的習慣中的蠢貨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20350 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20350, 4, 0, 'zhTW', '時機恰當的時候，赫爾庫拉……等到時機恰當的時候……');
