DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20353 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20353, 0, 0, 'zhTW', '那麼你真的可以教我這個……這個……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20353 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20353, 1, 0, 'zhTW', '肯瑞託呢？他們對通靈術有什麼看法？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20353 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20353, 2, 0, 'zhTW', '那麼，克爾蘇加德，教我吧，把你知道的東西都教給我……');
