INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20464, 1, 0, 'zhTW', '謝謝你帶回了我的貝希，$N。沒有她我簡直活不下去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20474 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20474, 0, 0, 'zhTW', '保護好那些管道！阻止入侵者！');
