INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20552, 0, 0, 'zhTW', '嘿！嘿，你！$R！到那邊去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20555 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20555, 0, 0, 'zhTW', '是誰，膽敢把這侮辱性的東西放在苟克的巢穴前？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20555 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20555, 1, 0, 'zhTW', '誰膽敢把苟克從沉睡中喚醒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20555 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20555, 2, 0, 'zhTW', '你的名字對我來說，像成千上萬的在苟剋死掉的人一樣微不足道。我要殺了你和$N。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20600 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20600, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20603 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20603, 0, 0, 'zhTW', '快接近阿克努斯了。我能感覺到他。走西北那條道。他應該就在那邊的拐角處。準備戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20603 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20603, 1, 0, 'zhTW', '這是一條錯誤的路，阿克努斯在另一條礦洞的盡頭。你不是膽小鬼，對吧？我可不會跟一個膽小鬼一起。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20610 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20610, 0, 0, 'zhTW', '%s向附近的雄羊呼救！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20677 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20677, 0, 0, 'zhTW', '你給了我自由！風之靈又一次願意與族人們交流並賜予我們力量了。謝謝你，陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20678 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20678, 0, 0, 'zhTW', '我自由了！我會請求火焰之靈回到族人身邊去，這樣我們或許就能鼓起勇氣反抗主人了！謝謝你，$R。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20679 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20679, 0, 0, 'zhTW', '我自由了！水流之靈將回到族人身邊去。在它的指引下，我們終將在這片荒蕪的土地上生存下去。我欠你一個人情，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20680 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20680, 0, 0, 'zhTW', '是那個破碎者渣滓給你這根法杖的吧？他有沒有告訴你，他就是那個出賣自己同胞的傢伙？無所謂，你們兩個都會為此付出代價的！');
