INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20756, 1, 3, 'zhTW', '$G國王:女王陛下，你覺得……世上真的有個……奧格瑞拉嗎？');
