INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20778, 0, 0, 'zhTW', '%s分裂成了小水滴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20787 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20787, 0, 0, 'zhTW', '你救了我的命！我會把你的功績彙報給阿米爾的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 0, 0, 'zhTW', '自從我們的死敵被允許進入我們的城市後，我的心中充滿著仇恨。那個沃雷塔爾被稱為先知以前，我就認識他了。正是他親手殺死了我的兄弟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 1, 0, 'zhTW', '我把那仇恨轉移到了伊利達雷和燃燒軍團身上……但是他們並不是那些背叛我們的傢伙。納魯選擇了我們！我們為了他們戰鬥到死！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 2, 0, 'zhTW', '當我心中的仇恨開始凝聚之後，整件事情就開始變得清晰起來。撒塔斯城必須和納魯一起被毀滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 3, 0, 'zhTW', '你錯了，阿德因。我的想法從來沒有這麼清晰過。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 4, 0, 'zhTW', '是……主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 5, 0, 'zhTW', '老師……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 6, 0, 'zhTW', '不！我都做了些什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20794 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20794, 7, 0, 'zhTW', '聖光賜予我力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 0, 0, 'zhTW', '我們開始吧……掩護我，我會做好這個工作的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 1, 0, 'zhTW', '以卡瑞許的第二個太陽之名，看這個地方！我只能認為薩哈達爾正在計劃著什麼。加油，我們繼續。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 2, 0, 'zhTW', '看那邊！薩哈達爾的管道！他一直吃得很不錯嘛……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 3, 0, 'zhTW', '好吧，在我放置這干擾器的時候好好保護我。這不會花費太長時間的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 4, 0, 'zhTW', '完成了！後退！後退！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 5, 0, 'zhTW', '我在這裡的工作大概已經完成了。去發射器塞塔那裡向阿米爾的影像報告吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20802 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20802, 6, 0, 'zhTW', '我受到攻擊！重複一遍，我受到攻擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20812 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20812, 0, 0, 'zhTW', '這是我最後一次被抓住！我保證！再見！');
