INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 1, 0, 'zhTW', '激怒我可不是個好主意！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 2, 0, 'zhTW', '完全不是我的對手，和其他的傢伙一樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 2, 1, 'zhTW', '你選錯了對手。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 3, 0, 'zhTW', '旋風斬！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 3, 1, 'zhTW', '我要把你們削成碎片！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 4, 0, 'zhTW', '感覺好多了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 4, 1, 'zhTW', '啊……真是太及時了。');
