DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 6, 0, 'zhTW', '嘿，你這就頂不住了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 6, 1, 'zhTW', '看起來我得獨自解決他們了。');
