INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 6, 2, 'zhTW', '我已經習慣於幫你收拾殘局了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 7, 0, 'zhTW', '恭喜。我想幹掉他已經很久了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 8, 0, 'zhTW', '我為什麼要叫你？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 9, 0, 'zhTW', '如果我想找人來像個肥胖的孔雀一樣走臺步，那我會叫你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20885 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20885, 10, 0, 'zhTW', '你還知道保證這個詞啊，sheet-sah？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 0, 0, 'zhTW', '你們是來殺達爾莉安的嗎？我可以在旁邊看嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 1, 0, 'zhTW', '終於有個發洩怒氣的目標了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 2, 0, 'zhTW', '啊，真令人滿足。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 3, 0, 'zhTW', '看招！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 3, 1, 'zhTW', '儘量保住自己的小命吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 4, 0, 'zhTW', '我就知道……這是唯一的結局。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 5, 0, 'zhTW', '遇到麻煩了嗎，達爾莉安？嘖嘖。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 5, 1, 'zhTW', '你八成活不過今天了，達爾莉安。多丟人啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 5 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 5, 2, 'zhTW', '我想到一個新的戰術，你吸引他們的火力，我去找援兵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 6, 0, 'zhTW', '哈哈！幹得好！');
