INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 7, 0, 'zhTW', '你剛才叫我？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 8, 0, 'zhTW', '大概是幫你搬東西之類的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 9, 0, 'zhTW', '我保證那時候我會對你不理不睬的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20886 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20886, 10, 0, 'zhTW', '你真應該被——等等，我們有伴了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 0, 0, 'zhTW', '我知道王子殿下會非常生氣，但是我……我不知道自己怎麼回事，居然把它們都放出來了！主人在對我說話，你也看到了……等等，有人來了。你們不是凱爾薩斯派來的！好極了……我會告訴王子殿下，是你們放走了囚犯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 1, 0, 'zhTW', '納魯把多種宇宙中最危險的怪物關在這些牢籠裡。請允許我向你們介紹下一種……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 2, 0, 'zhTW', '很好，很好……又是一個！你的意志是我的了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 3, 0, 'zhTW', '看吧！又一個擁有深不可測的力量的恐怖生物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 4, 0, 'zhTW', '這是什麼？一個卑微的地精？我下次會做得更好的，主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 5, 0, 'zhTW', '混亂！瘋狂！啊，您真是太睿智了！是的，我明白了，當然！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 6, 0, 'zhTW', '還剩下最後一個牢籠。好的，主人，馬上！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20904 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20904, 7, 0, 'zhTW', '歡迎您，主人。我是您謙卑的奴僕。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20905 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20905, 0, 0, 'zhTW', '我要去做飯了呀，然後我們去吃飯呀！');
