INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20911, 0, 0, 'zhTW', '可憐的下等凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20911 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20911, 1, 0, 'zhTW', '巨龍軍團會……吞噬你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 0, 0, 'zhTW', '控制弱者的思想是非常容易的事情……因為我所效忠的不被時間改變的力量，不被命運左右的力量。這個世界上沒有什麼力量能與此匹敵……即使是燃燒軍團也不行！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 1, 0, 'zhTW', '你們的死期到了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
