DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 3, 1, 'zhTW', '你的意志不屬於你自己。');
