INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 4, 0, 'zhTW', '恐懼吧！逃跑吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 4, 1, 'zhTW', '我會讓你體驗到前所未有的恐懼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 5, 0, 'zhTW', '我們遍佈宇宙的每一個角落，像群星一樣無窮無盡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20912 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20912, 6, 0, 'zhTW', '我只是一個……不值一提的小角色。');
