INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20923, 4, 0, 'zhTW', '為了卡加斯！為了勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 0, 0, 'zhTW', '我這是在什麼鬼地方？你們又是誰……啊啊啊，頭好疼啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 1, 0, 'zhTW', '“卑微”？我不在乎你是誰，夥計。沒有人敢說強大的米爾豪斯是個“卑微”的地精！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 2, 0, 'zhTW', '等等，我要準備一下。你們先上，我先來做點水……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 3, 0, 'zhTW', '好極了！接下來，還得有些保護性的法術。耶！這樣就對了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 4, 0, 'zhTW', '當然，我得先補充法力值。你們會看到我發威的，再等一會就行了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 5, 0, 'zhTW', '好啦！那麼是哪個蠢貨準備好好挨一頓打？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 6, 0, 'zhTW', '我甚至都沒有流一滴汗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 6, 1, 'zhTW', '你們隨時都可以來跟我一起作戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 7, 0, 'zhTW', '我要把你們烤熟了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 8, 0, 'zhTW', '冰冰涼，寶貝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 9, 0, 'zhTW', '治療我！天殺的，趕快治療我！我要嗝屁了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 10, 0, 'zhTW', '你很快就會收到我的律師函了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 11, 0, 'zhTW', '誰最猛？誰最猛？沒錯！我們最猛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 12, 0, 'zhTW', '我不知道這裡發生了什麼事情，但是我會很高興和你們一起收拾這個無理的蠢材！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20977 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20977, 13, 0, 'zhTW', '等死吧！白痴！');
