INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20985, 2, 0, 'zhTW', '機不可失，戰士們！讓我們上吧，為了卡瑞許！為了星界財團！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 20985 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (20985, 3, 0, 'zhTW', '你滅亡的日子到了，迪門修斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 0, 0, 'zhTW', '靠後，$n。靈魂可能會傷害到你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 1, 0, 'zhTW', '我們希望能幫助你，靈魂。我們尋求你的智慧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 2, 0, 'zhTW', '你是對的，靈魂。是我的同胞對你們做了這些錯事，但是請讓我們糾正這一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 3, 0, 'zhTW', '請告訴我們：森盧肯是誰，或者說，是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 4, 0, 'zhTW', '火……火焰之王？那不是一位元素之王嗎？難怪……古爾丹，你這個該死的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 5, 0, 'zhTW', '肯定有辦法解決的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 6, 0, 'zhTW', '不要懷疑我和我的朋友，靈魂。請告訴我們怎樣才能召喚炎魔之王。我的朋友們會消滅他的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 7, 0, 'zhTW', '我們會找到這些咒語。我們會召喚你的主人，並把他消滅掉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 8, 0, 'zhTW', '%s點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 9, 0, 'zhTW', '現在去找回遺失的咒語吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 10, 0, 'zhTW', '%s鞠了一躬。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21024 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21024, 11, 0, 'zhTW', '我聽到的和你一樣，兄弟。看看你身後……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21027 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21027, 0, 0, 'zhTW', '是痛苦的靈魂，我察覺到了。$n。他們在這裡，快點過來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21027 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
