INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21027, 2, 0, 'zhTW', '保護我，$n。我必須衝破他們邪惡的魔法！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21027 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21027, 3, 0, 'zhTW', '庫斯卡的納迦對他們的戰俘異常兇殘。我能在水牢裡活這麼長時間真是個奇蹟。感謝大地之母。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21027 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21027, 3, 1, 'zhTW', '瓦絲琪女王必須為這些暴行負責。她必將得到制裁！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21027 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21027, 3, 2, 'zhTW', '被折磨的水之魂在艾澤拉斯世界和德拉諾世界的水道中躁動……');
