INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21027, 6, 0, 'zhTW', '謝謝你，$n。請回去轉告我的兄弟，告訴他們維爾達安全了，他們在古爾丹之手附近的詛咒祭壇那裡。願大地之母保佑你……');
