INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21129, 1, 0, 'zhTW', '蠢貨！火焰之王森盧肯！當聯絡被切斷的時候，森盧肯醒了，是森盧肯的淚水注滿了這片遍是熔岩的大地。');
