INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21411, 0, 0, 'zhTW', '%s把腐爛的蛋敲碎，然後在眾目睽睽之下開始吮吸它腐爛的核心。');
