INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21411, 3, 0, 'zhTW', '那麼好吧，回去工作。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21426 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21426, 0, 0, 'zhTW', '騎兵們，讓我們殺出去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21427 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21427, 0, 0, 'zhTW', '你們需要什麼幫助嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21466 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21466, 0, 0, 'zhTW', '我將向你展示你做夢也想不到的噩夢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21466 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21466, 0, 1, 'zhTW', '我們跨越宇宙，像星河一樣浩瀚！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21467 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21467, 0, 0, 'zhTW', '我只是……無盡中的一員。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21469 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21469, 0, 0, 'zhTW', '太好了，$n，你正在受到魔法的影響。我必須馬上分析它，然後我們再談談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21502 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21502, 0, 0, 'zhTW', '末日領主卡扎克會高興的。你最好加快你進攻的步伐，用最快的速度消滅這些獸人和矮人的要塞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21502 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21502, 1, 0, 'zhTW', '不要擔心。我已經提高了死亡熔爐的產量，你會擁有足夠的地獄火的。不要讓我失望，約瓦安。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21502 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21502, 2, 0, 'zhTW', '嗯？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21502 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21502, 3, 0, 'zhTW', '箱子？我沒有給你箱子啊，約瓦安。你是不是應該去關心點別的？去工作！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 0, 0, 'zhTW', '確實，這不是一個要求。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 1, 0, 'zhTW', '杜隆必須得到增援！烏提斯完全是個災難。我不允許這種錯誤重演！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 2, 0, 'zhTW', '一路上我們受到了太多的挫折：地獄火堡壘、墜星山、火翼崗哨……凱爾薩斯王子不能再容忍任何延誤了。除了成功，我什麼都不想看到。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 3, 0, 'zhTW', '我要返回風暴要塞了。你們最好不要讓我有回來的理由！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 4, 0, 'zhTW', '暫時可以說不錯。無論如何，請將我的到來作為一個催促的訊號。凱爾薩斯王子對墜星山地區的水晶實驗的失敗很不滿意，這也是我們選擇塞納里奧的德魯伊們作為炸彈試驗地的原因之一。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 5, 0, 'zhTW', '如果院子裡的那顆魔法炸彈沒有很快對目標發射，不需要我再跟你說會發生什麼事情了吧？自從我們到了森林裡，不管是這裡，還是在圖雷姆，或是南面的噬骨廢墟，他們對我們行動的干擾都愈加地煩人了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 6, 0, 'zhTW', '我們應該給聯盟和部落一點教訓。刻骨銘心的教訓！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 7, 0, 'zhTW', '確保這一點，沙爾斯。否則我會親自看到你慢慢地被折磨致死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 8, 0, 'zhTW', '我似乎認得他們。快點解決掉這裡的麻煩，沙爾斯。然後用魔法炸彈摧毀他們的城鎮！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 9, 0, 'zhTW', '你以為你在做什麼？你居然敢幹擾我主人的試驗？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 10, 0, 'zhTW', '你喜歡我們在這兒做的事情嗎？也許我們會從整個外域的天空丟下這種水晶。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 11, 0, 'zhTW', '我對你在這兒治癒土地、平息能量召喚、讓巨人瘋狂的行為感到了厭煩。巨人之王葛利安索恩，凱爾薩斯王子和我要求你保護水晶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 12, 0, 'zhTW', '我們很快就會再見面的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 13, 0, 'zhTW', '起來，年輕的沃多恩。別自尋煩惱了。我奉了我們主人凱爾薩斯王子之命前來。他讓我檢查魔法炸彈的進展情況。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 20, 0, 'zhTW', '你以為你在做什麼？你居然敢幹擾我主人的試驗？ ');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 21, 0, 'zhTW', '你喜歡我們在這兒做的事情嗎？也許我們會從整個外域的天空丟下這種水晶。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 22, 0, 'zhTW', '我對你在這兒治癒土地、平息能量召喚、讓巨人瘋狂的行為感到了厭煩。巨人之王葛利安索恩，凱爾薩斯王子和我要求你保護水晶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21504 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21504, 23, 0, 'zhTW', '我們很快就會再見面的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21514 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21514, 0, 0, 'zhTW', '是誰膽敢汙染食龍者高格魯姆的祭壇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21514 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21514, 1, 0, 'zhTW', '等我搞定之後，我要把它碾碎，剝皮，吃肉，然後把它的骨頭一塊一塊敲成渣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21633 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21633, 0, 0, 'zhTW', '萬事俱備了，戰爭使者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21633 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21633, 1, 0, 'zhTW', '戰爭使者，這可能需要動用要塞中所有的地獄火，我們也許會很容易遭到反擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21633 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21633, 2, 0, 'zhTW', '謹遵教誨，戰爭使者。還有最後一個問題，我是否可以……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21633 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21633, 3, 0, 'zhTW', '箱子裡有什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21644 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21644, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21648 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21648, 0, 0, 'zhTW', '謝謝你，凡人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 0, 0, 'zhTW', '%s變得狂怒無比！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 0, 'zhTW', '你的末日到了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 1, 'zhTW', '別想輕易逃跑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 2, 'zhTW', '我會得到獎賞的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 3, 'zhTW', '毀滅降臨了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 4, 'zhTW', '以薩格拉斯的名義！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 5, 'zhTW', '我必須這麼做！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 6, 'zhTW', '燃燒軍團是世界的主宰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21661 AND `GroupID` = 1 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21661, 1, 7, 'zhTW', '蠢貨，哪兒都別想去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 0, 0, 'zhTW', '你不是一個人在戰鬥，你不是一個人，$n！讓我們一起放逐這地獄之火的子嗣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 1, 0, 'zhTW', '那麼我們走了，託洛克。我只有一個要求……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 2, 0, 'zhTW', '歐魯諾克·裂心等人把他們的武器交給了大地治癒者託洛克。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 3, 0, 'zhTW', '把這些武器交給英雄們，助他們一臂之力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 4, 0, 'zhTW', '我們會用武力把元素之靈從你的魔掌中解救出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 5, 0, 'zhTW', '你準備好了我們就開戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 6, 0, 'zhTW', '元素們說了些什麼，託洛克？我什麼都沒聽到。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21685 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21685, 7, 0, 'zhTW', '他們得到了救贖！那麼我們勝利了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21687 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21687, 0, 0, 'zhTW', '結……結束了嗎？它被摧毀了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21694 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21694, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21699 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21699, 0, 0, 'zhTW', '快點放了我！不然就面對我的憤怒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21699 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21699, 1, 0, 'zhTW', '如果我們期望的是同一件事，阿卡瑪，那麼你就放了我！如果伊利丹要死，那也要是死在我的手上！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21699 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21699, 2, 0, 'zhTW', '我詛咒你，阿卡瑪！我不是你的棋子……我有我自己的意志。當我對伊利丹傾瀉我的憤怒時，那必定和你愚蠢的陰謀沒有任何關係！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 0, 0, 'zhTW', '不要害怕，$r。繼續假裝下去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 1, 0, 'zhTW', '一點小麻煩而已，我保證！請轉告主人，阿卡瑪和他手下的死誓者會盡心盡職地看守囚犯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 2, 0, 'zhTW', '請原諒我的粗暴，我不能讓背叛者知道真相。無論如何都要守住我的秘密！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 3, 0, 'zhTW', '不會太久了，瑪維。我花了這麼多年來籌劃我的行動——我不能讓這個計劃因為操之過急而毀於一旦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 4, 0, 'zhTW', '憤怒之心……很久以前，維倫持有它的時候，我目睹過它的力量。而現在，我依然可以感覺到相同的力量正在它內部澎湃著！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 5, 0, 'zhTW', '有了這塊水晶的力量，我的死誓者和我……將會不可抵擋！我們甚至可以消滅伊利丹！我們可以……替代他成為新的外域之王！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 6, 0, 'zhTW', '但那不是納魯在我的夢境中給予我的指示……那不是……我解救同胞的方式。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 7, 0, 'zhTW', '$n，你必須把憤怒之心帶到安全的地方去……你必須把它交給阿達爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 8, 0, 'zhTW', '奧魯姆，我的老朋友。看到你一切安好，真是令人欣慰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 9, 0, 'zhTW', '伊利丹會起疑心，這是毫無疑問的。不過我們會挺過去的，一直以來不都是這樣嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 10, 0, 'zhTW', '你……不要開玩笑，奧魯姆。你已經做出了太多的犧牲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 11, 0, 'zhTW', '看來你已經做出了決定，那麼好吧。我們會儘可能讓你進入靈魂世界的過程沒有痛苦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 12, 0, 'zhTW', '再會，我的朋友。當我們在這個世界的使命完結之後，就可以在另一個世界中再次相聚了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 13, 0, 'zhTW', '主人！我們抓住了從瓦絲琪那裡逃跑的叛徒！他的屍體就躺在我的面前！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 14, 0, 'zhTW', '但是，大人！您誤解了我的行動……我確實知道有個您非常信任的人想要背叛您，他就是凱爾薩斯那條狗！他現在投靠了基爾加丹，想要取代您，統治外域！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21700 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21700, 15, 0, 'zhTW', '遵命，大人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21717 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21717, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21739 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21739, 0, 0, 'zhTW', '保重，凡人……大地治癒者瞭解火焰之靈的感受……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21739 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21739, 1, 0, 'zhTW', '就應該是現在這樣，薩滿祭司。你幹得不錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21740 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21740, 0, 0, 'zhTW', '是的……對這裡的元素來說，已經很好了，但是密碼已經被別人知道了……火焰之靈正在騷動……如果不阻止這股力量，這些凡人所屬的世界將會滅亡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21767 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21767, 0, 0, 'zhTW', '哪個$r竟敢傷害我的手下？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21768 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21768, 0, 0, 'zhTW', '這裡有凡人？這是什麼意思，你這可悲的破碎者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21768 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21768, 1, 0, 'zhTW', '阿卡瑪，別跟我耍花招。伊利丹大人要我密切注視瑪維·影歌的一舉一動。要是你敢對我隱瞞什麼，我就親手捏碎你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21769 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21769, 0, 0, 'zhTW', '你想從我這裡得到什麼，薩滿祭司？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21769 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21769, 1, 0, 'zhTW', '你瞎了嗎？你沒看見惡魔已經打到家門口了嗎？我沒有人手給你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21769 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21769, 2, 0, 'zhTW', '向你的神祈禱吧，薩滿祭司。也許他們會來幫助你的。然而部落是不可能……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21771 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21771, 0, 0, 'zhTW', '有這樣的獎勵，他們怎麼可能拒絕呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21773 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21773, 0, 0, 'zhTW', '我不明白！你瞎了嗎？你沒看到惡魔們正在攻擊我們的大門嗎？我能派誰出去和你的薩滿朋友談話？告訴我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21780 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21780, 0, 0, 'zhTW', '%s開始將能量輸送給迪門修斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21797 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21797, 0, 0, 'zhTW', '你的軀體為我所有！我們的命運將永遠糾纏在一起！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21797 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21797, 1, 0, 'zhTW', '我們總有一天……會再見面的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21797 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21797, 2, 0, 'zhTW', '死亡的化身再度降臨這個世界！塔隆·血魔回來了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21838 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21838, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21838 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21838, 1, 0, 'zhTW', '呱！你殺不了我，我是無敵的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21838 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21838, 2, 0, 'zhTW', '%s看見手中的盾牌破碎之後，更加惱怒了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21861 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21861, 0, 0, 'zhTW', '在最黑暗的夜晚，烏鴉將再次飛起，它將飛入陰影，顯露本性。當它到來之時，虔誠的信徒會隨它一併飛翔，剩餘的人將被遺忘在大地之上，夾著翅膀羞愧不已。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21861 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21861, 1, 0, 'zhTW', '堅定你的信念，扞衛你的想法。黑暗之翼會淹沒與吞噬弱者的信念。他們的雙腳將永遠無法離開大地高飛。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21861 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21861, 2, 0, 'zhTW', '古神的血液會因為烏鴉的到來而再度流淌，黑暗將在天際重現。猩紅的夜晚，古神將會復生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21861 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21861, 3, 0, 'zhTW', '烏鴉曾因貿然飛得太高而被擊落。黑暗守望者為了他的飛翔準備了億萬年，就是為了在地平線上拉起黑暗的斗篷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21867 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21867, 0, 0, 'zhTW', '我們總有一天……會再見面的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21867 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21867, 1, 0, 'zhTW', '死亡的化身再度降臨這個世界！塔隆·血魔回來了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21872 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21872, 0, 0, 'zhTW', '不要浪費時間，蠢貨！用我們的力量來消滅那些擋路的傢伙！在你被抑制之前消滅卡修斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21873 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21873, 0, 0, 'zhTW', '以納沙塔爾的名義！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21873 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21873, 0, 1, 'zhTW', '死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21873 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21873, 0, 2, 'zhTW', '主人至高無上！');
