INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21875, 1, 0, 'zhTW', '我終於解放了，我很久沒嚐到自由的味道了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21877 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21877, 0, 0, 'zhTW', '血魔，你最好打消逃跑的念頭。離開這個$G小夥子:姑娘的軀體，投降吧！即便你全力以赴，也是不可能逃走的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 21877 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21877, 1, 0, 'zhTW', '你……做了些什麼……');
