INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (21983, 0, 0, 'zhTW', '嗯，他是拜龍教的人，西邊黑翼集會所的副指揮。');
