INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22006, 1, 0, 'zhTW', '你永遠都別想得到憤怒之心！那是屬於伊利丹大人的！');
