INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22083, 2, 0, 'zhTW', '你給我閉嘴，白痴。你真是個不可理喻的蠢材……');
