INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22083, 6, 0, 'zhTW', '我希望立即在神殿內看到這個渣滓的屍塊。否則你們就將遭受比死亡更痛苦的命運！');
