INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22314, 0, 4, 'zhTW', '哈哈！我們愛你！你救了我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22343 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22343, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22366 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22366, 0, 0, 'zhTW', '謝謝你肯讓我洞察你的內心，$n。你的靈魂很有趣，只是比我想象得要聰明許多……不然我還會多待一會兒的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22373 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22373, 0, 0, 'zhTW', '更多泰羅克的奴僕過來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22373 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22373, 1, 0, 'zhTW', '入侵者持續不斷地湧了過來！守住！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22373 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22373, 2, 0, 'zhTW', '泰羅克的化身！！準備戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22373 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22373, 3, 0, 'zhTW', '泰羅克的化身被擊敗了！去死吧，泰羅克！去死吧，斯克提斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22373 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22373, 4, 0, 'zhTW', '%s指向天空。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22374 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22374, 0, 0, 'zhTW', '是哪個膽大妄為的傢伙殺死了卡加斯指揮官？我要你用生命償還這一切！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22377 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22377, 0, 0, 'zhTW', '讓我們離開這個地方，我受夠了這些瘋子了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22377 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22377, 1, 0, 'zhTW', '小心！更多教徒過來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22377 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22377, 2, 0, 'zhTW', '我在這兒能找到回去的路了。我的朋友米克達會為你的友善行為付出獎勵的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22381 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22381, 0, 0, 'zhTW', '無能的蠢貨！奧金頓是我們的……瞧瞧你們那抱頭鼠竄的醜樣兒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22384 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22384, 0, 0, 'zhTW', '你去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22396 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22396, 0, 0, 'zhTW', '%s變得怒不可遏！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22424 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22424, 0, 0, 'zhTW', '%s尖叫著走向沙拉斯鴉巢，快跟上！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22424 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22424, 1, 0, 'zhTW', '%s在樹前稍作停留，又繼續向裡走。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22424 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22424, 2, 0, 'zhTW', '%s好像在找什麼東西。他示意你跟著他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22424 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22424, 3, 0, 'zhTW', '%s飛到了下面的平臺。如果你想跟上就跳下去，快點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22424 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22424, 5, 0, 'zhTW', '終於擺脫了永恆的恐怖詛咒！謝謝你，$N。請轉告救贖者瑞拉克我沒事了。我的命運與斯克提斯緊緊相連。泰羅克必敗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 0, 0, 'zhTW', '是時候了。驅魔儀式馬上開始……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 1, 0, 'zhTW', '做好準備。不要讓這儀式被打斷，否則我們會失去他……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 2, 0, 'zhTW', '退卻吧，骯髒的黑暗！你在這裡沒有力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 2, 1, 'zhTW', '聖光之力在強迫你，返回你的位置！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 2, 2, 'zhTW', '人類，要使用聖光之力去清除邪惡。不要讓惡魔的腐朽之力湮沒你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 2, 3, 'zhTW', '聖光指引著我……它一直支援著我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 2, 4, 'zhTW', '我……不能……倒下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 2 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 2, 5, 'zhTW', '退散！我命令你退散……信念的腐蝕者！痛苦的創造者！不要再回來，否則你會遭受到和今天同樣的失敗命運。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22431 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22431, 3, 0, 'zhTW', '我……不能……失敗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 0, 0, 'zhTW', '小心。這個蠢貨交給我來對付。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 1, 0, 'zhTW', '啊！停止你的咒語，學者！停下，否則我會讓你體會到你們這些可悲的凡人從未想象過的痛苦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 1, 1, 'zhTW', '給我們一點時間……讓這人死去吧……我誰都不是……我誰都不是……讓那學者感到恐懼吧……讓那學者感到恐懼吧……巴拉達……巴拉達。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 1, 2, 'zhTW', '這是徒勞的，德萊尼人！你和你弱小的助手們奪不回這個悲慘人類的控制權。他是我的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 1, 3, 'zhTW', '我會把你的靈魂撕成碎片，把它們放在惡魔之火上慢慢灸烤！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 1, 4, 'zhTW', '學者，一切盡失了！終止希望。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22432 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22432, 1, 5, 'zhTW', '我看到了你的祖先，學者！他們在黑暗中翻滾著，尖叫著……他們和我們在一起！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22448 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22448, 0, 0, 'zhTW', '我是雷克薩，莫克納薩的子民，部落的勇士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22448 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22448, 1, 0, 'zhTW', '他們在你手上承受痛苦日子就要結束了。以我的名義，我要殺了你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22448 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22448, 2, 0, 'zhTW', '準備迎接滅亡吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22448 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22448, 3, 0, 'zhTW', '沒有問題我不可能取得勝利，我們回雷神要塞再說吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22452 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22452, 0, 0, 'zhTW', '太快了，太急躁了！我仍然很虛弱……這是什麼！誰……算了，無所謂！受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 0, 0, 'zhTW', '好吧，聽好了！在我周圍排成圓圈，然後出發！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 1, 0, 'zhTW', '好吧，$r，你只需要在我們工作的時候保護我們不被傷害。等我們回去以後會付給你酬勞的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 2, 0, 'zhTW', '那個挖掘站就在這裡的北面。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 3, 0, 'zhTW', '我們到了！開始挖掘！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 4, 0, 'zhTW', '我覺得這裡的沙子底下埋著東西！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 5, 0, 'zhTW', '就快了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 6, 0, 'zhTW', '以布萊恩喜歡吃的爛香蕉的名義！這是什麼？看上去……像只鼓。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 7, 0, 'zhTW', '你瘋了嗎？你竟然不希望我去敲打這隻鼓，不希望看看接下來會發生什麼事？那可有違鐵爐堡之子的名聲！絕不能這樣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 8, 0, 'zhTW', '閉嘴！反正我現在就要狠敲這隻鼓！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 9, 0, 'zhTW', '哈哈！我告訴過你這裡有東西的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 10, 0, 'zhTW', '不要就這麼站在那裡！幫幫$g他:她！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 11, 0, 'zhTW', '你給予了我們相當大的幫助，$R！我們趕緊離開這兒吧，免得再惹麻煩上身！我會轉告杜瓦弗維茲，說你出色地完成了自己的任務。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22458 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22458, 12, 0, 'zhTW', '%s撿起了鼓離開了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22459 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22459, 0, 0, 'zhTW', '讚美納魯，我獲救了。我會自己回去的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22459 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22459, 0, 1, 'zhTW', '我雖然受傷了，可是我還能走。謝謝, 陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22459 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22459, 0, 2, 'zhTW', '謝謝你，陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22459 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22459, 0, 3, 'zhTW', '我太虛弱了，不能和你一起戰鬥了。請幫我找找我的朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22460 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22460, 0, 0, 'zhTW', '%s使用鑰匙去開啟籠子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 0, 0, 'zhTW', '哇……一隻鼓。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 1, 0, 'zhTW', '這個發現肯定會動搖現代考古學的基礎理念。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 2, 0, 'zhTW', '是啊，太棒了。我們現在能回去了嗎？這片沙漠讓我渾身發癢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 3, 0, 'zhTW', '這讓我想起了過去，那時候，你為了尋找所謂沙漠地精的證據，讓我們搜遍了整個希利蘇斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 4, 0, 'zhTW', '還有那一次，你告訴我們說，你發現了治癒20世紀疾病的辦法。這所謂的20世紀又到底是什麼東西？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 5, 0, 'zhTW', '我覺得還是那一次最勁。那次他說他認為阿爾薩斯表弟的骨骼被凍在冬泉谷的冰河之下。我永遠都不會原諒你，雷托爾。說真的……阿爾薩斯的表弟又是誰了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 6, 0, 'zhTW', '我真不知道雷托爾腦子裡裝的是什麼。有一次他居然試圖說服我們，說我們不過是某種生物臆想出來的意識體，是他們用來取樂的調劑品。那段時間，每次晚餐的時候他都會喋喋不休地說個不停。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22464 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22464, 7, 0, 'zhTW', '那麼，你們都聽到了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22473 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22473, 0, 0, 'zhTW', '讓你知道取走你性命的人的名字是個正確的選擇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22473 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22473, 1, 0, 'zhTW', '我是薩博邁恩男爵。你很快就要撥出生命中的最後一口氣息了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22473 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22473, 2, 0, 'zhTW', '開始吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22473 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22473, 3, 0, 'zhTW', '我們能再談談，不過先離開這裡。');
