INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22485, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22820 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22820, 0, 0, 'zhTW', '阿卡瑪！你聽到訊息了嗎？我被瓦絲琪的人跟蹤了。我們的秘密就要暴露了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22820 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22820, 1, 0, 'zhTW', '伊利丹正在搜捕我。我在這裡非常危險，我們大家都非常危險。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22820 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22820, 2, 0, 'zhTW', '伊利丹必定會抓住我，那時候，他肯定會得知灰舌部隊的秘密。這對他來說根本沒有什麼難度！不，我們只有一個辦法。是我的愚蠢和疏忽導致了今天的局面，那麼就讓我進入靈魂的世界，結束這次危機。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22820 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22820, 3, 0, 'zhTW', '我已經下定了決心，不要再勸說我了。我把自己的生命都獻給了我們的計劃，如果現在前功盡棄，我們怎麼能對得起那些為此犧牲的夥伴？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22820 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22820, 4, 0, 'zhTW', '謝謝你，阿卡瑪。你讓我感到了無上的榮耀，我感到自己的兄弟們就在身邊。再會，朋友。好好指引我們的同胞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22834 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22834, 0, 0, 'zhTW', '%s突然跪下，但他的心思似乎遊離在別處。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22834 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22834, 1, 0, 'zhTW', '你在伊瑟拉的領域裡幹什麼，入侵者？走開！你們在這裡不受歡迎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22834 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22834, 2, 0, 'zhTW', '%s站穩了腳跟，開始辨識周圍的環境。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22834 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22834, 3, 0, 'zhTW', '你……你不是他們的同黨！快，在他們找到我們之前，得躲進某個隱密的地方！快點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22834 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22834, 4, 0, 'zhTW', '他們還在追我，$r！快點，在我們被發現前告訴我，你來這裡幹什麼！要是被他們抓住了，我們兩個人都得死！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22844 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22844, 0, 0, 'zhTW', '%s變得憤怒了！');
