INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22864, 0, 0, 'zhTW', '前進，占星者！讓伊利丹的侍從們見識一下我們的厲害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22865 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22865, 0, 0, 'zhTW', '你讓我失望了，阿卡瑪。我本想要親自審訊這條狡猾的蟲子！現在我有些懷疑你們這些破碎者的忠誠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22865 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22865, 1, 0, 'zhTW', '看來你沒有撒謊，阿卡瑪。凱爾薩斯的背叛並沒有讓我感到多麼吃驚，我並沒有某些傢伙所想的那樣健忘。你的同族與他有重大的牽連，這讓我不得不質疑你的忠誠。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22865 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22865, 2, 0, 'zhTW', '將你的灰舌部隊派進風暴要塞，去殺掉他最得意的部下，那隻名叫奧的鳳凰。以此來向我證明你不是他的同黨。不要妄圖背叛我，破碎者。我們都知道你的靈魂在誰的掌握中！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22871 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22871, 0, 0, 'zhTW', '對我來說，死亡之輪已經旋轉了許多次。時間已經流逝了許多……有太多事情要做了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22871 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
