INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22917, 8, 0, 'zhTW', '阿卡瑪。你的兩面三刀並沒有讓我感到意外。我早就應該把你和你那些畸形的同胞全部殺掉。');
