INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22940, 1, 0, 'zhTW', '要是你們這些小傢伙不去刀鋒山和莫戈多格談話，葛羅克會生氣的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22940 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22940, 1, 1, 'zhTW', '刀塔氏族沒有公平地戰鬥。他們有戈隆幫忙。你去刀鋒山，和枯瘦的莫戈多格談談。去消滅戈隆吧。');
