INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22940, 1, 2, 'zhTW', '枯瘦的莫戈多格告訴葛羅克，要去城市裡為血槌氏族尋求幫助。葛羅克就來了。');
