DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22982 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22982, 0, 1, 'zhTW', '$n，你的坐騎還撐得住吧？最近情況很艱難嗎？');
