INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22982, 0, 5, 'zhTW', '嗯，這不是我們的常駐飛行員$n嗎……最近怎麼樣啊，王牌飛行員？');
