DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22989 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22989, 0, 0, 'zhTW', '這一天我已經等待許多年了！伊利丹和他的走狗都將徹底被毀滅！');
