INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (22990, 3, 0, 'zhTW', '我們的計劃早已危在旦夕。好像瑪維決定以她自己的方式來做事。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 22990 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
