INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23035, 1, 0, 'zhTW', '你的法術……呱——呱……脆弱的魔法……輕而易舉地就能轉而對付你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23035 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
