DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23049 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23049, 0, 0, 'zhTW', '狂暴姿態！無情地攻擊他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23049 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23049, 1, 0, 'zhTW', '狂暴姿態！無情地攻擊他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23049 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23049, 2, 0, 'zhTW', '防禦姿態！用盾牌擋住攻擊，然後迅速反擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23054 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23054, 0, 0, 'zhTW', '你手下那群猴子可恥地失敗了，納魯。雖然我已經落敗，但是我還活著……當我們控制納魯飛船的時候，絕對沒有犯下這樣的錯誤。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23054 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23054, 1, 0, 'zhTW', '這一切都是為了什麼？幾樣無關緊要的小玩意？太遲了。迎接主人歸來的準備工作早就開始了。很快，他就會重返這個世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23054 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23054, 2, 0, 'zhTW', '你，或是伊利丹那個蠢貨，都根本不能阻止我！你們一直扮演著我的僕從的角色，只是你們對此一無所知罷了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23054 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23054, 3, 0, 'zhTW', '放下武器，向基爾加丹的力量屈服吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23083 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23083, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 0, 0, 'zhTW', '在我們和伊利丹之間就只剩下這扇門了。站開點，朋友們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 1, 0, 'zhTW', '我一個人無法做到……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 2, 0, 'zhTW', '我感謝你們的幫助，兄弟們。我們的人民會報答你們的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 3, 0, 'zhTW', '當心點，朋友們。背叛者就在那邊的大廳中冥想。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 4, 0, 'zhTW', '我們要終結你的統治，伊利丹！我的人民，以及整個外域，都將重獲自由！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 5, 0, 'zhTW', '時機來臨了，終於等到這一刻了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 6, 0, 'zhTW', '我來對付這些渣滓！進攻吧，朋友們！向伊利丹發起進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 7, 0, 'zhTW', '聖光會再次照耀這陰暗的大廳……我發誓。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23089 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23089, 8, 0, 'zhTW', '讓我們結束這一切吧。當你恢復了全部的力量之後，我會帶你去伊利丹的居所。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 0, 0, 'zhTW', '過來，$n。伊利丹大人在等你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 1, 0, 'zhTW', '龍喉氏族的勇士們，都聚集過來吧！就在你們中間，一位佼佼者已經晉升為領主了！向$n領主致敬！表達你們的敬意和忠誠吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 2, 0, 'zhTW', '伊利丹大人很快就來到這裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 3, 0, 'zhTW', '伊利丹大人萬歲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 4, 0, 'zhTW', '伊利丹大人，這位就是我和其他人向您提到過的龍喉氏族的英雄。他會引領我們走向勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 5, 0, 'zhTW', '但是……大人，我不明白。$n……這個獸人曾經為我們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 6, 0, 'zhTW', '遵命，主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 7, 0, 'zhTW', '你膽敢欺騙莫格霍爾！在將你送到伊利丹大人的神殿之前，我要讓你嚐嚐你想都不敢想的痛苦！我要折磨你，享受復仇的樂趣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 8, 0, 'zhTW', '我不想說太多廢話，女伯爵希奈絲特拉。就直接告訴我你想從龍喉氏族這裡得到什麼吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 9, 0, 'zhTW', '主……主人？他還活著？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 10, 0, 'zhTW', '%s顯得非常緊張，話都說不利索了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23139 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23139, 11, 0, 'zhTW', '是……是，是的……當然，我們只需要這個地方的水晶和礦石。也就是說……我們需要坐騎。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23141 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23141, 0, 0, 'zhTW', '你休想傷害這個孩子，莫格霍爾！$n，快點，爬到我的背上來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23146 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23146, 0, 0, 'zhTW', '你……你是誰？？你想要什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23146 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23146, 1, 0, 'zhTW', '好……好……我們馬上走開……請不要傷害我們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23152 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23152, 0, 0, 'zhTW', '可憐的傢伙，你們膽敢進攻伊利丹大人的神殿？好吧，我會讓這裡變成你們的墓地！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23152 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23152, 1, 0, 'zhTW', '你的死期就要到了，阿卡瑪。主人馬上就會得知你的背叛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23161 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23161, 0, 0, 'zhTW', '聽聽來自地下的聲音，他們在呼喚你的鮮血！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23162 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23162, 0, 0, 'zhTW', '瓦克奇斯攜著狂風朝你惡狠狠地撲過來。');
