INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23163, 0, 0, 'zhTW', '%s呲著牙發出嘶嘶聲，以示威脅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23163 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
