INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23165, 0, 0, 'zhTW', '你偷襲了卡爾洛格！卡爾洛格要殺了你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23191 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23191, 0, 0, 'zhTW', '灰舌破碎者們，你們的首領有話要說！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23191 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23191, 1, 0, 'zhTW', '背叛者不再掌控著我們的命運了，他施加在灰舌氏族靈魂上的邪惡魔咒已經消散了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23191 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23191, 2, 0, 'zhTW', '從陰影中解脫吧！我將領導你們對抗真正的敵人。脫下你們的鐐銬，拿起武器，去對抗你們的伊利達雷主人吧！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23196 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23196, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 0, 0, 'zhTW', '這一下是為了奈莎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 0, 1, 'zhTW', '像我一樣流血吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 0, 2, 'zhTW', '這一次，你不會有機會再進監獄了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 0, 3, 'zhTW', '迎接你的末日吧，惡魔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 1, 0, 'zhTW', '他們的憤怒和我的相比簡直不值一提，伊利丹。我們之間終於要決一勝負了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 2, 0, 'zhTW', '我長久以來的追獵終於要結束了！今天，正義將得到伸張！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 3, 0, 'zhTW', '這一次，你不會有機會再進監獄了！');
