INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 5, 0, 'zhTW', '結束了。你被打敗了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 6, 0, 'zhTW', '他說得對。我覺得很失落……我……什麼都不是。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23197 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23197, 7, 0, 'zhTW', '再會，勇士們。');
