DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23224 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 4, 'zhTW', '我跟其他的小鬼開會討論了一下，答案是“是”。不過有一個小鬼投了反對票。');
