INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 6, 'zhTW', '要我說出這樣的話真是有些難過，不過答案是“是”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23224 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 7, 'zhTW', '如果矮人會飛，答案就是“是”。他們真的會飛？那就是咯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23224 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 8, 'zhTW', '當然，但是你不會喜歡的。');
