INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 9, 'zhTW', '你在這裡聽到和看到的一切都要保密，$r。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23224 AND `GroupID` = 0 AND `ID` = 10 AND `Locale` = 'zhTW';
