INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 31, 'zhTW', '為啥我一定要回答你的問題？你會在別人搖晃你的時候占卜嗎？');
