INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 32, 'zhTW', '是的，今天會下雨。什麼？你沒有問這個問題？太遺憾了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23224 AND `GroupID` = 0 AND `ID` = 33 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 33, 'zhTW', '抱歉，我只會講惡魔語。');
