INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23224, 0, 34, 'zhTW', '是！我是說，不是！嗯……哪個答案可以讓你同意把我放出來？');
