INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23257, 0, 1, 'zhTW', '$n，天空的統帥，你在幹什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23257 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23257, 0, 2, 'zhTW', '立正，$n軍官來了！');
