INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23257, 0, 4, 'zhTW', '呵呵，有$n在天空飛翔，我們的敵人就要小心了！');
