INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23257, 0, 6, 'zhTW', '$n，你的坐騎還撐得住吧？最近情況很艱難嗎？');
