INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23257, 0, 9, 'zhTW', '在天空衛隊的隊員名單上，$n最為出眾，因此名字也排在首位。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23282 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23282, 0, 0, 'zhTW', '我覺得今晚我能享用一頓用$r和食人魔烹製的美餐。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 0, 0, 'zhTW', '在我把你做成我護甲上的又一個裝飾前，給我滾到一邊去。你的領袖和我有事要商量……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 1, 0, 'zhTW', '%s笑了笑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 2, 0, 'zhTW', '我還以為你認同我的觀點……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 3, 0, 'zhTW', '莫格霍爾大王，我想……能夠和你攀上交情真是榮幸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 4, 0, 'zhTW', '我是女伯爵希奈絲特拉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 5, 0, 'zhTW', '我相信你肯定已經聽說了奈法利安在艾澤拉斯的失敗……雖然他失敗了，但實驗仍然繼續著。我的主人……他繼續進行著他的兒子沒能完成的研究。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 6, 0, 'zhTW', '%s點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 7, 0, 'zhTW', '你曾是一位重要的軍官，莫格霍爾。我們不會輕易忘記你在格瑞姆巴托所做的一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 8, 0, 'zhTW', '現在……我們要你找回龍卵。靈翼龍卵。他們畢竟是主人的東西。無論你出多高的價錢，我們都會和你交換的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 9, 0, 'zhTW', '主人聽到這個訊息一定會很高興的。黑龍軍團會滿足你的一切要求，必要的情況下，你可以騎我們的幼龍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23284 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23284, 10, 0, 'zhTW', '感謝你的慷慨，莫格霍爾。但我現在必須走了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23311 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23311, 0, 0, 'zhTW', '啊！！訓誡靴！！');
