INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23678, 0, 0, 'zhTW', '%s顯得非常虛弱！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23678 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23678, 1, 0, 'zhTW', '我就知道魯莉爾蕾會派人來救我的！謝謝你，朋友，也幫我謝謝魯莉爾蕾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23678 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23678, 1, 1, 'zhTW', '我在哪裡？發生了什麼事？是你……救了我？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23678 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23678, 1, 2, 'zhTW', '謝謝你。我還以為我再也見不到我的姐妹啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23682 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23682, 0, 0, 'zhTW', '湮遠而艱辛的探索到此為止，真正的正義者將由命運擇示。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23682 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23682, 1, 0, 'zhTW', '我的軀體健壯而純潔！現在，讓我來治癒你們這幫陰暗的靈魂吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23682 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23682, 2, 0, 'zhTW', '嗤！感受燃燒的烈焰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23682 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23682, 3, 0, 'zhTW', '士兵們，起來戰鬥吧！為死去的騎士帶來勝利的榮耀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23682 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23682, 4, 0, 'zhTW', '我曾經經歷過這樣的結局。這次會有新意嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23685 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23685, 0, 0, 'zhTW', '你想喝酒？我們有酒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23685 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23685, 0, 1, 'zhTW', '嘿！喝食人魔的酒，變得更大更強！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23685 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23685, 0, 2, 'zhTW', '食人魔美酒！值得品嚐！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23720 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23720, 0, 0, 'zhTW', '謝謝你！真不知道那些野蠻人會怎麼對付我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23728 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23728, 0, 0, 'zhTW', '%s清了清嗓子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23728 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23728, 1, 0, 'zhTW', '每一次我望向這個基地時，唯一能看到……就是恐懼……等到天災軍團佔領了鐵爐堡或是暴風城以後，你們還會感到恐懼嗎？不！不會了！知道為什麼嗎？因為那時候你們早已沒命了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23728 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23728, 2, 0, 'zhTW', '如果你感覺脊椎下傳來陣陣涼意，甚至有尿褲子的衝動，倒是應該感到欣慰。讓這種感覺刺激你的情緒吧。恐懼是唯一能讓你保持呼吸的情感。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23728 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23728, 3, 0, 'zhTW', '我說得夠清楚了吧？你們聽明白沒？我可不想再送更多的棺材或者陣亡通知單回去了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23734 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23734, 0, 0, 'zhTW', '這樣或許可以延緩感染的速度。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23734 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23734, 1, 0, 'zhTW', '只能祈禱治療方案能生效了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23734 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23734, 2, 0, 'zhTW', '我根本沒有能治療你們的藥品和器械。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23734 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23734, 3, 0, 'zhTW', '哦……見鬼，讓我換個繃……帶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23734 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23734, 4, 0, 'zhTW', '別擔心，士兵。亞米娜會照顧好你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23734 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23734, 5, 0, 'zhTW', '%s搖了搖頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23736 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23736, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23768 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 1, 0, 'zhTW', '詹姆斯？詹姆斯……不，你不是詹姆斯，但我知道你是誰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23768 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 2, 0, 'zhTW', '你就是追蹤那幫野蠻的渣滓，替我們報仇的英雄。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 23768 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 3, 0, 'zhTW', '我千方百計地想要告訴詹姆斯……想要告訴所有人……誰才是幕後黑手，可惜始終沒有機會……');
