INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23768, 5, 0, 'zhTW', '吉米，我也不知道我們何時才能與你爸爸重逢。但你要知道，他愛你，無時無刻都在思念你。');
