INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (23775, 0, 0, 'zhTW', '你們竟如此渴望將我滅亡。可卻不知，首級還在，我便可避過一切災殃！');
