INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24035, 0, 15, 'zhTW', '你必須阻止這瘋狂的一切，否則就來不及了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24035 AND `GroupID` = 0 AND `ID` = 16 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24035, 0, 16, 'zhTW', '你救了我的命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24041 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24041, 0, 0, 'zhTW', '阿爾薩斯準備賜予你力量，超乎你想象的力量。比起以後你將領導的天災軍團來說，眼下你手中的軍隊簡直脆弱得可笑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24041 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24041, 1, 0, 'zhTW', '千萬小心那些維庫人！這是一個嗜血而兇殘的種族，每日所想不過是征伐與殺戮。更何況，他們已經向巫妖王宣誓效忠！維庫人在附近建立了多處定居點，他們的人數幾乎是你們的5倍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24041 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24041, 2, 0, 'zhTW', '做出選擇吧，安希爾姆。回到巫妖王的軍隊，與天災軍團並肩作戰或者對你所謂的女王保持忠誠，直到天災軍團將你驅出他們的家園！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24041 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24041, 3, 0, 'zhTW', '瞧你這喪氣的模樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24041 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24041, 4, 0, 'zhTW', '我要吸取你們的靈魂，我要聽你們臨死前的哀號！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24041 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24041, 5, 0, 'zhTW', '這絕不是你最後一次看見我。等烏特加德的大軍將你踐踏至渣後，我還會回來朝你的屍體吐口水！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24052 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24052, 0, 0, 'zhTW', '我們不負責給騾子釘馬蹄鐵。準確地說，那是遠征隊的事兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24052 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24052, 1, 0, 'zhTW', '這又不是我的問題！如果你這麼著急建房子的話，就在要塞裡建好了，省得你整天抱怨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24052 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24052, 2, 0, 'zhTW', '你能不能從我的熔爐旁滾開……');
