INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24068, 0, 0, 'zhTW', '因格瓦爾！你這可恥的失敗將警示所有巫妖王的僕從！你被詛咒了！站起來，重新執行主人的意志！');
