INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24077, 0, 1, 'zhTW', '我……不行了……失血過多……別管我了，告訴凱勒……還有人在裡面……');
