INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24077, 0, 3, 'zhTW', '我的傷勢太重了。沒法活著回去了……村民們……被關在籠子裡……儀式……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24077 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24077, 0, 4, 'zhTW', '他們把我們釘在這裡，就是為了給其他人一個警告……還有些人活著……囚禁……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24077 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24077, 0, 5, 'zhTW', '務必轉告我的家人……我……永遠……愛他們……');
