DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24123 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24123, 0, 0, 'zhTW', '這些都非常不錯。非要從中選一個的話，真有點難以做決定。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24123 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24123, 1, 0, 'zhTW', '很好，我找到合適的號角啦。現在我要開始雕刻了，這恐怕會很難。我根本沒聽過雌雪人的叫聲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24123 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24123, 2, 0, 'zhTW', '我已經把大部分基礎圖案雕刻好了，在完成雕刻之前需要測試一下。你願意幫我測試嗎，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24126 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
