INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24126, 4, 0, 'zhTW', '我們是皇家藥劑師協會的成員！藥劑引起胃痛不在我們的工作範圍之內！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24126 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24126, 5, 0, 'zhTW', '你們都是業餘的嗎？明天早上，我要見到一份完整的分析報告！拉維恩，給我做事去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24126 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24126, 6, 0, 'zhTW', '幽暗城的藥劑樣本原本已經取得了一些進展。但是不知道怎麼回事，突然又不行了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24126 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24126, 6, 1, 'zhTW', '這些是幽暗城送來的最後10份藥劑樣本……可它們毫無價值！');
