INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24126, 6, 2, 'zhTW', '這樣叫我怎麼研究！我需要一份能在這種氣候下存活的藥劑樣本！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24131 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24131, 0, 0, 'zhTW', '為什麼啊？如果我們能將她和雛鳥做成標本，陳列在一起也挺不錯的呀……');
