INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24201, 0, 0, 'zhTW', '行了，別再估計什麼形勢不形勢的了，蠢貨！趕緊給我加入戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24201 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24201, 1, 0, 'zhTW', '再……見……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24201 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24201, 2, 0, 'zhTW', '真是……無上的……榮耀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24201 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24201, 3, 0, 'zhTW', '你或許也可以為我效勞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24201 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24201, 4, 0, 'zhTW', '斯卡瓦爾德，你這無能的廢物！滾回來，讓我把你變得更有用一點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 0, 'zhTW', '願天地間的精魂永遠保佑你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 1, 'zhTW', '我必須回去，祝你狩獵愉快。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 2, 'zhTW', '我欠你一條命，陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 3, 'zhTW', '這裡到處都是幽魂。小心！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 4, 'zhTW', '謝謝你，陌生人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 5, 'zhTW', '他們將我們分別關押起來。我敢肯定還有其他的倖存者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 6, 'zhTW', '我們不應該穿越裂木森林的。是個人都該明白這點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24211 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24211, 0, 7, 'zhTW', '你救了我的命。我欠你一份情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24213 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24213, 0, 0, 'zhTW', '獻給巫妖王更多的靈魂！來吧，小傢伙！來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24214 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24214, 0, 0, 'zhTW', '不錯……更多的肉來享用……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24215 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24215, 0, 0, 'zhTW', '芬爾烏斯算什麼！讓巫妖王手下真正的士兵來試試你的戰力吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24238 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24238, 0, 0, 'zhTW', '[維庫人土語]Bjorns mottar haelgond sygar！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24238 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24238, 1, 0, 'zhTW', '你竟敢辱罵我的媽媽！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24238 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24238, 2, 0, 'zhTW', '將入侵者驅逐出去！為安格博達女王而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24238 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24238, 2, 1, 'zhTW', '勇敢地戰鬥吧，瓦格里會獎賞你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24238 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24238, 2, 2, 'zhTW', '斯克恩部族必勝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 0, 0, 'zhTW', '%s轉身面對著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 1, 0, 'zhTW', '%s咧嘴一笑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 2, 0, 'zhTW', '薩滿的精魂將你帶來了這裡……我能感應到空氣中湧動著那種力量。*巫妖王大笑起來* 我也曾是個薩滿祭司。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 3, 0, 'zhTW', '不，我的僕從。這一個還沒有準備好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 4, 0, 'zhTW', '你感覺到了嗎，凡人？死亡之力從我身上滲透出來，覆蓋了所有我碰觸過的事物。只要我略彈手指，你的靈魂就將在詛咒中永遠地凋零消逝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 5, 0, 'zhTW', '但……現在還不是讓你為巫妖王效力的時候。是的，更偉大的命運還在等待著你。力量……在你為我效勞之前，你必須獲得更多的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 6, 0, 'zhTW', '看仔細了，瓦格里。看我如何施壓。你瞧，它還沒有成熟呢。它會爆裂，毫無生氣地隕落。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24248 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24248, 7, 0, 'zhTW', '這是毅力還是愚蠢？無所謂了。銘記這個教訓吧，凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24252 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24252, 0, 0, 'zhTW', '足骨……連線到髖骨！髖骨再……再連線到這裡好了！嗯嗯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24252 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24252, 0, 1, 'zhTW', '把這些東西拼起來可真夠難的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 0, 0, 'zhTW', '站住！立即出示身份證明！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 0, 1, 'zhTW', '這裡禁止入內！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 0, 2, 'zhTW', '我沒見過你這樣的傢伙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 0, 3, 'zhTW', '喂！站住！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 0, 4, 'zhTW', '站住！！站住！！廢鐵現在會自己移動了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 1, 2, 'zhTW', '好吧……是我的錯。我這是在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 1, 3, 'zhTW', '為偉大的創造者歡呼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 1, 4, 'zhTW', '你當然是對的。繼續。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 1, 5, 'zhTW', '原諒我的傲慢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 1, 6, 'zhTW', '我們會加倍努力的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 2, 0, 'zhTW', '消滅土靈入侵者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 2, 1, 'zhTW', '回答錯誤！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 0, 'zhTW', '繼續摧毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 1, 'zhTW', '不要到處閒逛。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 2, 'zhTW', '繼續工作。努力工作。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 3, 'zhTW', '什麼都瞞不過布隆特斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 4, 'zhTW', '援軍正在途中。確保功能正常。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 5, 'zhTW', '你是替創造者傳話的嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24271 AND `GroupID` = 3 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24271, 3, 6, 'zhTW', '向我們的創造者歡呼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24277 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24277, 0, 0, 'zhTW', '別打啞謎了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24284 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24284, 0, 0, 'zhTW', '掠龍維庫囚犯感到不適。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24314 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24314, 0, 0, 'zhTW', '我們也被詛咒了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24314 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24314, 1, 0, 'zhTW', '%s指著那個嬰兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24314 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24314, 2, 0, 'zhTW', '神靈拋棄了我們！我們必須在伊米隆國王發現之前處理掉它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24314 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24314, 3, 0, 'zhTW', '那要怎麼辦？一旦他們發現了這個畸形的胎兒，我們就會被處死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24315 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24315, 0, 0, 'zhTW', '%s嗚咽著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24315 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24315, 1, 0, 'zhTW', '不！你不能這樣！求你了！這是我們的孩子啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24315 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24315, 2, 0, 'zhTW', '我……我會把它藏起來，直到我為它找到一個家，一個遠離這裡的家……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 0, 0, 'zhTW', '%s要求大家安靜下來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 1, 0, 'zhTW', '維庫人，國王懇請你們安靜下來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 2, 0, 'zhTW', '人群在驚惶中騷動起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 3, 0, 'zhTW', '在最黑暗的時刻，他們依然不忘嘲笑我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 4, 0, 'zhTW', '在我們最需要泰坦指引的時候，他們又在哪兒呢？氏族誕生了畸形的胎兒，它們面貌醜陋，甚至無法站立！又醜又弱……一無是處……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 5, 0, 'zhTW', '伊米隆身心疲憊。自從我坐上王位，就一直在思考為什麼維庫人的生活如此艱難。答案只有一個……只有一個……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 6, 0, 'zhTW', '除了泰坦，還有誰能對我們下這樣的詛咒？誰能擁有那樣的力量？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 7, 0, 'zhTW', '沒有……是泰坦詛咒了我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 8, 0, 'zhTW', '人群歡呼起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 9, 0, 'zhTW', '今天，所有的維庫人都將拋棄過去的信仰！廢除我們曾經信奉的神靈！維庫人將效忠伊米隆國王！伊米隆會保護我們的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24321 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24321, 10, 0, 'zhTW', '現在，我頒佈第一道法令！所有維庫人畸形嬰兒一出生就要立即被處死！我們必須保證血統的純正！違抗伊米隆國王的法令的維庫人將被帶往亞勒伯龍處決！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24322 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24322, 0, 0, 'zhTW', '安靜！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24322 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24322, 1, 0, 'zhTW', '我的國王，手下留情！那是我們的骨肉啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24322 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24322, 2, 0, 'zhTW', '尊貴的伊米隆國王，萬歲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24323 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24323, 0, 0, 'zhTW', '絕不能對畸形兒心存憐憫！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24323 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24323, 1, 0, 'zhTW', '它們是禍害！維庫人的力量會因它們的存在而削弱！殺掉它們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24327 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24327, 0, 0, 'zhTW', '需要為您準備好一切嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24358 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24358, 0, 0, 'zhTW', '準備好。如果我們想進去的話，至少得有3個人幫我。跟著我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24358 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24358, 1, 0, 'zhTW', '根據我的計算，如果我們有足夠多的人同時敲鑼的話，那麼這些門上的封印就會被揭開，這樣我們就能進去了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24362 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24362, 0, 0, 'zhTW', '他們將工具放在這樣的箱子裡。去營帳附近找找看。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24362 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24362, 1, 0, 'zhTW', '接下來，我會幫你雕刻符文，它擁有支配巨人的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24362 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24362, 2, 0, 'zhTW', '我省掉了代表“北面”和“西面”的符文，因為我還不確定它們會對巨人產生怎樣的影響。而且，我還新增了限制控制時間的符文。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24362 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24362, 3, 0, 'zhTW', '瞧，命令符文……希望能起作用。它並不沒有鐵矮人那股邪惡的氣息，卻同樣具備操縱巨人的能力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24366 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24366, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24371 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24371, 0, 0, 'zhTW', '我敗了！弟兄們，別害怕！沒有誰能將你們趕出岩石熔爐！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24375 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24375, 0, 0, 'zhTW', '我詳細地研究了這個地方，我不會允許任何像你們這樣的竊賊進入這地方，並偷走屬於博物館的財寶。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24375 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24375, 1, 0, 'zhTW', '事實上，你最好留在這裡。你只會壞我的事……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24381 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24381, 0, 0, 'zhTW', '兄弟們，復活吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24381 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24381, 1, 0, 'zhTW', '鐵領主交給我們一項任務！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24381 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24381, 2, 0, 'zhTW', '跟著我進入山嶺，執行主人的計劃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24381 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24381, 3, 0, 'zhTW', '我們不能失敗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24405 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24405, 0, 0, 'zhTW', '謝謝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24458 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24458, 0, 0, 'zhTW', '我特意為你留著這個呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 0, 'zhTW', '我以為你不會這麼主動的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 1, 'zhTW', '我保證不會讓你得疣……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 2, 'zhTW', '不會太久吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 3, 'zhTW', '這就是我說的“青蛙風格”！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 4, 'zhTW', '喂，$n，我知道有塊沼澤離這裡不遠……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 5, 'zhTW', '是你的蓮花葉子還是我的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 6, 'zhTW', '感覺有點像小青蛙，是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24480 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24480, 0, 7, 'zhTW', '周圍跑來跑去的魔汁還不夠多……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24525 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24525, 0, 0, 'zhTW', '看著我的刀子，蠢貨！看著它，告訴我是誰背叛了我的兄弟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24525 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24525, 1, 0, 'zhTW', '朋友，你瞧，誰敢欺負我的朋友，我就讓他沒好果子吃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24528 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24528, 0, 0, 'zhTW', '為騾子釘上馬蹄鐵要花多少錢啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24528 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24528, 1, 0, 'zhTW', '你完全不瞭解狀況！如果我不趕緊出發的話，好的建築用地都會被別人搶先霸佔啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24528 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24528, 2, 0, 'zhTW', '那，那是頭騾子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24530 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24530, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24531 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24531, 0, 0, 'zhTW', '你說得對，親愛的。不過在莊稼成熟之前，咱們還不得靠羊肉維持生計……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24531 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24531, 1, 0, 'zhTW', '親愛的，我寧可聽騾子叫也不願意聽你講話。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24531 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24531, 2, 0, 'zhTW', '當然啦，親愛的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24532 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24532, 0, 0, 'zhTW', '我可不希望在咱們的土地上遇見恐怖的狼、巨人或是醜陋的山羊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24532 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24532, 1, 0, 'zhTW', '我寧可屠宰那些騾子！我說，你為什麼不帶些牲畜來呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24532 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24532, 2, 0, 'zhTW', '親愛的，我們得找到一塊帶溫泉的好地方。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 0, 0, 'zhTW', '歡迎來到維德瓦堡壘！瞧，那片土地等著你去佔領呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 1, 0, 'zhTW', '是啊，北裂境的環境極其惡劣，但是我們擁有強壯的體魄和勇敢的精神，能面對一切挑戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 2, 0, 'zhTW', '我們要用刀劍奪得這片土地的所有權，然後用犁來開墾荒地！而你們，將作為拓荒的先驅者，被後世傳頌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 3, 0, 'zhTW', '你們並不孤單。我們特意準備了一群騾子，運送你們所需的補給物資。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 4, 0, 'zhTW', '斧頭、鋤頭、種子、釘子、食物、毯子、水……任憑你們挑選。價格非常合理喲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 5, 0, 'zhTW', '我的物資供應非常充足。如果你們還需要其它的貨物，歡迎隨時來找我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24534 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24534, 6, 0, 'zhTW', '我忠誠的顧客，呃……朋友們，來吧，征服這片土地！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 0, 0, 'zhTW', '我們來自黑石山，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 1, 0, 'zhTW', '我們來喝你的酒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 2, 0, 'zhTW', '黑鐵矮人說到做到，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 3, 0, 'zhTW', '你對此清楚得很！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 4, 0, 'zhTW', '你未曾體會過我們的痛楚，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 5, 0, 'zhTW', '你未曾品嚐過我們的麥酒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 6, 0, 'zhTW', '美酒節上缺了我們的參與？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 7, 0, 'zhTW', '試試看吧，你只會落得慘敗的結果！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 8, 0, 'zhTW', '舉杯向科林祝酒，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 9, 0, 'zhTW', '還有霍爾雷·黑鬚！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 10, 0, 'zhTW', '酒味淡雅不上頭，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 11, 0, 'zhTW', '好在它還算是杯酒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 12, 0, 'zhTW', '我們暢飲辛辣的烈酒，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 13, 0, 'zhTW', '喝光所有的酒桶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 14, 0, 'zhTW', '飲酒、猜拳，猜拳、飲酒，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 15, 0, 'zhTW', '直到雙腿失去知覺！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 16, 0, 'zhTW', '飲下所有的美酒');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 17, 0, 'zhTW', '我們跳到暗影熔爐上');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24536, 18, 0, 'zhTW', '向拉格納羅斯舉杯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24536 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
