DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24690 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24690, 0, 5, 'zhTW', '你想偷能量！受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 0, 0, 'zhTW', '我們已經被天災軍團包圍了。從目前的情況看，我們還能堅持一段時間。但這將是一場你死我活的戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 1, 0, 'zhTW', '該採取行動了。我們必須在天災軍團摧毀我們之前解決他們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 2, 0, 'zhTW', '我不會讓將士們為了所謂的“榮耀”白白送命。如果沒人能活下來，那麼為生存而戰還有什麼意義呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 3, 0, 'zhTW', '杜爾姆，戰爭看來是不可避免的。但首先，我們得找到扭轉局勢的法子。埃恩雷，你有什麼提議嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 4, 0, 'zhTW', '杜爾姆，你所謂的榮譽又能挽救什麼？你的性命？我的性命？還是撫養你長大的盲眼老人瑪罕宗父的性命？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 5, 0, 'zhTW', '對死人而言，榮譽還有什麼意義。戰士可以為了榮耀投身沙場，但酋長要考慮的問題則要多得多。我們決定採取先知埃恩雷的計劃，繼續保衛村落。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24703 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24703, 6, 0, 'zhTW', '埃恩雷，$n將你要的獸皮帶回來了。請你趕快把它們拿走，我真是受不了這玩意兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24706 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24706, 0, 0, 'zhTW', '我們別無選擇，只能發動進攻。我知道局勢對我們不利，但是犛牛人絕不能坐以待斃。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24706 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24706, 1, 0, 'zhTW', '就算是死，我也要緊握沾滿敵人鮮血的戰斧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24706 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24706, 2, 0, 'zhTW', '嘖嘖，卑鄙的陰謀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24709 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24709, 0, 0, 'zhTW', '我們的先祖懂得如何擾亂敵人的心智。我們可以利用這種能力找出天災軍團的弱點，或是殺死他們的指揮官。沒有了首領的指揮，天災軍團很快就會敗下陣來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24709 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24709, 1, 0, 'zhTW', '我會拿走的。怎麼能讓偉大的酋長被一堆獸皮嚇得瑟瑟發抖呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 0, 0, 'zhTW', '好！讓我們來嚐嚐這個所謂的烈酒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 1, 0, 'zhTW', '天啊！真是好酒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 2, 0, 'zhTW', '$n，這啤酒……好吧，它可能是美酒節上最好的酒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 3, 0, 'zhTW', '真可惜，科林的烈酒不能在廣大啤酒愛好者中推廣開來！我知道這麼說可能不合適，但我真的很嫉妒那些黑鐵矮人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 4, 0, 'zhTW', '嗨，歡迎來到美酒節！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 4, 1, 'zhTW', '你好，朋友！歡迎來到美酒節！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24710 AND `GroupID` = 4 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24710, 4, 2, 'zhTW', '歡迎，$c！歡迎參加鐵爐堡一年一度的美酒節慶典！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 0, 0, 'zhTW', '好吧，時間就是金錢，光陰飛逝！我們來喝一杯吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 1, 0, 'zhTW', '哇！它真的可以潤滑蒸汽閥門！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 2, 0, 'zhTW', '如果我是一個誠實的地精，我要說這是節日上最好的啤酒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 3, 0, 'zhTW', '科林已經死了，這可真糟糕。如果我能從他手中買下這些酒再轉賣出去的話——當然要兌上水，重新裝瓶，再貼上自己的商標——那我肯定發財了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 4, 0, 'zhTW', '嗨，歡迎參加美酒節。過來喝上幾杯吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 4, 1, 'zhTW', '怎麼了，朋友？歡迎來到美酒節！現在就去買些酒喝喝吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24711 AND `GroupID` = 4 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24711, 4, 2, 'zhTW', '嗨，$c！歡迎來到美酒節慶典……現在盡情享受這裡的美酒美食吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24713 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24713, 0, 0, 'zhTW', '呸！是，我也是南海海盜的一員了——如果你想打什麼鬼主意，就趁早死了這條心。信不信我現在就砍翻你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24717 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24717, 0, 0, 'zhTW', '哇歐，哇歐，哇歐！夥計們，穩住！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24717 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24717, 1, 0, 'zhTW', '噢，尊貴的岩石與鋼鐵領主，您……您打算如何處理呢 ？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24717 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24717, 2, 0, 'zhTW', '矮人們突然都大笑起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24718 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24718, 0, 0, 'zhTW', '朋友，這行不通的。鐵矮人才不會喜歡那個大傢伙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24718 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24718, 1, 0, 'zhTW', '我說，你知道自己在幹什麼嗎？你竟然拖著那個金屬玩意兒踩過雷波斯基的地毯，看我怎麼收拾你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24718 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24718, 2, 0, 'zhTW', '很好。這桶螺釘或許能起作用……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24719 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24719, 0, 0, 'zhTW', '我非常傷心！就別開玩笑了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24720 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24720, 0, 0, 'zhTW', '要是爸爸能活著看到這一天該多好啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 0, 0, 'zhTW', '你們只會浪費我的時間！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 1, 0, 'zhTW', '我的渴求是無限的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 2, 0, 'zhTW', '對，沒錯，我就是神！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 3, 0, 'zhTW', '別打擾我了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 3, 1, 'zhTW', '我是不可戰勝的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 4, 0, 'zhTW', '不……更多，我還要更多！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24723 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24723, 5, 0, 'zhTW', '%s開始吸取附近邪能水晶的能量。快摧毀它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24742 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24742, 0, 0, 'zhTW', '呀啊啊啊！別想得到我的望遠鏡，你這隻配滾去艙底喝汙水的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24742 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24742, 0, 1, 'zhTW', '呀啊啊啊！別想得到我的望遠鏡，你這隻配滾去艙底喝汙水的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24742 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24742, 1, 0, 'zhTW', '你就是這樣報答主子的嗎？你這爛熊！啊啊啊啊啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24742 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24742, 1, 1, 'zhTW', '你就是這樣報答主子的嗎？你這爛熊！啊啊啊啊啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24744 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24744, 0, 0, 'zhTW', '抽取……生命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24744 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24744, 1, 0, 'zhTW', '無……法……控制。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24744 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24744, 2, 0, 'zhTW', '解……放！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24744 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24744, 3, 0, 'zhTW', '吞……噬。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24744 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24744, 4, 0, 'zhTW', '維薩魯斯放射出純淨的能量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24779 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24779, 0, 0, 'zhTW', '今晚我們要吃你的肉，喝你的血！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24779 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24779, 0, 1, 'zhTW', '真容易對付……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24779 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24779, 0, 2, 'zhTW', '誰才是獵物啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24788 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24788, 0, 0, 'zhTW', '當然啦，親愛的。把它算到哈里的賬上好不好呀？他欠我一杯酒呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24788 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24788, 1, 0, 'zhTW', '免費的朗姆酒？啊……這可是我的最愛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24788 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24788, 2, 0, 'zhTW', '太棒了！喝得……有點……多了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24790 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24790, 0, 0, 'zhTW', '呀啊啊啊！想要奪得我的財寶……你要費一番功夫了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24790 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24790, 1, 1, 'zhTW', '呀啊啊啊……又死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24796 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24796, 0, 0, 'zhTW', '你死定了，旱鴨子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24797 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24797, 0, 0, 'zhTW', '暗礁母海獅和公海獅找到了真愛。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24806 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24806, 0, 0, 'zhTW', '啟動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24807 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24807, 0, 0, 'zhTW', '瞧，完美的作品！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24807 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24807, 1, 0, 'zhTW', '雷波斯基，不懂就別折騰了！完全沒有必要！那些鐵矮人不會知道真相的！你不如回去調查到底是誰在你的地毯上搗鬼，這裡的工作就交給真正的科學家吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 24823 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (24823, 0, 0, 'zhTW', '鐵符文構造體U-9207無法識別你的聲音。雷波斯基，現在開始摧毀你的地毯。');
