INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25038, 3, 0, 'zhTW', '我比以前更強大了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25038 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25038, 4, 0, 'zhTW', '別再猶豫了！你們的命運就是如此了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25038 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25038, 5, 0, 'zhTW', '基爾加丹……會勝利的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25038 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25038, 6, 0, 'zhTW', '雖然瑪蒂苟薩的命運不該如此悲慘，你們的所作所為仍然是必須和必要的，不過，這場戰爭遠未結束！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25132 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25132, 0, 0, 'zhTW', '破碎殘陽的垃圾！隨意開火！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25144 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25144, 0, 0, 'zhTW', '西邊出現龍鷹！把那個$c打下來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25144 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25144, 0, 1, 'zhTW', '盯著惡魔。我們今天不是來消滅那些亡靈天災的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 0, 0, 'zhTW', '注意！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 1, 0, 'zhTW', '好吧，安靜。我們有很多事需要做，但時間只有那麼一點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 2, 0, 'zhTW', '我曾經和一些德萊尼人在斯克提斯並肩作戰，也曾經和另一些德萊尼人在影月谷對抗伊利丹。然而現在，我們是在艾澤拉斯，這裡的情況看上去很艱險。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 3, 0, 'zhTW', '首先，我要告訴你們這些辛多雷，我的要求很嚴格……這和占星者們的行事方式並不一樣。要麼給我打起精神，要麼就給我滾回去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 4, 0, 'zhTW', '既然沒人有異議，歡迎來到奎爾丹納斯島。太陽之井就在南邊的高地上，而凱爾薩斯王子則躲藏在東面的魔導師平臺裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 5, 0, 'zhTW', '我們是來這裡支援那些高階軍官召集來的所謂“冒險者”的。我們會幫助他們守衛島上的關鍵位置，讓他們遠離戰火，這樣他們就能安心去做他們的事情了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 6, 0, 'zhTW', '你們可以從小隊指揮官那裡得到更進一步的分配和指示。如果沒有什麼其他問題，就這樣，好運！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 7, 0, 'zhTW', '注意！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 8, 0, 'zhTW', '歡迎來到太陽之井。儘管這裡氣候宜人，景色秀麗，但女士們先生們，你們不是來這裡度假的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 9, 0, 'zhTW', '現在的情況是這樣：在那些更有經驗、並且裝備精良的夥計們對付凱爾薩斯王子時，我們正在努力保護我們所能保護的一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 10, 0, 'zhTW', '我知道，我們也以為他已經死了，不過事實並非如此。他正設法用太陽之井將燃燒軍團的主子——基爾加丹帶到這個世界來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 11, 0, 'zhTW', '我跟你們打保票，如果他成功了，這個世界將會遭受比外域更嚴重的災難！所以，我們必須保證這一切不會發生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 12, 0, 'zhTW', '在獵人們被指派狙擊敵方飛行員的同時，戰士們也將被分配前往關鍵地區進行防禦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 13, 0, 'zhTW', '我正在等待著給你們指派特殊任務的命令。在此期間，請待在這裡隨時準備出發！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 14, 0, 'zhTW', '注意！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 15, 0, 'zhTW', '新兵們，你們好。我是教官巴爾杜姆。在接下來的幾天內，你們會接受我的訓練。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 16, 0, 'zhTW', '凱爾薩斯·逐日者王子的軍隊佔領了奎爾丹納斯島。先前的情報表明他已經死了，但情報錯了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 17, 0, 'zhTW', '他和他的惡魔同伴們正在高地上設法重新點燃太陽井，開啟一道裂縫，把他們的首領基爾加丹重新召喚回這個世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 18, 0, 'zhTW', '我們的任務是在支援上頭派來的特種部隊的同時，儘可能多的消滅凱爾薩斯的手下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 19, 0, 'zhTW', '不用說也知道，我們中的很多人將一去不復返。但你們只需要牢記訓練的內容，時刻保持警惕，就可以大大提高生還的機率。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25162 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25162, 20, 0, 'zhTW', '我要說的就這些了。認真點，孩子們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25165 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25165, 0, 0, 'zhTW', '痛楚……');
