INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25165, 6, 0, 'zhTW', '時間，這是你永遠也無法擁有的奢侈之物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25165 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25165, 7, 0, 'zhTW', '奧蕾塞絲！你的火焰會在我心中燃燒下去！');
