INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25166, 9, 0, 'zhTW', '你們的好運到此為止了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25197 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25197, 0, 0, 'zhTW', '$n，你已經能夠與冬鱗魚人溝通了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25208 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25208, 0, 0, 'zhTW', '只要同心協力，我們一定能逃離這裡。你準備好了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25208 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25208, 1, 0, 'zhTW', '為什麼要將我強行關押起來啊！他們腦子壞了嗎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25208 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25208, 2, 0, 'zhTW', '我們已經脫離了危險。我可以自己回去的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25208 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25208, 3, 0, 'zhTW', '感謝你救了我，$r。請轉告國王我回來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25210 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25210, 0, 0, 'zhTW', '我是鑰匙的管理者，你是守護者嗎？');
