INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 0, 0, 'zhTW', '%s咕噥著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 1, 0, 'zhTW', '航道……補給……我快給你煩死了！薩魯法爾，部落需要的只是勇者無畏的精神罷了！既然我們已經在這片冰原上站穩了腳跟，還有什麼能阻擋我們呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 2, 0, 'zhTW', '我的計劃？你很快就會明白的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 3, 0, 'zhTW', '瞧……我們已經開闢出了一條航道。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 4, 0, 'zhTW', '不僅如此……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 5, 0, 'zhTW', '別跟我談什麼後果，老傢伙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 6, 0, 'zhTW', '你總不會認為那些孩子會永遠單純吧？他們長大之後，就會拿起武器來對付我們了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25237 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25237, 7, 0, 'zhTW', '薩魯法爾，你能活那麼久嗎？昔日的陰影難道不會吞噬你的軀殼嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25248 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25248, 0, 0, 'zhTW', '好吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25248 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25248, 1, 0, 'zhTW', '總算不用遮遮掩掩了！阿爾薩斯，賜予我力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25248 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25248, 2, 0, 'zhTW', '$c，你還不知道自己招惹到什麼人了吧！死神在朝你招手呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25248 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25248, 3, 0, 'zhTW', '好吧，然後呢？我不會坐以待斃的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25250 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25250, 0, 0, 'zhTW', '怎麼回事……我怎麼了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25250 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25250, 1, 0, 'zhTW', '啊……我感到頭暈目眩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25250 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25250, 2, 0, 'zhTW', '先驅者，我會認真考慮你的建議。同時，我們也會隨時向你們諮詢的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25251 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25251, 0, 0, 'zhTW', '薩薩里安！你還活著！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25251 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25251, 1, 0, 'zhTW', '我還以為……還以為你已經死了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25251 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25251, 2, 0, 'zhTW', '別再離我而去了！你想為你的祖國而戰，可你的祖國根本不願意接納你！他們派你來送死！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25251 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25251, 3, 0, 'zhTW', '你的眼神說明了一切……我說服不了你。別再讓我聽到你的噩耗了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 0, 0, 'zhTW', '我們被包圍了……加爾魯什，敵人正從四面八方湧來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 1, 0, 'zhTW', '天災軍團如蝗蟲一般揮師北下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 2, 0, 'zhTW', '聯盟控制著這個地區唯一一條安全的航道，即便如此，這條航道也面臨著隨時被致命的迷霧吞噬的危險。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 3, 0, 'zhTW', '唯一能夠正常運轉的補給港口位於這片大陸的另一端，在被遺忘者手中！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 4, 0, 'zhTW', '無法用地精飛艇運送的物資必須透過航運，橫穿整個北裂境才能到我們這裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 5, 0, 'zhTW', '攻城器械、彈藥、重型盔甲……沒有這些，你打算如何轟開寒冰皇冠的城牆？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 6, 0, 'zhTW', '這就是你所謂的計劃嗎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 7, 0, 'zhTW', '加爾魯什，你的脾氣和你父親簡直一模一樣。總是這麼暴躁……既暴躁又鹵莽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 8, 0, 'zhTW', '你腦子裡只想著戰爭與殺戮，完全不考慮後果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 9, 0, 'zhTW', '加爾魯什，我和你的父親都飲下了惡魔領主的鮮血。瑪諾洛斯的詛咒同樣在我的血脈裡流淌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 10, 0, 'zhTW', '我也曾征戰沙場，令敵人心膽俱裂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 11, 0, 'zhTW', '格羅姆付出了生命的代價，將我們從詛咒中解放出來，但他無法讓我們忘記那段可怕的歲月。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 12, 0, 'zhTW', '他也無法抹去我們犯下的可怕罪行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 13, 0, 'zhTW', '%s頓了一頓。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 14, 0, 'zhTW', '詛咒解除後的那個嚴冬，數以百計的獸人士兵都在絕望中迷失了方向，我也不例外。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 15, 0, 'zhTW', '我們終於恢復了理智，是的……終於能夠反省自己在燃燒軍團驅使下做出的魯莽行徑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 16, 0, 'zhTW', '%s點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 17, 0, 'zhTW', '最讓他們愧疚難安的就是德萊尼小孩的哭喊聲……日夜縈繞在耳畔……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 18, 0, 'zhTW', '你去過野豬農場吧？豬長到適合屠宰的年紀時……對，那種慘烈的嘶叫。你聽過豬臨死前的哀嚎聲麼……非常刺耳。那些日子對我們這樣的老兵來說真是煎熬。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 19, 0, 'zhTW', '%s搖了搖頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 20, 0, 'zhTW', '我指的不僅僅是敵人的孩子……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 21, 0, 'zhTW', '%s頓了一頓。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 22, 0, 'zhTW', '加爾魯什，我不能坐視不管，任由你帶領族人重新踏上那條黑暗的道路。我會在局勢無可挽回之前親手殺了你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 23, 0, 'zhTW', '我可不吃豬肉……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25256 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25256, 24, 0, 'zhTW', '%s啐了一口。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25285 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25285, 0, 0, 'zhTW', '將軍，我向你保證，我能在一個月內招募到兩個團的兵力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25285 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25285, 1, 0, 'zhTW', '好吧，將軍。如果你改變主意的話，我們會很樂意提供軍事援助的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25288 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25288, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25301 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25301, 0, 0, 'zhTW', '將軍，我們的軍隊主要是由村民和農夫構成的。他們都是很好的人，但是還沒有完全擺脫自小養成的偏見和迷信。他們還沒有準備好與外來盟友並肩作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 0, 0, 'zhTW', '基爾加丹開始引導黑暗能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 1, 0, 'zhTW', '離毀滅又近了一步！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 1, 1, 'zhTW', '基爾加丹開始引導黑暗能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 2, 0, 'zhTW', '你還能相信誰？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 2, 1, 'zhTW', '敵人就在你們中間！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 3, 0, 'zhTW', '這個消耗品已經沒用了！不管它了！現在我已經做到了連薩格拉斯都沒有做到的事情！我要徹底毀滅這個世界，真正成為燃燒軍團的主宰者！末日已經到來啦！讓這個世界就此支離破碎吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 4, 0, 'zhTW', '一切膽敢阻擋我們的敵人，');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 4, 1, 'zhTW', '毀滅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 4 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 4, 2, 'zhTW', '毀滅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 5, 0, 'zhTW', '我是不會失敗的！這個世界註定要毀滅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 6, 0, 'zhTW', '別再抱有幻想了！你們不可能贏！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 7, 0, 'zhTW', '啊啊啊！太陽之井的能量……開始……對抗我！你們都做了些什麼？你們都做了些什麼？？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25315 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25315, 8, 0, 'zhTW', '基爾加丹開始引導黑暗能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 0, 0, 'zhTW', '趁他虛弱時發動攻擊！殺死基爾加丹！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 1, 0, 'zhTW', '我會將我的力量匯入寶珠中！準備好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 2, 0, 'zhTW', '我又將能量灌入了另一顆寶珠！快去使用它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 2, 1, 'zhTW', '你們並不是在孤軍奮戰！藍龍軍團會幫助你們消滅欺詐者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 3, 0, 'zhTW', '又有一顆寶珠準備好了！快點行動！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 5, 0, 'zhTW', '安薇娜，你必須覺醒過來！這個世界需要你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 6, 0, 'zhTW', '你必須清醒過來！變回過去的你，變回你原來的樣子！就是現在，安薇娜！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 7, 0, 'zhTW', '安薇娜，我愛你！仔細聆聽我的聲音！回到我的身邊來！只有你才能淨化太陽之井！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 8, 0, 'zhTW', '對，安薇娜！投入命運的懷抱吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 9, 0, 'zhTW', '永別了，我摯愛的安薇娜。儘管只有我們少數人會記住你，但是你今天的英勇事蹟改變了命運的軌跡。曾被玷汙的太陽之井又重歸純淨。英雄們，千萬不要讓安薇娜白白地犧牲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25319 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25319, 10, 0, 'zhTW', '你們並不是在孤軍奮戰！藍龍軍團會幫助你們消滅欺詐者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25321 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25321, 0, 0, 'zhTW', '謝謝你救了我！願好運永遠伴隨你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25321 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25321, 0, 1, 'zhTW', '卡斯卡拉會銘記你的恩情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25322 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25322, 0, 0, 'zhTW', '$c，謝謝你給予我們的幫助，願先祖永遠庇佑你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25322 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25322, 0, 1, 'zhTW', '謝謝你，$c。願微風與海洋保佑你。');
