INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25335, 0, 0, 'zhTW', '$n會幫助我們展開攻擊。讓祖先的靈魂重歸寧靜吧！');
