INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25335, 4, 0, 'zhTW', '喏，瞧見那面旗幟和他的屍體了吧。怎麼回事？他朝我們衝了過來！');
