INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25335, 5, 0, 'zhTW', '你做得很好。返回北方的獸人要塞吧，告訴博古洛克大王我們成功了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25359 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25359, 0, 0, 'zhTW', '我自由了！謝謝你。');
