INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25372, 0, 0, 'zhTW', '可悲的蟲子！放了我，也許我可以讓你們死得痛快點！');
