INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25379, 0, 0, 'zhTW', '$n，別讓這名逃兵再溜走了。至少我們得維護聯盟的顏面。');
