INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25478, 4, 0, 'zhTW', '告訴你吧，我們已經封印了那位尊貴的大法師。就算你能找到她，可鑰匙在莎爾蘭德手中。你不過是在白費力氣！');
