INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25478, 6, 0, 'zhTW', '不！！！這太過份了！你已經問出大法師的下落了……為什麼還不放了我？');
