INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25806, 0, 5, 'zhTW', '不是吧！30個犀牛頭就能換一個犀牛頭盔？給我來兩個！');
