INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25832, 0, 0, 'zhTW', '我是麥卡佐德的使者。我們會治好你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25833 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25833, 0, 0, 'zhTW', '鬧劇該結束了。一旦我搞定你，麥卡佐德就會治癒你身上的詛咒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25834 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25834, 0, 0, 'zhTW', '孩子，你是來找我的嗎？$n，為什麼要殺我呢？我只是想幫忙啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25834 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25834, 1, 0, 'zhTW', '我再次復甦啦，這樣我們就能回到那個完美的時代……泰坦的時代！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25834 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25834, 2, 0, 'zhTW', '你的眼神和心跳騙不了我，雖然我能讓你永生，但是你還是會殺了我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25834 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25834, 3, 0, 'zhTW', '非常好。事情變成這樣真令我難過。我把你們都當作自己的孩子。如果有必要的話，我會殺了你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25835 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25835, 0, 0, 'zhTW', '真是怪事！這畜生剝掉了自己的皮！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25835 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25835, 0, 1, 'zhTW', '中頭彩了！');
