INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25835, 0, 3, 'zhTW', '就差一隻，我就能弄齊一套奈辛瓦里牛排刀啦！');
