DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25850 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25850, 0, 0, 'zhTW', '%s對你發出了讚許的哼哼聲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25885 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25885, 0, 0, 'zhTW', '嘿，先驅者，調查進行得怎麼樣了？如果你在訂購期限前購買的話，就有機會得到一塊超導聊天鐵哦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25885 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25885, 1, 0, 'zhTW', '來率先體驗一下超級無敵的靜電除汙器吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25885 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25885, 2, 0, 'zhTW', '源自破碎殘陽的軍用高階技術，輕鬆去除各類頑固汙漬！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25885 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25885, 3, 0, 'zhTW', '無論是酒漬、泥漬，還是寵物留下的汙漬，靜電除汙器都能將它們清除乾淨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25885 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25885, 4, 0, 'zhTW', '不要猶豫了！現在訂購還能得到我免費贈送的超導聊天鐵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25949 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25949, 0, 0, 'zhTW', '這些石頭應該是最後一批了。我們和耐普圖隆部隊的合作將會無懈可擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25949 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25949, 1, 0, 'zhTW', '那麼你們自己的準備做得怎麼樣了？冰霜之王會開啟通往傳送門的道路嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25949 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25949, 2, 0, 'zhTW', '盤牙水庫的儀式將在埃霍恩完全準備好的時候喚醒它，炎魔之王和冰霜之王的衝突將會對這個世界的根基造成傷害。我們的最終目的終於就要實現了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25951 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25951, 0, 0, 'zhTW', '是的，獵潮者會對這項部署非常滿意。火焰領主的威力將被削弱。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25951 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25951, 1, 0, 'zhTW', '卡希斯已經告訴我們了。我們已經進入了奴隸圍欄，就等你們的冰術師了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 25979 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (25979, 0, 0, 'zhTW', '讓我們較量一下吧！');
