INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26073, 0, 0, 'zhTW', '是誰打斷了我的冥想？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26076 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26076, 0, 0, 'zhTW', '搞什麼啊？！是誰打擾我享用美餐！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26097 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26097, 0, 0, 'zhTW', '謝謝你救了我們。我們偶然發現了機甲專家麥卡佐德的零件，並把他重新組裝了起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26097 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26097, 1, 0, 'zhTW', '作為感謝，他要為我們“驅除詛咒”，將我們“變回”機械體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26097 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26097, 2, 0, 'zhTW', '他聲稱泰坦的創造物都中了什麼“血肉的詛咒”。他還說地精原本都是機械地精。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26097 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26097, 3, 0, 'zhTW', '他瘋了！必須阻止他，否則就遲了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 0, 0, 'zhTW', '放鬆點，幼龍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 1, 0, 'zhTW', '一份完美的標本。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 1, 1, 'zhTW', '沉睡吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 1, 2, 'zhTW', '很好，這將使我的研究更進一步……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 2, 0, 'zhTW', '克莉斯塔薩！要不是局勢惡劣，我真希望為你舉行歡迎儀式。你平安地回來了，命運真是仁慈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 3, 0, 'zhTW', '瑪裡苟斯——現身？天大的好機會啊。我這就去召集同胞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26117 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26117, 4, 0, 'zhTW', '當然，女王。再見……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26165 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26165, 0, 0, 'zhTW', '死亡不過是無盡痛苦的開始。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 0, 0, 'zhTW', '%s哭了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 1, 0, 'zhTW', '停下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 2, 0, 'zhTW', '小心！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 3, 0, 'zhTW', '%s指了指東北方。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 4, 0, 'zhTW', '遠處那股煙……啊，是沃圖克。他想要告訴我們什麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 5, 0, 'zhTW', '%s熟練地破譯出了烽煙中包含的資訊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 6, 0, 'zhTW', '不……這不可能……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26167 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26167, 7, 0, 'zhTW', '冰霧村……但願不是冰霧村……不！！！快！英雄，跟我來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 0, 0, 'zhTW', '莉蕾薩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 1, 0, 'zhTW', '你這個混蛋精靈雜種，你對我的妹妹做了什麼！？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 2, 0, 'zhTW', '我寧願自行了斷。為了你對同胞犯下的罪行，阿爾薩斯，為了你對我犯下的罪行，你會付出代價的！我發誓！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 3, 0, 'zhTW', '莉蕾薩……你……你沒事吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 4, 0, 'zhTW', '我還不能跟你回家，莉蕾薩。我和天災軍團之間的賬還沒有算清呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 5, 0, 'zhTW', '也許你是對的，莉蕾薩。我早已經不再虧欠我的祖國和國王任何東西，可是……我還欠自己一個交代。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26170 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26170, 6, 0, 'zhTW', '別擔心，莉蕾薩。我完成使命後就回去找你。那時，世界上就再也沒有任何東西能阻擋我回家的腳步了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26179 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26179, 0, 0, 'zhTW', '非勝即死！為了部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26184 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26184, 0, 0, 'zhTW', '非勝即死！為了部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26196 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26196, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26199 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26199, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26203 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26203, 0, 0, 'zhTW', '你在這裡所取得的進展令人眼前一亮，血之王子。我很滿意。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26203 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26203, 1, 0, 'zhTW', '這可真是個驚喜，薩薩里安。我已經數月沒有聽到有關莫格萊尼和其他死亡騎士的訊息了。我猜，你是回來重新加入天災軍團的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26203 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26203, 2, 0, 'zhTW', '別讓我失望，薩萊因。把這個蠢貨的首級帶回寒冰皇冠，否則就不用回去見我了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 0, 0, 'zhTW', '跟緊我，$n。我不能讓你受到任何傷害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 1, 0, 'zhTW', '瑪裡苟斯！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 2, 0, 'zhTW', '來吧，魔法之王，奪回你親愛的配偶……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 3, 0, 'zhTW', '……奪回她的屍體吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 4, 0, 'zhTW', '跟我來，$n。讓我們瞧瞧目前取得的成果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 5, 0, 'zhTW', '快跑，$n！快！你必須活下去，完成我們未竟的事業……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26237 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26237, 6, 0, 'zhTW', '休想！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 0, 0, 'zhTW', '凡人英雄們，很早以前的預言之中就昭示了你們今天的勝利。我那墮落兄弟的悽慘號叫將會響徹整個宇宙——這也會把希望帶給那些仍然在反抗著燃燒軍團的人們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 1, 0, 'zhTW', '燃燒軍團徹底滅亡的日子又更近了一步，你們再一次將這個世界從火焰中拯救下來，你們應當為此而自豪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 2, 0, 'zhTW', '這一天標誌著一個結束，這一天也宣告了一個全新的開始……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 3, 0, 'zhTW', '你們之前消滅的那隻熵魔，曾經是一位高貴的納魯，他名叫穆魯。生前，他一直將代表著光明與希望的能量帶給世人。不過，有一段時間，一些迷茫的孩子卻囚禁了它，偷取這些能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 4, 0, 'zhTW', '幸運的是，我在這位高貴的納魯隕落的地方回收了他的火種！在火種中，希望仍然沒有消逝，年輕的血精靈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 5, 0, 'zhTW', '凝視它，凡人們，凝視穆魯這顆依然純潔無瑕的心。沐浴在這創生的光芒之中吧，就如同在沐浴晨曦一般。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 6, 0, 'zhTW', '很快，其中蘊涵著的光明與希望——將重新構成一個不僅僅只是能量源泉的事物……或許，它們將構成一個國家的靈魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 7, 0, 'zhTW', '救贖，孩子。它在等待著我們所有人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26246 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26246, 8, 0, 'zhTW', '再見。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26247 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26247, 0, 0, 'zhTW', '我們的傲慢是無法寬恕的。我們竟然加害於一位如此高貴的存在，這樣的罪孽永遠也無法彌補。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26247 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26247, 1, 0, 'zhTW', '可以嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26247 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26247, 2, 0, 'zhTW', '多麼神聖的靈魂！我感覺到……那麼博愛……那麼高貴……這……不是語言可以形容的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26287 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26287, 0, 0, 'zhTW', '塞爾讚的護命匣滾落到冰雪風暴腳下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26293 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26293, 0, 0, 'zhTW', '巨大的冰蟲張開大嘴，顫抖了一會兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26310 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26310, 0, 0, 'zhTW', '克莉斯塔薩！你殺死了我的配偶……那就由你來代替她吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26321 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26321, 0, 0, 'zhTW', '%s向你致謝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26334 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26334, 0, 0, 'zhTW', '構造體，要不惜一切代價保住我們的主城！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26334 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26334, 0, 1, 'zhTW', '戰鬥吧，孩子們！不要對敵人心軟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26334 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26334, 0, 2, 'zhTW', '同胞們，消滅岩石的子嗣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26334 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26334, 0, 3, 'zhTW', '為了領主！為了洛肯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26349 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26349, 0, 0, 'zhTW', '你來晚了！協議已經達成。只剩下一些無關緊要的細節。比如……如何處理你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26379 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26379, 0, 0, 'zhTW', '$n，讓我們並肩戰鬥吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26379 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26379, 1, 0, 'zhTW', '歡迎加入部落，大酋長。Lok\'tar Ogar！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26379 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26379, 2, 0, 'zhTW', '為了部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 0, 0, 'zhTW', '$n，再次感謝你為我帶來這麼好聞的薰香。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 1, 0, 'zhTW', '%s吞噬了薰香。好胃口！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 2, 0, 'zhTW', '真是太棒啦！香味中充斥著能量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 3, 0, 'zhTW', '熊熊燃燒的火炬就應該散發出這樣濃烈的香味！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 4, 0, 'zhTW', '我能感受到體內湧動的能量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 5, 0, 'zhTW', '%s放聲大笑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 6, 0, 'zhTW', '就是現在！我們的計劃生效啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 7, 0, 'zhTW', '渺小的凡人，跪下！向炎魔之王拉格納羅斯的使者致敬！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 8, 0, 'zhTW', '你們都將在火焰中化為灰燼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 9, 0, 'zhTW', '%s眨了眨眼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26401 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26401, 10, 0, 'zhTW', '啊。我只是在開玩笑……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26417 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26417, 0, 0, 'zhTW', '鋼鐵之子，助我一臂之力吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26417 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26417, 0, 1, 'zhTW', '碾碎這些小矮子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26417 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26417, 0, 2, 'zhTW', '鋼鐵之王，請在戰鬥中助我一臂之力！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26417 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26417, 0, 3, 'zhTW', '敵人越戰越勇！快幫幫我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26417 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26417, 0, 4, 'zhTW', '可憐蟲，我們要殺死你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26420 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26420, 0, 0, 'zhTW', '啊，是的。我對洛肯非常瞭解。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26420 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26420, 1, 0, 'zhTW', '他指揮鋼鐵的子嗣，對我們發動了戰爭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26420 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26420, 2, 0, 'zhTW', '他藏身在不為人知的角落，監督著戰爭的準備工作，想要消滅石巨人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26421 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26421, 0, 0, 'zhTW', '%s對你提出的要求感到非常憤怒，朝你發動了攻擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26421 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26421, 1, 0, 'zhTW', '%s在離開前從身上剝下一塊樹皮遞給你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26437 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26437, 0, 0, 'zhTW', '時局動盪不安，我們卻頑強地抵禦了天災軍團猛烈的攻勢！能成為部落的一員真是榮幸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 0, 0, 'zhTW', '他也在找我的麻煩呢！如果我是你的話，我在這一帶走動時會額外小心的。你永遠都不知道他會躲在哪棵樹後面！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 1, 0, 'zhTW', '喬伊怎麼會問這樣的問題！好吧，我確實知道洛肯的事。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 2, 0, 'zhTW', '聖光在上！你殺死了喬伊，還搶走了肉！你是怎麼找到我們的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 3, 0, 'zhTW', '好吧，就算你要殺我，至少等我餵飽格里西達吧？我可憐的寶貝已經好些日子沒吃過東西啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 4, 0, 'zhTW', '寶貝，殺死喬伊的兇手很快就要對我們下手了，讓我最後再餵你一次吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 5, 0, 'zhTW', '你怎麼忍心對喬伊這樣手無寸鐵的老頭下毒手？你把肉帶回來又有什麼企圖？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 6, 0, 'zhTW', '真是匪夷所思，我完全不明白你是怎麼想的……我得說，我很難和你這樣的傢伙相處……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 7, 0, 'zhTW', '你最好趁格里西達還沒有胃口吃餐後甜點之前離開。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 8, 0, 'zhTW', '格里西達，快醒醒。嘿。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 9, 0, 'zhTW', '這裡很安全，對吧？他們抓走了喬伊和米克基，我們得躲起來，不能讓他們發現。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 9 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 9, 1, 'zhTW', '我們已經擺脫那些怪物了！格里西達，他們和我們截然不同。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 9 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 9, 2, 'zhTW', '我們是獵人。這裡沒有狼人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26484 AND `GroupID` = 9 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26484, 9, 3, 'zhTW', '小姑娘，保持警惕！別讓他們抓到我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26497 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26497, 0, 0, 'zhTW', '阿爾薩斯！你怎麼能……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26497 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26497, 1, 0, 'zhTW', '對不起，阿爾薩斯。我不能眼睜睜地看著你走上歧途。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 0, 0, 'zhTW', '烏瑟爾，你總算及時趕到了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 1, 0, 'zhTW', '我自然不會忘記這一點。聽著，烏瑟爾，現在我來告訴你關於天災的事……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 2, 0, 'zhTW', '糟糕。我們太遲了。他們已經被感染了！雖然他們現在表面上還正常，但是遲早會變成亡靈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 3, 0, 'zhTW', '必須淨化整座城市。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 4, 0, 'zhTW', '烏瑟爾，大膽！我是你未來的國君，我命令你清理這座城市！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 5, 0, 'zhTW', '那麼，我只能將你的決定視為叛國了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 6, 0, 'zhTW', '是這樣嗎？我以王儲的身份在此宣佈，解除烏瑟爾勳爵在白銀之手騎士團的所有權力與職務。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 7, 0, 'zhTW', '就這樣吧！有誰希望拯救這片土地的，就跟我來！其他人……給我滾遠點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 8, 0, 'zhTW', '珍娜？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 9, 0, 'zhTW', '部隊在這裡待命，我會親自率領一支小分隊進入斯坦索姆，開始清理行動。為了洛丹倫，我們必須除掉所有被感染的城民！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 10, 0, 'zhTW', '大家都做好準備了吧。記住，斯坦索姆的城民已經受到感染，很快就會喪命。我們必須清洗斯坦索姆，確保洛丹倫的其它地區免受天災軍團的侵蝕。出發吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 11, 0, 'zhTW', '你已經感染得太深了，我能做的只有讓你毫無痛苦地安息。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 12, 0, 'zhTW', '這只是個開始。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 13, 0, 'zhTW', '我不會讓你得逞的，瑪爾加尼斯！我絕對不會眼睜睜地看著他們成為你的奴僕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 14, 0, 'zhTW', '瑪爾加尼斯肯定會派出天災部隊阻撓我們。我希望能有些精通劍術或魔法的勇士對抗天災士兵。而我，會率領剩餘的軍隊清理斯坦索姆中的亡靈，將全城拯救出來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 15, 0, 'zhTW', '立即與我在市政廳會合，勇士。我們必須直接挑戰瑪爾加尼斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 16, 0, 'zhTW', '跟我來，我知道路。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 17, 0, 'zhTW', '是的，我很高興能在災難大爆發之前找到你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 18, 0, 'zhTW', '這是什麼巫術？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 19, 0, 'zhTW', '看來瑪爾加尼斯除了天災軍團的亡靈大軍外，還另有秘密武器。我們得抓緊時間了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 20, 0, 'zhTW', '又是這種邪惡的巫術！提高警惕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 21, 0, 'zhTW', '我們走吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 22, 0, 'zhTW', '小心背後，我們被包圍了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 23, 0, 'zhTW', '又少了一個障礙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 24, 0, 'zhTW', '瑪爾加尼斯不會讓我們好過的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 25, 0, 'zhTW', '它們還真是夠頑強的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 26, 0, 'zhTW', '他還會派些什麼東西來阻擋我們？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 27, 0, 'zhTW', '為了洛丹倫，我會竭盡所能，無論是你的言論還是行為，都無法阻止我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 28, 0, 'zhTW', '通向瑪爾加尼斯的最短路線就在前面那個書架之後。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 29, 0, 'zhTW', '這只需要一小會兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 30, 0, 'zhTW', '我確信這條秘道還通著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 31, 0, 'zhTW', '我們儘快離開這裡。否則，就算不被亡靈殺死，也要被火燒死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 32, 0, 'zhTW', '休息一會，你們抓緊時間喘口氣，我們馬上就得重新上路。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 33, 0, 'zhTW', '就這樣吧，我們必須繼續上路了。瑪爾加尼斯在等著我們呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 34, 0, 'zhTW', '聖光在上。市場小徑還沒有著火。瑪爾加尼斯應該就躲藏在前面的十字軍廣場。你們準備好繼續前進的話，就告訴我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 35 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26499, 35, 0, 'zhTW', '正義必將得到伸張。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26499 AND `GroupID` = 36 AND `ID` = 0 AND `Locale` = 'zhTW';
