INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26532, 0, 0, 'zhTW', '阿爾薩斯·米奈希爾王子殿下，今天，你的靈魂已經被某種強大的黑暗力量侵蝕。你想要以死亡淨化這座城市，現在你也要面對毀滅的命運了。');
