INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26533, 0, 0, 'zhTW', '對，這只是個開始。年輕的王子，我等你很久了。我就是瑪爾加尼斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26533 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26533, 1, 0, 'zhTW', '如你所見，你的子民現在已經屬於我了。我已經將城中的居民統統變成了我的奴僕，讓斯坦索姆的生命之火……永遠熄滅了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26533 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26533, 2, 0, 'zhTW', '這真是最好的試煉，阿爾薩斯王子殿下。');
