INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 0, 0, 'zhTW', '嗯……有頭狼折回來了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 1, 0, 'zhTW', '他是來抓小毛球的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 2, 0, 'zhTW', '噢，不！又來了一頭狼，好大！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 3, 0, 'zhTW', '他會吃掉小毛球的！你得幫幫小毛球！幫幫小毛球呀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 4, 0, 'zhTW', '小毛球遇到大壞蛋啦！救命啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 5, 0, 'zhTW', '我們必須衝出去，否則狼群就要來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 6, 0, 'zhTW', '別朝有光的地方跑，小毛球！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 7, 0, 'zhTW', '小毛球，你竟然沒事！謝謝你救了小毛球，太感謝了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 8, 0, 'zhTW', '是營地！小毛球，我們很快就要到家啦！快點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 9, 0, 'zhTW', '謝謝你幫我返回營地。請轉告瓦爾特，就說我已經平安無事啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 10, 0, 'zhTW', '謝謝你幫我返回營地。請轉告瓦爾特，就說我已經平安無事啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 11, 0, 'zhTW', '小毛球，準備好了嗎？靠近我，小心這些狼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26588 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26588, 12, 0, 'zhTW', '謝謝你幫我返回營地。請轉告瓦爾特，就說我已經平安無事啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26593 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26593, 0, 0, 'zhTW', '很好。看來不派你去好好地教訓他們一下，他們是搞不清楚狀況的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26594 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26594, 0, 0, 'zhTW', '你成功釋放了你的靈魂！現在你可以充當我的眼睛了。讓我們找出真相。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26594 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26594, 1, 0, 'zhTW', '你已經到了村子上方！睜大你的眼睛。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26594 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26594, 2, 0, 'zhTW', '湖床上發生了什麼事？有奇怪的能量從那裡湧出。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26594 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26594, 3, 0, 'zhTW', '不……不！我的組人要麼變成了亡魂，要麼喪失了心智！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26594 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26594, 4, 0, 'zhTW', '那是長者瑪納洛的雕像。它注視著你，這是個好兆頭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26594 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26594, 5, 0, 'zhTW', '回來吧，$N。如果你的靈魂離開肉體太久的話，可能會回不來的。我們需要好好談一談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26602 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26602, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26604 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26604, 0, 0, 'zhTW', '墮落的巨魔……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26604 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26604, 1, 0, 'zhTW', '……接受烈焰的懲罰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26604 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26604, 2, 0, 'zhTW', '好啦！扯遠了……你覺得呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 0, 0, 'zhTW', '放棄吧，犛牛人！你們不是天災軍團的對手！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 0, 1, 'zhTW', '不留活口！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 0, 2, 'zhTW', '將這座村落夷為平地吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 1, 0, 'zhTW', '別以為你們從此就高枕無憂了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 2, 0, 'zhTW', '傲慢的凡人！你死定了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 3, 0, 'zhTW', '啊！！這不可能！怎麼會……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26608 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26608, 4, 0, 'zhTW', '阿努布耶坎被打敗了！隨便撿一塊蟲殼碎片，作為你獲勝的證明吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26626 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26626, 0, 0, 'zhTW', '別急著逃走呀！我還有份“餞別”禮物呢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26626 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26626, 1, 0, 'zhTW', '戰士們，站起來為你們的新主子而戰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26626 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26626, 2, 0, 'zhTW', '讓他們陪伴你吧，巫妖王向你致意！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26630 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26630, 0, 0, 'zhTW', '我要內臟！要鮮血！要食物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26630 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26630, 1, 0, 'zhTW', '把你剁碎，再吃掉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26630 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26630, 2, 0, 'zhTW', '好餓啊！必須吃飯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26630 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26630, 3, 0, 'zhTW', '要爆炸啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26630 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26630, 4, 0, 'zhTW', '要爆炸啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 0, 0, 'zhTW', '籠罩你的寒氣就是厄運的先兆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 1, 0, 'zhTW', '這就是反抗巫妖王的下場！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 2, 0, 'zhTW', '這一切……都是毫無意義的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 3, 0, 'zhTW', '協助防禦！快點，廢物們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 4, 0, 'zhTW', '很快你們就會發現一切都是徒勞無功。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 4, 1, 'zhTW', '放棄吧，老老實實地受死吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26631 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26631, 5, 0, 'zhTW', '%s尋求幫助！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 0, 0, 'zhTW', '薩隆亞已經預見了一切！凡人的徒勞努力根本無法毀滅永恆的王朝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 1, 0, 'zhTW', '正如薩隆亞所料！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 1, 1, 'zhTW', '正如預言所說！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 2, 0, 'zhTW', '你的血肉現在要為薩隆亞效勞了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 2, 1, 'zhTW', '你的軀殼對薩隆亞還有些用處！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 3, 0, 'zhTW', '不，這感覺……太短暫了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 3, 1, 'zhTW', '啊啊啊！我還要這種感覺！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26632 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26632, 4, 0, 'zhTW', '不……不可能！薩隆亞是不朽的！薩隆亞是……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26635 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26635, 0, 0, 'zhTW', '幫幫忙啊！我抗不住了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26635 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26635, 1, 0, 'zhTW', '增援！我們需要增援！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 0, 0, 'zhTW', '$n，為什麼召喚我？你和這裡的巨魔在策劃什麼陰謀？你想要殺死我，奪取我的力量嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 1, 0, 'zhTW', '你是卡魯亞克氏族的朋友？我對此持保留意見。如果你想讓我為他們占卜的話，就先證明自己的忠誠吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 2, 0, 'zhTW', '我要你做的事也不算太過分。當著我的面跳入深海吧，這樣你才能與我的精神融合，以此表達你的誠意。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 3, 0, 'zhTW', '雖說我提出了要求，不過你可以選擇跳或是不跳。我給你20秒做決定。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 4, 0, 'zhTW', '$n，你拒絕了我的要求。那麼我也拒絕占卜卡魯亞克氏族的命運。在你鼓起勇氣接受挑戰之前，別再召喚我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 5, 0, 'zhTW', '很好，$n。你充分表達了自己的誠意。我會如約告訴你關於卡魯亞克氏族的命運，請轉告他們吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 6, 0, 'zhTW', '請你轉告卡魯亞克海象人，逃亡是沒有出路的。一旦選擇逃亡，他們的靈魂將被北裂境滋生的邪靈毀滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 7, 0, 'zhTW', '告訴秘法師，卡魯亞克氏族必須與部落和聯盟並肩戰鬥，共同抵抗瑪裡苟斯和巫妖王的軍隊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 8, 0, 'zhTW', '你的使命已經達成，游回去吧。盡你所能地幫助他們，$r。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26648 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26648, 9, 0, 'zhTW', '$n，你拒絕了我的要求。那麼我也拒絕占卜卡魯亞克氏族的命運。在你鼓起勇氣接受挑戰之前，別再召喚我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 0, 0, 'zhTW', '放我出去，朋友！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 0, 1, 'zhTW', '你最好祈禱我永遠也出不來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 1, 0, 'zhTW', '我……自由了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 2, 0, 'zhTW', '他們對我的族人做了什麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 3, 0, 'zhTW', '你將為自己的所作所為付出代價，接受先祖的懲罰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 4, 0, 'zhTW', '重生吧，我的兄弟……站起來……再次投入戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 5, 0, 'zhTW', '為了冰霧村！為了犛牛人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 6, 0, 'zhTW', '來和我較量較量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26654 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26654, 7, 0, 'zhTW', '我會擊敗你的！風啊，讓我飛翔吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26660 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26660, 0, 0, 'zhTW', '趁現在！抬起那根木材就跑吧。部落不會打上一輩子仗，眼下正是賺錢的好機會呀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26666 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26666, 0, 0, 'zhTW', '酋長，刀下留人。他還有利用價值。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26666 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26666, 1, 0, 'zhTW', '還記得你找到的那本矮人日記嗎？呃，它的主人很可能就是我們追捕布萊恩·銅鬚的重要線索。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26666 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26666, 2, 0, 'zhTW', '我相信你會的，除非你想為難自己。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26666 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26666, 3, 0, 'zhTW', '托爾瑪克，你對此滿意嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26668 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26668, 0, 0, 'zhTW', '這感覺……真是超乎想象。我將永遠聽命於您，陛下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26668 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26668, 1, 0, 'zhTW', '能以您的名義殺死這些螻蟻令我十分榮幸，來吧，天災軍團的敵人們！我讓你們看看巫妖王的真正力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26668 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26668, 2, 0, 'zhTW', '我要征服你們的靈魂！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26668 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26668, 3, 0, 'zhTW', '妄圖挑戰巫妖王的力量？你太愚蠢了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26668 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
