DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 0, 0, 'zhTW', '別小瞧我，我也能一箭射中野獸的眉心……而且是在兩倍距離開外。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 1, 0, 'zhTW', '你居然敢侮辱我的父親。他比你勇敢得多。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 2, 0, 'zhTW', '我寧願死也不要變成你們那副模樣！你們還是人嗎？是……畜生！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 3, 0, 'zhTW', '畜生！快說！我的妹妹在哪兒，否則我不會放過你們的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 4, 0, 'zhTW', '安婭在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 5, 0, 'zhTW', '只剩最後一件事了。我必須知道阿魯高的下落。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 6, 0, 'zhTW', '安婭！！你平安無事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 7, 0, 'zhTW', '邪月島？是血月島吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26935 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26935, 8, 0, 'zhTW', '別害怕……現在你安全啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 0, 0, 'zhTW', '小姑娘，你才多大？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 1, 0, 'zhTW', '你是不可能擺脫宿命的，明白嗎？你不過是個孩子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 2, 0, 'zhTW', '你的父親是個懦夫，薩莎……他沒有勇氣完成自己的使命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 3, 0, 'zhTW', '最終，我們都會成為巫妖王的僕從。孩子，這比變成一具腐爛的屍體好多了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 4, 0, 'zhTW', '等等！別開槍！不要傷害塔特亞娜！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 5, 0, 'zhTW', '囚犯們被關押在山脈另一側的狼穴中。你說的姑娘很快就會被送到阿魯高那裡了。我們可以走了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 6, 0, 'zhTW', '原諒我，塔特亞娜……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 26971 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (26971, 7, 0, 'zhTW', '和阿魯高比起來，你對我們的威懾力差得遠了！我要將你撕成碎片！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27002 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27002, 0, 0, 'zhTW', '我要消滅你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27002 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27002, 1, 0, 'zhTW', '你不是猛獁人！你的……力量……是……怎麼來的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27003 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27003, 0, 0, 'zhTW', '我知道你為什麼會來這裡——平原上那些愚蠢的猛獁人多管閒事，竟然膽敢與龍族交戰。當他們的走狗很有趣嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27003 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27003, 1, 0, 'zhTW', '小傢伙，你在尋找他們的首領……你竟然想要挑戰雷霆使者戈洛塔爾領導的猛獁人氏族。別急著去送死吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27003 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27003, 2, 0, 'zhTW', '哈！好吧。碧藍巨龍聖地以南有一處火炬環繞之地，在那裡吹響猛獁人首領號角。向你信奉的諸神祈禱吧……戈洛塔爾就會出現。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27004 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27004, 0, 0, 'zhTW', '哈哈！我的奴隸這次帶來了正餐了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27005 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27005, 0, 0, 'zhTW', '哈哈！我的奴隸這次帶來了正餐了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27061 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27061, 0, 0, 'zhTW', '辛克的伐木機已經就緒，準備隨時伐木。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27061 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27061, 1, 0, 'zhTW', '辛克的伐木機的安全功能已經啟用。正在返回營地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27113 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27113, 0, 0, 'zhTW', '謝謝你救了我，我的同胞還被關押在上面幾層！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27114 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27114, 0, 0, 'zhTW', '謝天謝地！我正擔心他們會不會強迫我去對付石巨人呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27115 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27115, 0, 0, 'zhTW', '這幫鐵矮人瘋子！他們反覆談論要為“洛肯大人”效勞，但是據我所知，只有少數人接到他的指令而已。');
