INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27163, 0, 1, 'zhTW', '別讓他們靠近我！我保證能在15秒內搞定這玩意兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27163 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27163, 0, 2, 'zhTW', '掩護我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27163 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27163, 0, 3, 'zhTW', '看著吧，我會把這臺天災戰車包裝得像是地精的工程製品！保護我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27163 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27163, 0, 4, 'zhTW', '別讓那些壞人靠近我！');
