INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27163, 1, 0, 'zhTW', '%s嫻熟地裝配出一臺外形奇特的機械。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27163 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27163, 2, 0, 'zhTW', '就快搞定啦！再給我幾秒鐘。');
