INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27199, 0, 0, 'zhTW', '總算來了一份有價值的祭品！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27199 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27199, 1, 0, 'zhTW', '啊！！發生了什麼事？');
