INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27199, 2, 0, 'zhTW', '你連祭品都沒有準備就敢召喚我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 0, 0, 'zhTW', '阿比迪斯大人將會淨化你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 0, 1, 'zhTW', '你這個不潔者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 0, 2, 'zhTW', '哎！你幹什麼呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 1, 0, 'zhTW', '步兵，我能聞到你身上的土臭味兒。換班之前，向主教報到吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 1, 1, 'zhTW', '你的信仰很堅定，孩子。繼續做事吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 1, 2, 'zhTW', '韋斯溫大人正在這一帶巡視呢！如果再讓我看見你在崗位上划水，我就把你撕成碎片。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 1, 3, 'zhTW', '你需要主教大人的祝福。快去找他吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27202 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27202, 2, 0, 'zhTW', '幫幫我！幫幫我！這傢伙偷走了我的影像！');
