INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27203, 0, 0, 'zhTW', '鋼鐵的利刃將你淨化！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27203 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27203, 0, 1, 'zhTW', '聖光在上！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27203 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27203, 0, 2, 'zhTW', '以聖光之名！');
