INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 2, 0, 'zhTW', '等等……等等！你到底想知道什麼啊？！我知道你是個名叫$n的$C。');
