INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 3, 0, 'zhTW', '噢……不！我們知道是你偷了我們的盔甲、武器，還有馬匹！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 4, 0, 'zhTW', '我們知道……你們無法理解……為什麼我們……對所謂的病菌免疫。海軍上將巴利·韋斯溫似乎向高階修士傳授了什麼禱言。啊啊，求你了……住手……好嗎？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 5, 0, 'zhTW', '啊啊啊啊啊！求求你……我們……知道……有間諜……混進了……我們中間！我……我……我就知道這麼多啦。求求你……發發慈悲吧……停手呀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 6, 0, 'zhTW', '求你……住手。我……我什麼都願意做……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 7, 0, 'zhTW', '我求求你……住手。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 8, 0, 'zhTW', '啊啊啊啊啊啊啊啊啊啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 9, 0, 'zhTW', '你別想……從我這裡……得到……任何東西！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 10, 0, 'zhTW', '他們……都在……乞求……活命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 11, 0, 'zhTW', '我告訴你……我……什麼……都不知道！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27209 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27209, 12, 0, 'zhTW', '讓一切……結束吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27210 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27210, 0, 0, 'zhTW', '我會讓你們見識見識先鋒軍的真正實力！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27212 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27212, 0, 0, 'zhTW', '監工，進展太緩慢了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27212 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27212, 1, 0, 'zhTW', '命運不會為誰停留。在石巨人大軍抵達奧杜爾之前，你必須監督工匠提高作戰魔像的產量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27212 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27212, 2, 0, 'zhTW', '告訴你手下的符文鐵匠，必須加緊改造石巨人。摧毀那些不服從指令的傢伙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27212 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27212, 3, 0, 'zhTW', '如果石巨人膽敢阻撓我們在奧杜爾的工事，我就撤消你和你的領主的權利。絕不允許凡人幫助巨人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27212 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27212, 4, 0, 'zhTW', '回到你的崗位上去吧，監工。必須讓工匠們明白任務的急迫性。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 0, 0, 'zhTW', '讓我們瞧瞧這管不管用。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 1, 0, 'zhTW', '矮人，歡迎拜訪歐尼瓦營地的犛牛人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 2, 0, 'zhTW', '如果你願意幫助我們抵禦共同的敵人，我們保證不傷害你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 3, 0, 'zhTW', '考慮一下吧，勘查員，希望你能儘快做出決定。我們必須立即採取行動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 4, 0, 'zhTW', '你的計劃竟然成功了，我真是又驚又喜。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 5, 0, 'zhTW', '我們不能讓你回到同伴身邊，也不能讓你和我們呆在一起……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27221 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27221, 6, 0, 'zhTW', '他還有利用價值，就留著他吧。矮人，如果我是你的話，我會更加謹慎的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27224 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27224, 0, 0, 'zhTW', '這一切都是為什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27224 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27224, 0, 1, 'zhTW', '全是謊言……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27224 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27224, 0, 2, 'zhTW', '叛徒，你還記得對我們許下的諾言嗎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27224 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27224, 0, 3, 'zhTW', '王子拋棄了我們！所有的希望都破滅了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27224 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27224, 0, 4, 'zhTW', '阿爾薩斯！你這個騙子！我們都被你給害了！');
