INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27225, 0, 5, 'zhTW', '我們的性命遠比你那所謂的血海深仇重要……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27227 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27227, 0, 0, 'zhTW', '我……我這是在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27227 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27227, 1, 0, 'zhTW', '等等！你說過如果我幫你的忙，你就放我一條生路的。我可是一直遵照約定幫助你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27227 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27227, 2, 0, 'zhTW', '聖光在上，布萊恩還活著？我死也不會幫你追捕他的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27234 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27234, 0, 0, 'zhTW', '你們被騙了！血色先鋒軍都是騙子！天災軍團和被遺忘者不是我們的敵人！醒醒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27235 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27235, 0, 0, 'zhTW', '與血色先鋒軍斷絕關係！別再聽信將軍和元帥編造的謊言了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27236 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27236, 0, 0, 'zhTW', '阿比迪斯就是個臭婊子！海軍上將巴利·韋斯溫也不過是個皮條客，他以低廉的價格出賣了阿比迪斯，就像出賣我們一樣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27237 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27237, 0, 0, 'zhTW', '阿比迪斯將軍親口對我說，北征北裂境是個錯誤，我們被詛咒了！我奉勸你們趕緊放下武器，趁早離開這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27238 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27238, 0, 0, 'zhTW', '天哪，我漂亮的小磨坊！你！我要你為此付出性命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27246 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27246, 0, 0, 'zhTW', '你能來真是太好啦，我的孩子。聖光對你的眷顧正在消退。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27246 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27246, 1, 0, 'zhTW', '好了。好好為聖光效勞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27246 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27246, 2, 0, 'zhTW', '你竟敢幹擾我們正義的事業？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27248 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27248, 0, 0, 'zhTW', '笨手笨腳的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27248 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27248, 1, 0, 'zhTW', '你把這批樣本完全搞砸了！你還有什麼可辯解的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27248 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27248, 2, 0, 'zhTW', '對不起？就會說對不起？！我對你太失望了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27248 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27248, 3, 0, 'zhTW', '哎呀。我覺得這玩意兒起作用啦！真奇怪。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27248 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27248, 4, 0, 'zhTW', '等我處理完收尾工作，就換個新助手！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27250 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27250, 0, 0, 'zhTW', '嗯？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27250 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27250, 1, 0, 'zhTW', '但是……我是嚴格按照你的指令做的！我該說對不起嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27250 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27250, 2, 0, 'zhTW', '耶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 0, 0, 'zhTW', '你真的懂得如何駕馭獅鷲嗎？我怎麼覺得有點晃悠悠的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 0, 1, 'zhTW', '我不是忘恩負義的傢伙啦，但是你能飛得再低一點嗎？我恐高！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 0, 2, 'zhTW', '我真是選了個戒酒的好日子啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 0, 3, 'zhTW', '我有點頭暈……嘔……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 0, 4, 'zhTW', '你救了我！謝謝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 0, 5, 'zhTW', '你真是我的守護天使！你就像來自天堂的白衣騎士，將我從地獄的深淵中解救出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 0, 'zhTW', '我該怎麼報答你呢，朋友？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 1, 'zhTW', '萬歲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 2, 'zhTW', '烏瑞克，這位勇士真是太善良了。謝謝你，英雄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 3, 'zhTW', '我的店門將永遠對你敞開，朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 4, 'zhTW', '終於安全了！謝謝你，陌生人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 5, 'zhTW', '謝謝你的幫助，勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27315 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27315, 1, 6, 'zhTW', '我們成功了！我們真的成功了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 0, 0, 'zhTW', '退後點，$n。這頭野獸可能會突然暴起傷人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 1, 0, 'zhTW', '高弗雷！你這惡魔！你聽仔細了！我要代表聖光將你從邪惡中拯救出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 2, 0, 'zhTW', '很好。高弗雷，你肯聽我說話了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 3, 0, 'zhTW', '高弗雷，這事兒吧有兩種解決方式，我更喜歡開門見山的做法。你看，不如你直接告訴我秘典上的邪惡符號是什麼含義。怎麼樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 4, 0, 'zhTW', '好吧，那我就要用第二種解決方式了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 5, 0, 'zhTW', '迷失的靈魂，我會為你念上一段禱言。願聖光擁你入懷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 6, 0, 'zhTW', '訓誡開始。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 7, 0, 'zhTW', '讓聖光擁抱你吧，野獸！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 8, 0, 'zhTW', '在聖火中化為灰燼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 9, 0, 'zhTW', '讓聖光滲入你的靈魂，高弗雷！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 10, 0, 'zhTW', '屈服在聖光的力量下吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 11, 0, 'zhTW', '高弗雷，你已經見識到聖光的力量了……惡魔，說吧。秘典上都寫了些什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 12, 0, 'zhTW', '一派胡言！高弗雷，你當我是傻子嗎？別拿天災軍團那套邪說來恐嚇聖光的戰士！你放聰明點，不然我就叫人把你丟進裝滿聖水的木桶，像給狗除跳蚤那樣讓你衝個聖水浴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 13, 0, 'zhTW', '什麼！？暮冬城舊址下面有一座陵墓？我們對此事竟然毫不知情！高弗雷，我們會消滅你的主子，結束這場噩夢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 14, 0, 'zhTW', '高弗雷，我們自會對付塞爾贊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 15, 0, 'zhTW', '$n，向哈爾弗彙報這位“坦誠”的市長先生招供的情報吧。剩下的事交給我解決，說不定還能從他口中榨出一些有關塞爾讚的訊息呢。現在，我就讓高弗雷見識一下罕見的“第三種解決方式”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27316 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27316, 16, 0, 'zhTW', '來吧，我們開誠佈公地談一談。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27328 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27328, 0, 0, 'zhTW', '站到我身後，$r。我會盡力保護你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27328 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27328, 1, 0, 'zhTW', '如果不能拯救烏索克，那我的自由也就毫無意義了。要快，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27328 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27328, 2, 0, 'zhTW', '我會保護你和你的盟友，$r。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27328 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27328, 3, 0, 'zhTW', '烏索克，烏索爾的兄弟，熊怪部族的守護者……現身吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27328 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27328, 4, 0, 'zhTW', '烏索克，烏索爾的兄弟，熊怪部族的守護者……現身吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 0, 0, 'zhTW', '你真的懂得如何駕馭獅鷲嗎？我怎麼覺得有點晃悠悠的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 0, 1, 'zhTW', '我不是忘恩負義的傢伙啦，但是你能飛得再低一點嗎？我恐高！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 0, 2, 'zhTW', '我真是選了個戒酒的好日子啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 0, 3, 'zhTW', '我有點頭暈……嘔……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 0, 4, 'zhTW', '你救了我！謝謝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 0, 5, 'zhTW', '你真是我的守護天使！你就像來自天堂的白衣騎士，將我從地獄的深淵中解救出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 0, 'zhTW', '我該怎麼報答你呢，朋友？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 1, 'zhTW', '萬歲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 2, 'zhTW', '烏瑞克，這位勇士真是太善良了。謝謝你，英雄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 3, 'zhTW', '我的店門將永遠對你敞開，朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 4, 'zhTW', '終於安全了！謝謝你，陌生人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 5, 'zhTW', '謝謝你的幫助，勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27336 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27336, 1, 6, 'zhTW', '我們成功了！我們真的成功了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27344 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27344, 0, 0, 'zhTW', '衛兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27349 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27349, 0, 0, 'zhTW', '%s呻吟著，但是似乎並沒有受到感染。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27351 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27351, 0, 0, 'zhTW', '與聖光同行，朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27351 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27351, 0, 1, 'zhTW', '聖光護佑著你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27351 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27351, 0, 2, 'zhTW', '哦！我想那個食屍鬼的頭爆炸了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27351 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27351, 0, 3, 'zhTW', '他們曾經也是人……現在？視新鮮血肉如命的亡靈怪物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27355 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27355, 0, 0, 'zhTW', '不……天哪！你都做了什麼？！竟然殺死了這麼多遠古巨龍……這是什麼魔法？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27355 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27355, 1, 0, 'zhTW', '愚蠢的$g小子:小丫頭……你竟然敢打擾我的工作，受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27355 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27355, 2, 0, 'zhTW', '事情遠沒有結束……死亡……會令我……更加強大……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27359 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27359, 0, 0, 'zhTW', '你來得正是時候，英雄！我差點被那畜生給吃了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27359 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27359, 0, 1, 'zhTW', '終於，來了一位英雄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27359 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27359, 0, 2, 'zhTW', '謝謝你，善良的靈魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27359 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27359, 0, 3, 'zhTW', '我永遠不會忘記你的，朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27373 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27373, 0, 0, 'zhTW', '謝謝你們。將沃達希爾砍倒的德魯伊做出了明智的決定，蟄伏在地底的遠古邪靈已經侵淫了那棵世界之樹的根鬚。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27373 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27373, 1, 0, 'zhTW', '你們將這種生物稱為上古之神。它就是尤格-薩隆，擁有一千張嘴的怪物。它透過沃達希爾的根鬚散播著邪惡之力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27376 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27376, 0, 0, 'zhTW', '什麼叫我的日子到頭了？！把話說清楚，不然我宰了你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27376 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27376, 1, 0, 'zhTW', '嘿，在這兒呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27378 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27378, 0, 0, 'zhTW', '你不會是想……我要把你的罪行詳細記錄下來，$C！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27378 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27378, 1, 0, 'zhTW', '你一看就是個大好人，放我出去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27379 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27379, 0, 0, 'zhTW', '不！我求求你！千萬別殺我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27379 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27379, 1, 0, 'zhTW', '誰放我出去呀？我還要返回怨毒鎮換班呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27381 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27381, 0, 0, 'zhTW', '這到底是什麼意思？！住手！他們付你多少？？我可以給你兩倍的錢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27381 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27381, 1, 0, 'zhTW', '我剛剛到怨毒鎮啊，怎麼可能招惹到你？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 0, 0, 'zhTW', '凡人，曾經……我和你一樣，血肉之軀，不堪一擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 1, 0, 'zhTW', '阿爾薩斯王子從我身上看到了凡人的脆弱。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 2, 0, 'zhTW', '“終生為我效勞吧。我承諾，我會抹除你靈魂中的弱點。徹底抹除！”我以這樣的方式被巫妖王選中……接受了他的賜福。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 3, 0, 'zhTW', '我成為了巫妖王的僕從……恐怖之城納克薩瑪斯能重返北裂境全都是我的功勞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 4, 0, 'zhTW', '到此為止吧……你歷經萬難，終於站到了黃昏使者面前。我不會令你失望的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 5, 0, 'zhTW', '讓我拯救你吧，就像阿爾薩斯王子拯救我一樣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 6, 0, 'zhTW', '聖騎士，這將是你最後一次提及那個名字！受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27383 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27383, 7, 0, 'zhTW', '復活吧，我的侍從！聽從主人的命令！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27389 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27389, 0, 0, 'zhTW', '行了，別再估計什麼形勢不形勢的了，蠢貨！趕緊給我加入戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27389 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27389, 1, 0, 'zhTW', '再……見……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27389 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27389, 2, 0, 'zhTW', '真是……無上的……榮耀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27389 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27389, 3, 0, 'zhTW', '你或許也可以為我效勞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27389 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27389, 4, 0, 'zhTW', '斯卡瓦爾德，你這無能的廢物！滾回來，讓我把你變得更有用一點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27390 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27390, 0, 0, 'zhTW', '達爾隆！你有沒有勇氣和我一起上啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27390 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27390, 1, 0, 'zhTW', '沒……完……呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27390 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27390, 2, 0, 'zhTW', '一個戰士的……死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27390 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27390, 3, 0, 'zhTW', '呸！通靈師豈有死了就放棄的道理？你這沒用的東西！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27390 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27390, 4, 0, 'zhTW', '呸！通靈師豈有死了就放棄的道理？你這沒用的東西！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27405 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27405, 0, 0, 'zhTW', '這裡發生了什麼事，長官？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27406 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27406, 0, 0, 'zhTW', '我不知道。為了安全起見，最好將他們統統殺掉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27411 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27411, 0, 0, 'zhTW', '你被咬了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27411 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27411, 1, 1, 'zhTW', '回答我啊！你是不是被咬了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27411 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27411, 2, 2, 'zhTW', '你不知道？獵戶？他們已經不是人類了……我們必須離開這裡！快走！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27411 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27411, 3, 3, 'zhTW', '牽走杜卡爾的馬吧，他已經徹底淪陷了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27411 AND `GroupID` = 4 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27411, 4, 4, 'zhTW', '喏，後面有燈油——你知道該怎麼做吧。那幫混蛋對火焰又恨又怕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27430 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27430, 0, 0, 'zhTW', '毀滅結界正在充能。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27430 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27430, 1, 0, 'zhTW', '毀滅結界充能完畢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27439 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27439, 0, 0, 'zhTW', '我知道有個僻靜的去處，我們可以去那裡單獨談談。跟我來吧，孩子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27439 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27439, 1, 0, 'zhTW', '你覺著我看不出你那拙劣的偽裝嗎，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27439 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27439, 2, 0, 'zhTW', '$r，世間有許多你無法瞭解的玄機。只有全知全能的主上才能洞悉一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27439 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27439, 3, 0, 'zhTW', '他早就預知你會來對付我。我親眼目睹了你對我的同胞做過的事。但是，我是不會死在你手上的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27439 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27439, 4, 0, 'zhTW', '別妄想了。我將以自己選擇的方式離開這個世界。但是，我會遵照主上的意志捲土重來的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27439 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27439, 5, 0, 'zhTW', '啊啊啊啊啊啊啊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27447 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27447, 0, 0, 'zhTW', '我是不會心慈手軟的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27447 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27447, 1, 1, 'zhTW', '炸死他們！摧毀他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27447 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27447, 2, 2, 'zhTW', '%s召喚出一名碧藍魔環上尉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27447 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27447, 3, 3, 'zhTW', '他們……咳……太強大！我低估了……他們的頑強。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27447 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27447, 4, 0, 'zhTW', '入侵者，你們一路的勝勢到此為止了。我是指揮官瓦爾洛斯。我和飛龍們制御著這裡的天空，保護著這裡的管線，也將保證魔樞之眼不會落入你們的手中！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 0, 0, 'zhTW', '上尉，衛兵怎麼都不在自己的哨位裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 1, 0, 'zhTW', '烏瑟爾要召回我的軍隊？見鬼！如果戰士們離我而去，我要怎麼殺死瑪爾加尼斯？必須要趕在他們回到海邊之前燒燬船隻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 2, 0, 'zhTW', '全都燒成灰燼！我們事業未盡，誰也不能提前回家！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 3, 0, 'zhTW', '別管我了，穆拉丁。你沒見過瑪爾加尼斯對我的家鄉做了什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 4, 0, 'zhTW', '看，穆拉丁，我們最後的希望，霜之哀傷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 5, 0, 'zhTW', '為了拯救我的祖國，再惡毒的詛咒我也承受。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 6, 0, 'zhTW', '該死！無論是誰，都無法阻止我的復仇，老朋友。你，也不行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 7, 0, 'zhTW', '現在，我召喚鎮守此地的魂靈。我願付出任何代價，做出任何犧牲，只要你能協助我拯救祖國的人民。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27455 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27455, 8, 0, 'zhTW', '現在，我召喚鎮守此地的魂靈。我願付出任何代價，做出任何犧牲，只要你能協助我拯救祖國的人民。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27461 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27461, 0, 0, 'zhTW', '不！！！媽媽！！！我們會為你報仇的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27462 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27462, 0, 0, 'zhTW', '嘖嘖，臭鼬、小白兔和小鹿結伴出遊。這樣的場景還真是少見啊。不過我的晚餐倒是有著落了！難得的野味啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27463 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27463, 0, 0, 'zhTW', '啊……感覺好多了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27463 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27463, 0, 1, 'zhTW', '哇咧！我差點死在這裡。謝謝你，$r！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27463 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27463, 0, 2, 'zhTW', '謝謝你，$c。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27476 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27476, 0, 0, 'zhTW', '抱歉，大使閣下，但王子殿下因故離開了。請問您來這片冰霜廢土有什麼事嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27476 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27476, 1, 0, 'zhTW', '這麼說我們要馬上離開這裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27476 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27476, 2, 0, 'zhTW', '該死的亡靈！弟兄們，直接從森林中穿過去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27476 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27476, 3, 0, 'zhTW', '呃，殿下，您的父王應烏瑟爾大人的請求召回了全軍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27480 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27480, 0, 0, 'zhTW', '這是否太過分了，夥計？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27480 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27480, 1, 0, 'zhTW', '你對你的部下說謊，還背叛了為你而戰的僱傭兵。你到底怎麼了，阿爾薩斯？你就只有復仇這個念頭了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27480 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27480, 2, 0, 'zhTW', '等等，夥計。基座上有一行銘文，好像是警告。上面說，“持此劍者將獲永恆之力。此劍喋血以展鋒銳，此力噬靈以顯威能”。噢，我早該知道的。這把劍被詛咒了。我們快走吧，別管它了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27480 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27480, 3, 0, 'zhTW', '別去動它，阿爾薩斯。忘了它吧，帶你的弟兄們回家。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27480 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27480, 4, 0, 'zhTW', '啊……頭疼……我……我在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27480 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27480, 5, 0, 'zhTW', '我……我是誰？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27482 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27482, 0, 0, 'zhTW', '就在我近乎絕望的時候，你為我帶來了生的希望！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27482 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27482, 0, 1, 'zhTW', '祝福你，朋友。我快……不行了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27482 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27482, 0, 2, 'zhTW', '要不是你，我肯定沒命了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27482 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27482, 0, 3, 'zhTW', '謝謝你，$r！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27483 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27483, 0, 0, 'zhTW', '%s兇狠地舉起了爪子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27492 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27492, 0, 0, 'zhTW', '根據皇家敕令，部隊立刻返回洛丹倫。烏瑟爾大人已經說服國王陛下召回這支遠征軍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27492 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27492, 1, 0, 'zhTW', '沒錯。我的手下也報告說，從這裡通向海岸的道路被亡靈佔據了。你必須另找一條路回到船上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27539 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27539, 0, 0, 'zhTW', '每一個倒下的戰士都會補充成為我們的一員。和我們對抗毫無勝算。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27539 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27539, 0, 1, 'zhTW', '站起來吧……吞噬他們的血肉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27539 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27539, 0, 2, 'zhTW', '巨龍的時代即將終結……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27539 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27539, 0, 3, 'zhTW', '毫無希望。你們終將失敗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27539 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27539, 0, 4, 'zhTW', '你們在死後也別想得到安寧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27539 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27539, 0, 5, 'zhTW', '你們的抗爭毫無意義。你們終將倒在無盡的天災大軍之下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27551 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27551, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27570 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27570, 0, 0, 'zhTW', '我們會沒命的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27570 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27570, 0, 1, 'zhTW', '逃出這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27570 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27570, 0, 2, 'zhTW', '我根本不想呆在這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27570 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27570, 0, 3, 'zhTW', '我不管啦！我要回家！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27570 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27570, 0, 4, 'zhTW', '我可沒有同意做這樣的事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 0, 0, 'zhTW', '%s咆哮著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 1, 0, 'zhTW', '%s發出嘶嘶聲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 2, 0, 'zhTW', '我不會告訴你的，你這神棍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 3, 0, 'zhTW', '你能把我怎麼樣？你莫非比克爾蘇加德更殘忍？比巫妖王更厲害？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 4, 0, 'zhTW', '你說得沒錯，這本秘典是拯救你們的唯一希望……但是你永遠無法知道真相了！我什麼都不會說！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 5, 0, 'zhTW', '聖光！不要！求求你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 6, 0, 'zhTW', '我從未體驗過這樣的煎熬！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 7, 0, 'zhTW', '秘典中記載了即將到來的天啟。世界將在灰燼中毀滅，然後重獲新生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 8, 0, 'zhTW', '不要啊！！！我說！我什麼都說！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 9, 0, 'zhTW', '人類……自作孽。納克薩瑪斯為什麼會攻擊這裡？就因為你們在暮冬城地下建起的陵墓！塞爾贊躲在你們的墓穴中，喚醒成千上萬的殭屍與你們為敵！你們將被毀滅……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 10, 0, 'zhTW', '你們打算如何對付他？人類真是既天真又愚蠢。居然想打敗黃昏使者塞爾贊！為了獲得力量，他犧牲了原本的血肉之軀。巫妖王庇佑著如今的巫妖塞爾贊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27577 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27577, 11, 0, 'zhTW', '你們不可能阻止塞爾贊！他擁有巫妖王陛下賜予的黑暗之能！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 0, 0, 'zhTW', '要不是你，我們就死定了。謝謝你帶我們回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 0, 1, 'zhTW', '為了聯盟，為了弗塔根公爵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 0, 2, 'zhTW', '啊！騎兵隊到啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 0, 3, 'zhTW', '技術不錯啊！我們毫髮無損！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 0, 'zhTW', '我看見了一輛天災戰車！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 1, 'zhTW', '薩多爾大橋是我炸燬的！我難道沒有告訴你們？真的，所謂黑鐵矮人破壞了大橋，那都是謠傳！我才是真兇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 2, 'zhTW', '這樣毫無道理啊。為什麼天災軍團不將納克薩瑪斯飛到暮冬要塞上空，然後直接炸燬它呢？我是說，如果我是克爾蘇加德，肯定這麼做啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 3, 'zhTW', '或許有一天，我們能揭開這種神秘礦石的真面目。那時我們就可以好好利用它啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 4, 'zhTW', '嘿，你們認識瓦加德的米克高維爾嗎？他是我的叔叔哦。那你們知道他的頭銜嗎？“專家。”聽聽，多帥氣啊。我也想成為一名專家。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 5, 'zhTW', '什麼東西這麼臭啊！肯定不是我。地精散發著黃油和陽光的味道，才不像那些髒兮兮的矮人。他們簡直像從穴居人的腋窩裡爬出來的一樣！這裡沒有矮人，對吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 6, 'zhTW', '我認識一個矮人，這傢伙宣稱地精是從地下進化來的。我們的祖先是沙漠地精。簡直是一派胡言！還沙漠地精呢！我呸！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 7, 'zhTW', '我從未見過如此嚴重的破壞程度……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 8, 'zhTW', '安靜！我們要保持警惕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 9, 'zhTW', '死亡的氣息覆蓋著這裡的每一寸土地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 10, 'zhTW', '聽說你獨自一人就將村民們空運到安全地帶，使他們免受苦難的折磨。是真的嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 11, 'zhTW', '有誰知道塞爾贊嗎？他是誰？他是如何成為統領天災軍團地面部隊的統帥的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 12, 'zhTW', '瞧瞧眼前的慘狀……天災軍團會此付出代價的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 13 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 13, 'zhTW', '屍體都到哪兒去了？他們對村民們做了什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 1 AND `ID` = 14 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 1, 14, 'zhTW', '我希望自己能親眼目睹阿爾薩斯接受命運的審判！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27588 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27588, 2, 0, 'zhTW', '報告，長官！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27619 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27619, 0, 0, 'zhTW', '覺醒吧，阿魯高！巫妖王的力量命令你覺醒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27624 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27624, 0, 0, 'zhTW', '對……他完全符合我們的要求。請你將他送去冬至村吧。如果我們不能按時完成阿爾薩斯陛下交代的任務，他會不滿意的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 0, 'zhTW', '你準備好作戰了嗎，$c？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 1, 'zhTW', '讓我們一起加入戰鬥吧，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 2, 'zhTW', '我們是先攻打聖地呢，還是先對付敵軍？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 3, 'zhTW', '我們一直在盼望著你，$n。現在我們總算佔據了優勢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 4, 'zhTW', '真不敢相信，藍龍軍團居然會攻擊我們。我們要發動反擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 5, 'zhTW', '我準備好了。讓我們保衛神廟吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 6, 'zhTW', '從哪裡著手呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 0, 7, 'zhTW', '$n，久仰大名啊。這場戰鬥一定會非常有趣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 0, 'zhTW', '我從來沒有想過自己會載著一名$r投身戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 1, 'zhTW', '又一隻藍龍倒下啦。我們的配合真是天衣無縫！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 2, 'zhTW', '只要我們通力合作，這場戰爭很快就能分出勝負。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 3, 'zhTW', '瑪裡苟斯顯然是瘋了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 4, 'zhTW', '幹得不錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 5, 'zhTW', '我從未見過這樣的場面。有你陪同真是太好了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 6, 'zhTW', '還好你留意到那隻藍龍啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 1 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 1, 7, 'zhTW', '抓緊。讓我們勇敢地迎接挑戰吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27629 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27629, 2, 0, 'zhTW', '我們應該離開這裡。我需要恢復！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27631 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27631, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27646 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27646, 0, 0, 'zhTW', '你不會吃掉我的，對吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27646 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27646, 1, 0, 'zhTW', '姐姐！那些卑鄙的傢伙打算將我帶去邪月島，把我變成他們的一員。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27646 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27646, 2, 0, 'zhTW', '對，就是那個島嶼！邪月島！薩莎……別再離開我啦！他們抓走了爸爸，然後又抓走了你……我不想和他們單獨相處！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 0, 0, 'zhTW', '絕不能釋放這些囚犯！瑪裡苟斯的話就是律法！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 1, 0, 'zhTW', '多麼恰當的懲罰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 1, 1, 'zhTW', '行刑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 1, 2, 'zhTW', '又一個戰爭的犧牲品。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 2, 0, 'zhTW', '戰爭……還會繼續的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 3, 0, 'zhTW', '現在逃跑已經太晚了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 3, 1, 'zhTW', '都給我過來……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 3, 2, 'zhTW', '誰也別想逃跑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 3, 3, 'zhTW', '我判處你們死刑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 4, 0, 'zhTW', '顫抖吧，蠕蟲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 4, 1, 'zhTW', '我要消滅你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27654 AND `GroupID` = 4 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27654, 4, 2, 'zhTW', '會飛麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 0, 0, 'zhTW', '看看是誰來了？一群公然蔑視並挑戰織法者的狂徒？一群完全缺乏理解與遠見的蠢貨。我怎樣才能讓你們看清這真相呢？瑪裡苟斯是在拯救這個世界！咳，我為什麼要跟你們廢話？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 1, 0, 'zhTW', '顯然，我的寵物們失敗了。看來還得另外安排一次示範。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 2, 0, 'zhTW', '你們還要打下去嗎？你們仍然遵守著被扭曲的教條嗎？如果你們能活下來，就到中央的圓環中找我吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 3, 0, 'zhTW', '可憐而無知的蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 4, 0, 'zhTW', '%s開始施放強化魔爆術！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 5, 0, 'zhTW', '稍微見識見識吧……見識一下織法者的真正力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 5, 1, 'zhTW', '這麼多不穩定的能量……但為了消滅你們，這點風險不算什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 6, 0, 'zhTW', '我所做的一切……都是為了艾澤拉斯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 7, 0, 'zhTW', '如果你能早點理解就好了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 7 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 7, 1, 'zhTW', '你明白了嗎？明白了嗎？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27655 AND `GroupID` = 7 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27655, 7, 2, 'zhTW', '真不幸，但這是必要的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 0, 0, 'zhTW', '蠢貨！你們根本無法理解這種你們正在對抗著的偉大力量。魔網能量的傳輸是不會被你們干擾的！而你們，唯一的結局只有失敗與死亡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 1, 0, 'zhTW', '你們這些莽撞的入侵者已經無計可施了！我要親自把你們碾碎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 2, 0, 'zhTW', '如此肆意妄為，如此驕縱輕狂……必須懲罰你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 3, 0, 'zhTW', '這可要很久才能落地的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 3, 1, 'zhTW', '回到塵土中去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 3, 2, 'zhTW', '好好享受墜落的快感！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 4, 0, 'zhTW', '好好珍惜這場勝利吧，愚蠢的低等動物。你們和你們的龍類盟友或許贏得了這次戰役，但我們……才是整個魔樞戰爭的勝利者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 5, 0, 'zhTW', '奧術魔法歸我們號令！休想用它來對付我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 5, 1, 'zhTW', '熄滅你們的小火苗，完全沒有難度！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27656 AND `GroupID` = 5 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27656, 5, 2, 'zhTW', '自然魔法現在幫不了你們啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27658 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27658, 0, 0, 'zhTW', '感謝你們，凡人。藍龍軍團已經察覺到你們的動向，你們要當心。眼下，瑪裡苟斯任命瓦爾洛斯·雲擊率領碧藍魔環衛士死守魔環。請接受我們的幫助，這樣才有機會擊敗敵人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27683 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27683, 0, 0, 'zhTW', '我一直守護著這座被雅立史卓莎女王祝福過的聖地，光陰荏苒……連我都不記得度過了多長時間。在最為黑暗的年代，我未能盡到自己的職守……我倒在了死亡騎士血毒的腳下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27683 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27683, 1, 0, 'zhTW', '達莉亞想起那個名字，往地上啐了口口水。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27683 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27683, 2, 0, 'zhTW', '巫妖王已經伸出魔爪……肆無忌憚地踐踏著龍族最神聖的領地。他想逼迫我們採取行動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27683 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27683, 3, 0, 'zhTW', '我的時日不多了……我為雅立史卓莎女王奉獻了一生，可死亡終將阻斷我的奉獻之意。紅玉巨龍聖地需要一名新的守護者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27683 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27683, 4, 0, 'zhTW', '謝謝你……謝謝你將我從被詛咒的枷鎖中解救出來。你是個英雄……我知道你還會幹出驚天動地的大事來的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27683 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27683, 5, 0, 'zhTW', '達莉亞之魂逐漸消失了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 0, 0, 'zhTW', '%s飛走了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 1, 0, 'zhTW', '朋友，歡迎你。在這裡記得隨時保持警惕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 2, 0, 'zhTW', '使用吸血之毒對敵人造成傷害，同時保持對我的治療。噩夢之觸非常強大，但會對我造成傷害，所以只能在我的生命值較高的情況下使用！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 3, 0, 'zhTW', '我已經具備全部力量，可以使用夢境通道了。你能利用它治療其他幼龍，但這個技能會消耗我的生命值，因此必須與吸血之毒配合使用！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 4, 0, 'zhTW', '我傷得很重！我無法承受更多的傷害了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 5, 0, 'zhTW', '還有$3486W個離心構造體。我們必須摧毀它們，才能破除瓦爾洛斯·雲擊的護盾。你可以在位於魔環中層的加速之環找到那些構造體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 6, 0, 'zhTW', '只剩1個離心構造體了。我們必須摧毀它們，才能破除瓦爾洛斯·雲擊的護盾。你可以在位於魔環中層的加速之環找到那些構造體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 7, 0, 'zhTW', '破除護盾，削弱瓦爾洛斯的防禦力量！擊敗他，碧藍魔環衛士就會消失，這樣我們就能繼續往上層前進了。前往位於魔環中層的加速之環，在浮動平臺上找到瓦爾洛斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 8, 0, 'zhTW', '下一個目標是法師領主伊洛姆。前往靠近魔環頂層的轉化之環，在浮動平臺上找到伊洛姆。他正在引導藍色的魔樞能量旋。當心，這位強大的咒術師能召喚僕從幫他作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 9, 0, 'zhTW', '只要除掉魔網守護者埃雷苟斯，我們就能控制魔環。他就在位於魔環頂層的校準之環上方盤旋。埃雷苟斯擁有難以想象的力量。開戰之後你待在我背上吧，讓我來對付他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27692 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27692, 10, 0, 'zhTW', '只要除掉魔網守護者埃雷苟斯，我們就能控制魔環。他就在位於魔環頂層的校準之環上方盤旋。埃雷苟斯擁有難以想象的力量。開戰之後你待在我背上吧，讓我來對付他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 0, 'zhTW', '這是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 1, 'zhTW', '一切都結束了？只要阻止塞爾讚的陰謀，天譴之門的戰事就能取得勝利？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 2, 'zhTW', '能與你們並肩作戰是我無上的榮耀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 3, 'zhTW', '死亡終究會奪走我們的性命，但是有時候它比預想的來得要快。今天，我們將其稱之為盲勇……明天，後人或許就將其形容為愚蠢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 4, 'zhTW', '來吧……結束這場噩夢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 5, 'zhTW', '看上去像是通往地獄的大門！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 6, 'zhTW', '我有些擔心。原本應該站出來領導我們的英雄在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 0, 7, 'zhTW', '如果我不能重返暮冬要塞，請轉告我的家人，我從未放棄過與他們團聚的夢想……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27713 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27713, 1, 0, 'zhTW', '公爵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27719 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27719, 0, 0, 'zhTW', '女士們，先生們！我說……你們一定不想錯過這場戰鬥吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27726 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27726, 0, 0, 'zhTW', '面對困境，我做出了明智的判斷，而你卻束手無策。克雷娜，我不願意眼睜睜地看著你將我們帶上絕路！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27726 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27726, 1, 1, 'zhTW', '我們有必要鬧得這麼僵嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27726 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27726, 2, 2, 'zhTW', '我們走著瞧吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27726 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27726, 3, 3, 'zhTW', '為什麼……為什麼？我們非要鬧到這步田地嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27727 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27727, 0, 0, 'zhTW', '你揹著我耍花招，無視我的命令。你會付出代價的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27727 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27727, 1, 1, 'zhTW', '夠了。這場戰鬥結束後，我與你便再無瓜葛。那時，即便是座狼，也不願意靠近你的屍體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 0, 0, 'zhTW', '%s飛走了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 1, 0, 'zhTW', '朋友，歡迎你。在這裡記得隨時保持警惕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 2, 0, 'zhTW', '使用震擊之槍對敵人造成傷害。如果我們遇到麻煩，就使用停止時間將敵人凍結，然後使用震擊之槍對他們造成大量傷害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 3, 0, 'zhTW', '我已經具備全部力量，可以使用時間裂隙了。你能利用它對敵人造成額外的傷害並獲得震擊能量。積攢足夠的能量後，再使用震擊之槍造成大量傷害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 4, 0, 'zhTW', '我傷得很重！我無法承受更多的傷害了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 5, 0, 'zhTW', '還有$3486W個離心構造體。我們必須摧毀它們，才能破除瓦爾洛斯·雲擊的護盾。你可以在位於魔環中層的加速之環找到那些構造體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 6, 0, 'zhTW', '只剩1個離心構造體了。我們必須摧毀它們，才能破除瓦爾洛斯·雲擊的護盾。你可以在位於魔環中層的加速之環找到那些構造體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 7, 0, 'zhTW', '破除護盾，削弱瓦爾洛斯的防禦力量！擊敗他，碧藍魔環衛士就會消失，這樣我們就能繼續往上層前進了。前往位於魔環中層的加速之環，在浮動平臺上找到瓦爾洛斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 8, 0, 'zhTW', '下一個目標是法師領主伊洛姆。前往靠近魔環頂層的轉化之環，在浮動平臺上找到伊洛姆。他正在引導藍色的魔樞能量旋。當心，這位強大的咒術師能召喚僕從幫他作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 9, 0, 'zhTW', '只要除掉魔網守護者埃雷苟斯，我們就能控制魔環。他就在位於魔環頂層的校準之環上方盤旋。埃雷苟斯擁有難以想象的力量。開戰之後你待在我背上吧，讓我來對付他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27755 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27755, 10, 0, 'zhTW', '只要除掉魔網守護者埃雷苟斯，我們就能控制魔環。他就在位於魔環頂層的校準之環上方盤旋。埃雷苟斯擁有難以想象的力量。開戰之後你待在我背上吧，讓我來對付他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 0, 0, 'zhTW', '%s飛走了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 1, 0, 'zhTW', '朋友，歡迎你。在這裡記得隨時保持警惕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 2, 0, 'zhTW', '使用灼熱之怒對敵人造成傷害；如果我開始承受傷害，就使用閃避機動。記住，我必須以承受傷害的方式積攢閃避能量，才能使用閃避機動！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 3, 0, 'zhTW', '我已經具備全部力量，可以使用殉難了。你能利用它保護其他幼龍，但這會讓我承受大量傷害，因此必須與閃避機動配合使用！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 4, 0, 'zhTW', '我傷得很重！我無法承受更多的傷害了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 5, 0, 'zhTW', '還有$3486W個離心構造體。我們必須摧毀它們，才能破除瓦爾洛斯·雲擊的護盾。你可以在位於魔環中層的加速之環找到那些構造體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 6, 0, 'zhTW', '只剩1個離心構造體了。我們必須摧毀它們，才能破除瓦爾洛斯·雲擊的護盾。你可以在位於魔環中層的加速之環找到那些構造體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 7, 0, 'zhTW', '破除護盾，削弱瓦爾洛斯的防禦力量！擊敗他，碧藍魔環衛士就會消失，這樣我們就能繼續往上層前進了。前往位於魔環中層的加速之環，在浮動平臺上找到瓦爾洛斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 8, 0, 'zhTW', '下一個目標是法師領主伊洛姆。前往靠近魔環頂層的轉化之環，在浮動平臺上找到伊洛姆。他正在引導藍色的魔樞能量旋。當心，這位強大的咒術師能召喚僕從幫他作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 9, 0, 'zhTW', '只要除掉魔網守護者埃雷苟斯，我們就能控制魔環。他就在位於魔環頂層的校準之環上方盤旋。埃雷苟斯擁有難以想象的力量。開戰之後你待在我背上吧，讓我來對付他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27756 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27756, 10, 0, 'zhTW', '只要除掉魔網守護者埃雷苟斯，我們就能控制魔環。他就在位於魔環頂層的校準之環上方盤旋。埃雷苟斯擁有難以想象的力量。開戰之後你待在我背上吧，讓我來對付他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 0, 0, 'zhTW', '接下來介紹盤踞在納克薩瑪斯頂端的生物。他們擁有無可思議的強大力量，當之無愧地被冠以北裂境兩大威脅的稱號。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 1, 0, 'zhTW', '接下來介紹納克薩瑪斯的死亡騎士區。在腐化力量的侵蝕下，我們最傑出的戰士淪為了天災軍團的走狗。如今，戰爭的號角日夜在死亡騎士區的大廳中迴盪。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 2, 0, 'zhTW', '接下來介紹納克薩瑪斯毒氣繚繞的憎惡區。天災軍團在這裡製造大批強壯而醜陋的怪物，以此擴充他們的軍事武裝力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 3, 0, 'zhTW', '接下來介紹納克薩瑪斯被詛咒的蜘蛛區。天災軍團在這裡培育蛛怪的變種，以便繁殖出毒性更厲害的危險生物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 4, 0, 'zhTW', '接下來介紹納克薩瑪斯恐怖的天災區。天災軍團在這裡進行藥理研究，企圖改良他們在洛丹倫傳播的藥劑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 5, 0, 'zhTW', '這尊影像就留給你們觀察吧。仔細研究對手的能力，他的優勢很可能也是致命的弱點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 6, 0, 'zhTW', '薩菲隆。它本是高貴的藍龍，自由地翱翔在北裂境的冰峰間，被征戰極寒之地的阿爾薩斯所殺。克爾蘇加德復活了薩菲隆，如今這頭冰霜巨龍守衛著主子的巢穴，等待那些膽敢挑戰克爾蘇加德的冒險者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 7, 0, 'zhTW', '巫妖克爾蘇加德。顯然他為巫妖王效力。克爾蘇加德生前是一名強大的通靈師，死後自然而然地成為了巫術大師。據說他是巫妖王最忠誠的部下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 8, 0, 'zhTW', '克爾蘇加德透過了最為嚴酷的試煉。即便是聖光兄弟會的成員，這樣的試煉也會撼動他們的靈魂。克爾蘇加德將自己的生命完完全全交給了阿爾薩斯，然後藉助太陽之井的力量得以復生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 9, 0, 'zhTW', '克爾蘇加德再次被駐紮在瘟疫之地的銀色黎明擊敗。可是他的護符匣落到了聖光兄弟會某個不忠誠的成員手中。至今我們還不知道是誰偷走了護符匣以及其中的陰謀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 10, 0, 'zhTW', '注意。這是教官拉蘇維奧斯，由克爾蘇加德親自指派的死亡騎士訓練師。這位威嚴的教官擁有獨特的教學法則，據說只有他的學徒才有可能承受得住他的威力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 11, 0, 'zhTW', '收割者戈提克。作為巫咒與魔法的大師，據說戈提克能瞬間召喚出亡靈軍團為他作戰。在他的指導下，即便是能力最弱的死亡騎士也能令亡者復生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 12, 0, 'zhTW', '天啟四騎士是納克薩瑪斯中最強大的死亡騎士，是克爾蘇加德麾下最頂尖的防禦將領。首先介紹庫爾塔茲領主，他能操縱火焰的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 13, 0, 'zhTW', '下一位是女公爵布勞繆克絲。她能召喚暗影的力量，吞噬活人的靈魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 14, 0, 'zhTW', '瑟裡耶克爵士。生前他是一名信仰堅定的聖騎士，雖然他已是死靈之軀，卻依然能召喚聖光的力量懲擊敵人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 15, 0, 'zhTW', '最後一位死亡騎士是大領主莫格萊尼。他曾經是一名傑出的戰士，最優秀的死亡騎士在他面前也會黯然失色。但是，當他在艾澤拉斯經歷了一系列的變故後，便消失得無影無蹤了。目前還不知道克爾蘇加德指派了誰來取代他的位置。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 16, 0, 'zhTW', '這是帕奇維克。聖光兄弟會第一次聽聞他的傳言時，沒有誰相信憎惡也能擁有如此迅捷的速度和可怕的力量。當帕奇維克初戰告捷後，大家便不再認為那是謠言了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 17, 0, 'zhTW', '格羅布魯斯，天災軍團製造的血肉巨人。格羅布魯斯體內蠕動著納克薩瑪斯的軟泥怪，能侵蝕給任何敢於靠近它的敵人。被注入軟泥怪的受體通常會逃回盟友身邊，頃刻之間就能擊潰所有人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 18, 0, 'zhTW', '格拉斯，納克薩瑪斯骯髒的天災犬。據說這隻野獸極其貪婪，每天費爾根都會給它送去一批缺乏作戰力的亡靈。格拉斯堪稱是天災軍團廢物利用系統的終端。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 19, 0, 'zhTW', '塔迪烏斯，用女人與孩子的血肉縫合而成的巨人。據說他們的靈魂也融入塔迪烏斯體內，永遠被禁錮在這骯髒的囚牢中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 20, 0, 'zhTW', '阿努佈雷坎，艾卓-尼魯布最傑出的蛛怪領主之一。多年前，他與蛛怪之王阿努巴拉克都慘敗在巫妖王手中，此後便被天災軍團控制了。據說他曾是阿努巴拉克麾下最忠誠的領主。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 21, 0, 'zhTW', '黑女巫法琳娜。生前她是一位植物學家，死後她為巫妖王效力，負責管理蜘蛛區的蛛怪培育與毒藥研製工作。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 22, 0, 'zhTW', '邁克斯納。數百年前，這隻出生在北裂境冰峰深處的蜘蛛就被天災軍團虜進了納克薩瑪斯。她在這座恐怖之城中繁衍後代，那些膽敢進入納克薩瑪斯的冒險者都淪為了蜘蛛的美餐。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 23, 0, 'zhTW', '這是藥劑師諾斯。天災軍團將人們囚禁在冰冷的死靈牢籠的計劃，便是他提出的創意。至今，諾斯仍然負責監督並完善這一流程。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 24, 0, 'zhTW', '這是骯髒的希爾蓋。他就是指揮天災軍團利用天災之鍋將艾澤拉斯寧靜的曠野變成詛咒之地的罪魁禍首。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 25, 0, 'zhTW', '據說希爾蓋對納克薩瑪斯的牆壁和地板進行了改造，設定了大量可以隨意觸發的可控陷阱。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27784 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27784, 26, 0, 'zhTW', '洛歐塞布。據說這個地方的詛咒與艾澤拉斯的沼澤獸縫合而成的怪物擁有控制治療能量的本領。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27788 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27788, 0, 0, 'zhTW', '我差點被食屍鬼給吃了！謝謝你救了我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27788 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27788, 0, 1, 'zhTW', '謝天謝地，你來救我們啦！我們還以為這次肯定完蛋了呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27788 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27788, 0, 2, 'zhTW', '謝謝你掩護我！下面簡直就像精神病院！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27788 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27788, 0, 3, 'zhTW', '哇，我還以為我死定了呢！謝謝你，朋友！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 0, 0, 'zhTW', '地精們今晚又有蝙蝠胃囊吃啦……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 0, 1, 'zhTW', '他們想讓蝙蝠以那種危險的飛行角度降落嗎？好呀，就讓乘客們摔斷脖子吧，他們還能喝到鮮美的蝙蝠湯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 0, 2, 'zhTW', '“我們都喜歡樹木，芬裡克。它們是很好的遮蔽物。”呸，就是不肯讓我砍掉這些討厭的植物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 0, 3, 'zhTW', '援軍正陸續趕來，不知道傷亡人數要上升到什麼程度，他們才肯同意我砍掉這些討厭的樹木。我們的蝙蝠損失嚴重。或許我應該給它們配備盔甲……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27842 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27842, 1, 0, 'zhTW', '衛兵！快來幫幫我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27843 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27843, 0, 0, 'zhTW', '$n，我會將她趕出藏身之地。你要做好準備，待會她一露面就動手！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27844 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27844, 0, 0, 'zhTW', '開火！！擊中她！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27851 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27851, 0, 0, 'zhTW', '霜之哀傷洞穴劇烈地搖晃起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27857 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27857, 0, 0, 'zhTW', '士兵們，振作起來。$n已經幫我們揭開了最後的謎團。巫妖塞爾贊很快就會顯身，讓我們一舉擊敗他吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27857 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27857, 1, 0, 'zhTW', '這就是塞爾讚的護命匣，它是我們取勝的關鍵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27857 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27857, 2, 0, 'zhTW', '士兵們，堅持住！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27858 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27858, 0, 0, 'zhTW', '榮耀、勇氣、憐憫、公正！塞爾贊，當年你也曾發誓恪守這些美德，成為一名合格的銀色黎明祭司。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27858 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27858, 1, 0, 'zhTW', '你將全副身心都花在對抗天災軍團的大業上。你曾親眼目睹他們在洛丹倫犯下的罪行。巫妖王奪走了你的一切！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27858 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27858, 2, 0, 'zhTW', '那麼英尼戈·蒙托爾神父是如何墮落的呢？身為銀色黎明的精神領袖，他為什麼會變成自己百般唾棄的魔鬼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27858 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27858, 3, 0, 'zhTW', '加入戰鬥吧！讓我們了結這一切！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27858 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27858, 4, 0, 'zhTW', '勝利屬於聯盟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27858 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27858, 5, 0, 'zhTW', '你拯救了暮冬要塞！塞爾讚的威脅已經解除，殘餘的天災士兵就交給第七軍團解決吧。等你處理完這裡的事務後，就去天譴之門安加薩報到吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27871 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27871, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 1, 0, 'zhTW', '嗨，$n。別害怕。我……就是來自未來的……你。我是來幫你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 2, 0, 'zhTW', '瞧……他們來了。我會盡全力幫助你。別讓他們靠近沙漏！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 3, 0, 'zhTW', '你可千萬別出事啊。你若是死了，我也就不存在了，對吧？但是如果你真的死了的話，我又是如何能從未來返回呢。我被繞糊塗了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 4, 0, 'zhTW', '真不敢相信，我竟然穿過這樣的裝備。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 5, 0, 'zhTW', '不好意思，克羅米禁止我透露任何未來的事情。她警告說，如果我告訴了你，那我有可能就不會存在了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 6, 0, 'zhTW', '啊，我差點忘記啦，原來以前我是這麼缺乏經驗啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 7, 0, 'zhTW', '瞧瞧你在戰鬥中的表現，難怪我會染上酒癮。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 8, 0, 'zhTW', '什麼？你應該很清楚吧，我們的命運是休慼相關的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 9, 0, 'zhTW', '聽著。我本來不打算告訴你的，很快你就會接到聚會的邀請。總之，千萬別喝宴會上的飲料！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 10, 0, 'zhTW', '我真希望能想起來到底有多少永恆之龍想阻止你。這場戰鬥實在是太久遠啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 11, 0, 'zhTW', '瞧，沙漏顯現出諾茲多姆的影像！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27899 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27899, 12, 0, 'zhTW', '再見，$n。好好活著，搞些更好的裝備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27914 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27914, 0, 0, 'zhTW', '我到啦。我們開始吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27914 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27914, 1, 0, 'zhTW', '啊，我要吸取更多的精華……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27914 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27914, 2, 0, 'zhTW', '這是你的那份。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27915 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27915, 0, 0, 'zhTW', '幹得漂亮！到斯坦索姆的大門去，我會交給你下一項任務！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27915 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27915, 1, 0, 'zhTW', '冒險者，你要加快點速度了。時光守護者的力量可無法持續太久。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27915 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27915, 2, 0, 'zhTW', '我僅能維持一會了，我看到時光守護者的時間線在迅速衰退。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27923 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27923, 0, 0, 'zhTW', '坐穩啦，$n！向無賴港出發！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27923 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27923, 1, 0, 'zhTW', '啊！我們到啦！你瞧，無賴港！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27928 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27928, 0, 0, 'zhTW', '別出現在我面前，不然我殺了你。我再說一次。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27928 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27928, 0, 1, 'zhTW', '不要。滾遠點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27928 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27928, 0, 2, 'zhTW', '離我遠點，愛德華。否則我要你好看。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27933 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27933, 0, 0, 'zhTW', '旅途愉快！這是單程航線！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27951 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27951, 0, 0, 'zhTW', '阿比迪斯，殺光他們！別讓我失望！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27951 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27951, 1, 0, 'zhTW', '海軍上將眯起眼睛，仔細地打量著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27951 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27951, 2, 0, 'zhTW', '你已經體現了自己的價值。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27951 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27951, 3, 0, 'zhTW', '到寒冰皇冠來找我吧，懦夫……如果你們還能活著到那裡的話！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27959 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27959, 0, 0, 'zhTW', '你以為冥想能幫助你洗滌內心的雜念嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27959 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27959, 1, 0, 'zhTW', '蠢貨！我要徹底摧毀你，成為你內心世界真正的主宰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27959 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27959, 2, 0, 'zhTW', '別想打敗我。我是你身體不可分割的一部分！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27959 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27959, 3, 0, 'zhTW', '不！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 0, 0, 'zhTW', '你不該來這裡……現在你就要死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 1, 0, 'zhTW', '為什麼會這樣呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 1, 1, 'zhTW', '是你逼我這麼做的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 1, 2, 'zhTW', '我心中的負擔更加沉重了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 1, 3, 'zhTW', '都是你的錯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 2, 0, 'zhTW', '我詛咒你們爛在這裡！我……不想要這個結局……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27975 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27975, 3, 0, 'zhTW', '失去了這麼多時間……你們永遠也無法挽回！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27977 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27977, 0, 0, 'zhTW', '壓……扁……你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27977 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27977, 1, 0, 'zhTW', '哈……哈……哈……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27977 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27977, 2, 0, 'zhTW', '啊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27977 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27977, 3, 0, 'zhTW', '打……碎……你……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27978 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27978, 0, 0, 'zhTW', '看看你們那軟弱的軀殼和短暫的生命。你們永遠也無法逃避血肉的詛咒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27978 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27978, 1, 0, 'zhTW', '血肉永遠無法勝過鋼鐵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27978 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27978, 1, 1, 'zhTW', '鋼鐵的大軍將令整個世界窒息！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27978 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27978, 1, 2, 'zhTW', '洛肯是不會放棄的……他一定會奪回熔爐！你們……什麼也無法改變！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27978 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27978, 2, 0, 'zhTW', '洛肯是不會放棄的……他一定會奪回熔爐！你們……什麼也無法改變！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27986 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27986, 0, 0, 'zhTW', '好吧，我會嚐嚐的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27986 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27986, 1, 0, 'zhTW', '這正是我夢寐以求的美酒啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27986 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27986, 2, 0, 'zhTW', '釀造得很成功啊！這酒的後勁還挺大的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27986 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27986, 3, 0, 'zhTW', '多里安，你錯過了一場驚心動魄的戰鬥！真是難忘的經歷啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27986 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27986, 4, 0, 'zhTW', '我們騎在斯塔比背上，全速開戰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27986 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27986, 5, 0, 'zhTW', '好啊，小夥子，你可以從閱讀《荊棘谷的青山》開始。然後，也許你能和我一同參加行動，你覺得如何？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27987 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27987, 0, 0, 'zhTW', '在這裡，東南方。啊，你也落到他們手裡了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 0, 0, 'zhTW', '你來晚了，$n。來自達拉然的另一位訪客已經來過這裡，同樣是為了瞭解有關遠古龍劍的事情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 1, 0, 'zhTW', '根據你的描述我可以斷定，我借給那位訪客的書能使你很容易地對這把武器做出鑑定。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 2, 0, 'zhTW', '恐怕，你得找——嗯，或許卡雷苟斯會幫忙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 3, 0, 'zhTW', '$n可能已經發現了古劍的碎片，卡雷苟斯。你會幫助我們的到訪者嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 4, 0, 'zhTW', '你認為我們的盟友沒有能力控制這些劍的力量？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 5, 0, 'zhTW', '我們都會如此。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 6, 0, 'zhTW', '拜託你了，凡人，同達拉然的奧術師泰拜林談一談。他可能有辦法和奪日者進行交涉，讓你看一看那本書。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 7, 0, 'zhTW', '拜託你了，凡人，在達拉然找到魔導師哈瑟爾。他可能有辦法和銀色盟約進行交涉，讓你看一看那本書。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27990 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27990, 8, 0, 'zhTW', '放心吧，科科，她就是紅龍女王。我們在和他們一同工作的時候，經常會變成更小的軀體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27992 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27992, 0, 0, 'zhTW', '長屋被摧毀了！警報聲響徹雲霄。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27992 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27992, 1, 0, 'zhTW', '直接命中碼頭！掠龍防禦者已經被驚動了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27992 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27992, 2, 0, 'zhTW', '維庫人的倉庫燃起了熊熊烈焰！掠龍防禦者已經被驚動了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 0, 1, 'zhTW', '這片廣袤的土地便是巨龍先祖的埋骨地。他們的靈魂已經昇華，在龍神之廳中享受著永恆的寧靜。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 0, 2, 'zhTW', '迦拉克隆是龍族的祖先。泰坦以它為雛形，甄選了五條巨龍來守護艾澤拉斯世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 0, 3, 'zhTW', '藍龍軍團竟然選擇瞭如此殘酷而冷血的道路，整個龍族都因此蒙羞。我卻不得不與瑪裡苟斯的子嗣交戰，做出這樣的決定真令我痛心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 0, 4, 'zhTW', '最近，女王陛下召集議會談論了奧杜爾遭遇的一場災難。風暴峭壁似乎出了什麼大事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 0, 5, 'zhTW', '朋友，今天真是個美好的日子。我一直待在龍眠神殿，已經很久沒有在龍骨荒野上空自由飛翔了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 0, 6, 'zhTW', '天災軍團的行徑將會世界造成不可挽回的惡劣影響。必須阻止他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 1, 0, 'zhTW', '我還沒有完全成熟，必須依賴進食來強化自身的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 27996 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (27996, 2, 0, 'zhTW', '朋友，我必須返回龍眠神殿了。再見！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 0, 0, 'zhTW', '你以為自己嬴了，是嗎？嚐嚐安提沃克的怒火吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 1, 0, 'zhTW', '迦拉克隆的骸骨很快就要從永恆的長眠中覺醒，為世界帶來一場殘酷的浩劫！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 2, 0, 'zhTW', '奴僕們！聽從我的號令吧！通靈主宰命令你們：肅清敵人，否則你們要為失敗付出慘痛的代價！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 2, 1, 'zhTW', '奴僕們！聽從我的號令吧！通靈主宰命令你們：肅清敵人，否則你們要為失敗付出慘痛的代價！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 2, 2, 'zhTW', '奴僕們！聽從我的號令吧！通靈主宰命令你們：肅清敵人，否則你們要為失敗付出慘痛的代價！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 2, 3, 'zhTW', '奴僕們！聽從我的號令吧！通靈主宰命令你們：肅清敵人，否則你們要為失敗付出慘痛的代價！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28006 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28006, 2, 4, 'zhTW', '奴僕們！聽從我的號令吧！通靈主宰命令你們：肅清敵人，否則你們要為失敗付出慘痛的代價！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28012 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28012, 0, 0, 'zhTW', '狡猾的法師領主伊洛姆守護著第三道環。表面上他顯得孤立無援，但那不過是欺騙敵人的假象！伊洛姆是位強大的咒術師，能召喚各種幽靈生物為他作戰。去上面找他吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28012 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28012, 1, 1, 'zhTW', '你即將面臨新一輪的挑戰。魔網守護者埃雷苟斯擁有可怕的力量。他就在魔樞頂層盤旋。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 0, 0, 'zhTW', '啊，終於回到了達克薩隆要塞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 1, 0, 'zhTW', '達庫魯凝視著達克薩隆要塞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 2, 0, 'zhTW', '朋友，幹得好……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 3, 0, 'zhTW', '你遠遠超出了我的期望。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 4, 0, 'zhTW', '對於你付出的努力，我一定要給你豐厚的報酬……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 5, 0, 'zhTW', '真相！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 6, 0, 'zhTW', '朋友，現在來安靜地領悟真相吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 7, 0, 'zhTW', '主人，我的任務完成了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 8, 0, 'zhTW', '在這些凡人的幫助下，所有膽敢反抗我們的傢伙都已經被清除了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 9, 0, 'zhTW', '遵命，我的主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 10, 0, 'zhTW', '朋友，請原諒，我欺騙了你。這樣是為了你好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 11, 0, 'zhTW', '那時，你要證明自己的價值……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 12, 0, 'zhTW', '而我，則急需優秀的下屬，能支配強大力量的下屬，在祖爾德拉克為我效勞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 13, 0, 'zhTW', '自己權衡一番吧。要知道，巫陛下對於所有忠誠的僕從都非常慷慨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28016 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28016, 14, 0, 'zhTW', '朋友，只要踏上這條路，很快你也能成為不朽的存在！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 0, 'zhTW', '休想逃走。嚐嚐我的怒火吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 1, 'zhTW', '永恆的詛咒就是你的下場！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 2, 'zhTW', '你的命運由我主宰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 3, 'zhTW', '盡情告饒吧。我是不會心軟的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 4, 'zhTW', '在怒火中煎熬吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 5, 'zhTW', '死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 6, 'zhTW', '你殺了我，現在輪到我殺你了……反反覆覆地殺！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28030 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28030, 0, 7, 'zhTW', '就憑這點能耐，也想打敗我？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28033 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28033, 0, 0, 'zhTW', '我們總算找到零件，可以修理諾姆瑞根之魂了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28033 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28033, 1, 0, 'zhTW', '讓我瞧瞧，擰一擰，再調整一下……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28033 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28033, 2, 0, 'zhTW', '你看，諾姆瑞根之魂！修好啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28033 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28033, 3, 0, 'zhTW', '你可以開著她去兜風，不過萬一你在座椅上發現了刀片，可別來跟我抱怨。你要知道，我好不容易才湊齊了零件修理她，就別那麼講究啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 0, 'zhTW', '千萬小心，$c。那些巨魔連他們崇拜的蛇神都敢殺！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 1, 'zhTW', '保持警惕。達卡萊巨魔生性卑鄙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 2, 'zhTW', '達卡萊巨魔真是麻煩。我們必須繼續前進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 3, 'zhTW', '再見。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 4, 'zhTW', '我想知道我們這是去哪兒，以及誰會來對付這些傢伙？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 5, 'zhTW', '好吧。我還是返回中士身邊吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28041 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28041, 0, 6, 'zhTW', '$n？我聽說你已經死了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28047 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28047, 0, 0, 'zhTW', '我對葛瑞姆釀造的酒總是充滿興趣的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28047 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28047, 1, 0, 'zhTW', '呃，我的妻子應該會喜歡這種果味酒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28047 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28047, 2, 0, 'zhTW', '哇，仔細品味後才發現口感一流啊！葛瑞姆總是能為我帶來驚喜！我喜歡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28054 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28054, 0, 0, 'zhTW', '我的鬍子！兩邊不對稱了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28054 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28054, 0, 1, 'zhTW', '痛！我不幹了，我不要當靶子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28054 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28054, 0, 2, 'zhTW', '耳朵！你弄傷了我的耳朵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28054 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28054, 1, 0, 'zhTW', '好準！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 0, 0, 'zhTW', '嗯，再來點魔精。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 1, 0, 'zhTW', '不！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 0, 'zhTW', '他們竟敢發動攻擊？這幫蠢貨！他們難道不清楚我們有多強大嗎？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 1, 'zhTW', '狂野諸神的力量在我們的血脈中燃燒，即便是巫妖王，也無法阻擋我們前進的道路！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 2, 'zhTW', '我看見你了，螻蟻！過來吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 3, 'zhTW', '殺死入侵者！看看誰敢來褻瀆我們神聖的祭壇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 4, 'zhTW', '我要消滅銀白十字軍！我要消滅天災軍團！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 5, 'zhTW', '殺死他們，然後我們去南邊對付他們的同胞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 6, 'zhTW', '西萊圖斯的魔精屬於我們啦。世間萬物都將臣服於達卡萊的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28068 AND `GroupID` = 2 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28068, 2, 7, 'zhTW', '兄弟，乾杯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 0, 0, 'zhTW', '幹得好，你們的晚飯算是有著落了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 0, 1, 'zhTW', '抓緊，這邊走這邊走！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 0, 2, 'zhTW', '讓我們看看入口附近的大門後面藏著什麼。我會悄悄地潛過去。去那裡和我碰面吧，我會帶你們進去吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 1, 0, 'zhTW', '我……我就要掛了……要堅持……不住了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 2, 0, 'zhTW', '我……還沒……還沒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 3, 0, 'zhTW', '我已經竭盡全力了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 3, 1, 'zhTW', '聖光會保佑你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 3, 2, 'zhTW', '希望這犧牲是值得的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 4, 0, 'zhTW', '是該收穫答案了！讓我們一路殺過去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 5, 0, 'zhTW', '嘿！別擔心！老布萊恩在後面給你們加油呢！把這些該死的金屬疙瘩給我擋住，讓我來好好跟這臺可愛的大機器談談，讓它幫幫你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 6, 0, 'zhTW', '嗯……它的確比之前碰見過的所有機器都詭秘複雜……啊，見鬼……敵人來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 7, 0, 'zhTW', '瑪多蘭在上，這玩意到底幹了些什麼？哦！等等，我馬上就搞定它了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 8, 0, 'zhTW', '哈，終於搞定了！援軍來了！接招吧，你們這群白痴鐵疙瘩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 9, 0, 'zhTW', '休息一會，然後和我一起來啟動這個東西。一切……馬上就要真相大白了。好了，我們開始吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 10, 0, 'zhTW', '嗯，你們幫我看著點外面。我這樣的強者只要錘兩下就能搞定這破爛……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 11, 0, 'zhTW', '噢，見鬼，好像有點不太妙，看來我們遇到點小麻煩啦……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 12, 0, 'zhTW', '嘿，破機器，怎麼樣？你想跟我來硬的？太可惜了，這是屬於我的遊戲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 13, 0, 'zhTW', '再給我幾分鐘，馬上就能……啊噢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 14, 0, 'zhTW', '提高？這算是好訊息嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 15, 0, 'zhTW', '哈！終於找到問題出在哪兒了！我馬上就能搞定了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 16, 0, 'zhTW', '等等！你想清理誰啊！有我在，沒門！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 17, 0, 'zhTW', '哈！看來還是我這把老骨頭厲害呀！然後再看看這裡……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 18, 0, 'zhTW', '消除？不不不不……呀，我剛才搞到哪來著？啊哈！應該是這樣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 19, 0, 'zhTW', '問詢？要不你以為我來這幹嘛？喝下午茶嗎？少廢話！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 20, 0, 'zhTW', '告訴我矮人是怎樣演化出來的！從最初開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 21, 0, 'zhTW', '對，對。我已經知道土靈是用石頭創造出來，用以改造地下世界的。但變異是怎麼發生的？我聽說過什麼母體擾動？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 22, 0, 'zhTW', '寄生性噬主……什麼來著？講通用語會死嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 23, 0, 'zhTW', '上古之神是吧，也就是說他們給土靈施加了什麼血肉的詛咒，然後怎麼樣了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 24, 0, 'zhTW', '如果他們真的殺光上古之神，那艾澤拉斯也就毀滅了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 25, 0, 'zhTW', '什麼守護者？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 26, 0, 'zhTW', '艾塞爾與瓦尼爾……好吧，這麼說意志熔爐又從頭開始創造了新的土靈……那老的怎麼樣了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 27, 0, 'zhTW', '等等！等等！你是說艾塞爾與瓦尼爾之間爆發了戰爭？為什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 28, 0, 'zhTW', '這個“洛肯”聽起來真是陰險狡詐。還好不用再理會他了。那麼……如果我的理解沒有錯，最初的原始土靈是否因為某種原因從休眠倉裡甦醒了過來，還受了這個什麼母體擾動的影響，最終演化成現代的矮人？至少……是現代矮人的祖先。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 29, 0, 'zhTW', '啊，現在我得花上很長時間來好好消化這些知識。我要在這裡再待一會兒。謝謝你們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 30, 0, 'zhTW', '洛肯？！這下我們碰到大麻煩了……雖然鐵矮人已經被全部擺平了，但我敢打賭不知道什麼鬼地方還有臺機器，正不停向外吐著鐵維庫人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 31, 0, 'zhTW', '我會用熔爐來製造一些土靈，讓他們保衛這裡……但現在最大的挑戰是：找到並阻止洛肯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28070 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28070, 32, 0, 'zhTW', '讓我們看看入口附近的大門後面藏著什麼。我會悄悄地潛過去。去那裡和我碰面吧，我會帶你們進去吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28076 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28076, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28077 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28077, 0, 0, 'zhTW', '你竟然和大舌頭怪攪和在一起！你不再是狂心氏族的朋友了。狂心狼獾人要讓你嚐嚐厲害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28078 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28078, 0, 0, 'zhTW', '%s進入狂暴狀態！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28090 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28090, 0, 0, 'zhTW', '我們會淨化這片土地！阿爾薩斯，等著瞧吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28090 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28090, 0, 1, 'zhTW', '你說得對！我們能做到！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28090 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28090, 0, 2, 'zhTW', '你說得對！我在想什麼呢！天災軍團，放馬過來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28092 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28092, 0, 0, 'zhTW', '放置歐米伽符文。成功啟用。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28095 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28095, 0, 0, 'zhTW', '啊！你竟然搶走屬於我的獵物！基克吉克要幹掉你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28095 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28095, 1, 0, 'zhTW', '笨蛋！停止射擊！格利基克想要完整的戰利品！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28095 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28095, 2, 0, 'zhTW', '別讓它逃走！這次一定要抓住它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28095 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28095, 2, 1, 'zhTW', '當心！別像上次那樣被它抓傷了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28095 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28095, 2, 2, 'zhTW', '啊啊！它直衝著我們來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28103 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28103, 0, 0, 'zhTW', '烏格雷斯開始施放強大的黑暗力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28105 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28105, 0, 0, 'zhTW', '我的寶藏！可恥的叛徒，不許偷塔爾特克的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28105 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28105, 1, 0, 'zhTW', '塔爾特克要和兇暴的龍一起殺了你！蠢貨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 0, 0, 'zhTW', '請收下……我亮閃閃的財寶。結束了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 0, 1, 'zhTW', '我們……什麼都沒做啊……我搞不明白。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 0, 2, 'zhTW', '把我的寶藏拿去吧……這樣天氣就會好轉……亡靈也會離開。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 0, 3, 'zhTW', '我們把閃閃發光的寶貝都供奉給了神殿……我們一點也不貪心啊……為什麼會這樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 0, 4, 'zhTW', '我做錯事了？對不起……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 1, 0, 'zhTW', '我們得救啦。你真好，幹皮人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 1, 1, 'zhTW', '或許你也能讓天氣好轉？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 1, 2, 'zhTW', '你救了我們！謝謝你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 1, 3, 'zhTW', '謝謝你！你是個好人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28113 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28113, 3, 0, 'zhTW', '苔行村受害者發出痛苦的呻吟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 0, 0, 'zhTW', '噢！閃閃發亮的寶貝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 0, 1, 'zhTW', '沒準還有更多閃閃發亮的蟲蟲！我們愛蟲蟲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 0, 2, 'zhTW', '拉弗烏的寶藏！祭壇的寶藏！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 0, 3, 'zhTW', '我挖，我挖，我挖……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 0, 4, 'zhTW', '這些蟲蟲又脆又美味。要不要來點？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 0, 5, 'zhTW', '太古怪了。有人把蟲蟲都搶走了。不會是你乾的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 1, 0, 'zhTW', '它再也不能來搗亂啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 2, 0, 'zhTW', '沒準你能成為索幹皮。你喜歡嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 2, 1, 'zhTW', '有餡餅嗎？以前有人給過我一塊餡餅。好吃極了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 2, 2, 'zhTW', '大樹。溫暖的家。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 2, 3, 'zhTW', '我沒有見過造物主。真的，只見過他們留下的祭壇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 2, 4, 'zhTW', '你的眼珠看起來好有趣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 3, 0, 'zhTW', '家裡真好，可惜呆不長！我們要更多的冒險！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28120 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28120, 4, 0, 'zhTW', '嘶嘶……嘶嘶……死了。都死了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 0, 0, 'zhTW', '亮閃閃！亮閃閃！雖然不如我的水晶閃亮，但依然很閃亮！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 0, 1, 'zhTW', '更多的寶藏！各種各樣的寶藏！寶藏！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 0, 2, 'zhTW', '亮閃閃的水晶怎麼都不嫌多啊！不嫌多！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 0, 3, 'zhTW', '我們挖地的速度可快啦！真的哦！你瞧……完成啦！是不是很快呀？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 1, 0, 'zhTW', '你喜歡嗎？我打賭你不會喜歡的！因為你已經死啦！哈哈哈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 1, 1, 'zhTW', '勝……利……啦！啾啾啾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 1, 2, 'zhTW', '殺戮盛宴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 2, 0, 'zhTW', '喚霧者擅長利用祭壇來控制氣候。他們知道各種水晶的用途！對，他們知道得一清二楚！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 2, 1, 'zhTW', '你被自己絆倒過嗎？我們有過這樣的經歷誒。有點痛。不好玩，我們不要再絆倒了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 2, 2, 'zhTW', '要幫忙嗎？要幫忙嗎？我們是很樂於助人的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 2, 3, 'zhTW', '你好！你看上去又強壯又和善。我喜歡你。我們做朋友好不好啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 2, 4, 'zhTW', '霧氣。好重的霧氣啊。對你來說，這或許算不上濃霧吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 2 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 2, 5, 'zhTW', '來來，一起從樹上跳下去吧！超級好玩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 3, 0, 'zhTW', '追趕幼體！追趕幼體！快跑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 3, 1, 'zhTW', '造物主能夠保證家的安全，因為他們喜歡先知！他們知道鱷魚人都是好人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 3, 2, 'zhTW', '家！家！家……閃閃發亮的地方！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 4, 0, 'zhTW', '我們知道你們有龍！但我們不怕！我們要將你們統統打扁！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 4, 1, 'zhTW', '讓你偷我們的財寶！財寶屬於……我們，明白嗎？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 4 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 4, 2, 'zhTW', '逃命去吧，狗狗人！我們來抓你們啦……最好滾回自己的山上去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28121 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28121, 5, 0, 'zhTW', '塔爾特克比不上你！你真夠厲害的。呀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 0, 0, 'zhTW', '這裡怎麼會有亮閃閃的兔子啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 0, 1, 'zhTW', '你瞧，我剛剛認識那傢伙，他就派我來這裡挖掘沒用的小玩意兒……你覺得這件事正常嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 0, 2, 'zhTW', '嗨……或許我們會找到更多沒用的蟲蟲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 0, 3, 'zhTW', '唉……又是泥土。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 1, 0, 'zhTW', '我不敢相信……他們全都……死了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 1, 1, 'zhTW', '又倒下一個。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 2, 0, 'zhTW', '為什麼我們還留在這裡？給我個說得過去的理由啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 2, 1, 'zhTW', '呀，我們出發吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 2, 2, 'zhTW', '事情辦好啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 3, 0, 'zhTW', '要去睡個午覺嗎？對於在您睡覺時不小心踩到您的臉，我謹此致歉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 3, 1, 'zhTW', '打算再坐一會兒，還是現在就去做一些實際有用的事情？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 3, 2, 'zhTW', '我是最聰明、最強壯、最有修養的鱷魚人，但是索烏塞卻擁有氏族的統治權……你覺得這件事正常嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 4, 0, 'zhTW', '苔行村鱷魚人是好人，他們不應該有此遭遇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 4, 1, 'zhTW', '我希望我可以和他們交談，可我不想他們死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 4 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 4, 2, 'zhTW', '看到這些鱷魚人比我想象中要堅強我就很開心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 4 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 4, 3, 'zhTW', '可能還有更多倖存者，我們要繼續！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 4 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 4, 4, 'zhTW', '難以置信，他們還有倖存者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 4 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 4, 5, 'zhTW', '他們將屍體拖到哪裡？他們要做什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 5, 0, 'zhTW', '這次就靠你自己了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28122 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28122, 6, 0, 'zhTW', '唯一值得欣慰的是，他們沒有變成亡靈。');
