INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28142, 0, 0, 'zhTW', '<嘆氣>……呃，我還以為事情會更糟糕呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28142 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28142, 1, 0, 'zhTW', '<嘆氣>……這次大劫難逃了。');
