INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28160, 0, 0, 'zhTW', '我會讓你搭乘我的飛行器的。睜大你的眼睛，給我調查清楚赫米特的情況！');
