INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28167, 0, 0, 'zhTW', '讚美聖光！是阿爾薩斯王子！殿下，我們都被感染了，現在該怎麼辦？');
