INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28175, 3, 0, 'zhTW', '見鬼！連一絲裂痕都沒留下！這是我見過的最硬的礦石！');
