INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28179, 0, 0, 'zhTW', '巫妖王對此次反擊迅速做出了反應，竟然比我預想中的還要快。');
