INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28179, 2, 0, 'zhTW', '說話小心點，死亡騎士。你身邊的人都是聖光虔誠的信徒。');
