INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28189, 1, 0, 'zhTW', '您賜予我的力量使我能夠更好地控制人類的思維。這些祭品就是證據。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28189 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28189, 2, 0, 'zhTW', '讓我來對付這些入侵者吧。我會將他們的內臟拿去喂蛆。');
