INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 17, 0, 'zhTW', '原始魔精！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 18, 0, 'zhTW', '迅猛龍爪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 19, 0, 'zhTW', '琥珀種子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 20, 0, 'zhTW', '皺巴巴的龍爪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 21, 0, 'zhTW', '冰冷的毒蛇粘液！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 22, 0, 'zhTW', '結晶的野豬鼻涕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 23, 0, 'zhTW', '碎裂的石化蜥蜴水晶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 24, 0, 'zhTW', '巨魔殺除劑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28205 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28205, 25, 0, 'zhTW', '結冰的蜘蛛毒液！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28213 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28213, 0, 0, 'zhTW', '%s憤怒地尖嘯著，衝過來幫助她的孩子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 0, 'zhTW', '到家啦！奴隸，你最好為格利基克帶回了足夠的肉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 1, 'zhTW', '格利基克要去睡一會兒。奴隸，你去給我搞點吃的回來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 2, 'zhTW', '格利基克去搞點酒喝。你乖乖地待在角落裡等我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 3, 'zhTW', '格利基克餓死了。奴隸，快趴到火堆上去。等你烤熟之後告訴格利基克一聲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 4, 'zhTW', '格利基克要去抓雞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 5, 'zhTW', '你最好耐心地等著格利基克。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 0, 6, 'zhTW', '你一邊待著去，奴隸。格利基克正在吃飯呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 0, 'zhTW', '格利基克是最好的獵人……永遠是。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 1, 'zhTW', '哈！是格利基克殺的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 2, 'zhTW', '下次格利基克讓你試試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 3, 'zhTW', '一擊必中！格利基克真厲害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 4, 'zhTW', '它們可真靈活！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 5, 'zhTW', '狂心狼獾人最厲害！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 1 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 1, 6, 'zhTW', '奴隸，看清楚了吧。或許有一天你也能領悟這一招。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 2, 0, 'zhTW', '格利基克為什麼要帶上你啊。你這廢物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 2, 1, 'zhTW', '我可不管長者怎麼說，反正你永遠都是格利基克的奴隸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 2, 2, 'zhTW', '匹奇根本構不成威脅嘛……要不然格利基克肯定不會放過他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 2, 3, 'zhTW', '吃到苦頭了吧！哈哈！你這蠢奴隸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 0, 'zhTW', '當心點，壞心腸的軟皮猩猩能一口吃掉你！哈哈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 1, 'zhTW', '獵殺硬皮猩猩對格利基克來說容易極了……它們很愚蠢的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 2, 'zhTW', '軟皮猩猩是我們重要的生活來源。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 3, 'zhTW', '快跑呀，軟皮猩猩！格利基克來抓你們啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 4, 'zhTW', '奴隸，你待在一旁看著就是了。讓格利基克來對付這些硬皮猩猩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 5, 'zhTW', '別擋格利基克的道！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 6, 'zhTW', '愚蠢的奴隸，別擋道！這是格利基克的獵物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 3 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 3, 7, 'zhTW', '格利基克的主要工作之一就是獵捕硬皮猩猩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 4, 0, 'zhTW', '哈哈！格利基克是最最厲害的獵手！格利基克殺死了個頭最大的硬皮猩猩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28214 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28214, 5, 0, 'zhTW', '狂心狼獾人用大舌頭怪餵養卡塔克，保證自己不會淪為他的食物。奴隸，這就是我們比你聰明的證據。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 0, 'zhTW', '不久前，狂心氏族在這裡安了新家……大舌頭怪的屋子看上去很漂亮啊，我們其實可以搶來自己住。它們那麼醜，才不配住這麼好看的地方。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 1, 'zhTW', '這裡有許多優秀的獵手，大部分都是達伊克調教出來的。不過教你這樣的傢伙還是頭一次。要知道，你並不是狂心氏族的成員。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 2, 'zhTW', '我們改吃鋼刺野豬怎麼樣？我不要再跑來跑去的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 3, 'zhTW', '狂心狼獾人不去追雞是有原因的。因為如果追不上的話，就太丟臉了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 4, 'zhTW', '你可能沒注意到，雞……跑得有點快。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 5, 'zhTW', '再來聽聽達伊克的小建議！如果格利基克又把雞給放跑了，就讓他把雞們都捉回去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 6, 'zhTW', '我在柵欄上安了許多尖刺。它們看上去挺鋒利的。你覺得呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 0, 7, 'zhTW', '噢！達伊克想到個辦法！我們來學雞叫，它們或許會循聲而來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 1, 0, 'zhTW', '把屍體清理乾淨！達伊克最討厭剝皮的時候被什麼東西給擋著了。很煩人的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 1, 1, 'zhTW', '你瞧見它的臉了嗎？一副惶恐的表情，“啊，我要被那個大傢伙砸扁啦！”哈哈哈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 1, 2, 'zhTW', '哈！或許你能學到點什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 1, 3, 'zhTW', '對！多捅幾下，以防萬一！捅得好！捅得好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 1, 4, 'zhTW', '真不明白它怎麼能捕殺那些多生物。不過反正它已經死了，威脅解除啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 2, 0, 'zhTW', '我們來這裡是有目的的，對吧？我想不起來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 2, 1, 'zhTW', '看看你有沒有忘記什麼東西啊。我以前就老忘事兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 2, 2, 'zhTW', '達伊克從來沒有見你吃過東西。你也要吃東西的，對吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 2, 3, 'zhTW', '我本來想寫一份詳細的攻擊計劃的……但是你拿走了我的筆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 2, 4, 'zhTW', '再來聽聽達伊克的小建議！在你搜刮戰利品之前，要確保敵人已經死翹翹了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 3, 0, 'zhTW', '每次來蟲巢，達伊克都覺得這裡的巨蜂又變多了。它們的數量怎麼就不見少呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 3, 1, 'zhTW', '再來聽聽達伊克的小建議！儘量別用臉去擋刺。沒什麼用的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 3, 2, 'zhTW', '我告訴你，被蜇的滋味可不好受。你最好別去嘗試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 3, 3, 'zhTW', '雄蜂只是外表兇悍而已，其實很容易對付的。巨蜂就比較麻煩一點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 3, 4, 'zhTW', '再來聽聽達伊克的小建議！儘量別用臉去擋刺。沒什麼用的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 4, 0, 'zhTW', '什麼！你殺死了蜂后！怎麼可能……呃，沒什麼。好吧，沒什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 5, 0, 'zhTW', '達伊克的上一個學徒就是被躲在沙裡的怪物給吃掉的。我們最好別落得同樣的下場！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 6, 0, 'zhTW', '蜂后是殺不絕的。很快就會產生新的蜂后。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 7, 0, 'zhTW', '有時候大舌頭怪會來這裡採集水晶。當然，它們現在敢來的話，就是找死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 7 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 7, 1, 'zhTW', '再來聽聽達伊克的小建議！水晶不適合用來撓背。你最好別去嘗試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 7 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 7, 2, 'zhTW', '某個強大的存在製造了柱子、水晶以及別的東西。不過它已經不在這裡了，所以我們不用害怕。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 8, 0, 'zhTW', '如果你是來戳軟皮猩猩的話，達伊克就要戳你了。別學格利基克的壞習慣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 8 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 8, 1, 'zhTW', '哈……我們在哪兒？不對呀。我們不是來找硬皮猩猩的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 9, 0, 'zhTW', '再來聽聽達伊克的小建議！好多亡靈啊，這意味著我們有很大的機率被變成亡靈。達伊克要逃命去了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 9 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 9, 1, 'zhTW', '你看那堆死屍，這就是靠近破柱子的下場。它們已經得到教訓了。我們回家吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28215 AND `GroupID` = 9 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28215, 9, 2, 'zhTW', '好吧！你什麼都學會啦！沒錯！達伊克不管你了，你去研究那根邪惡的紅柱子吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 0, 0, 'zhTW', '只要你能帶回上等的肉，我們就把你當作高階薩滿祭司那樣伺候一天。很不錯的交易吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 0, 1, 'zhTW', '長者哈爾卡克是個大好人。在我年幼的時候，他幫過我很多忙，一點也不像達伊克。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 0, 2, 'zhTW', '我又不急著辦什麼事。我們甚至可以在這裡休息一陣子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 0, 3, 'zhTW', '我很少呆在營地……不久前，我還獨自遊歷了不少地方呢。嗯，我喜歡那些關於野獸、巨龍和神靈的傳說。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 0, 4, 'zhTW', '你應該把雞們都放出來，然後說是格利基克乾的。這招屢試不爽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 1, 0, 'zhTW', '哈哈哈！你看見沒有？閃電直接擊中了他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 1, 1, 'zhTW', '幹得好！它一點也沒有察覺。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 1, 2, 'zhTW', '不玩了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 0, 'zhTW', '你有沒有跟巨龍、神靈或者別的什麼打過架啊？瑟匹克最喜歡聽故事啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 1, 'zhTW', '技術不錯嘛！狩獵手法和我一樣純熟自然。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 2, 'zhTW', '格利基克總是擺出一副高高在上的模樣，但這傢伙每天吃那麼多，打回來的獵物卻少得可憐。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 3, 'zhTW', '只要你能帶回上等的肉，我們就把你當作高階薩滿祭司那樣伺候一天。很不錯的交易吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 4, 'zhTW', '達伊克經常會忘記他在做什麼，忘記他在哪兒……甚至會忘記自己的名字。有時候，他還真算不上是個好老師。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 5, 'zhTW', '長者哈爾卡克是個大好人。在我年幼的時候，他幫過我很多忙，一點也不像達伊克。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 6, 'zhTW', '格利基克才不會錯過抓雞活動呢……格利基克得填飽他的肚子。每次抓完雞，我們都會發現有一隻雞不見了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 2 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 2, 7, 'zhTW', '達伊克一直想教我狩獵的技巧，事實上，我按自己的方式來做，效果反而更好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 0, 'zhTW', '嚐嚐厲害吧，大舌頭怪！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 1, 'zhTW', '哈哈！給瑟匹克留點獵物吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 2, 'zhTW', '附近的湖裡全是海洋生物。不知道是怎麼來的……莫非是洪水？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 3, 'zhTW', '我喜歡狩獵大舌頭怪的原因之一……就是它們不像其他獵物那樣愚蠢。懂得耍花招的獵物才是真正的挑戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 4, 'zhTW', '霧語大舌頭怪很會利用那些祭壇搗鬼……它們能讓迷霧覆蓋整片區域，令我們難以發現它們的行蹤。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 5, 'zhTW', '哈！真有趣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 3 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 3, 6, 'zhTW', '烈焰！死亡！毀滅！黑色的火焰在我心中燃燒！我必須……釋放它！哈哈哈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 4, 0, 'zhTW', '相信我——你會喜歡的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28216 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28216, 5, 0, 'zhTW', '砰！真棒！再來！再來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28217 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28217, 0, 0, 'zhTW', '受傷的雨聲神諭者笨拙地站了起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28217 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28217, 1, 0, 'zhTW', '等你做好準備，我們就啟程回家吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28217 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28217, 2, 0, 'zhTW', '就快到家啦。走吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28217 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28217, 3, 0, 'zhTW', '謝謝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28217 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28217, 4, 0, 'zhTW', '不妙！我們被狗狗人跟蹤了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28229 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28229, 0, 0, 'zhTW', '又有入侵者？我倒要看看誰敢和風險投資公司過不去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 0, 0, 'zhTW', '我們得搞清楚，為什麼天災軍團如此看重這種礦石。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 1, 0, 'zhTW', '科爾法克斯，你知道薩隆邪鐵嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 2, 0, 'zhTW', '萊茵，雷布拉特，試試自然與元素的力量？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 3, 0, 'zhTW', '梅茲？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 4, 0, 'zhTW', '你會什麼力量啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 5, 0, 'zhTW', '%s撣去身上的灰塵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 6, 0, 'zhTW', '好吧，事情毫無進展。我們還是將這塊薩隆邪鐵交給大領主弗丁研究吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28244 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28244, 7, 0, 'zhTW', '朋友們，謝謝你們的嘗試。我們一定會揭開其中秘密，只希望一切不會太遲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28256 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28256, 0, 0, 'zhTW', '這麼說，神諭者決定幫助你了。好吧，我會把我所知的一切都告訴你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28256 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28256, 1, 0, 'zhTW', '碎角犀牛的族長法魯恩就是你的同伴尋找的目標。他很少和族群的其他成員待在一起。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28256 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28256, 2, 0, 'zhTW', '法魯恩喜歡獨自在苦潮瀑布以北的林地遊蕩。你可以在那裡找到他；不過你很快就會明白，他並不需要族群其他成員的保護。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28256 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28256, 3, 0, 'zhTW', '告訴你的同伴，讓他去那裡獵殺法魯恩，然後領取獎賞吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28256 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28256, 4, 0, 'zhTW', '事情辦完之後，就讓他趁早離開。他並不屬於這裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28284 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28284, 0, 0, 'zhTW', '哎呀，好粘啊！它們是怎麼結網的啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28284 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28284, 1, 0, 'zhTW', '啊！見鬼，我把自己給網住了！粘死啦。哎呀，我的髮型！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28284 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28284, 2, 0, 'zhTW', '好吧！讓我看看能不能將這堆破銅爛鐵改造成有用的裝置。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28284 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28284, 3, 0, 'zhTW', '我知道了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28313 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28313, 0, 0, 'zhTW', '遠行者，那些炮火……呃，我是說那些人……他們是對抗維庫人的重要資源。啊，我說的是“資源”？好吧，我的意思是“盟友”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28315 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28315, 0, 0, 'zhTW', '你要是敢回來，狂心狼獾人就要你的命。從現在開始，你是我們的敵人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28325 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28325, 0, 0, 'zhTW', '你聽到附近傳來一聲低沉的咆哮。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28327 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28327, 0, 0, 'zhTW', '薩滿祭司維克伊克從旁邊的灌木叢中走了出來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28327 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28327, 1, 0, 'zhTW', '你竟然幫助雨聲鱷魚人！我都看見了！你這個叛徒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28327 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28327, 2, 0, 'zhTW', '如果你要和大舌頭怪交朋友，那你就不是狂心狼獾人的朋友啦！我要告訴全村人！我們再也不會相信你了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28327 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28327, 3, 0, 'zhTW', '薩滿祭司維克伊克朝狂心嶺的方向奔去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28328 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28328, 0, 0, 'zhTW', '只是有點傷自尊嘛，夥計。振作一點啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28328 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28328, 0, 1, 'zhTW', '別抱怨了。你的運氣還不錯啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28328 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28328, 0, 2, 'zhTW', '呸，還是有進步的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28328 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28328, 0, 3, 'zhTW', '冷靜點，夥計。這只是小號鉛彈啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28328 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28328, 1, 0, 'zhTW', '記住，$n，這不是短期的考驗。對獵人而言，真正的考驗是在長途跋涉中鍛鍊自己的耐性。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 0, 0, 'zhTW', '烏雷特，你調配出新的混合藥劑了嗎？店裡堆滿了該死的孢子，我快被煩死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 1, 0, 'zhTW', '下次放雙倍的劑量好了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 2, 0, 'zhTW', '記住：你犯下的錯誤永遠比你想象的要嚴重得多。給我加雙倍的劑量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 3, 0, 'zhTW', '下次就放一半的劑量吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 4, 0, 'zhTW', '你每次都這麼說。有時候，我甚至懷疑你永遠也配製不出那玩意兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 5, 0, 'zhTW', '你好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 5, 1, 'zhTW', '你好啊，$c。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 5 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 5, 2, 'zhTW', '歡迎！請隨便看看。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 5 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 5, 3, 'zhTW', '你需要什麼，可以直接告訴我，$c。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28347 AND `GroupID` = 5 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28347, 5, 4, 'zhTW', '你好。我能幫上什麼忙嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28355 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28355, 0, 0, 'zhTW', '先生，有客戶投訴說我們出售的致命藥膏中，魔女之毒的含量不足。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28355 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28355, 1, 0, 'zhTW', '先生，我認為上一張配方中死亡根鬚的用量已經很接近合適劑量了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28355 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28355, 2, 0, 'zhTW', '我還在調製啊，我可不想隨便出售連我自己都不滿意的半成品。用不了多久啦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28355 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28355, 3, 0, 'zhTW', '先生，有客戶投訴說我們出售的麻醉藥膏中，喪命草的含量過高。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28374 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28374, 0, 0, 'zhTW', '我憑什麼要替你照顧龍崽啊，多里安。我還要搞研究工作呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28374 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28374, 1, 0, 'zhTW', '不要，我討厭齒輪！別讓我碰那玩意兒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28376 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28376, 0, 0, 'zhTW', '呃，才沒有。我是來照料篝火堆的，順便找蘇特菲茲談談機械零件的缺陷問題。我承認，這件戰利品看上去是挺不錯的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28376 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28376, 1, 0, 'zhTW', '蘇特菲茲，今天是你的幸運日。$n為你帶回了更多的龍崽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28376 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28376, 2, 0, 'zhTW', '好吧，你隨時可以返回營地，幫助維斯雷擺弄那堆齒輪……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28401 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28401, 0, 0, 'zhTW', '$n，到我這裡來。我就在希姆託加。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28401 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28401, 1, 0, 'zhTW', '不，也不是哈克婭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 0, 'zhTW', '不準喝藥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 1, 'zhTW', '$n，你給我記好了，今天將是你徹底潰敗的日子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 2, 'zhTW', '看我怎麼把你揍趴下，菜鳥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 3, 'zhTW', '你以為和我打架很好玩？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 4, 'zhTW', '嘖嘖，哭鼻子啦……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 5, 'zhTW', '你這是在挑戰死神！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 6, 'zhTW', '看看誰才是巫妖王麾下真正的勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 7, 'zhTW', '你快完蛋了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 0 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 0, 8, 'zhTW', '你贏不了的，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28406 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28406, 1, 0, 'zhTW', '決鬥即將開始……');
