INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28415, 0, 1, 'zhTW', '朋友，我欠你一份情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28415 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28415, 0, 2, 'zhTW', '我還以為自己死定了呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28444 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28444, 0, 0, 'zhTW', '%s召喚出天災軍團的大軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28444 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28444, 1, 0, 'zhTW', '天災軍團，聽我的號令！血色十字軍的末日已經降臨！攻佔這片土地吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 0, 0, 'zhTW', '多里安，你錯過了一場驚心動魄的戰鬥！真是難忘的經歷啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 1, 0, 'zhTW', '我們騎在斯塔比背上，全速開戰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 2, 0, 'zhTW', '我感覺周圍的景象在顫抖，差點抓不住手中的槍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 3, 0, 'zhTW', '接著，那隻恐怖的野獸進入了我們的視線！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 4, 0, 'zhTW', '$n全神貫注地控制斯塔比戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 5, 0, 'zhTW', '這場戰鬥真是腥風血雨啊。母龍的攻擊速度越來越快了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 6, 0, 'zhTW', '但是，我，還有$n憑藉卓越的智慧和完美的合作，最終取得了勝利。喏，這就是我們的戰利品。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28451 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28451, 7, 0, 'zhTW', '多里安，怎麼你看上去有點嫉妒啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28473 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28473, 0, 0, 'zhTW', '將你的肉體拋諸腦後吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28479 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28479, 0, 0, 'zhTW', '上古之神，我們乞求你的幫助。我們應該怎麼做，才能拯救這片土地的神靈？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28486 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28486, 0, 0, 'zhTW', '小……小姐，您的戰馬需要梳……梳洗嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28486 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28486, 0, 1, 'zhTW', '小……小姐，您的盔甲需要拋……拋光嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28486 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28486, 0, 2, 'zhTW', '小……小姐，您需……需要更多的屍塵嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28486 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28486, 1, 0, 'zhTW', '遵命，尊貴的小……小姐……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28494 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28494, 0, 0, 'zhTW', '殺死贊達拉巨魔和他們的傀儡！誰也別想阻止我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28495 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28495, 0, 0, 'zhTW', '殺光他們！殺光他們，奪回希姆託加！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28496 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28496, 0, 0, 'zhTW', '哈！別想奪走我的財寶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28498 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28498, 0, 0, 'zhTW', '你做得很好，達庫魯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28498 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28498, 1, 0, 'zhTW', '你對達卡萊帝國的背叛為我製造出了一支新的軍團。');
