INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 1, 4, 'zhTW', '啊……痛……差點就趕上我小時候在學校裡受過的鞭刑了。');
