INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 3, 0, 'zhTW', '我們……我們只知道“血色黎明”象徵著覺醒。你……你瞧，聖光給了阿比迪斯將軍新的啟示。是聖光……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 4, 0, 'zhTW', '是聖光在指引我們。天災軍團抵達之前，這次行動就已經開始了……我們……只是簡單地奉命行事。我們必須服從軍令。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 5, 0, 'zhTW', '其他的我就不清楚了……阿比迪斯將軍決定誰走誰留。我只知道這些……你要相信我啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 6, 0, 'zhTW', '撒謊！接下來你要承受的痛苦足夠你談論好幾年！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 7, 0, 'zhTW', '啊！住手！還有一件事我忘記說了……很快就會有信差……從壁爐谷趕來。嗯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 0, 'zhTW', '我遲早會掏出埋在你心裡的所有秘密！只要你肯開口，我就饒你一命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 1, 'zhTW', '關於“血色黎明”，你都知道些什麼？快說，不然就等著吃鞭子吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 2, 'zhTW', '我對你已經夠客氣的了！“血色黎明”到底是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 3, 'zhTW', '你的性命就這麼不值錢嗎？只要你告訴我關於“血色黎明”的資料，我就立即結束你的痛苦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 4, 'zhTW', '我有的是精力對付你！說吧，“血色黎明”是什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 5, 'zhTW', '“血色黎明”是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28610 AND `GroupID` = 8 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28610, 8, 6, 'zhTW', '“血色黎明”究竟是什麼！說！');
