INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28611, 0, 4, 'zhTW', '我要將你獻給阿比迪斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28611 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28611, 0, 5, 'zhTW', '接受聖光的洗滌吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28611 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28611, 0, 6, 'zhTW', '聖光保佑你，我的孩子。');
