INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28636, 2, 0, 'zhTW', '受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 0, 0, 'zhTW', '啟航！當心那些藤蔓植物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 1, 0, 'zhTW', '看來前面的區域已經被天災軍團清掃過了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 2, 0, 'zhTW', '看見了嗎？她……真大啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 3, 0, 'zhTW', '來吧！坐穩啦——前面有強氣流！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 4, 0, 'zhTW', '冰川正在逐漸擴展……到處都是亡靈！先等教授控制這裡的局勢吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 5, 0, 'zhTW', '他們發動攻擊了！當心那些火箭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28646 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28646, 6, 0, 'zhTW', '啊啊啊！被擊中了！你得幫幫忙！快，趁飛行器還沒有爆炸！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28654 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28654, 0, 0, 'zhTW', '黑暗在等待……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28658 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28658, 0, 0, 'zhTW', '在我把你變成糞便和垃圾之前，快點進去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28659 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28659, 0, 0, 'zhTW', '啊，英雄。我聽你的小夥伴說，你會來的。這樣挺好的，省去了我親自搜尋你的麻煩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28659 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28659, 1, 0, 'zhTW', '我經歷了一百年的戰爭與痛苦。你真的覺得，憑著血肉之軀與不死生物作對是明智的選擇嗎？我敢說，你很可能會失敗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28659 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28659, 2, 0, 'zhTW', '即便是碎裂成粉末，這些水晶依然在削弱我的力量……或許我不該低估泰坦的強大……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28659 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28659, 3, 0, 'zhTW', '這兩個有勇無謀的蠢貨彼此厭惡，卻異口同聲地稱你為英雄。你或許還不願意做出選擇……那麼，就讓我多給你一點時間吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28659 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28659, 4, 0, 'zhTW', '阿圖裡斯升起了護罩。你必須迅速打斷他的法術。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28659 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28659, 5, 0, 'zhTW', '阿爾薩斯也曾擁有……同樣的力量……或許你應該沿著他的足跡追尋力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28665 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28665, 0, 0, 'zhTW', '謝謝你救了我，$n。這是我唯一能為你做的。握緊了，我們出發吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28665 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28665, 1, 0, 'zhTW', '事情似乎不太順利。千萬別跌下去。那裡滿是骯髒的東西！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28665 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28665, 2, 0, 'zhTW', '天哪……奎絲魯恩死了！別動。我們偷偷繞過先知。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28665 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28665, 3, 0, 'zhTW', '我們被發現了！別慌張。我們得離開這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28665 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28665, 4, 0, 'zhTW', '我想我們現在安全了。回去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28665 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28665, 5, 0, 'zhTW', '成功啦！保重，$n。再次對你表示感謝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28667 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28667, 0, 0, 'zhTW', '我們躲在你身後，這次你休想抓到我們！現在要好好教訓你！哼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28668 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28668, 0, 0, 'zhTW', '壞東西，你很快就要死了！你再也不能打擾瑟匹克睡覺啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28671 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28671, 0, 0, 'zhTW', '你來做什麼，可悲的傢伙？送死嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28671 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28671, 1, 0, 'zhTW', '我很熟悉你身上的臭味。捕殺雪豹時，你一路潛行尾隨在我身後！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28671 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
