INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28684, 4, 0, 'zhTW', '小心守著隧道。我們不能讓任何人透過！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28684 AND `GroupID` = 4 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28684, 4, 1, 'zhTW', '我聽到了腳步聲。提高警惕。');
