INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28684, 5, 0, 'zhTW', '我們被攻擊了！立刻出擊，把敵人的屍體給我帶回來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28684 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28684, 5, 1, 'zhTW', '我們必須守住大門。進攻！將他們撕成碎片！');
