INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28787, 6, 0, 'zhTW', '我們趕緊離開這裡吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28788 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28788, 0, 0, 'zhTW', '很不錯啊，死亡騎士。返回生者的世界，領取你應得的獎勵吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28793 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28793, 0, 1, 'zhTW', '你的偽裝騙不了我！我要殺了你，達庫魯一定會很滿意的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28841 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28841, 0, 0, 'zhTW', '這東西是從哪兒來的？趁工頭還沒發現，我最好趕緊把它拖到船上去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28841 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28841, 1, 0, 'zhTW', '管它做什麼呢。放在這裡就是了，不會有人發現的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 0, 0, 'zhTW', '你要和我比誰射擊速度更快嗎？我已經射殺11個了哦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 0, 1, 'zhTW', '10個！你多少擊殺了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 0, 2, 'zhTW', '9！我閉著眼睛都能命中獵物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 0, 3, 'zhTW', '11！如果你打敗了德洛斯坦後果很嚴重的哦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 1, 0, 'zhTW', '我已經擊殺15了！超過你了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 1, 1, 'zhTW', '擊殺數：16！真是太簡單了呀！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 1, 2, 'zhTW', '你要加把勁趕上來才行啊，否則這算什麼比賽呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 1, 3, 'zhTW', '哈哈，16了哦！你多少了？10個，嗯……或許幸運點的話，11？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 2, 0, 'zhTW', '這是我的第25個擊殺了呀。你被我落下幾個了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 2, 1, 'zhTW', '26！你不會剛準備開始吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 2, 2, 'zhTW', '我媽媽的速度都比你快，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 2, 3, 'zhTW', '我已經殺了26個，這還只是熱身而已。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 3, 0, 'zhTW', '唔，我已經佔據領先優勢啦，可以小睡一會兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 4, 0, 'zhTW', '啊……睡得真舒服。狩獵比賽的情況如何啦？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 5, 0, 'zhTW', '哎呀，我領先很多了嘛。我去釣會兒魚好了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 6, 0, 'zhTW', '現在，讓我們用自己的能力來比賽吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 6, 1, 'zhTW', '41個咯 ！我的本事怎麼樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 6 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 6, 2, 'zhTW', '41！我已經完成三分之二了。加油加油！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 6 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 6, 3, 'zhTW', '嘿，我分明已經瞄準了那隻獵物。你偷了我的獵物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 7, 0, 'zhTW', '啊……才48個。好難啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 7 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 7, 1, 'zhTW', '沒什麼樂子找了。你還沒射殺48只嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 7 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 7, 2, 'zhTW', '48。我準備慢點等等你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 7 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 7, 3, 'zhTW', '有人將那些從我手中逃掉的獵物殺了。能有48個的成績已經很不錯了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 8, 0, 'zhTW', '哈，54！進入最後衝刺階段！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 8 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 8, 1, 'zhTW', '54個咯！我可不會輸給你的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 8 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 8, 2, 'zhTW', '54！遙遙領先！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28857 AND `GroupID` = 8 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28857, 8, 3, 'zhTW', '54個了，你一會別忘了恭喜我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 0, 0, 'zhTW', '低等生物，竟敢入侵這裡！可惜你們過度膨脹的勇氣，無法挽救愚蠢所導致的悲慘結局！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 0, 1, 'zhTW', '這裡除了藍龍軍團，沒有人可以進來。看來是雅立史卓莎在搞鬼？很好，她實際上是派你們來送死的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 0, 2, 'zhTW', '你們以為自己能做些什麼呢？自大地在我的領域橫衝直撞，用毀滅性的魔法來對付……我？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 0, 3, 'zhTW', '我在這裡不受任何約束。那些你們必須遵循的法則對我無效。在這個領域之中，我就是一切！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 0, 4, 'zhTW', '我給你們一次機會吧。向我宣誓效忠，這是讓我原諒你們的傲慢與無禮的唯一機會。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 1, 0, 'zhTW', '我的耐心到此為止了。我要親自消滅你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 2, 0, 'zhTW', '在我的龍息之下，一切都將蕩然無存！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 3, 0, 'zhTW', '你們的愚蠢必將葬送自己！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 3, 1, 'zhTW', '又有更多的神器可以沒收了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 3, 2, 'zhTW', '太天真了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 4, 0, 'zhTW', '我原本只是想盡快結束你們的生命……可你們竟然遠比我想象得要堅韌。雖然如此，你們的努力仍將付諸東流。事實上，這場戰爭本身就是因為你們凡人不計後果的行為而起，我只是在儘自己的責任罷了。如果這責任意味著要滅絕你們……那就這樣吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 5, 0, 'zhTW', '沒有人體驗過你們將要承受的痛苦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 6, 0, 'zhTW', '我要讓你們這些無知的孩子重新瞭解魔法的概念。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 7, 0, 'zhTW', '就這樣無助地看著希望破滅吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 8, 0, 'zhTW', '我會妥善利用你們留下的魔法能量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 8 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 8, 1, 'zhTW', '我是織法者！我的力量是無窮無盡的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 8 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 8, 2, 'zhTW', '你們的靈魂將永遠在這裡遊蕩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 9, 0, 'zhTW', '夠了！既然你們這麼想奪回艾澤拉斯的魔法，我就給你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 10, 0, 'zhTW', '現在你們幕後的主使終於出現了，但已經太遲了！這裡瀰漫著的能量已經足以將世界毀滅十次。你們覺得他們會對你們做些什麼呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 11, 0, 'zhTW', '投降吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 12, 0, 'zhTW', '%s深深地吸了一口氣……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 13, 0, 'zhTW', '在這裡湧動的力量早已超越了你們的理解與想象！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 14, 0, 'zhTW', '我無堅不摧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 15, 0, 'zhTW', '雅立史卓莎，又有一個你的孩子倒下了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 15 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 15, 1, 'zhTW', '就比小蟲子強了一點點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 15 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 15, 2, 'zhTW', '紅龍軍團也將步你們的後塵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 16, 0, 'zhTW', '竟然還沒倒下？不會太久了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 16 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 16, 1, 'zhTW', '你們的妄想破滅了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 16 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 16, 2, 'zhTW', '你們脆弱的精神即將崩潰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 17, 0, 'zhTW', '不可思議！這群凡人……竟然毀滅了一切！我的妹妹，你都做了些……什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28859 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 18, 0, 'zhTW', '%s在注視你！');
