INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28859, 19, 0, 'zhTW', '%s變得狂暴不已！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28860 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28860, 0, 0, 'zhTW', '我的職責是保護這些龍卵。在傷害到它們之前，你們就會被我的龍息燒成灰燼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28860 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28860, 1, 0, 'zhTW', '你們這可笑的騷擾到此為止了！');
