INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28942, 2, 2, 'zhTW', '如果你再不露面，我們就踏平這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28942 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28942, 2, 3, 'zhTW', '我的家人都被殺害了！在我們最需要軍隊幫助的時候，他們在哪兒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28942 AND `GroupID` = 2 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28942, 2, 4, 'zhTW', '納克薩瑪斯飛走了？我們才不關心呢！來自阿徹魯斯的死亡騎士正在大肆屠殺我們的同胞！');
