INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28948, 2, 0, 'zhTW', '主人從達克薩隆來到這裡時，就預言了你到此造訪的時間。');
