INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28948, 3, 0, 'zhTW', '你應該感到榮幸。主人要我們向你展示沃爾塔魯斯的工事，這還是頭一遭。');
