INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28948, 4, 0, 'zhTW', '我向你展示的東西絕對不能在沃爾塔魯斯以外提起。我們的秘密很快就能揭曉了！');
