INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28948, 8, 0, 'zhTW', '我們覺得最好將他們安置在這裡，讓他們乖乖地接受註定的命運。');
