DELETE FROM `creature_text_locale` WHERE `CreatureID` = 28998 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (28998, 7, 0, 'zhTW', '主人，就是這個無恥的凡人出賣了我們。我們一定要好好教訓他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29001 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29001, 0, 0, 'zhTW', '十字軍會從這個世界上抹去你們的存在！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29001 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29001, 1, 0, 'zhTW', '看樣子我得親自對付你了。嚐嚐大檢查官的厲害吧，天災軍團！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29001 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29001, 2, 0, 'zhTW', '你想要尋求救贖？我就是你的救星！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29001 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29001, 2, 1, 'zhTW', '接受聖光的淨化吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29001 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29001, 2, 2, 'zhTW', '懦夫！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29001 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29001, 3, 0, 'zhTW', '%s的屍體倒在了地上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29021 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29021, 0, 0, 'zhTW', '未來仍然籠罩著陰霾。$n，這是你的命運。雖然你和你的夥伴或許不是先知的對手，但是，你必須嘗試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29022 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29022, 0, 0, 'zhTW', '庫弗，我們再次聽到你的召喚。請允許我們給你和$n幾句忠告。你們即將面臨巨大的威脅，如果不趕緊行動的話，你們和哈克婭都會喪命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29023 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29023, 0, 0, 'zhTW', '只有殺死奎絲魯恩祭壇典獄官，獲得充滿活力的典獄官精華，才能引出阿卡里先知。你必須將這兩件稀罕物交給哈克婭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29024 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29024, 0, 0, 'zhTW', '唯有完美的守衛者徽記能傳達挑釁的意圖。擁有這顆徽記的守衛者就在戒備森嚴的希姆魯克。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 0, 0, 'zhTW', '這是什麼？我殺死阿卡里時就認出你了。你是$n，他們都很懼怕你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 1, 0, 'zhTW', '你根本不足為患，$g小子:小丫頭。相反，我正想殺了你。誰也別想阻止我進入希姆託加！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 2, 0, 'zhTW', '直到現在你才明白——我擁有神靈的力量，這真是遺憾。你不過是個凡人，怎可能擊敗我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 3, 0, 'zhTW', '多管閒事。你只是闖入巨魔帝國的外來者。去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 4, 0, 'zhTW', '先知開始施放殲滅儀式。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 5, 0, 'zhTW', '什麼？哈克婭？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 6, 0, 'zhTW', '很好，小東西。看來我也不必對你手下留情了。等我解決掉這個蠢貨，再來對付你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29028 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29028, 7, 0, 'zhTW', '不！我是不會被打敗的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 0, 0, 'zhTW', '你是來執行任務的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 1, 0, 'zhTW', '你是來執行任務的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 2, 0, 'zhTW', '你是來執行任務的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 3, 0, 'zhTW', '看著我的眼睛……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 4, 0, 'zhTW', '啊，來自鐵爐堡的孩子，你想做什麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 5, 0, 'zhTW', '很諷刺吧？身為被遺忘者，還能再死一次……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 6, 0, 'zhTW', '能不能讓我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 7, 0, 'zhTW', '我是來……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 8, 0, 'zhTW', '我要像獸人那樣死去……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 9, 0, 'zhTW', '我是來……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 10, 0, 'zhTW', '%s因為傷勢過重而死掉了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 11, 0, 'zhTW', '$n？夥計？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 12, 0, 'zhTW', '$n，我認得你的臉龐……他們……他們對你做了些什麼，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 13, 0, 'zhTW', '$n，我認得你的鬍鬚……他們……他們對你做了些什麼，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 14, 0, 'zhTW', '$n，我認得你的臉龐……他們……他們對你做了些什麼，$g小夥子:小姑娘？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 15, 0, 'zhTW', '$n，我認得你的骨頭……他們……他們對你做了些什麼，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 16, 0, 'zhTW', '$n，我認得你的犄角……他們……他們對你做了些什麼，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 17, 0, 'zhTW', '$n，我認得你的獠牙……他們……他們對你做了些什麼，夥計？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 18, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為德萊尼人的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 19, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為鐵爐堡的孩子的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 20, 0, 'zhTW', '你不記得我了嗎？很久很久以前，我們曾經是人類。天災軍團攻陷洛丹倫後，我們相繼淪為殭屍。但是不久之後，黑暗女王解放了我們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 21, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為地精的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 22, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為人類的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 23, 0, 'zhTW', '你不記得我了？那時候，你還是襁褓中的嬰兒。你的母親每次去月神殿當值時，就會把你託付給我。我抱著你，餵你蜂蜜和羊奶。我耐心地哄你睡覺，直到你的母親回家。你就像我的小天使。該死的天災軍團……他們對你做了什麼，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 24, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為獸人的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 25, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為牛頭人的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 26, 0, 'zhTW', '你不記得我了？該死的天災軍團！他們榨乾了你的魔精，泯滅了你最後一絲良知……還有你身為巨魔的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 27, 0, 'zhTW', '我們曾經起誓！要向巫妖王復仇！他摧毀了我們的王國，我們發誓要讓他付出代價！我們組建起被遺忘者大軍，和天災軍團作戰，將他們趕回了瘟疫之地，解放了提瑞斯法林地！你和我都曾是被遺忘者氏族的勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 28, 0, 'zhTW', '想想生命的壯麗畫卷。你，曾是卡多雷的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 29, 0, 'zhTW', '$n，仔細回憶。想想銀月城宏偉的殿堂，那是你的家鄉。想想生命的壯麗畫卷。你，曾是辛多雷氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 30, 0, 'zhTW', '$n，仔細回憶。想想阿古斯高聳的山脊，那是你的家鄉。想想生命的壯麗畫卷。你，曾是德萊尼氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 31, 0, 'zhTW', '$n，仔細回憶。想想丹莫洛被白雪覆蓋的山脊，那是你的家鄉。想想生命的壯麗畫卷。你，曾是矮人氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 32, 0, 'zhTW', '$n，仔細回憶。想想穴居人入侵前的諾姆瑞根！想想手握弧光扳手的感覺。你，曾是地精氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 33, 0, 'zhTW', '$n，仔細回憶。想想艾爾文森林靜謐的山谷，那是你的家鄉。想想生命的壯麗畫卷。你，曾是聯盟的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 34, 0, 'zhTW', '$n，仔細回憶。想想杜洛塔！氏族的勇士不惜犧牲自己，解除了嗜血的詛咒。想想我們的誕生之地——試煉谷。那時，我們的世界一片祥和，不曾翻湧著惡魔的氣息。我們共同書寫了壯麗的生命畫卷，$n。你，曾是部落的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 35 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 35, 0, 'zhTW', '$n，仔細回憶。想想莫高雷起伏的草原，那是你的家鄉。想想生命的壯麗畫卷。你，曾是牛頭人氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 36 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 36, 0, 'zhTW', '$n，仔細回憶。我們是暗矛巨魔啊，朋友！我們情同手足！還記得我們擊敗扎拉贊恩的英雄事蹟嗎？我們打敗了他，解放了回音群島！朋友！好好想想！你曾經是暗矛巨魔氏族的勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 37 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29032, 37, 0, 'zhTW', '聽我說，$n。你必須擺脫巫妖王的控制。他一心盤算著毀掉這個世界，毀掉我們的家園。你不該淪為任由他擺佈的棋子！過去，你曾是一名偉大的英雄；現在，我相信你能為新的英雄。反抗吧！擺脫巫妖王的控制！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29032 AND `GroupID` = 38 AND `ID` = 0 AND `Locale` = 'zhTW';
