INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29061, 12, 0, 'zhTW', '$n，我認得你的臉龐……他們……他們對你做了些什麼，$n？');
