DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29065 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29065, 12, 0, 'zhTW', '$n，我認得你的臉龐……他們……他們對你做了些什麼，$n？');
