DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 17, 0, 'zhTW', '$n，我認得你的獠牙……他們……他們對你做了些什麼，$g小夥子:小姑娘？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 18, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為德萊尼人的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 19, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為鐵爐堡的孩子的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 20, 0, 'zhTW', '你不記得我了嗎？很久很久以前，我們曾經是人類。天災軍團攻陷洛丹倫後，我們相繼淪為殭屍。但是不久之後，黑暗女王解放了我們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 21, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為地精的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 22, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為人類的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 23, 0, 'zhTW', '你不記得我了？那時候，你還是襁褓中的嬰兒。你的母親每次去月神殿當值時，就會把你託付給我。我抱著你，餵你蜂蜜和羊奶。我耐心地哄你睡覺，直到你的母親回家。你就像我的小天使。該死的天災軍團……他們對你做了什麼，$n？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 24, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為獸人的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 25, 0, 'zhTW', '你不記得我了？該死的天災軍團……他們挫敗了你的正義之氣、泯滅了你最後一絲良知……還有你身為牛頭人的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 26, 0, 'zhTW', '你不記得我了？該死的天災軍團！他們榨乾了你的魔精，泯滅了你最後一絲良知……還有你身為巨魔的天性！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 27, 0, 'zhTW', '我們曾經起誓！要向巫妖王復仇！他摧毀了我們的王國，我們發誓要讓他付出代價！我們組建起被遺忘者大軍，和天災軍團作戰，將他們趕回了瘟疫之地，解放了提瑞斯法林地！你和我都曾是被遺忘者氏族的勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 28, 0, 'zhTW', '想想生命的壯麗畫卷。你，曾是卡多雷的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 29, 0, 'zhTW', '$n，仔細回憶。想想銀月城宏偉的殿堂，那是你的家鄉。想想生命的壯麗畫卷。你，曾是辛多雷氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 30, 0, 'zhTW', '$n，仔細回憶。想想阿古斯高聳的山脊，那是你的家鄉。想想生命的壯麗畫卷。你，曾是德萊尼氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 31, 0, 'zhTW', '$n，仔細回憶。想想丹莫洛被白雪覆蓋的山脊，那是你的家鄉。想想生命的壯麗畫卷。你，曾是矮人氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 32, 0, 'zhTW', '$n，仔細回憶。想想穴居人入侵前的諾姆瑞根！想想手握弧光扳手的感覺。你，曾是地精氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 33, 0, 'zhTW', '$n，仔細回憶。想想艾爾文森林靜謐的山谷，那是你的家鄉。想想生命的壯麗畫卷。你，曾是聯盟的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 34, 0, 'zhTW', '$n，仔細回憶。想想杜洛塔！氏族的勇士不惜犧牲自己，解除了嗜血的詛咒。想想我們的誕生之地——試煉谷。那時，我們的世界一片祥和，不曾翻湧著惡魔的氣息。我們共同書寫了壯麗的生命畫卷，$n。你，曾是部落的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 35 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 35, 0, 'zhTW', '$n，仔細回憶。想想莫高雷起伏的草原，那是你的家鄉。想想生命的壯麗畫卷。你，曾是牛頭人氏族的勇士！眼前的你，不是真正的你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 36 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 36, 0, 'zhTW', '$n，仔細回憶。我們是暗矛巨魔啊，朋友！我們情同手足！還記得我們擊敗扎拉贊恩的英雄事蹟嗎？我們打敗了他，解放了回音群島！朋友！好好想想！你曾經是暗矛巨魔氏族的勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 37 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 37, 0, 'zhTW', '聽我說，$n。你必須擺脫巫妖王的控制。他一心盤算著毀掉這個世界，毀掉我們的家園。你不該淪為任由他擺佈的棋子！過去，你曾是一名偉大的英雄；現在，我相信你能為新的英雄。反抗吧！擺脫巫妖王的控制！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29072 AND `GroupID` = 38 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29072, 38, 0, 'zhTW', '聽我說，$n。你必須擺脫巫妖王的控制。他一心盤算著毀掉這個世界，毀掉我們的家園。你不該淪為任由他擺佈的棋子！過去，你曾是一名偉大的英雄；現在，我相信你能為新的英雄。反抗吧！擺脫巫妖王的控制！');
