INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29074, 53, 0, 'zhTW', '%s因為傷勢過重而死掉了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29076 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29076, 0, 0, 'zhTW', '呃，這棵樹真奇怪。我必須研究一下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29076 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29076, 1, 0, 'zhTW', '這是什麼！？這根本不是樹！守衛！來人啊！');
