INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29120, 0, 0, 'zhTW', '無盡的痛苦在等待著你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29120 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29120, 1, 0, 'zhTW', '很快，你就將聽到主人的召喚。');
