INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29120, 2, 0, 'zhTW', '啊……啊啊啊！從沒有想到……我還能擺脫……他的魔掌……');
