INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29120, 3, 0, 'zhTW', '在我的蟲群面前，你的盔甲毫無用處！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29120 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29120, 3, 1, 'zhTW', 'Uunak-hissss tik-k-k-k-k！');
