INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 7, 'zhTW', '不留活口！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 8, 'zhTW', '這是什麼？！我的……我不能攻擊了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 9, 'zhTW', '服從我，灰燼使者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 10, 'zhTW', '遵照我的意願！我是你的主人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 11, 'zhTW', '我……我竟不能……這把劍背叛了我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 12, 'zhTW', '到底是怎麼了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 13 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 13, 'zhTW', '力量……消失了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 14 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 14, 'zhTW', '灰燼使者正在抗拒我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 8 AND `ID` = 15 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 8, 15, 'zhTW', '僕從們，快來幫我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 26, 0, 'zhTW', '死亡騎士們，撤退。我們戰敗了……這裡的……聖光之力…………我們輸定了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 30, 0, 'zhTW', '省點力氣吧，老傢伙。這將是你的最後一口氣息了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 32, 0, 'zhTW', '父親！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 33, 0, 'zhTW', '啊……這……這是……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 43 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 43, 0, 'zhTW', '你……背叛了我。你背叛了我們所有人，怪物！感受莫格萊尼的力量吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 51 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 51, 0, 'zhTW', '但，不是今天……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 52 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 52, 0, 'zhTW', '提里奧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 67 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 67, 0, 'zhTW', '這也是黑鋒騎士們的心願……儘管在你們的世界中已沒有立足之地，但我們仍要為打倒巫妖王而戰鬥。我在此立誓！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 68 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 68, 0, 'zhTW', '數以千計的天災爪牙在大領主的召喚下醒來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 69 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 69, 0, 'zhTW', '天災軍團的爪牙向聖光之願禮拜堂進軍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 70 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 70, 0, 'zhTW', '一百名聖光護衛者倒下後，大領主提里奧·弗丁趕到了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 72 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 72, 0, 'zhTW', '%s被提里奧·弗丁擊敗，跪倒在地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 77 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 77, 0, 'zhTW', '%s變回了自己，表情很是憤怒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 81 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 81, 0, 'zhTW', '%s將墮落的灰燼使者拋向提里奧·弗丁，提里奧身上神聖充滿了聖光之力將灰燼使者淨化。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 82 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 82, 0, 'zhTW', '%s倒下了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29173 AND `GroupID` = 85 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29173, 85, 0, 'zhTW', '聖光洗禮了禮拜堂嗎？黎明曙光即將重現。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 24, 0, 'zhTW', '你贏不了的，達里安！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 25, 0, 'zhTW', '帶到禮拜堂前！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 27, 0, 'zhTW', '你難道還不明白嗎，孩子？你已經淪為了你父親畢生都在對抗的存在！你已經和阿爾薩斯那個懦夫一樣，甘心墮入黑暗……墮入仇恨……以殺害他人為生！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 28, 0, 'zhTW', '你的主子知道禮拜堂下面埋藏著什麼。所以他才不敢露面！你和你的死亡騎士就是他派來送死的，達里安。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 29, 0, 'zhTW', '你現在感受到的，是上千個迷失靈魂的痛苦！他們都是犧牲在你和你的主人劍下的英靈！聖光會把你撕碎的，達里安！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 46 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 46, 0, 'zhTW', '阿爾薩斯，你這該死的怪物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 53 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 53, 0, 'zhTW', '阿爾薩斯！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 55 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 55, 0, 'zhTW', '你完了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 59 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 59, 0, 'zhTW', '站起來，達里安，你聽著……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 60 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 60, 0, 'zhTW', '我們見證了一場可怕的悲劇。善良人的鮮血早已將這整片土地染紅！無數高貴而英勇的騎士，為了保衛我們而犧牲在這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 61 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 61, 0, 'zhTW', '我們永遠不會忘記這一幕，我們仍然需要保持警惕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 62 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 62, 0, 'zhTW', '巫妖王必須為他的所作所為付出代價，我們絕不能再讓他繼續破壞這個世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 63 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 63, 0, 'zhTW', '兄弟們，姐妹們，我向你們發誓：巫妖王一定會被消滅！今天，我們大家要重新團結起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 64 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 64, 0, 'zhTW', '銀色黎明和白銀之手騎士團將在此合二為一！我們一定可以完成前人未盡的事業！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 65 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 65, 0, 'zhTW', '我們要繼續抗爭阿爾薩斯，我們終將推倒寒冰皇冠的城牆！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 66 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 66, 0, 'zhTW', '阿爾薩斯，銀白十字軍向你宣戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 79 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 79, 0, 'zhTW', '%s氣喘吁吁。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29175 AND `GroupID` = 83 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29175, 83, 0, 'zhTW', '%s握著灰燼使者衝向巫妖王，對他進行全力一擊。巫妖王被震退了一個踉蹌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29176 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29176, 6, 0, 'zhTW', '天災軍團來了！');
