INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29178, 7, 0, 'zhTW', '兄弟姐妹們，堅持住！聖光必勝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29178 AND `GroupID` = 49 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29178, 49, 0, 'zhTW', '打！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 42 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 42, 0, 'zhTW', '真感人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 44 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 44, 0, 'zhTW', '他現在歸我了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 45 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 45, 0, 'zhTW', '真可憐……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 47 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 47, 0, 'zhTW', '你說對了，弗丁。我就是派他們去送死的。他們的生命毫無意義，但你的不同……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 48 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 48, 0, 'zhTW', '把偉大的提里奧·弗丁揪出來還真是容易啊。你已經暴露了，聖騎士。誰也救不了你了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 50 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 50, 0, 'zhTW', '末日！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 54 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 54, 0, 'zhTW', '怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 56 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 56, 0, 'zhTW', '這不可能……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 57 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 57, 0, 'zhTW', '還……沒有完呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 58 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 58, 0, 'zhTW', '下一次，我們就不會在這片聖地上決戰了，聖騎士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 78 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 78, 0, 'zhTW', '%s對提里奧釋放咒語。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 80 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 80, 0, 'zhTW', '%s釋放了一個強大的魔法，殺死了大教堂附近的騎士和守衛。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29183 AND `GroupID` = 84 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29183, 84, 0, 'zhTW', '%s消失了，提里奧·弗丁慢慢的走向達瑞安·莫萊格尼大領主。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 0, 0, 'zhTW', '作為鮮血學徒，你們必須懂得如何掌控敵人的生命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 1, 0, 'zhTW', '藉助武器或咒術，鮮血能提高我們的攻擊力，同時削弱敵人的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 2, 0, 'zhTW', '真正的大師能利用鮮血在戰鬥中爆發出超越自身的強大力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 3, 0, 'zhTW', '無論對手是一息尚存還是已然斃命，我們都能汲取他們的能量，以此獲得遠勝於低等生物的生存力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 4, 0, 'zhTW', '敵人倒下後，我們能竊取並利用他們殘餘的所有能量繼續展開攻擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 5, 0, 'zhTW', '對鮮血大師來說，戰鬥是永無止境的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 6, 0, 'zhTW', '我們渴望著鮮血的洗禮……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 7, 0, 'zhTW', '我們擁有敵人永遠無法戰勝的力量……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29196 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29196, 8, 0, 'zhTW', '鮮血大師掌控著生命與死亡。膽敢與我們為敵的傢伙，會被抽乾所有的能量，淪為毫無生氣的死屍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29204 AND `GroupID` = 71 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29204, 71, 0, 'zhTW', '%s逃跑了。');
