INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29227, 76, 0, 'zhTW', '%s突然消失了，巫妖王出現了並奪取了他的靈魂。');
