INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29228, 37, 0, 'zhTW', '父親，我也想加入部隊，和您一起抵抗亡靈。我也要戰鬥，不能再袖手旁觀了！');
