INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29572, 0, 0, 'zhTW', '你休想從我嘴裡問出元帥的下落。我還不至於受你擺佈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29572 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29572, 1, 0, 'zhTW', '不。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29572 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29572, 2, 0, 'zhTW', '住手！用不著這樣。我告訴你他的下落。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29572 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29572, 3, 0, 'zhTW', '這座島嶼的南端有一處極端隱蔽的洞穴。元帥就躲在那兒，策劃著對巫妖王的最後決戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29572 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29572, 4, 0, 'zhTW', '啊啊啊啊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29573 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29573, 0, 0, 'zhTW', '%s聚集了魔精，向前衝去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29573 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29573, 1, 0, 'zhTW', '隨著%s最後的殘骸滲入地下，附近的祭壇開始散發出微弱的光芒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 0, 0, 'zhTW', '我……我能聽懂！呃，既然我們能夠對話，那麼我想聽聽你的解釋！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 1, 0, 'zhTW', '你是怎麼從探險者協會那裡拿到我的聯絡器的？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 2, 0, 'zhTW', '探險者協會真的派出了其他探員？我一個也沒見著。我在一座被鐵矮人攻佔的營地裡發現了你的日記。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 3, 0, 'zhTW', '你解決了鐵矮人，我很感謝你。但是部落為什麼會對我感興趣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 4, 0, 'zhTW', '有個斥候在索爾莫丹發現了這本日記的剩餘部分。從那時起，我們就開始尋找你的下落了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 5, 0, 'zhTW', '該不會是斥候沃塔肯吧？連我都聽說過他冷酷無情的名頭。所以他是打算綁架我的吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 6, 0, 'zhTW', '如果你看過日記，就該知道我發現了什麼。泰坦的造物正在自相殘殺！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 7, 0, 'zhTW', '洛肯和他的鐵矮人已經將土靈逐出了奧杜爾，並佔領了這座城市。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 8, 0, 'zhTW', '如果我們繼續廝殺，洛肯就會利用奧杜爾的資源將聯盟和部落一起摧毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29579 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29579, 9, 0, 'zhTW', '去和指揮官談談，勸他放棄沃塔肯的愚蠢計劃吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29614 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29614, 0, 0, 'zhTW', '即便在死後，你也無路可逃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29614 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29614, 0, 1, 'zhTW', '我要吞噬你的靈魂！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29614 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29614, 0, 2, 'zhTW', '既然你已經知道了，那就必須死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29614 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29614, 0, 3, 'zhTW', '你休想活著離開這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29614 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29614, 1, 0, 'zhTW', '黑暗編織者衝你露出邪惡的笑容，他的身體緊接著變成了完全不同的形態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29618 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29618, 0, 0, 'zhTW', '“吼！”');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29618 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29618, 0, 1, 'zhTW', '我們不害怕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29618 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29618, 0, 2, 'zhTW', '絲網攔不住我！不……網把我攔住了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29618 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29618, 0, 3, 'zhTW', '別殺我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29618 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29618, 0, 4, 'zhTW', '不！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29618 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29618, 0, 5, 'zhTW', '別想……抓住我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 0, 0, 'zhTW', '啊！我在那具虛弱的軀殼中待得太久了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 1, 0, 'zhTW', '[惡魔語]Kirel narak！我是瑪爾加尼斯！我是不朽的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 2, 0, 'zhTW', '[惡魔語]Anach kyree！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 2, 1, 'zhTW', '我的先鋒軍，將會蕩平巫妖王的部隊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 2, 2, 'zhTW', '你的犧牲是徒勞的，渺小的凡人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 2 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 2, 3, 'zhTW', '你的生命結束了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 3, 0, 'zhTW', '夠了！我在這裡浪費了不少時間，必須回到家鄉去回覆體力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29620 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29620, 4, 0, 'zhTW', '沒有我的部隊，你們永遠也別想擊敗巫妖王。我會向他復仇的……還有你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29621 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29621, 0, 0, 'zhTW', '你怎麼找到我的？難道蘭德雷全招了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29621 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29621, 1, 0, 'zhTW', '你們覺得我會甘心等死嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29621 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29621, 2, 0, 'zhTW', '什麼？！沒關係。就算沒有魔法屏障，我仍然可以輕易消滅你們！在絕望中感受我真正的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29626 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
