DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29895 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29895, 0, 0, 'zhTW', '主人！不！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29895 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29895, 1, 1, 'zhTW', '塞穆來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29914 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29914, 0, 0, 'zhTW', '雷鑄鐵矮人從殘破的屍體中湧了出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29919 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29919, 1, 0, 'zhTW', '黯刃騎士團指揮官、天災軍團征服者以及暗影拱頂征服者——蘭克拉爾公爵命令你束手就擒。你接不接受這份裁決？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29919 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29919, 2, 0, 'zhTW', '怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29919 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29919, 3, 0, 'zhTW', '接不接受？這就是我的回答，小信差！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29919 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29919, 4, 0, 'zhTW', '我要拿你去領賞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 29920 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (29920, 0, 0, 'zhTW', '魔精池裡似乎有什麼生物在騷動……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 0, 0, 'zhTW', '除非親眼目睹，否則接下來的戰鬥將令人難以置信！這位即將出場的戰士原本是個脾氣溫和的海象人漁夫，但是他的全家被惡毒的海獅和暴躁的企鵝殺死了，從此他就變成了一個行屍走肉般的僱傭兵。現在，他只為金幣而戰！女士們先生們，他就是奧裡努克·碎牙！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 1, 0, 'zhTW', '冰斧巨魔的勇士向你發起了挑戰，$n！希望你已經做好了準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 2, 0, 'zhTW', '奧特蘭克山谷的訪客，鬥獸場中迄今為止最為兇猛的鬥士：血怒者科爾拉克！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 3, 0, 'zhTW', '戰鬥即將開始！我沒念錯吧？這……這是邪惡的猛獁人領主，惡臭之須！是的，各位，是惡臭之須！$n毫無取勝的希望！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 6, 0, 'zhTW', '你們感覺到了嗎？能量在空氣中沸騰！這隻能說明……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 7, 0, 'zhTW', '進入痛苦鬥獸場吧，$n。戰鬥開始後，你就必須留在競技場裡。要麼獲勝，要麼死亡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 7 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 7, 1, 'zhTW', '進入痛苦鬥獸場吧，$n。戰鬥開始後，你就必須留在競技場裡。要麼獲勝，要麼死亡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 8, 0, 'zhTW', '女士們先生們，我們又見面啦。痛苦鬥獸場的生死大戰即將拉開帷幕！這一輪，將由$N對陣龐大的冰蟲伊戈……伊戈達？伊戈杜斯？這名字是誰起的？！好吧，由$N對陣大蟲子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 9, 0, 'zhTW', '做好準備，$N！進入鬥獸場，準備戰鬥！記住，你和你的對手都不能離開競技場，否則你會被取消資格！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 10, 0, 'zhTW', '$n擊敗了伊戈……伊戈這隻大蟲子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 10 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 10, 1, 'zhTW', '$n擊敗了伊戈……伊戈這隻大蟲子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 10 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 10, 2, 'zhTW', '$n擊敗了伊戈……伊戈這隻大蟲子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 10 AND `ID` = 3 AND `Locale` = 'zhTW';
