DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 11, 0, 'zhTW', '$n又一次勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 11 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 11, 1, 'zhTW', '$n又一次勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 11 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 11, 2, 'zhTW', '$n又一次勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 12, 0, 'zhTW', '$n以絕對優勢戰勝了猛獁人領主！龍骨荒野的猛獁人氏族會懷念惡臭之須的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 13, 0, 'zhTW', '來自寒冰皇冠野蠻之臺的屠夫烏拉多弗以及他的猛獁象恩諾姆斯！各位，這次我們的挑戰者恐怕會被轟得連渣都不剩！讓我們共同期待一場腥風血雨的大戰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 14, 0, 'zhTW', '難以置信！新的痛苦鬥獸場勇士誕生了！！！一群無名小卒擊敗了屠夫烏拉多弗！真是個奇蹟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 15, 0, 'zhTW', '挑戰者只留下了一灘血跡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 15 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 15, 1, 'zhTW', '女士們先生們，請閉上雙眼！這簡直是大屠殺！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 15 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 15, 2, 'zhTW', '不如叫些小丑來！神聖的鬥獸場已經淪為馬戲團了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 15 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 15, 3, 'zhTW', '哇！那傢伙需要好好地“刮一刮”！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 15 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 15, 4, 'zhTW', '我還沒回過神來——就聽見“砰”的一聲！挑戰者就死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30007 AND `GroupID` = 15 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30007, 15, 5, 'zhTW', '他們還真是不堪一擊啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30012 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30012, 0, 0, 'zhTW', '你休想打敗我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30012 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30012, 0, 1, 'zhTW', '你不配與托里姆並肩作戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30012 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30012, 0, 2, 'zhTW', '祝你好運……你需要的就是運氣了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30012 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30012, 0, 3, 'zhTW', '強者將獲得勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30012 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30012, 0, 4, 'zhTW', '我什麼都不怕——來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30014 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30014, 1, 0, 'zhTW', '%s出場了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30017 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30017, 0, 0, 'zhTW', '%s變得憤怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30017 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30017, 1, 0, 'zhTW', '一群小不點，惡臭之須來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30019 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30019, 1, 0, 'zhTW', '我要熔化你們的血肉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30019 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30019, 2, 0, 'zhTW', '你無法用火焰燒燬我的王國！來吧，僕從們，我還不打算退位呢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30020 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30020, 0, 0, 'zhTW', '來吧，旱鴨子。面對我的怒火吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30020 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30020, 1, 0, 'zhTW', '凍須！你在哪兒？！快來幫我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30022 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30022, 1, 0, 'zhTW', '嗨，寶貝兒，將他們統統撕碎！我們才是真正的王者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30022 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30022, 2, 0, 'zhTW', '沒用的傢伙！看來我得親自動手了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30022 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30022, 3, 0, 'zhTW', '烏拉多弗躍下了猛獁象！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30022 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30022, 4, 0, 'zhTW', '%s開始旋轉，一個魔法護盾包圍了他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30023 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30023, 1, 0, 'zhTW', '科爾拉克來了！雪落墓地屬於冰斧的勇士！呃，科爾拉克是想要說，鬥獸場屬於冰斧的勇士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30023 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30023, 2, 0, 'zhTW', '別想對科爾拉克耍花招，鬥獸場可沒有墓地！去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30024 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30024, 1, 0, 'zhTW', '為獵潮者而戰！海洋與風暴的力量，摧毀我的敵人吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30024 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30024, 2, 0, 'zhTW', '我是萬惡之惡，冷血之王！過來吧，元素僕從們，讓我們冰封一切，統治世界！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30025 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30025, 1, 0, 'zhTW', '站起來吧，大地的兄弟們。伊拉修斯要消滅這群凡人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30025 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30025, 2, 0, 'zhTW', '我是至高無上的土靈之王！僕從們，現身吧——快來幫助你們的君王！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30026 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30026, 1, 0, 'zhTW', '風之領主，讓我的敵人迅速死去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30026 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30026, 2, 0, 'zhTW', '我帶起一陣足以吹倒大樹的狂風！僕從們，快來幫我，他們不會得逞的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30037 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30037, 0, 0, 'zhTW', '放馬過來吧，$r$c，我可不會等你一整天！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30037 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30037, 0, 1, 'zhTW', '就算殺了你，也不能證明我在瓦哈拉斯的地位，就當是消遣好了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30037 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30037, 0, 2, 'zhTW', '如果你找死，那麼我就成全你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30037 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30037, 0, 3, 'zhTW', '對你來說是一次到地底的快速旅行，對我來說哈哈一笑。聽起來是個公平的交易。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30081 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30081, 0, 0, 'zhTW', '你竟敢挑戰我？！別以為這樣就能阻止我向巫妖王效忠！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30084 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30084, 0, 0, 'zhTW', '附近的裂隙中冒出了一團能量火花！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30086 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30086, 0, 0, 'zhTW', '嚐嚐我的鐵拳吧，小鬼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30086 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30086, 1, 0, 'zhTW', '打得不錯啊，小傢伙。我輸了。我們還會再見面的。下次我一定會做好充分的準備。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30098 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 0, 'zhTW', '小吃！');
