INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 1, 'zhTW', '出售小吃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30098 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 2, 'zhTW', '來買點小吃吧！');
