INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 3, 'zhTW', '小吃！來買點小吃吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30098 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 4, 'zhTW', '爆米花！來買點爆米花吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30098 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 5, 'zhTW', '花生！來買點花生吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30098 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 6, 'zhTW', '痛苦啤酒！來買點冰鎮的痛苦啤酒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30098 AND `GroupID` = 0 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30098, 0, 7, 'zhTW', '爆米花！花生！啤酒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 0, 0, 'zhTW', '你修復了鑰石，我對此感激不盡。我保證，你的努力將成就偉大的事業。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 1, 0, 'zhTW', '鐵矮人……到處都是……他們衝我們來了。這幫固執的傢伙看來是不會放過我們的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 2, 0, 'zhTW', '他們想要擊落飛機！我沒法往上攀升……別讓他們靠近我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 3, 0, 'zhTW', '前面還有更多的鐵矮人——堅持！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 4, 0, 'zhTW', '我們就快脫險啦……還差一點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 5, 0, 'zhTW', '只要別被巨人扔下的石塊砸到，我們就很安全……雖然下面已經被砸得一團糟了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 6, 0, 'zhTW', '他們的數量多得難以置信……好在雷心國王伸出了援手。我聽說過他的許多事蹟——是時候見見他了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 7, 0, 'zhTW', '可憐的克萊特烏斯。他是個優秀的守護者……至少他完成了自己的使命。我相信，這件事的重要性對他來說是不言而喻的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30107 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30107, 8, 0, 'zhTW', '我們就快抵達冰霜堡了。如果你能在離開前把我介紹給雷心國王，我會非常感激你的。我們倆都欠他一份情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30124 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30124, 0, 0, 'zhTW', '哦，你好，小$r。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30142 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30142, 0, 0, 'zhTW', '鋼鐵觀察者捂著受傷的雙眼，盲目地橫衝直撞。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30142 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30142, 1, 0, 'zhTW', '鋼鐵觀察者發出一聲怒吼，摔倒在地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30146 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30146, 0, 0, 'zhTW', '該死的！你不能把我當牲口一樣對待！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30146 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30146, 0, 1, 'zhTW', '夠了！我要教你學會懂禮貌！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30146 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30146, 0, 2, 'zhTW', '我寧願戰死，也不會為了苟活而去做奴隸！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30146 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30146, 1, 0, 'zhTW', '回去……工作……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30146 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30146, 1, 1, 'zhTW', '總有一天……我們要復仇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30146 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30146, 1, 2, 'zhTW', '在你眼裡，我們連牲口都不如！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30147 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30147, 0, 0, 'zhTW', '抓住他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30152 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30152, 0, 0, 'zhTW', '你的奴僕將再也不能攻擊岩石的子嗣和他們的盟友了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30152 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30152, 1, 0, 'zhTW', '我要終結你的性命，瓦杜蘭！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30152 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30152, 2, 0, 'zhTW', '幹得好！今天我們取得了勝利，但是戰爭還在繼續！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30154 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30154, 0, 0, 'zhTW', '我什麼都不怕——來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30162 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30162, 0, 0, 'zhTW', '啊！！！！我要宰了你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30162 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30162, 1, 0, 'zhTW', '喲！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30163 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30163, 0, 0, 'zhTW', '雷鑄鐵矮人從殘破的屍體中湧了出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30180 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30180, 0, 0, 'zhTW', '奧努森要宰了你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 0, 0, 'zhTW', '檢測到不明金屬樣本。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 1, 0, 'zhTW', '開始分析……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 2, 0, 'zhTW', '確認樣本為薩隆邪鐵與鐵的合金。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 3, 0, 'zhTW', '該樣品中的礦石成分來自艾澤拉斯的地殼深處，這種礦石是最近才被挖掘出來的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 4, 0, 'zhTW', '該樣品中薩隆邪鐵的純度非常高。在自然狀態下，這種礦石是不會出現在艾澤拉斯表面的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 5, 0, 'zhTW', '只有強大而邪惡的力量才能創造出這種礦石。嘗試訪問資料庫，搜尋更多資訊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 6, 0, 'zhTW', '拒絕訪問？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 7, 0, 'zhTW', '要了解更多資訊，必須獲取守護者洛肯的指令，然後訪問奧杜爾的檔案。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 8, 0, 'zhTW', '我敢肯定的是：從護甲板的尺寸、厚度以及螺絲孔的位置來看，它肯定是某個巨型裝置的護甲。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30190 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30190, 9, 0, 'zhTW', '指令完成。返回待機模式。');
