INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 1, 0, 'zhTW', '托里姆！快出來吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 2, 0, 'zhTW', '風暴之王，您的$r僕人做出了超乎尋常的高尚行為。透過努力，$g他:她已經成功地軟化了我的子民的心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 3, 0, 'zhTW', '托里姆竟然說出過如此謙卑的言辭。我會將你的這番話轉達給丹尼芬雷的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 4, 0, 'zhTW', '我們決定寬恕你在黑暗時代的所作所為。不會再有誰提起那些往事了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 5, 0, 'zhTW', '作為我們重鑄友誼的見證，我就把這東西物歸原主吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 6, 0, 'zhTW', '大爆炸來臨時，我的父親對錘子施放了符文，絕不能讓它落入敵人之手。這是他做的最後一件事……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 7, 0, 'zhTW', '托里姆，希望今後還能與你並肩作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30331 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30331, 8, 0, 'zhTW', '我必須返回丹尼芬雷了。風暴之王，我相信我們還會見面的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30344 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
