INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 0, 0, 'zhTW', '你要對付的有史以來最狡猾、最聰明、最兇狠的生物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 1, 0, 'zhTW', '巫妖王不同於已往的任何敵人，大領主。雖然你曾在聖光之願禮拜堂打敗過他，但如今，你卻身處巫妖王統御下的邪惡王國中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 2, 0, 'zhTW', '你不可能獲勝。照目前的情形，是毫無希望的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 3, 0, 'zhTW', '什麼也不能。你的能力受到聖光的侷限，在這種情況下你什麼都做不了。聖光完全控制了你，將你牢牢地束縛在它所能觸及的範圍之內。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 4, 0, 'zhTW', '%s搖了搖頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 5, 0, 'zhTW', '大領主，認清眼前的局勢吧。巫妖王已經徹底封鎖了你的前路，佔據了上風。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 6, 0, 'zhTW', '蛛魔的巨網將迅速封印你開啟的突破口。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 7, 0, 'zhTW', '在迴音谷，你的士兵成為了阻擋炮火的肉盾，幫助巫妖王的軍隊順利地攻陷了你的營地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 8, 0, 'zhTW', '巫妖王清楚你心中的底線，大領主。他知道你是不會對自己人開火的。你還不明白嗎？對他來說，不談底線，不講原則。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30377 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30377, 9, 0, 'zhTW', '那你就輸定了，大領主。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 0, 0, 'zhTW', '你的存在差點就被抹殺了。$n勇敢地與北風作戰，保護了關於你的歷史。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 1, 0, 'zhTW', '雷蹄，你與北風的戰鬥已經過去了數百年。你重創了它，這些年來它一直都很沉寂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 2, 0, 'zhTW', '但是北風不甘心就此落敗。相反，它一直在積聚力量，等待時機，意圖摧毀你的歷史和這座村莊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 3, 0, 'zhTW', '北風讓它的爪牙扭曲了這個地區的歷史，意圖改變犛牛人口口相傳的故事並消滅先祖的亡魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 4, 0, 'zhTW', '要不是$n和我循著北風扭曲歷史的線索，找到了破壞的源頭：你與北風的那場遠古之戰，它們的陰謀已經得逞了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 5, 0, 'zhTW', '在我的幫助下，$n及時返回了那場戰鬥的時間流，維護了歷史的真相。北風的命運已經被封印起來，你的故事也得以恢復正常。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 6, 0, 'zhTW', '安息吧，勇士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 7, 0, 'zhTW', '完全不對，$n。在馴風者巴蘭告訴我的傳說裡，雷蹄是個英雄，不是暴徒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 8, 0, 'zhTW', '北風是犛牛人的夙敵。它統治著元素生物，肆意踐踏著犛牛人的性命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 9, 0, 'zhTW', '他們寧願死，也不願意臣服於北風。這裡出了差錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 10, 0, 'zhTW', '知識之錘……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 11, 0, 'zhTW', '這證實了我們的懷疑。時間流的程序被切斷了，歷史也被篡改了。這是怎麼做到的呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 12, 0, 'zhTW', '毫無疑問，有東西在干擾雷蹄和唐卡洛戰士的真實歷史。這究竟是怎麼回事呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 13, 0, 'zhTW', '不！真實的歷史不容褻瀆。我們將恢復被你摧毀的一切！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30381 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30381, 14, 0, 'zhTW', '$n，我們必須儘快確定北風是從什麼時候開始篡改時間流的。然後我們才有可能打敗他並糾正歷史。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30388 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30388, 0, 0, 'zhTW', '號角！趁它進入虛弱狀態吹響號角！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30388 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30388, 1, 0, 'zhTW', '進入神廟中心，使用元素憤怒號角！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30390 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30390, 0, 0, 'zhTW', '約庫姆國王，是你在召喚我嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30390 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30390, 1, 0, 'zhTW', '約庫姆國王，安格里姆之子，我一直對自己的行為感到後悔。我壓抑不住內心的傷痛，深深地傷害了身邊的親人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30390 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30390, 2, 0, 'zhTW', '請求您寬恕我為您和您的子民帶來的痛苦和傷害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30390 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30390, 3, 0, 'zhTW', '科洛米爾……謝謝你，約庫姆。我都不敢奢望它還完好無損。很快，它將再次見證光輝的戰役！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 0, 0, 'zhTW', '我的兄弟雷蹄，是一位比我更出色的戰士。在我接受繼任氏族酋長的訓練時，他正在為一項重要的任務做準備。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 1, 0, 'zhTW', '他怎麼會有危險呢？他只是想讓我們獲得力量，控制那些令我們難以安生的元素生物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 2, 0, 'zhTW', '他要去找一件神器……一隻號角。他離開了村子，踏上了尋找它的漫漫長途。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 3, 0, 'zhTW', '在他奪得號角之後，有個可怕的敵人追上了他……但是，我不記得……後來發生了什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 4, 0, 'zhTW', '我的記憶似乎被一層迷霧籠罩了。我甚至不記得我的兄弟後來出了什麼事。這就是你所說的危險嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 5, 0, 'zhTW', '墳墓在騷動，他們一定被捲進來了。看看你的四周，$n。你看見他們了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30395 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30395, 6, 0, 'zhTW', '是的，情況不妙，但是我無力阻止他們。你能向唐卡洛營地發出警告嗎，陌生人？告訴他們，歷史和他們的祖先正在危險之中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 0, 0, 'zhTW', '托里姆，急著和你心愛的西芙做伴嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 1, 0, 'zhTW', '夠了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 2, 0, 'zhTW', '在公平對決的情況下，你似乎有機會戰勝我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 3, 0, 'zhTW', '不幸的是……這場戰鬥並不公平！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 4, 0, 'zhTW', '這就要感謝你的小朋友了。你離開了風暴神殿，在那裡你才能發揮出全部的力量。而現在，我們戰鬥的地方更靠近主人的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 5, 0, 'zhTW', '奴隸們！把我的兄弟和他的飛龍送去他們的新家吧。別傷了那頭畜生的性命。我還有個針對她的特別計劃呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 6, 0, 'zhTW', '凡人，我會考慮饒恕你的性命的。畢竟……我為什麼要殺掉最得力的僕從啊？我在海德尼爾礦洞裡等了你好幾周呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30396 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30396, 7, 0, 'zhTW', '這當然不是我的真實相貌。如果你不是那麼鹵莽的話，你早就看見我過去的幻影了。但是你畢竟幫助我渡過了難關……我必須謝謝你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 0, 0, 'zhTW', '是時候阻止洛肯的愚蠢行徑了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 1, 0, 'zhTW', '洛肯！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 2, 0, 'zhTW', '來吧，和我交戰！你這沒用的叛徒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 3, 0, 'zhTW', '你竟敢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 4, 0, 'zhTW', '直呼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30399 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30399, 5, 0, 'zhTW', '她的名諱！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 0, 0, 'zhTW', '國王派你來接受試煉？他一定在你身上發現了某種潛質，不然也不會讓你參加如此神聖的儀式。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 1, 0, 'zhTW', '我知道你對霜脈矮人還缺乏瞭解，因此我會在路上為你做一些簡單的介紹。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 2, 0, 'zhTW', '很多年前，我的父親和一些霜脈矮人行走在穿越龍骨荒野的艱難歸程中。他們遇到了暴風雪……比我們見過的任何一場暴風雪都厲害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 3, 0, 'zhTW', '沿著雪地上的血跡，他們遇見了一位流浪的矮人。他操著一口難以理解的方言……嗯，因為他不是一般的矮人啊。這個神秘的流浪者自稱是高山矮人——我們從未聽說過這個氏族。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 4, 0, 'zhTW', '高山矮人似乎迷了路，不記得自己是從哪兒來的，甚至不記得自己的名字。他們不忍心將這位表親丟在冰天雪地裡，於是收留了他，然後踏上了返回冰霜堡的旅途。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 5, 0, 'zhTW', '走著走著，他們面前的雪地突然裂開了，一隻像維拉努斯那麼大的冰蟲襲擊了他們……其中一位夥伴還來不及反應，就被整個吞了下去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 6, 0, 'zhTW', '我的父親以為大家都難逃此劫……但聽背後的雪地裡傳來一聲怒吼，他扭頭看見高山矮人的體型正在增大，他的皮膚上浮現出岩石般的紋理，他的手上冒出嘶嘶作響的閃電。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 7, 0, 'zhTW', '高山矮人帶著悶雷般的吼聲向前衝去，將一把閃亮的金屬錘直接擲進了冰蟲的喉嚨，我的父親還看見金屬錘的表面環繞著閃電。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 8, 0, 'zhTW', '那隻冰蟲立即倒下了，它的腦袋勉強掛在不斷抽搐的軀體上。我的父親敬畏地注視著高山矮人，舉起拳頭表示讚美……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 9, 0, 'zhTW', '這位神秘的高山矮人沒有名字，於是我的父親尊稱他為“約爾格”，這是傳說中的勇士才能享受的稱呼。很多年以後，他成為了霜脈矮人熟知的國王——約爾格·雷心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 10, 0, 'zhTW', '國王對我們進行了嚴格的訓練……讓我們成長為可怕的戰士。如今的我們，遠比當年與冰霜巨人交戰時吹噓的還要厲害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 11, 0, 'zhTW', '作為霜脈戰士最嚴厲的試煉之一，就是戰勝比自己高大許多的敵人，比如巨人、龍或是冰蟲——由此證明體型並不是我們的弱點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 12, 0, 'zhTW', '接受今天的試煉吧。殺死鋼鐵觀察者，再回來見我們，然後你就能成為倍受尊敬的霜脈戰士了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30401 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30401, 13, 0, 'zhTW', '歲月的侵蝕令他變得行動遲緩……你只要保持身手敏捷，他是不可能戰勝你的。雷心國王在默默地支援你——別讓他失望。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30403 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30403, 0, 0, 'zhTW', '當你跳上尼爾蓋德時，構造體上腐爛的血肉突然活了起來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30403 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30403, 1, 0, 'zhTW', '%s碎裂開來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30404 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30404, 0, 0, 'zhTW', '誰敢？！就算要犧牲尼爾蓋德，我也會抓到你，將你的肉一片片地割下來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30404 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30404, 1, 0, 'zhTW', '我會東山再起的，到時候我會報仇的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30404 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30404, 2, 0, 'zhTW', '我會東山再起的，到時候我會報仇的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 0, 0, 'zhTW', '天啊……這不是……穆拉丁嗎？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 1, 0, 'zhTW', '哥們兒，我怎麼會搞錯啊——肯定是你。你不認識自己的弟弟了嗎？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 2, 0, 'zhTW', '我真不敢相信自己的眼睛！你不是死了嗎？大家都這麼認為……到底發生了什麼事，穆拉丁。你怎麼會在這裡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 3, 0, 'zhTW', '天哪！如果麥格尼見到你，不知道他會高興成什麼樣子呢！他已經很久沒有聽到過好訊息了，這次一定能令他欣喜若狂！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 4, 0, 'zhTW', '眼下麥格尼就在北裂境，他是來尋找你的下落的。暮冬城的先知傳來訊息，說你還活著。於是麥格尼立即離開鐵爐堡，來這裡找你了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 5, 0, 'zhTW', '說起來……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 6, 0, 'zhTW', '那已經是陳年舊事了，穆拉丁。後悔是沒有用的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 7, 0, 'zhTW', '穆拉丁，保重。我很想與你同行，但是我正在發掘一個足以震驚世界的秘密。我不能半途而廢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30405 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30405, 8, 0, 'zhTW', '再見。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 0, 0, 'zhTW', '我們快離開這兒吧！趕快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 1, 0, 'zhTW', '快一點，勇士！我們必須趕回銀色前線基地，把進攻的事告訴他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 1, 1, 'zhTW', '他們有幾百人！甚至可能有幾千人！他們隨時可能發動進攻！我敢肯定！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 1, 2, 'zhTW', '如果你不來的話，我就死定了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 1, 3, 'zhTW', '他們正在策劃一場大襲擊！我們必須去警告大領主弗丁！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 2, 0, 'zhTW', '謝謝你，勇士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30407 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30407, 2, 1, 'zhTW', '謝謝你，朋友。但是我們還沒有徹底擺脫危險！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 0, 0, 'zhTW', '什麼？你是在和我說話嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 1, 0, 'zhTW', '我的弟弟？呃……我倒是有幾個兄弟……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 2, 0, 'zhTW', '穆拉丁抓著腦袋，使勁地晃了晃，一幕幕的往事漸漸湧入他的腦海。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 3, 0, 'zhTW', '……布萊恩？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 4, 0, 'zhTW', '我……我不知道，布萊恩。我在這裡待了很長時間……但是在此之前的記憶，只剩下支離破碎的噩夢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 5, 0, 'zhTW', '見到你我還是很高興的。我真是激動得不知道說什麼好了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 6, 0, 'zhTW', '麥格尼！很抱歉啊，我的記憶恢復得很慢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 7, 0, 'zhTW', '霜脈矮人對我很好。他們非常強壯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 8, 0, 'zhTW', '我不太記得了，麥格尼。我經常做噩夢，夢見一個人類……很高……淺色的頭髮……死黑色的盔甲。他的名字……話在嘴邊卻說不出口……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 9, 0, 'zhTW', '……阿爾薩斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 10, 0, 'zhTW', '嗯，我知道。我親眼目睹了他的轉變……我看著他拋棄正義，而我卻沒有伸出援手……等我意識到事情的嚴重性時，一切都晚了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 11, 0, 'zhTW', '是的……後悔是沒用的。但是我能糾正這一切……我必須這麼做。我要找到那個孩子，讓他為自己的所作所為負責。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 12, 0, 'zhTW', '我是認真的，麥格尼。我會小心處理的，別擔心。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30408 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30408, 13, 0, 'zhTW', '去吧，布萊恩。下次見面時，你再告訴我這個驚天動地的故事吧。再見，兄弟們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30409 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30409, 0, 0, 'zhTW', '你是衝著博士的計劃來的！你只有死路一條！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30409 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30409, 1, 0, 'zhTW', '博士委託我執行關於尼爾蓋德的計劃，那可是完全由瓦古制成的血肉巨人！它將成為最強大的血肉巨人，只要有一整支這樣的巨人組成的部隊，你們就全都玩完了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 0, 0, 'zhTW', '拉格努斯，我一直覺得你是個人材，不過我的耐心正在逐漸消失。我知道穆拉丁在這裡，但是你到底能不能帶我找到他？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 1, 0, 'zhTW', '我的兄弟！真的是你！我幾乎不敢相信自己的眼睛……你還活著！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 2, 0, 'zhTW', '能再見到你真是太好了，穆拉丁。我聽說你現在登上了王座，真的嗎？銅鬚家族的人註定是要成為大人物的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 3, 0, 'zhTW', '似乎的確如此！你看上去還是那麼強壯。你還記得發生了什麼事嗎，穆拉丁？在你離開的日子裡，命運愈發糟糕了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 4, 0, 'zhTW', '麥格尼點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 5, 0, 'zhTW', '他不再是你記憶中的男孩了，穆拉丁。他已經完全變了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 6, 0, 'zhTW', '你是認真的嗎，穆拉丁？這些年來，我一直以為你已經死了，現在好不容易才找到你，我不想再失去你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30411 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30411, 7, 0, 'zhTW', '那就這樣吧。我要回去了。祝你平安。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 0, 0, 'zhTW', '你們這些下等生物根本無法對我構成任何威脅！使出全力戰鬥吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 1, 0, 'zhTW', '你唯一可以做到的事情，就是體面地戰死！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 1, 1, 'zhTW', '這就是你的全部實力了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 2, 0, 'zhTW', '我還能……繼續……戰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 3, 0, 'zhTW', '我要用你們的骨頭來剔牙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 4, 0, 'zhTW', '父親大人對你的評價一點都沒錯，薩塔里奧。你就是個廢物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 5, 0, 'zhTW', '你們好像有兩下子啊，那麼就讓你們看看我的招數吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30449, 5, 1, 'zhTW', '與你們不同的是，我有無數的絕技！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30449 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
