INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30836, 0, 0, 'zhTW', '彙報情況吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30836 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30836, 1, 0, 'zhTW', '描述一下這名維庫人吧。他長什麼模樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30836 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30836, 2, 0, 'zhTW', '我沒興趣聽你找藉口。他們總該告訴過你他的名字吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30836 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30836, 3, 0, 'zhTW', '伊斯卡德爾？！蠢貨！你沒聽過他的名頭嗎？他是有史以來最偉大的維庫人戰士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30836 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30836, 4, 0, 'zhTW', '立即返回尤頓海姆，告訴他們，在我抵達之前不準讓他甦醒過來。我要親眼看看這個維庫人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30838 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30838, 1, 1, 'zhTW', '你想要挑戰死亡本身嗎？來吧，“王”。面對莫格萊尼的怒火！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30838 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30838, 2, 1, 'zhTW', '我會在迴音谷等你。朋友，堅持住。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30839 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30839, 1, 1, 'zhTW', '連這樣的場面都應付不了，你還真夠弱的。好吧……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30839 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30839, 2, 2, 'zhTW', '在我離開之前，你還需要什麼幫助嗎？好吧，我不認為……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30840 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30840, 1, 1, 'zhTW', '來，和我的小夥伴打聲招呼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30840 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30840, 2, 2, 'zhTW', '現身吧，熔屍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30840 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30840, 3, 3, 'zhTW', '這裡沒我們的事了。我走了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30884 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30884, 1, 1, 'zhTW', '是伊斯卡德爾。！快，使用白骨女巫的護符！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30891 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30891, 0, 0, 'zhTW', '十字軍的神聖軍旗已經插好了。\\n保護旗幟，擊退攻擊者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30897 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30897, 0, 0, 'zhTW', '已超出威脅指數標準。天界文件中斷。提高安全級別。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30897 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30897, 1, 0, 'zhTW', '另有後臺資訊與你的問詢關聯：在艾塞爾和瓦尼爾的全面戰爭之後——');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30897 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30897, 2, 0, 'zhTW', '不詳。資料顯示，全面戰爭是由首席管理官洛肯發起的，他在此之後中和了所有殘餘的艾塞爾與瓦尼爾，結束了衝突。接著，他停止了包括土靈、巨人和維庫人在內的數個源種生物的演化程序，並將他們全部封存在指定的封存倉內。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30897 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30897, 3, 0, 'zhTW', '本質上的確如此。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30898 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30898, 0, 0, 'zhTW', '安全系統發現不明入侵。歷史文件的分析工作優先順序轉為低。對策程式立即啟動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30898 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30898, 1, 0, 'zhTW', '正在檢索……造物主曾經親自回來清除噬主共體生物所造成的感染。根據當時的評估，上古之神滋生所造成的危害非常嚴重。強行分離被感染部分將導致宿主損毀——');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30898 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30898, 2, 0, 'zhTW', '正確。造物主決定中和寄生體的威脅，並將其封鎖在宿主內部。之後，包括意志熔爐在內的各系統受命開始創造新的土靈。植入了新的安全機制，並任命了守護者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30898 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30898, 3, 0, 'zhTW', '名稱：艾塞爾與瓦尼爾。如果用通用語命名，則是風暴巨人與岩石巨人，最高領袖為哨兵洛肯。守護巨龍受命監管艾澤拉斯世界的進化過程。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 0, 0, 'zhTW', '警告：生命體形態模式無法辨識。文件處理程式中斷。繼續幹涉程式將導致安全對策啟動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 1, 0, 'zhTW', '威脅指數過高。虛空分析程式關閉。啟動清理協議。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 2, 0, 'zhTW', '警告：安全系統自動修復裝置已被關閉。立刻消除化全部儲存器內容並……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 3, 0, 'zhTW', '系統已上線。生命形態模式已確認。您好，銅鬚先生。是否需要問詢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 4, 0, 'zhTW', '正在檢索史前資料……文件定位完畢。創世之初，土靈的使命是——');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 5, 0, 'zhTW', '正在檢索……在其發展週期的初始階段，艾澤拉斯世界遭受到了寄生性噬主共體生物的感染。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 6, 0, 'zhTW', '名稱：上古之神。上古之神感染了包括土靈在內的整個毫無防備的系統，意圖將所有事物向他們自身同化。這種擾動母體結構的行為與現象被定義為“血肉詛咒”。擾動的效果與日俱增。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30899 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30899, 7, 0, 'zhTW', '收到，布萊恩布隆贊。程序終止。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30920 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30920, 0, 0, 'zhTW', '小惡鬼想要什麼啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30920 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30920, 0, 1, 'zhTW', '禮物？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30920 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30920, 0, 2, 'zhTW', '那樣可不太好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30920 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30920, 0, 3, 'zhTW', '幹嘛給我炸彈？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30920 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30920, 0, 4, 'zhTW', '是要我送到什麼地方去嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30920 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30920, 0, 5, 'zhTW', '恐怕不太安全吧，小惡鬼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30922 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30922, 0, 0, 'zhTW', '是誰扔的石頭？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30924 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30924, 0, 0, 'zhTW', '來戰，$n！殺死伊斯卡德爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30945 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30945, 0, 0, 'zhTW', '伊斯卡德爾，你總算露面了。怎麼？你已經開始戰鬥了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30945 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30945, 1, 0, 'zhTW', '天哪！這怎麼可能？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30945 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30945, 2, 0, 'zhTW', '我不明白怎麼會這樣，但是你一定是伊斯卡德爾。等等……怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30945 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30945, 3, 0, 'zhTW', '滾遠點！別碰我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30945 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30945, 4, 0, 'zhTW', '哈哈哈哈！好啦。回到我待的洞穴去吧。我們還有很多要事要商量呢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30955 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30955, 0, 0, 'zhTW', '怎麼回事？你被我控制了！我是來複仇的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30956 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30956, 0, 0, 'zhTW', '我就知道你會來的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30956 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30956, 1, 0, 'zhTW', '剛才的戰鬥給我留下了深刻的印象。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30956 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30956, 2, 0, 'zhTW', '歡迎來到亡者的世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30956 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30956, 3, 0, 'zhTW', '打得不錯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30992 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30992, 1, 0, 'zhTW', '嘖嘖。你犯下了如此可怕的錯誤，是不是感覺很自豪啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30992 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30992, 2, 0, 'zhTW', '我本來就打算銷燬他，看來可以提前完成了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30992 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30992, 3, 0, 'zhTW', '哎呀，這些質量上等，可以重複利用的零件都要報廢啦……真是可惜……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30993 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30993, 1, 0, 'zhTW', '補丁要向薩布諾克博士復仇！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30993 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30993, 2, 0, 'zhTW', '補丁再也不想被隨意地切開或是縫合了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30994 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30994, 0, 0, 'zhTW', '藥物根本不起作用——整座城市在痛苦中呻吟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30994 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30994, 0, 1, 'zhTW', '關於變質糧食的傳聞在士兵之間流傳，恐慌正在蔓延。市民們互相指責鄰居就是投毒者。城市已經陷入騷亂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30994 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30994, 0, 2, 'zhTW', '所有人都病倒了——這是天災！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30994 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30994, 1, 0, 'zhTW', '我發誓，我的不適感源於焦慮……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30994 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30994, 1, 1, 'zhTW', '面對如此大規模的危機，我要如何應對？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 30994 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (30994, 1, 2, 'zhTW', '我完全不知所措。面對這樣的災難，我又能做些什麼呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31003 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31003, 0, 0, 'zhTW', '天啊！該死的怪物！看看它們對我們的人民做了些什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31003 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31003, 1, 0, 'zhTW', '燒死它們。燒燬這一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31003 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31003, 2, 0, 'zhTW', '來吧。讓它們為此付出代價！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31003 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31003, 3, 0, 'zhTW', '成功啦！我們從天災軍團手中奪得了十字軍之巔！立刻向古斯塔夫神父彙報這一好訊息！我們要立即展開建設工事！快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31013 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31013, 0, 0, 'zhTW', '不留活口！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31013 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31013, 1, 0, 'zhTW', '面對我的恐怖造物，顫抖吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31013 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31013, 2, 0, 'zhTW', '僕從們，把他們都消滅！');
