INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31033, 0, 0, 'zhTW', '瞧，前線基地的英雄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31033 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31033, 0, 1, 'zhTW', '%s向你歡呼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31033 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31033, 0, 2, 'zhTW', '沒有你的幫助，我們很難取得勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31033 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31033, 0, 3, 'zhTW', '你是我們的榮耀，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31033 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31033, 0, 4, 'zhTW', '謝謝，$n。衷心地感謝你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31033 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31033, 0, 5, 'zhTW', '隨時為你效勞，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31036 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31036, 0, 0, 'zhTW', '部落的第一座塔樓已經被摧毀了！只要我們掃平全部三座塔樓，敵人就不得不撤退了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31036 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31036, 1, 0, 'zhTW', '第二座塔樓已經被摧毀了！只要我們解決最後一座塔樓，敵人就不得不撤退了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31036 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31036, 2, 0, 'zhTW', '部落的塔樓全部被摧毀了！他們已經落敗。解決殘餘的敵人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31036 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31036, 3, 0, 'zhTW', '別對那些禽獸心軟，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31057 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31057, 0, 0, 'zhTW', '你好。弗拉斯·希亞比現在不在。明天再來光顧希亞比的菸草店吧！嗶嗶！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31091 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31091, 0, 0, 'zhTW', '聯盟的第一座塔樓已經被摧毀了！只要我們掃平全部三座塔樓，敵人就不得不撤退了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31091 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31091, 1, 0, 'zhTW', '為了部落！第二座塔樓已經被摧毀了！只要我們解決最後一座塔樓，敵人就不得不撤退了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31091 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31091, 2, 0, 'zhTW', '聯盟的塔樓全部被摧毀了！他們已經落敗。解決殘餘的敵人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31091 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31091, 3, 0, 'zhTW', '別對那些禽獸心軟，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31108 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31108, 0, 0, 'zhTW', '你要阻止部落收集灰燼，$n。我們不能讓他們在以後的戰鬥中佔據優勢！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31109 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31109, 0, 0, 'zhTW', '毀掉那些邪惡的戰爭機器，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31125 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31125, 0, 0, 'zhTW', '%s變得狂暴不已！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31125 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31125, 1, 0, 'zhTW', '%s向$n衝來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31126 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31126, 0, 0, 'zhTW', '啊，是阿爾薩斯王子。您來的正是時候。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31126 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31126, 1, 0, 'zhTW', '阿爾薩斯，你不需要弄明白這是什麼。你唯一要做的，就是等死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 0, 0, 'zhTW', '讓我們來做個了斷吧，肯瑞託的勇士們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 1, 0, 'zhTW', '我要終結肯瑞託！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 1, 1, 'zhTW', '達拉然即將淪陷！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 1, 2, 'zhTW', '你對織法者的冒犯到此為止了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 2, 0, 'zhTW', '或許……我們……低估了……你們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 3, 0, 'zhTW', '真是一群英勇的衛兵，但這座城市必須被夷平。我必須親自執行瑪裡苟斯大人的指令！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 4, 0, 'zhTW', '我打斷了什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 5, 0, 'zhTW', '顫抖著去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 6, 0, 'zhTW', '這個世界已經忘記什麼時候魔法？讓我來提醒一下吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31134 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31134, 6, 1, 'zhTW', '有誰能在我的力量面前屹立不倒？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 0, 0, 'zhTW', '瓦哈拉斯是你抉擇生死之地，$n。在任何情況下，你都不能擅自退出比武場。如果你選擇逃跑，就意味著你可恥地輸掉了比賽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 1, 1, 'zhTW', '$n和$g他:她的戰友被選中，將在神聖的瓦哈拉斯進行光榮的戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 2 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 2, 2, 'zhTW', '瓦哈拉斯的戰鬥只有一個結果：必須有一方倒下。$n，如果你想要證明自己的力量，就必須將對手的屍體踩在腳下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 3 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 3, 3, 'zhTW', '瓦哈拉斯的英雄之魂現身了，準備再次投入戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 4 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 4, 4, 'zhTW', '$n戰勝了瓦哈拉斯的英雄之魂。雖然這僅僅是一場熱身賽，但是也算是精彩的對決吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 5 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 5, 5, 'zhTW', '做好準備吧。西塔利克斯將從東南方進入瓦哈拉斯。記住，不要離開比武場，否則你就會輸掉比賽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 6 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 6, 6, 'zhTW', '$n接受了黑暗主宰西塔利克斯的挑戰。西塔利克斯絕不會手下留情的，願諸神保佑$g他:她吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 7 AND `ID` = 7 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 7, 7, 'zhTW', '黑暗主宰西塔利克斯從東南方衝進了瓦哈拉斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 8 AND `ID` = 8 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 8, 8, 'zhTW', '$n和$g他:她的戰友擊敗了黑暗主宰西塔利克斯。下一場挑戰馬上開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 9 AND `ID` = 9 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 9, 9, 'zhTW', '齊格莉德·冰魂已經重返尤頓海姆，她將與$n展開對決。他們上次交手時，$n戰勝了她。這場比賽的勝負如何呢？讓我們拭目以待吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 10 AND `ID` = 10 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 10, 10, 'zhTW', '齊格莉德·冰魂在瓦哈拉斯上空盤旋，她是來複仇的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 11 AND `ID` = 11 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 11, 11, 'zhTW', '$n再次擊敗了齊格莉德·冰魂。好吧，雖然$g他:她是在隊友的幫助下獲勝的，但是勝利就是勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 12 AND `ID` = 12 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 12, 12, 'zhTW', '卡納基來啦！記住，在任何情況下，都不能離開比武場，否則就取消你們的參賽資格。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 13 AND `ID` = 13 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 13, 13, 'zhTW', '卡納基來自曲徑幽深的地下大廳。勇敢又愚蠢的$n已經接受了這個挑戰。$G他:她將率領自己的隊伍面對這個怪物。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 14 AND `ID` = 14 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 14, 14, 'zhTW', '南方飄來的氣味預示了卡納基的到來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 15 AND `ID` = 15 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 15, 15, 'zhTW', '可怕的卡納基已經不復存在啦。$n真的配得上瓦哈拉斯的戰鬥嗎？讓我們拭目以待吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 16 AND `ID` = 16 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 16, 16, 'zhTW', '往東南方看，領主很快就會出現在殘忍的亞納爾附近的平臺上。等他自己下來。不要離開瓦哈拉斯的競技場。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 17 AND `ID` = 17 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 17, 17, 'zhTW', '數個世紀後，巴納霍格領主首次重返瓦哈拉斯。他要證明，只有維庫人才有資格在這片聖地上戰鬥。$n能證明他錯了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 18 AND `ID` = 18 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 18, 18, 'zhTW', '巴納霍格領主出現在東南方的高臺上！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 19 AND `ID` = 19 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 19, 19, 'zhTW', '巴納霍格領主敗在了$n和$g他:她的戰友手下。挑戰者即將迎來最後一場對決。他們的對手是誰呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 20 AND `ID` = 20 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 20, 20, 'zhTW', '現在逃跑已經太遲啦。不要離開比武場。慷慨地赴死吧，$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 21 AND `ID` = 21 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 21, 21, 'zhTW', '挑戰者的對手來自冰冠堡壘，這位被巫妖王選中的勇士是來終結$n及其戰友的生命的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 22 AND `ID` = 22 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 22, 22, 'zhTW', '尤頓海姆的戰士們，他就是血精靈王子薩杜瓦爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 23 AND `ID` = 23 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 23, 23, 'zhTW', '薩杜瓦爾王子在毫無徵兆的情況下，如幻影般出現在瓦哈拉斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 24 AND `ID` = 24 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 24, 24, 'zhTW', '難以置信啊……$n殺死了薩杜瓦爾王子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 25 AND `ID` = 25 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 25, 25, 'zhTW', '挑戰者擊敗了王子，這證明$g他:她及其戰友完全有資格在維庫人的聖地上戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 26 AND `ID` = 26 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 26, 26, 'zhTW', '向$n，瓦哈拉斯的勇士歡呼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31135 AND `GroupID` = 27 AND `ID` = 27 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31135, 27, 27, 'zhTW', '你們這是自尋死路！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31161 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31161, 0, 0, 'zhTW', '我就知道你會來的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31161 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31161, 1, 0, 'zhTW', '剛才的戰鬥給我留下了深刻的印象。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31161 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31161, 2, 0, 'zhTW', '歡迎來到亡者的世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31161 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
