INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31222, 0, 0, 'zhTW', '戰鬥結束後，我就要把你們的徽記掛在艾卓-尼魯布的城牆上！');
