INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31235, 1, 0, 'zhTW', '要不是你，我早就淪為巫妖王的奴僕，成為天災軍團中的一員了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31235 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31235, 2, 0, 'zhTW', '稍後我會正式地感謝你，但是現在我們還有一場仗要打！');
