INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31237, 0, 0, 'zhTW', '你不該那麼做的！他不喜歡那樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31238 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31238, 0, 0, 'zhTW', '來吧，雲翼。我們來飛一圈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31238 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31238, 0, 1, 'zhTW', '你也像我一樣安靜不下來吧，雲翼？那我們去飛一會兒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31238 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31238, 0, 2, 'zhTW', '好無聊啊，雲翼。走吧！');
