INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31277, 0, 0, 'zhTW', '夠了！你們這些爬蟲也配在這片聖地上戰鬥！你們的戰鬥有何榮譽可言！別想戰勝我！');
