INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31279, 0, 0, 'zhTW', '謝謝你救了我。回去之後，我一定會向大家宣揚你的勇敢。請你竭盡所能，與天災軍團抗衡吧。我們會幫助你的。');
