INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31279, 1, 0, 'zhTW', '$n，在我最需要幫助的時候，是聖光的賜福讓你找到了我。');
