INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31283, 2, 0, 'zhTW', '巫妖王賜予我的力量遠遠超過了你們的想象。看招！');
