INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31283, 6, 0, 'zhTW', '你總算來了，達里安！我正在猜想你什麼時候會露面呢。');
