INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31290, 0, 0, 'zhTW', '奧爾巴茲·血毒，就憑你也敢自稱是巫妖王的左膀右臂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31290 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31290, 1, 0, 'zhTW', '你迫不及待地想要除掉我，然後獨攬大權是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31290 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31290, 2, 0, 'zhTW', '奧爾巴茲，你根本就不具備領袖的天賦，你連一隊沒腦子的骷髏都指揮不了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31290 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31290, 3, 0, 'zhTW', '終於除掉了禍根。');
