INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31301, 2, 0, 'zhTW', '停止無力的抵抗吧，這僅僅能延緩你的毀滅罷了。');
