INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31301, 3, 0, 'zhTW', '趁你還活著，只管宣揚這些陳詞濫調吧。你終究會落到我的手裡，摩比烏斯將宣告你的死訊！');
