INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31301, 4, 0, 'zhTW', '摩比烏斯，讓他們知道，敢於違抗國王的旨意是什麼下場！');
