INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 0, 2, 'zhTW', '不！你錯了！我腦海中的聲音非常美妙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31397 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 0, 3, 'zhTW', '我的生命屬於你！');
