INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 0, 4, 'zhTW', '我來了，主人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31397 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 0, 5, 'zhTW', '我是不會離開的！');
