INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 0, 7, 'zhTW', '我要到地底深處去，到主人身邊去。我一定要跳下去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31397 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 1, 0, 'zhTW', '求求你，住手。');
