INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 1, 1, 'zhTW', '再打我一下試試，你會後悔的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31397 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 1, 2, 'zhTW', '哎喲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31397 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 1, 3, 'zhTW', '對不起。我會努力幹活的。');
