INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31397, 1, 4, 'zhTW', '主人很快就會召我回去的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31419 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31419, 0, 0, 'zhTW', '普勞德摩爾女士，酋長說的是實話。這是瓦里瑪薩斯和大藥劑師普特雷斯安排的詭計。並非部落的本意。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31419 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31419, 1, 0, 'zhTW', '自從聯盟和部落進軍天譴之門以來，幽暗城就發生了暴亂。瓦里瑪薩斯和他的惡魔同黨叛變了，殘忍地殺害了數百名無辜的平民。我是好不容易才逃出來的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31426 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31426, 0, 0, 'zhTW', '衛兵！');
