INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31428, 0, 0, 'zhTW', '你會為自己的行徑付出代價的！為銀白十字軍而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31437 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31437, 0, 0, 'zhTW', '我們失去了幽暗城。只有惡魔和大藥劑師普特雷斯在那兒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31437 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31437, 0, 1, 'zhTW', '他們殺了成百人！我們好不容易才從這場劫難中逃出來！救救我們！');
