INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31437, 0, 2, 'zhTW', '黑暗女王竭盡所能地救助我們逃離……我希望她還活著。請幫幫我們！');
