INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31530, 5, 0, 'zhTW', '我不會束手就擒！我做了這麼多的努力！這些年來……我……我需要更多的能量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31530 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31530, 6, 0, 'zhTW', '力量在我體內流淌！我能看見……一切！');
