INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31530, 7, 0, 'zhTW', '品嚐更多的痛苦吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31565 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 0, 0, 'zhTW', '歡迎來到我的黑暗王國！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31565 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 1, 0, 'zhTW', '你喜歡我的那些恐怖的造物嗎？很厲害，不是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31565 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 2, 0, 'zhTW', '真是天真，你們想奪回這座城市？那就來吧，英雄們！你們的靈魂會讓我更強大！而你們只能奪回一片廢墟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31565 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 3, 0, 'zhTW', '你真聰明……');
