INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 4, 0, 'zhTW', '我的兄弟們都餓了，你們的靈魂一定很合他們的胃口！');
