INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 6, 0, 'zhTW', '接受你的未來吧——命運什麼都沒給你留下……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31565 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 7, 0, 'zhTW', '長久以來……我們不知疲倦地謀劃，不應該落得這樣的結局……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31565 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 8, 0, 'zhTW', '再給我一點時間……主人就在附近……');
