INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 9, 0, 'zhTW', '強大的力量！凡人們，你們感受不到嗎？別愚蠢啦，加入我們吧！');
