INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31565, 12, 0, 'zhTW', '我乞求您的寬恕，主人！我一定會親手解決入侵者的！');
