INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31649, 0, 0, 'zhTW', '夥計們呀！幽暗城的戰鬥已經打響啦！索爾正在裡面奮戰，你可以進去找他並肩作戰，你也可以在這兒等他。他隨時都會回來。');
