DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31814 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31814, 2, 0, 'zhTW', '土靈已經將你視為忠實的盟友。');
