INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31814, 3, 0, 'zhTW', '在戰鬥以及尋找鑰石的過程中，你和你的同伴都證明了自己。');
