INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31814, 4, 0, 'zhTW', '你們的動機是純潔的。鑰石的碎片將得以重新拼合。前往奧杜爾尋找你想要的答案吧，布萊恩·銅鬚。');
