INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31882, 0, 0, 'zhTW', '我會為你殺死一名敵人的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31882 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31882, 0, 1, 'zhTW', '我下去啦。祝你們好運！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31882 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31882, 0, 2, 'zhTW', '謝謝你掩護我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31882 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31882, 0, 3, 'zhTW', '順利抵達目的地——這裡就是本次偵察任務的目標地點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 31882 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (31882, 0, 4, 'zhTW', '滲透行動開始。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32149 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32149, 0, 0, 'zhTW', '這真可怕……我夢見我正在和自己的朋友作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32149 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32149, 0, 1, 'zhTW', '我累壞了，讓我先休息一下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32149 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32149, 0, 2, 'zhTW', '我聽不到那些尖叫聲了。一切都結束了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32149 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32149, 0, 3, 'zhTW', '終於……現在我能夠休息了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32149 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32149, 0, 4, 'zhTW', '我的噩夢終於結束了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32162 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32162, 0, 0, 'zhTW', '你以為自己能從我手裡奪得這座壁壘的控制權嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32162 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32162, 1, 0, 'zhTW', '我覺得你做不到。傲慢的傢伙，你戰敗之後，我會將你的屍體用尖刺釘起來，為其他“英雄”做個示範！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32169 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32169, 0, 0, 'zhTW', '勇士們，冬握湖需要增援，我已經開啟了一個直接到達冬握湖的傳送門！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32170 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32170, 0, 0, 'zhTW', '冬握湖的戰鬥將於5分鐘後開始，請做好準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 0, 0, 'zhTW', '不速之客！你們以為自己能偷偷地溜進我的王國嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 1, 0, 'zhTW', '我必須承認……我早已預知你們的到來。希望你們能找到安息地……適合你們的安息地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 2, 0, 'zhTW', '我們上次交手時，你佔盡了聖地的優勢。但如今，你會發現我們的境遇已經發生了……逆轉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 3, 0, 'zhTW', '別虛張聲勢了，你畢竟是一名聖騎士。你對於救贖的痴迷已經到了不可救藥的地步。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 4, 0, 'zhTW', '你想要“挽救”我這個任性的孩子，不願意放棄人道救贖的唯一機會，因此你只會死得更快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 5, 0, 'zhTW', '啊啊啊！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32184 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32184, 6, 0, 'zhTW', '你……會為此付出代價！殺光他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32222 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32222, 0, 0, 'zhTW', '我會為你殺死一名敵人的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32222 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32222, 0, 1, 'zhTW', '我下去啦。祝你們好運！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32222 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32222, 0, 2, 'zhTW', '謝謝你掩護我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32222 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32222, 0, 3, 'zhTW', '順利抵達目的地——這裡就是本次偵察任務的目標地點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32222 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32222, 0, 4, 'zhTW', '滲透行動開始。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 0, 0, 'zhTW', '我突然覺得很好笑。呃？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 0, 1, 'zhTW', '好吧，誰朝我扔了寶珠？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 0, 2, 'zhTW', '什麼？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 0, 3, 'zhTW', '不！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 1, 0, 'zhTW', '是誤會啊。我是被陷害的。別把我扔下去！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 1, 1, 'zhTW', '你搞錯了。我是黑暗壓制者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 2, 0, 'zhTW', '不！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32236 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32236, 2, 1, 'zhTW', '不！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 0, 0, 'zhTW', '時間到了。願聖光賜予我們力量吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 1, 0, 'zhTW', '保持冷靜，聽我的指揮。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 2, 0, 'zhTW', '它來了。做好準備。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 3, 0, 'zhTW', '不對勁……我感覺到黑暗的氣息。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 4, 0, 'zhTW', '巫妖王就在這裡。願聖光指引我們的劍刃吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 5, 0, 'zhTW', '你似乎過於自信了。你不如想想上次我們交手的結果。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 6, 0, 'zhTW', '或許吧。就算我的雙腳沒有踏在聖地上，也能用灰燼使者摧毀你的徽記。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 7, 0, 'zhTW', '徽記……那是你殘存的最後一絲人性。我要在你徹底喪失人性之前親自摧毀它。我相信……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32239 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32239, 8, 0, 'zhTW', '你心中只剩下往昔的陰影，無可救贖了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32241 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32241, 0, 0, 'zhTW', '提里奧倒下了！用你們的生命保護他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32273 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32273, 0, 0, 'zhTW', '你竟敢幹預我們的事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32273 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32273, 1, 0, 'zhTW', '我的生命……結束了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32273 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32273, 2, 0, 'zhTW', '任務完成！我在這裡的工作結束了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32277 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32277, 0, 0, 'zhTW', '你真讓我失望，瓦里瑪薩斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32277 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32277, 5, 0, 'zhTW', '你真讓我失望，瓦里瑪薩斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32295 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32295, 0, 0, 'zhTW', '我只是盡了我應盡的義務，兄長。你讓我別無選擇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32295 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32295, 1, 0, 'zhTW', '魔樞戰爭就此結束了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32295 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32295, 2, 0, 'zhTW', '這個決定令我的心靈深處痛楚不已，但這生靈塗炭與天地崩裂的局面也終於得到了休止。無論瑪裡苟斯犯過什麼大錯，我都會為他的死默哀。他曾是一位高貴的守護者。今天，世界上最強大的守護者之一，就這樣逝去了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32295 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32295, 3, 0, 'zhTW', '紅龍軍團將會擔負起修復世界創傷的責任與義務。回去吧，和你的同伴們一起回去，好好休息。明天，你們還要應對新的挑戰，你們必須時刻為此做好準備。生命……仍要繼續。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32310 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32310, 0, 0, 'zhTW', '我們打擾了你們的聚會，請不要介意。我還帶來了一些老朋友！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32310 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32310, 1, 0, 'zhTW', '看來提里奧的確對巫妖王造成了一定傷害。可惜我們不能殺死他……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32312 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32312, 0, 0, 'zhTW', '快穿過傳送門！他堅持不了多久的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32312 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32312, 1, 0, 'zhTW', '耐心點……我們會有機會幹掉巫妖王的。這次，提里奧欠我們一份情。對此我已經很滿足了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 0, 0, 'zhTW', '我知道他會幹什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 1, 0, 'zhTW', '他會對你說：索爾，領導你的人民。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 2, 0, 'zhTW', '讓我們回家吧，老朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 15, 0, 'zhTW', '那名聖騎士還活著？是真的嗎，大領主？他居然還活著？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 16, 0, 'zhTW', '我們一定要救他！如果我們救回了伯瓦爾·弗塔根，我們應該就可以平息聯盟與部落之間的爭鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 17, 0, 'zhTW', '我們的任務現在很明確：巫妖王必須為他的罪行付出代價以及我們要拯救伯瓦爾·弗塔根公爵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32315 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32315, 18, 0, 'zhTW', '庫卡隆，準備奧格瑞姆之錘最後的航行！勇士們，我們的飛艇會在堡壘上方找到停靠點。在那兒匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32346 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32346, 0, 0, 'zhTW', '千萬不要激怒部落，$N。酋長已經同意與我們坦誠相見。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32346 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32346, 1, 0, 'zhTW', '出發吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 0, 0, 'zhTW', '庫卡隆，退下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 1, 0, 'zhTW', '珍娜……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 2, 0, 'zhTW', '珍娜，天譴之門的事，是因為我們中間出了叛徒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 3, 0, 'zhTW', '部落已經失去了幽暗城。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 4, 0, 'zhTW', '我們正準備圍攻那座城市，將這群不可饒恕的罪魁禍首繩之以法。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 5, 0, 'zhTW', '如果鬧起內訌，巫妖王就會摧毀我們的北裂境的駐軍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 6, 0, 'zhTW', '我們會妥善處理的，珍娜。請你把這裡的情況轉告國王吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32363 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32363, 7, 0, 'zhTW', '庫卡隆，準備傳送到幽暗城。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32364 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32364, 0, 0, 'zhTW', '索爾，出了什麼事？國王正在備戰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32364 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32364, 1, 0, 'zhTW', '我會轉告國王的，索爾，但是……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32364 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32364, 2, 0, 'zhTW', '伯瓦爾和他情同手足。國王離開期間，是他維繫著聯盟的團結。在最艱難的日子裡，他是人民的支柱，他監護著安度因，將其視如己出。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32364 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32364, 3, 0, 'zhTW', '我擔心國王剋制不了他心中的怒火，索爾，我希望我能說服他吧，但是我們必須做好最壞的打算……比如戰爭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32364 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32364, 4, 0, 'zhTW', '再見，酋長。希望下次見面時，我們能夠成為盟友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 0, 0, 'zhTW', '%s唱起歌來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 1, 0, 'zhTW', '升降梯有問題，酋長，摔下去的人都難逃一死。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 2, 0, 'zhTW', '他們對我美麗的城市都做了些什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 3, 0, 'zhTW', '參與暴亂的叛徒們唯一的救贖就是痛苦地死去。我的復仇將迅速而絕不留情！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 4, 0, 'zhTW', '很好，酋長。皇家區在這邊，保持警惕，誰也不知道瓦里瑪薩斯和普特雷斯會有什麼圈套。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 5, 0, 'zhTW', '停！我感覺到了黑暗的魔法，是惡魔的法術……準備戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 6, 0, 'zhTW', '前面不遠就是皇家區了，酋長。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32365 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32365, 7, 0, 'zhTW', '酋長，這就是與部落為敵的下場。現在，該去對付普特雷斯那個惡棍了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 0, 0, 'zhTW', '聯盟的英雄們，國王在召喚！隨我攻入下水道的入口吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 1, 0, 'zhTW', '那個在天譴之門屠殺我們同胞的兇手，就龜縮在這座骯髒的城市裡！他必須受到正義的裁決！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 2, 0, 'zhTW', '很快我們就會進入這個被詛咒的地方，清除一切邪惡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 3, 0, 'zhTW', '救贖的時刻即將來臨，做好準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 4, 0, 'zhTW', '前進！攻打幽暗城！英雄們，接受國王的祝福吧！跟著我！為聯盟的榮耀而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 5, 0, 'zhTW', '前進兄弟姐妹們！命運在等待！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 6, 0, 'zhTW', '我們即將進入這邪惡的深淵！保持警惕！珍娜，賜予我們力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 7, 0, 'zhTW', '怎麼回事？穩住陣腳，別讓敵人得逞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 8, 0, 'zhTW', '士兵們集合，包圍大廳！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 9, 0, 'zhTW', '這些畸形的野獸擋不住聯盟，普特雷斯！等著瞧吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 10, 0, 'zhTW', '是部落。看這種情形，他們的軍隊應該，就在附近。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 11, 0, 'zhTW', '保持警惕，我們不知道前邊還有怎樣的恐怖。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 12, 0, 'zhTW', '前進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 13, 0, 'zhTW', '主廳在這個方向，我們走！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 14, 0, 'zhTW', '在那邊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 15, 0, 'zhTW', '你無處可逃了，怪物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 16, 0, 'zhTW', '正義得以伸張！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 17, 0, 'zhTW', '沒話可說了吧，普特雷斯？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 18, 0, 'zhTW', '看看四周，兄弟姐妹們。睜開眼睛！看看王國被踐踏成了什麼樣子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 19, 0, 'zhTW', '你們還要對這種野蠻的踐踏容忍多久！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 20, 0, 'zhTW', '我對部落瞭如指掌。無論是他們的城市，還是他們的思維……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 21, 0, 'zhTW', '我深知，獸人的內心是多麼邪惡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 22, 0, 'zhTW', '索爾！他來了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 23, 0, 'zhTW', '前進！結束這一切吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 24, 0, 'zhTW', '眾所周知，獸人有一句口號：LOK\'TAR OGAR！意思是“贏不了就去死”，真適合……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 25, 0, 'zhTW', '向王座前進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 26, 0, 'zhTW', '我離開得太久了。好幾位偉大的英雄為此付出了生命的代價。而你這種人渣，還有這個邪惡的女巫卻還在世上，為所欲為。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 27, 0, 'zhTW', '匡扶正義的時刻到了，我要摧毀這個滿是兇手和竊賊的王國！普特雷斯只是個開始。好戲剛剛開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 28, 0, 'zhTW', '這一刻我等了很久，索爾。每當我被扔進你那該死的獸人競技場……每當我殺死一隻和你一樣可憎的綠皮怪物……我都只有一個念頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 29, 0, 'zhTW', '如果沒有你和你那扭曲的部落，世界將多麼美好……酋長，你們要完蛋了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32401 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32401, 30, 0, 'zhTW', '進攻！為了暴風城！為了伯瓦爾！為了聯盟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32402 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32402, 0, 0, 'zhTW', '遵命，陛下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32402 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32402, 1, 0, 'zhTW', '究竟發生了什麼事？到處都是屍體……惡臭熏天……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32402 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32402, 2, 0, 'zhTW', '瓦里安，停下！我不會幫你這麼做的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32402 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32402, 3, 0, 'zhTW', '不，瓦里安！住手！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32402 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32402, 4, 0, 'zhTW', '事情不該變成這樣的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32414 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32414, 0, 0, 'zhTW', '您是來給士兵們訓話的嗎，長官？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32442 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32442, 0, 0, 'zhTW', '天災之鍋劇烈地沸騰起來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32443 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32443, 0, 0, 'zhTW', '復活吧，辛達苟薩！帶領霜巢巨龍投入戰鬥！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32445 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32445, 0, 0, 'zhTW', '有什麼東西從鍋裡冒了出來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32445 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32445, 1, 0, 'zhTW', '天災之鍋還在沸騰……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32445 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32445, 2, 0, 'zhTW', '天災之鍋中的東西被中和了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32451 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32451, 0, 0, 'zhTW', '她約我在這裡碰面的……難道我找錯地方了？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32451 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32451, 0, 1, 'zhTW', '好在巫妖王的魔爪還沒有伸到達拉然來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32451 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32451, 0, 2, 'zhTW', '偶爾離開聖殿，呼吸一下新鮮空氣也是很不錯的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32511 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32511, 0, 0, 'zhTW', '你沒有獲勝的希望！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 0, 0, 'zhTW', '我們勝利了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 1, 0, 'zhTW', '部落奪回了幽暗城！LOK\'TAR！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 2, 0, 'zhTW', '部落的英雄，酋長在召喚你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 3, 0, 'zhTW', '跟隨我到幽暗城門口集合！我們要奪回這座淪陷的城市——為了部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 4, 0, 'zhTW', '鮮血與雷霆，部落的勇士們！今天，我們要為死去的兄弟姐妹而戰！不要悲傷，因為他們都是心懷榮耀的勇者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 5, 0, 'zhTW', '雖然我們面臨著巨大的分歧，但只要我們齊心協力，就一定能消滅敵人！所有對部落的不公正都將被勢不可擋的力量碾碎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 6, 0, 'zhTW', '四方之靈，將你們的祝福賜予部落吧！今天，我們的事業是正義而高尚的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 7, 0, 'zhTW', '風之靈，將這曲戰歌送到小薩魯法爾耳畔吧，為所有陣亡的同胞們報仇雪恨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 8, 0, 'zhTW', '幽暗城的戰鬥即將打響！吹響戰爭的號角！部落的勇士們，接受酋長賦予你們的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32518 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32518, 9, 0, 'zhTW', '前進！');
