DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32857 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 0, 0, 'zhTW', '任你是天下最厲害的惡棍，還是最強大的英雄，都只不過是凡人之軀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32857 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 1, 0, 'zhTW', '可憐的傢伙！');
