INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 2, 0, 'zhTW', '站好了，凝視這耀眼的光芒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32857 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 3, 0, 'zhTW', '雷暴之雲在空中聚結，降下死亡之雨吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32857 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 4, 0, 'zhTW', '風暴的力量仍將長存。');
