INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 5, 0, 'zhTW', '你們盲目地衝進了瘋狂之喉！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32857 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 6, 0, 'zhTW', '鋼鐵議會的正事都被你們耽擱了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32857 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32857, 7, 0, 'zhTW', '%s過載了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 0, 0, 'zhTW', '入侵者！你們這些凡人竟敢壞了我的興致，看我怎麼……等等，你們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 0, 1, 'zhTW', '我記得你們……在群山中……但是你們……這是怎麼回事？我這是在——');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 1, 0, 'zhTW', '現在，為我們復仇的重任落到了你們的肩膀上，勇士們。前方的路途依然無比艱險，但我會鼎力相助。你們必須取得勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 2, 0, 'zhTW', '不要退縮！幹掉他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 3, 0, 'zhTW', '現在，為我們復仇的重任落到了你們的肩膀上，勇士們。前方的路途依然無比艱險，但我會鼎力相助。你們必須取得勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 4, 0, 'zhTW', '狂妄的小崽子們，竟敢在我的地盤上挑戰我？我要親自碾碎你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 5, 0, 'zhTW', '你能不能使出點真本事來？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 5, 1, 'zhTW', '可憐。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 6, 0, 'zhTW', '我的耐心已經到頭了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 7, 0, 'zhTW', '沒用的廢物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 8, 0, 'zhTW', '住手！我認輸了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 9, 0, 'zhTW', '我覺得自己像是從一場噩夢中驚醒過來，但是這裡的陰影仍然揮之不去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 10, 0, 'zhTW', '西芙……西芙在這裡嗎？不可能——她被我的兄弟殺死了。一場黑暗的噩夢……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 11, 0, 'zhTW', '我需要一些時間仔細思考……如果你們需要我的幫助，請儘管開口。這是我欠你們的人情。保重。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 12, 0, 'zhTW', '你！你這個惡魔，你不是我的愛人！滾開！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 13, 0, 'zhTW', '看吧，這隱藏在一切罪惡幕後的黑手，它覆滅了奧杜爾，將我的王國夷為廢墟，腐蝕了我的兄弟，殺害了我的妻子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32865 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32865, 14, 0, 'zhTW', '現在，為我們復仇的重任落到了你們的肩膀上，勇士們。前方的路途依然無比艱險，但我會鼎力相助。你們必須取得勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 0, 0, 'zhTW', '你們這些入侵者，休想輕易擊敗鋼鐵議會！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 1, 0, 'zhTW', '真是不堪一擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 1, 1, 'zhTW', '血肉……礙事的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 2, 0, 'zhTW', '你們想要探尋奧杜爾的秘密？那就拿去吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 3, 0, 'zhTW', '我的死只會加速你們的滅亡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 4, 0, 'zhTW', '這不可能……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32867 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32867, 5, 0, 'zhTW', '鋼鐵議會的正事都被你們耽擱了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 0, 0, 'zhTW', '遷移完成。開始對艾澤拉斯展開行星分析。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 1, 0, 'zhTW', '退後，凡人們。我不是來這裡跟你們打架的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 2, 0, 'zhTW', '如果我的分析結果表明確實存在系統級的汙染，對這顆行星進行結構重組無疑是最妥當的方案。不要插手。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 3, 0, 'zhTW', '你們的行動不合邏輯。這場戰鬥所有可能產生的結果都已被計算在內。無論結果如何，萬神殿都會收到觀察者發出的資訊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 4, 0, 'zhTW', '透過我的雙眼來觀察你們的世界吧：一個廣袤無垠的宇宙，即使是你們當中最睿智的人，也無法理解這一切。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 5, 0, 'zhTW', '群星將為我而戰！');
