INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 7, 0, 'zhTW', '見證宇宙的怒火吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 32871 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (32871, 8, 0, 'zhTW', '%s開始施放大爆炸！');
