INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33210, 0, 0, 'zhTW', '歡迎，勇士們。我們多次嘗試擊落她，但是都失敗了。你們能不能來幫幫忙，用這些魚叉炮把她打下來？');
