INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33220, 0, 0, 'zhTW', '這是真的嗎？經歷了多年的磨難，我竟然還能重獲自由？');
