INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 0, 0, 'zhTW', '你們擊敗了鋼鐵議會，開啟了檔案館！幹得好，夥計們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
