INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 2, 0, 'zhTW', '新的指令！開啟天文館的大門。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 3, 0, 'zhTW', '四位守護者？徽記？你這廢銅爛鐵，說話能不能別這麼拐彎抹角啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 4, 0, 'zhTW', '我叫你看看我的許可權，你這爛機器。瞧好了：諾甘農的鑰匙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 5, 0, 'zhTW', '看起來跟我們找到的其它泰坦檔案庫也沒什麼不同嘛，只不過舊了點……大了點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 6, 0, 'zhTW', '且慢。不對啊！這個一閃一閃的訊號燈……奧爾加隆是啥玩意？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 7, 0, 'zhTW', '首席管理官？我在哪裡聽過這名字來著？對了！洛肯就是艾澤拉斯的首席管理官啊。洛肯的死亡觸發了這東西？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 8, 0, 'zhTW', '然後呢？誰在監聽這個訊號？會發生什麼事情嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 9, 0, 'zhTW', '行星結構重組？把話說明白點，你這破爛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 10, 0, 'zhTW', '聽到了嗎，夥計們？我們的世界要完蛋了！你還等什麼啊，破爛機器？快傳送回覆程式碼阿爾法。一切正常！盡在掌握中！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 11, 0, 'zhTW', '啊，這個奧爾加隆分析出了什麼結果來？我們有多大的機率不被毀滅？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 12, 0, 'zhTW', '真要命啊，夥計們。看來我們有一場硬仗要打了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 13, 0, 'zhTW', '那我們怎樣才能搞到他們的徽記啊？走過去跟他們好聲好氣地借嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 14, 0, 'zhTW', '那你倒是告訴我們怎樣才能解除這種威脅啊？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33235 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33235, 15, 0, 'zhTW', '多少年來，我做夢都想在泰坦之城遊覽。沒想到今天居然要跟他們創造的東西作戰。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33241 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33241, 0, 0, 'zhTW', '如你所願，$n。');
