INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 0, 0, 'zhTW', '哦，天哪！我沒想到有人要來！工作間裡真是一片狼藉。真丟人啊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 1, 0, 'zhTW', '嘿，你們為什麼要這麼做啊？沒看到上面寫著“不要按這個按鈕”嗎？你們啟用了自毀系統，還怎麼完成測試呀？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 2, 0, 'zhTW', '我們時間不多了，朋友們！來幫忙測試一下我所發明的最新型、最強大的機體吧。在你們改變主意之前，請允許我提醒一下，你們把XT-002搞得一團糟，應該算是欠我個人情吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 3, 0, 'zhTW', '醫生！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 3, 1, 'zhTW', '我可以修好它……也許不行！呀，真是一團糟……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 4, 0, 'zhTW', '太棒了！測試結果非常好！外殼完整率百分之九十八點九！幾乎沒有劃傷！繼續。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 5, 0, 'zhTW', '看呀，VX-001反步兵突擊炮，你們也許應該找掩護。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 6, 0, 'zhTW', '真棒。我想他們應該是把這個叫做“完美擊殺”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 6, 1, 'zhTW', '我得記下來：火炮對血肉之軀非常有效。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 7, 0, 'zhTW', '非常感謝，朋友們！你們的幫助使我獲得了一些極其珍貴的資料！下面，我要讓你們——咦，我把它放哪去了？哦！這裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 8, 0, 'zhTW', '是不是很漂亮？我把它稱為華麗的空中指揮單位！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 9, 0, 'zhTW', '你敗了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 9 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 9, 1, 'zhTW', '你的表現應該比這更好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 10, 0, 'zhTW', '初步測試階段完成。真正的測試開始啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 11, 0, 'zhTW', '莊嚴地注目它吧！沐浴在它的榮耀中吧！將要出場的是……V-07-TR-0N！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 12, 0, 'zhTW', '手下留情？不行！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 12 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 12, 1, 'zhTW', '這一下你就別想再站起來啦，朋友。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 13, 0, 'zhTW', '看起來我的計算有一點小小的偏差。監獄中的惡魔侵蝕了我的思維，篡改了我的主要指令。所有系統都已恢復正常。完畢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33350 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33350, 14, 0, 'zhTW', '哦，天哪！我們好像已經超時了，朋友們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33382 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33382, 0, 0, 'zhTW', '預備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33382 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
