DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33417 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33417, 0, 0, 'zhTW', '現在，我要將聖光之力注入這塊水晶，讓它揭穿一切謊言與欺瞞的偽裝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33417 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33417, 1, 0, 'zhTW', '賜予我們洞悉真相的能力吧。如果兇手就在我們之中，請指引我們尋求正義的裁決。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33436 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33436, 0, 0, 'zhTW', '壞訊息，陛下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33436 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33436, 1, 0, 'zhTW', '獸人氏族在黑手的統一指揮下發起了攻擊。他們會一致作戰，直到暴風城淪陷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33436 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33436, 2, 0, 'zhTW', '古爾丹和他的術士們將在晚上抵達。在那之前，黑石氏族會集中火力攻打東面的城牆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33436 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33436, 3, 0, 'zhTW', '部落的領袖同意你的看法。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33437 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33437, 0, 0, 'zhTW', '我們要堅守陣地，等待援軍到達。只要勇敢的將士仍在保衛城牆和王庭，暴風城就不會淪陷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33441 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33441, 0, 0, 'zhTW', '你的執著真是令人欽佩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33441 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33441, 1, 0, 'zhTW', '我會毀滅你……就像我毀滅了他那樣！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33442 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
