INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33448, 2, 13, 'zhTW', '看來我低估了你的本事。幹得不錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33448 AND `GroupID` = 2 AND `ID` = 14 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33448, 2, 14, 'zhTW', '我輸了。打得好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33459 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33459, 0, 0, 'zhTW', '這根本不是榮耀之戰。我渴望揮舞戰斧，浴血沙場！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33459 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33459, 1, 0, 'zhTW', '他們都是我的敵人。在戰場上，你也會是我的敵人！你們的國王已經向我族宣戰了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33459 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33459, 2, 0, 'zhTW', '我卻不能像同胞們一樣浴血奮戰。我能做的，只是端著一根笨重的長槍，哄著座狼朝對手發起衝鋒，根本就不是真正的攻擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33459 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33459, 3, 0, 'zhTW', '這就不是獸人的作戰方式！酋長的命令與個人的榮耀令我左右為難。我不信仰聖光，但是你看起來像是個不錯的顧問，我想聽聽你的建議。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33459 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33459, 4, 0, 'zhTW', '這就不是獸人的作戰方式！酋長的命令與個人的榮耀令我左右為難。我不信仰聖光，但是你看起來像是個不錯的顧問，我想聽聽你的建議。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33462 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33462, 0, 0, 'zhTW', '我都不知道自己有沒有得打！他們的塊頭比我大多了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33462 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33462, 1, 0, 'zhTW', '我估算了一下勝出的機率，發現這種可能性低得要命！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33462 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33462, 2, 0, 'zhTW', '在讓長槍保持最精確的角度並讓盾牌處於任何時候都能提供最佳保護的位置的同時我還怎麼算得清該為機械陸行鳥載入多大的電荷！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33462 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33462, 3, 0, 'zhTW', '……而且有些坐騎可以把我踩扁！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33465 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33465, 0, 0, 'zhTW', '我在來這裡的路上毆打了一隻企鵝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33465 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33465, 1, 0, 'zhTW', '哈哈，騙你的。我只是想看看你臉上的表情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33465 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33465, 2, 0, 'zhTW', '哈哈，騙你的。我只是想看看你臉上的表情。');
