DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33467 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33467, 0, 0, 'zhTW', '沒完沒了的戰鬥。我不知道自己還能堅持多久。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33467 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33467, 1, 0, 'zhTW', '賽場上這種裝腔作勢的打鬥……根本毫無意義。有什麼用呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33467 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33467, 2, 0, 'zhTW', '而且我的髮型都被頭盔壓扁了。真是太滑稽了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33467 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33467, 3, 0, 'zhTW', '而且我的髮型都被頭盔壓扁了。真是太滑稽了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33477 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33477, 0, 0, 'zhTW', '我的心情一天比一天沉重，神官。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33477 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33477, 1, 0, 'zhTW', '我被派來這裡，以暴風城的名義作戰。但是我所做的一切都毫無意義。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33477 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33477, 2, 0, 'zhTW', '在賽場之外，天災軍團仍在肆意破壞著我們的家園。那裡才是真正的戰場。而我，應該前往真正的戰場。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33477 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33477, 3, 0, 'zhTW', '我怎麼能留在這裡，讓那些需要我來保護的人們慘死呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33480 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33480, 0, 0, 'zhTW', '姑娘，我要向你坦白一件事。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33480 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33480, 1, 0, 'zhTW', '我有一種……衝動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33480 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33480, 2, 0, 'zhTW', '我在聽你佈道時，心中湧起了一股強烈的情感，我快瘋掉了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33480 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33480, 3, 0, 'zhTW', '……我想喝一杯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33488 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33488, 0, 0, 'zhTW', '一團薩隆邪鐵蒸汽在附近聚集起來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33495 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33495, 0, 0, 'zhTW', '這可怕的光芒……難道是……？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 0, 0, 'zhTW', '有些東西，最好永遠都不去碰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 1, 1, 'zhTW', '死人是不會洩密的。');
