INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 1, 2, 'zhTW', '你們無路可逃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 2, 0, 'zhTW', '%s啟用了野性防禦者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 3, 0, 'zhTW', '你們在浪費我的時間！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 4, 0, 'zhTW', '%s開始施放恐嚇尖嘯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33515 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33515, 5, 0, 'zhTW', '%s啟用了野性防禦者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33522 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33522, 0, 0, 'zhTW', '$n向黑騎士發起挑戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33522 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33522, 1, 0, 'zhTW', '祝你好運，$n。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33523 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33523, 0, 0, 'zhTW', '完成了。大家都付出了自己該付出的。現在，我將永遠封印巨龍之魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33523 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33523, 1, 0, 'zhTW', '是的。必須這樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 1, 0, 'zhTW', '看！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 2, 0, 'zhTW', '你回來啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 3, 0, 'zhTW', '這場雪仗打得真精彩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 4, 0, 'zhTW', '看啊！那一定是強大的戰士科科！看到了吧？科科說什麼來著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 5, 0, 'zhTW', '嗯……那個科科已經非常老了。而狂心氏族的首領一定要更老一些。這很不錯。作為戰士和首領，科科有著美好的未來。科科很高興你能帶他參觀這裡。孤兒院的阿姨從不帶科科來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 6, 0, 'zhTW', '喔！科科終於找到赫米特·奈辛瓦里了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 7, 0, 'zhTW', '在你來到索拉查以後，就連狂心氏族也知道了你的事情。也許你能教科科兩招？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 8, 0, 'zhTW', '科科不知道閱讀有什麼用。科科不會閱讀，但如果赫米特·奈辛瓦里要科科這樣做，科科就會努力去做。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 9, 0, 'zhTW', '也許你最終會徹底放棄，但現在，你還需要堅持。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 10, 0, 'zhTW', '你相信總有一天，科科會帶領狂心氏族回家，就像熊人贏得最終的勝利奪回樹城那樣。科科想要自己的家，而不是遍佈紫人的城市，更不是大舌頭怪出沒的叢林。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 11, 0, 'zhTW', '科科還以為我們會看到紅龍女王。但那只是個長著可愛犄角的女精靈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 12, 0, 'zhTW', '但這到底該怎樣解釋？龍巨大而強猛。精靈女士卻弱不禁風。科科想要看到紅龍女王真正的樣貌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33532 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33532, 13, 0, 'zhTW', '哦！現在科科明白了。科科不想被強大的女王捏扁。也許等這裡不太擠的時候，科科還會回來。不管怎樣，很高興見到你，女王。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 1, 0, 'zhTW', '看！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 2, 0, 'zhTW', '我們也能跳舞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 3, 0, 'zhTW', '我們有了一個新朋友！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 4, 0, 'zhTW', '我們到了！如果這是世界之樹，那他們把整個世界放進這裡的時候，它不會被撐破嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 5, 0, 'zhTW', '看啊！那是我們嗎？我們覺得那是我們。只是好像有一點老？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 6, 0, 'zhTW', '我們也許真的得到了造物主的祝福！也許有一天，聖壇的魔法會把我們變成大神諭者？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 7, 0, 'zhTW', '喔！真正的造物主？我們完全沒有想到索烏塞遇到過一個真正的造物主！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 8, 0, 'zhTW', '呃，你好，造物主。見到你是我們的榮幸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 9, 0, 'zhTW', '你睡著了嗎，造物主？我們知道，為了收集我們留給你的所有好東西，一定費了很大力氣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 10, 0, 'zhTW', '我們為你帶來了一件禮物，造物主。也許你在醒來的時候會看到它。也許你會記得我們來看過你，是嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 11, 0, 'zhTW', '她就是紅龍女王？嗯……我們一直以為她應該更大一些。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 12, 0, 'zhTW', '她怎麼和其他的龍一點也不像？她真的可以變成一頭巨大的龍嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 13, 0, 'zhTW', '嗯……尊貴的殿下，你願意為我們變成一條龍嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33533 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33533, 14, 0, 'zhTW', '好啊……就現在吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33535 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33535, 0, 0, 'zhTW', '這是一件與眾不同的武器。一件絕無僅有的武器。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33552 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33552, 0, 0, 'zhTW', '被無情地殺戮……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33552 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33552, 2, 0, 'zhTW', '你們微不足道的抵抗只能讓我變得更加強大。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33552 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33552, 3, 0, 'zhTW', 'Yrr n\'lyeth... shuul anagg!');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33552 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33552, 4, 0, 'zhTW', '他會明白……沒有誰可以永遠坐在王位上，只有死亡才是永恆的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33552 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33552, 5, 0, 'zhTW', '他的族群沒用多久就得到了教訓。你們也快了！');
