INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33626, 0, 0, 'zhTW', '不行。我完全搞不明白這玩意兒是如何運作的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33626 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33626, 1, 0, 'zhTW', '嗯，我知道……我會繼續嘗試的。不過你也別抱太大的希望，這種科技完全超越了我能理解的範圍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 21, 0, 'zhTW', '歡迎，勇士們。今天，在你們的領袖與族人面前，你們將證明自己強大的實力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 22, 0, 'zhTW', '你首先會與這場錦標賽的三名總冠軍作戰。這些強大的戰士已經把他們的對手都一一擊敗了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 23, 0, 'zhTW', '開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 24, 0, 'zhTW', '幹得漂亮！你的下一個挑戰將來自於十字軍的騎士們。他們將以強大的實力對你進行測試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 31, 0, 'zhTW', '幹得好，今天，你證明了自己的實力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 34, 0, 'zhTW', '這是怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33628 AND `GroupID` = 41 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33628, 41, 0, 'zhTW', '可以開始了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33662 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33662, 0, 0, 'zhTW', '怎麼樣？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33662 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33662, 1, 0, 'zhTW', '別灰心。如果這確實是傳送器的話，那它對我們的進攻行動會很有幫助的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33686 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33686, 0, 0, 'zhTW', '我的用途就是儲存這座泰坦之城的重要資訊。我的主要功能包括傳達前沿防禦系統的狀況以及評估關押在這座龐大建築物中的實體的狀態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33686 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33686, 1, 0, 'zhTW', '目前，一切企圖進入泰坦之城的行動都將遭到制約。主防禦系統處於啟用狀態。次防禦系統處於未啟用狀態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33686 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33686, 2, 0, 'zhTW', '檢測到威脅，已啟動安全控制 － 允許查詢。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33686 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33686, 3, 0, 'zhTW', '主防禦系統包括鐵鑄像和風暴信標，後者將不斷地催生更多的構造體。輔助防禦系統包括軌道防禦炮臺。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33696 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33696, 0, 0, 'zhTW', '%s點了點頭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33696 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33696, 1, 0, 'zhTW', '%s低聲對布萊恩說著什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 0, 0, 'zhTW', '我聽說過一兩個關於奧達曼看門人的故事，和你的描述很像。你是否也有類似的用途呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 1, 0, 'zhTW', '前沿防禦系統？在布萊恩派人進入這座城市之前，我需要提醒他什麼嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 2, 0, 'zhTW', '你能詳細描述一下防禦系統的效能嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 3, 0, 'zhTW', '明白了。至少我們不用考慮那些軌道炮臺。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 4, 0, 'zhTW', '琳蒂安，請立即轉告布萊恩和大法師伯塔魯斯關於防禦系統的事兒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 5, 0, 'zhTW', '被囚禁的實體？是什麼實體？目前它處於什麼樣的狀態？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33701 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33701, 6, 0, 'zhTW', '尤格-薩隆被關押在這裡？看來我們有得忙了。');
