INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33749, 2, 3, 'zhTW', '我輸了。打得好！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33785 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33785, 0, 0, 'zhTW', '下馬來，敢不敢和我單挑！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33785 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33785, 1, 0, 'zhTW', '我不會讓你失望的，主人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33788 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33788, 0, 0, 'zhTW', '幫我們抵禦這刺骨的寒風吧，小樹苗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33788 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33788, 0, 1, 'zhTW', '瞧瞧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33788 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33788, 0, 2, 'zhTW', '生長吧，小傢伙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33853 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33853, 0, 0, 'zhTW', '本次錦標賽是數個世紀以來最盛大的賽事！買點紀念品回家送給家人和孩子吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33853 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33853, 0, 1, 'zhTW', '嘿！瞧瞧這些緊身衣！穿上它，既有了城市的代表色，又省去了寬鬆的戰袍帶來的麻煩事兒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33853 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33853, 0, 2, 'zhTW', '你是否已經厭倦了與野獸扭打，想要換個方式來展示自己的本事？無論你來自哪座城市，我都可以滿足你的願望！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33853 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33853, 0, 3, 'zhTW', '支援你最喜歡的冠軍吧！下一回合時，穿上和他們的代表色一致的衣服，讓大家都看看你喜歡誰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 0, 0, 'zhTW', '拒絕登入。許可權級別不足。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 1, 0, 'zhTW', '百分之九十九點九九。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 2, 0, 'zhTW', '小數點後無限迴圈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 3, 0, 'zhTW', '開始分析守護者弗蕾亞的狀態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 4, 0, 'zhTW', '古樹僕從的存在增強了守護者的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 5, 0, 'zhTW', '正在分析明葉長老的強化效果……太陽能增效提供了永久的區域性防護力增強。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 6, 0, 'zhTW', '石樹長老的分析結果表明，他的聲波防禦能力足以干擾魔法的使用。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 7, 0, 'zhTW', '鐵枝長老的掃描結果顯示，存在基於植物功能的移動阻礙機制。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 8, 0, 'zhTW', '另外，我的分析表明，每位古樹長老的存在都令弗蕾亞的魔法能力、物理攻擊或召喚能力得到增強。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 9, 0, 'zhTW', '摧毀古樹僕從可以導致守護者弗蕾亞失去這些增強效果。但是也極可能對弗蕾亞自身及其攜帶的物品，包括她的守護者徽記，造成永久性的傷害。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 10, 0, 'zhTW', '開始分析守護者霍迪爾的狀態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 11, 0, 'zhTW', '霍迪爾的徽記被放在一隻用來儲存神器的寶箱中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 12, 0, 'zhTW', '守護者霍迪爾的情緒和行為極度不穩定。如果戰鬥時間過長，極可能導致寶箱損毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 13, 0, 'zhTW', '與盟軍協同作戰可以提高戰鬥力，使戰鬥時長降到最短。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 14, 0, 'zhTW', '霍迪爾的徽記被放在一隻用來儲存神器的寶箱中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 15, 0, 'zhTW', '開始分析守護者托里姆的狀態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 16, 0, 'zhTW', '檢測到外部影響。其存在方式是偽裝成托里姆已故的配偶西芙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 17, 0, 'zhTW', '這一外部影響所導致的心智干擾極可能觸發區域性的記憶損傷。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 18, 0, 'zhTW', '戰術分析結果顯示，最佳方案為從前方進入競技場，同時派遣另一支分隊透過位於底層的小路。要在外部影響完全控制托里姆的心智之前抵達他所在的高臺，這是成功率最高的方案。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 19, 0, 'zhTW', '開始分析守護者米米爾隆的狀態。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 20, 0, 'zhTW', '守護者米米爾隆的徽記與一套自毀系統相關聯，該系統又與發明迴廊的完整性相關聯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 21, 0, 'zhTW', '這套自毀系統的觸發裝置被稱為“紅色大按鈕”，由米米爾隆自行製造。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 22, 0, 'zhTW', '要獲取米米爾隆的徽記，必須初始化自毀程式，並在流程執行完畢之前擊敗它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 23, 0, 'zhTW', '已獲得檔案館訪問許可權。入侵保護機制暫停。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 24, 0, 'zhTW', '正在初始化問詢。奧爾加隆保險系統是一套在首席管理官死亡時觸發的自動化緊急訊號系統。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 25, 0, 'zhTW', '正確。首席管理官洛肯被毀滅與訊號被啟用的時間戳相符。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 26, 0, 'zhTW', '正在搜尋……首席管理官的毀滅被判定為系統級行星故障的第一道報警資訊。觀察者奧爾加隆抵達之後所展開的行星分析，可能產生兩種回覆程式碼中的一種。回覆程式碼阿爾法代表“一切正常”；回覆程式碼歐米迦代表“行星結構重組”。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 27, 0, 'zhTW', '行星自身與其所承載的生命體將解離為基礎元素：金屬、岩石和氣體。隨後，這些元素將按照最初的行星藍圖完成重組。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 28, 0, 'zhTW', '請求被拒絕。回覆程式碼內建於奧爾加隆的軀體中。他既是信使，也是訊號本身。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 29, 0, 'zhTW', '奧爾加隆檢測到了侵入關鍵行星功能的系統級上古之神汙染。正在計算產生歐米迦回覆程式碼的機率……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 30, 0, 'zhTW', '請求被拒絕。需要四位守護者的徽記進行許可權確認。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 31, 0, 'zhTW', '奧杜爾的四位守護者是：弗蕾亞、托里姆、霍迪爾和米米爾隆。他們的徽記與其本體及心智的完整性密切相關。要進入天文臺，就必須擁有全部四枚徽記。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 32, 0, 'zhTW', '正在分析守護者的狀態。請稍候。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 33, 0, 'zhTW', '檢測到腐蝕。外部影響已經控制了守護者。徽記受到威脅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 34, 0, 'zhTW', '足夠的衝擊力可以使守護者重啟動，消除外部影響。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 35 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 35, 0, 'zhTW', '為了在這一過程中不對徽記造成損傷，我可以分析每位守護者的狀態，並根據計算結果給出具體建議。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 36 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 36, 0, 'zhTW', '正在進行碎片分析。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 37 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 37, 0, 'zhTW', '目標確認：瓦蘭奈爾，遠古王者之錘。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 38 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 38, 0, 'zhTW', '泰坦親自鑄造了瓦蘭奈爾，並將其交給了第一位土靈之王，尤雷爾·石心。透過這柄聖錘，他可以製造新的土靈，並賜予他們生命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 39 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 39, 0, 'zhTW', '在土靈和鐵矮人之間爆發的第一次戰爭中，瓦蘭奈爾碎裂了。據信它的殘片已在戰爭中遺失。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 40 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 40, 0, 'zhTW', '透過這個世界上實際存在的常規手段修復瓦蘭奈爾的可能性趨近於零。正在分析理論上可能存在的修復方式，請稍候。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33874 AND `GroupID` = 41 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33874, 41, 0, 'zhTW', '在名為尤格-薩隆的生物體內，理論上存在一種酸性極強的物質，可以將薩隆邪鐵液化。泰坦鑄成的合金可能透過浸沒在此物質中重新熔合。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33890 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33890, 0, 0, 'zhTW', '幻象消散，通往中央房間的道路開啟了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33972 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33972, 0, 0, 'zhTW', '對沖鋒目標使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目標處於脆弱狀態時立即衝鋒。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33973 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33973, 0, 0, 'zhTW', '給自己加上防禦。$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然後對近戰目標使用刺擊。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33974 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33974, 0, 0, 'zhTW', '對遠端目標使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目標毫無防禦力時再次碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33993 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33993, 0, 0, 'zhTW', '%s使一個風暴爪牙超載了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33993 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33993, 1, 0, 'zhTW', '一隻風暴爪牙冒出來幫助埃瑪爾隆作戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 33993 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (33993, 2, 0, 'zhTW', '%s變得狂暴不已！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34044 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34044, 0, 0, 'zhTW', '來得正是時候。我們趕緊搞定這件事吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34064 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34064, 0, 0, 'zhTW', '我們成功了，夥計們！終於搶在奧爾加隆前面來到了這裡。也許我們可以對系統做點手腳，改變他的分析結果——');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34064 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34064, 1, 0, 'zhTW', '我這就回檔案館，看看能不能堵塞他的訊號。在你們對付他的同時，我努力多爭取一點時間。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34064 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34064, 2, 0, 'zhTW', '我知道該去哪裡。你沒事吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 32, 0, 'zhTW', '銀色神官帕爾崔絲衝著銀月城冠軍拋了一個飛吻。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 40 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 40, 0, 'zhTW', '你有一副好心腸，我知道你想要侍奉聖光。但是戰場上的廝殺難以撼動天災軍團的首腦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 41 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 41, 0, 'zhTW', '錦標賽的目的就是要建立一支強大而團結的軍隊，雖然這個目標看上去並不十分明確。待到一切準備就緒，十字軍以及麾下所有勇士的目光就會轉向寒冰皇冠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 42 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 42, 0, 'zhTW', '我們將集結所有的力量向巫妖王發動攻擊，而他，註定會失敗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 43 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 43, 0, 'zhTW', '我知道你對此尚有疑惑，但是這會讓你更加接近聖光。戰鬥吧，我的兄弟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 50 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 50, 0, 'zhTW', '天吶，你連一點憐憫之心都沒有嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 100 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 100, 0, 'zhTW', '感謝大家參加此次佈道會。看到這麼多熟悉的面孔真是令人欣慰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 101 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 101, 0, 'zhTW', '今天，我要談談聖光的三大美德。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 102 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 102, 0, 'zhTW', '對我們來說，這是一個黑暗而艱苦的時代。天災軍團盤踞在南方。那些在戰場上犧牲的勇士們，轉瞬間就淪為了敵人的爪牙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 103 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 103, 0, 'zhTW', '你們中的大多數都體會過被背叛的苦楚。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 104 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 104, 0, 'zhTW', '但是你們堅持了下來，我們也必須這樣做。在這個時代，人們不應該對堅韌這一美德感到陌生。面對絕望與仇恨，我們仍然要堅守自己的信仰並繼續戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 105 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 105, 0, 'zhTW', '毫無疑問，你們擁有堅韌的意志……但是我們也不能忽略其它的美德。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 106 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 106, 0, 'zhTW', '尊重，是所有踏上聖光之路的人們應該首先學習的美德。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 107 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 107, 0, 'zhTW', '走廊對面，就是那些被你們視為敵人的傢伙。儘管仇恨讓彼此疏遠，但是他們依然擁有值得你們尊重的品德。他們的勇氣就值得欽佩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 108 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 108, 0, 'zhTW', '在場諸位都懂得榮譽之戰的概念吧。對戰時光明磊落是謂尊重，公平地對待敵人是謂尊重。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 109 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 109, 0, 'zhTW', '在戰場上，無論你的對手是兄弟還是宿敵，都要予以同樣的尊重。即便你們的信仰不同，這種尊重依然能在你們之間建立某種聯絡……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 110 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 110, 0, 'zhTW', '……而認可這種聯絡，你們就會更接近聖光。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 111 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 111, 0, 'zhTW', '要在聖光之路上更進一步，我們還必須學會同情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 112 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 112, 0, 'zhTW', '我們置身於競爭與對抗的年代。無論你們走到哪裡，都能看見分歧與爭執。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 113 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 113, 0, 'zhTW', '如何看透本質並尋求共同點，是我們面臨的挑戰。唯有理解，才能讓你們對他人所遭受的痛楚產生同情……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 114 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 114, 0, 'zhTW', '……即使是對那些身處不同陣營的犧牲者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 115 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 115, 0, 'zhTW', '一旦感受並理解這種對敵對友一視同仁的同情，你們就重申了自己與世界的聯絡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 116 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 116, 0, 'zhTW', '只要我們奉行這些原則與美德，這個世界就會變成彼此嚮往的美好世界。榮耀而正義的世界。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 117 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 117, 0, 'zhTW', '好好想想我的話吧，朋友們。黑暗籠罩著我們，人們更加需要聖光的指引。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34102 AND `GroupID` = 118 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34102, 118, 0, 'zhTW', '如果有誰想找我談談，我就在懺悔室的屏風後面等著你們。我很樂意為大家排解疑問、憂慮和彷徨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 0, 0, 'zhTW', '自毀程式已經啟動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 1, 0, 'zhTW', '自毀程式已中斷。過載程式碼A-9-0-5。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 2, 0, 'zhTW', '本區域將在十分鐘後自毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 3, 0, 'zhTW', '本區域將在九分鐘後自毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
