INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 5, 0, 'zhTW', '本區域將在七分鐘後自毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 6, 0, 'zhTW', '本區域將在六分鐘後自毀。');
