DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 10, 0, 'zhTW', '本區域將在二分鐘後自毀。');
