INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 11, 0, 'zhTW', '本區域將在一分鐘後自毀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34143 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34143, 12, 0, 'zhTW', '自毀程式確認啟動。祝你愉快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34386 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34386, 1, 0, 'zhTW', '我們會永遠記住這次拜訪。絕不要忘記你從新朋友那裡學到了什麼，小魯魯。遠大的未來正在前方等著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34387 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34387, 1, 0, 'zhTW', '別擔心，科科。你要長大，成為一名強壯的狂心者。你要率領族人返回舊日的家園。那裡不會再有大舌頭怪。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34489 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34489, 1, 0, 'zhTW', '想看看我能做些什麼嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34489 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34489, 2, 0, 'zhTW', '一起來跳舞吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34490 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34490, 1, 0, 'zhTW', '最好小心一些！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34490 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34490, 2, 0, 'zhTW', '你的樣子還不錯！');
