INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34909, 0, 0, 'zhTW', '達納蘇斯的暗夜精靈為$N而歡呼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34910 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34910, 0, 0, 'zhTW', '諾姆瑞根的地精為$N而歡呼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34924 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34924, 0, 0, 'zhTW', '大門被打破了！保衛要塞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 0, 0, 'zhTW', '感謝你，傳訊者，你的話真令我高興。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 1, 0, 'zhTW', '願聖光賜我力量，讓我不負眾望。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 2, 0, 'zhTW', '好，那麼，讓我們開始吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 3, 0, 'zhTW', '現在，讓時光在你腦中倒流。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 4, 0, 'zhTW', '只要敢於面對，即使是最黑暗的回憶也將不再可怕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 5, 0, 'zhTW', '下去休息吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 5 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 5, 1, 'zhTW', '安心的去吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34928 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34928, 6, 0, 'zhTW', '真是精彩！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34942 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34942, 0, 0, 'zhTW', '%s開始施放夢魘乍醒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 0, 'zhTW', '讓迷霧吞噬你的軀殼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 1, 'zhTW', '我要將你的靈魂捲入迷霧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 2, 'zhTW', '我要將你的屍體扔進大海！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 3, 'zhTW', '嘖嘖，迷路的小羊羔……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 4, 'zhTW', '呀！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 5, 'zhTW', '你還不夠利維洛斯塞牙縫的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34947 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34947, 0, 6, 'zhTW', '$r，擅自闖入他人的地盤就是你的不對了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34956 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34956, 0, 0, 'zhTW', '他們馬上就要把我綁在祭壇上，吸取我的靈魂裡。讓我們趕快離開這裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34960 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34960, 0, 0, 'zhTW', '全體登上飛行戰艦！做好開火準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34965 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34965, 0, 0, 'zhTW', '愚蠢的$c，你無法阻止克瓦迪爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34980 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34980, 0, 0, 'zhTW', '你竟敢挑戰德羅丁·洛斯加爾，諸海之王？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 0, 0, 'zhTW', '你的猛獸阻擋不了我的勇士！提里奧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 1, 0, 'zhTW', '聯盟對付這些部落垃圾不需要惡魔領主的幫助！來吧，蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 2, 0, 'zhTW', '我們的榮耀被玷汙了！他們對我們進行肆意的汙衊與誹謗。我要討回公道！請允許我的勇士代替你的人出場，提里奧。我們要挑戰部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 3, 0, 'zhTW', '為榮耀而戰！英雄們，為國王和人民而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 4, 0, 'zhTW', '榮耀屬於聯盟！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 5, 0, 'zhTW', '即使是巫妖王最強大的爪牙也無法與聯盟抗衡。為勝利歡呼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 6, 0, 'zhTW', '易如反掌。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 6, 1, 'zhTW', '哈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 6 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 6, 2, 'zhTW', '這就是部落最強的戰士？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 6 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 6, 3, 'zhTW', '沒用的東西。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 50 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 50, 0, 'zhTW', '我對這些遊戲可沒什麼興趣，提里奧。不過……我相信它們一定很精彩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 51 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 51, 0, 'zhTW', '不要只是傻站在那裡，幹掉他！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 52 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 52, 0, 'zhTW', '我到這裡來不是為了看野獸們無意義地彼此撕扯，提里奧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34990 AND `GroupID` = 53 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34990, 53, 0, 'zhTW', '你打得非常英勇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34994 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34994, 0, 0, 'zhTW', '打得好，部落！Lok\'tar Ogar！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34994 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34994, 1, 0, 'zhTW', '幹得好，勝利屬於部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34994 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34994, 2, 0, 'zhTW', '加爾魯什，夠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 0, 0, 'zhTW', '我在鮮血之環經歷過更強大的挑戰。這是浪費時間，聖騎士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 1, 0, 'zhTW', '狡詐的聯盟狗！召喚惡魔領主來對抗部落的戰士？你們離死不遠了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 2, 0, 'zhTW', '部落需要公正！我們向聯盟挑戰！請允許我們代你出戰，聖騎士。我們要讓那些狗知道侮辱部落的下場。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 3, 0, 'zhTW', '不要手下留情，部落勇士們！Lok\'tar Ogar！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 4, 0, 'zhTW', '這只是一個小小的開始。為了部落！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 5, 0, 'zhTW', '聖騎士，你還在懷疑部落的力量嗎？我們戰無不勝！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 6, 0, 'zhTW', '軟蛋！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 6, 1, 'zhTW', '沒希望了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 6 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 6, 2, 'zhTW', '敗了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 6 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 6, 3, 'zhTW', '感覺如何？哈！我很喜歡看著你們這些弱小的勇士是怎樣失敗的，人類。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 50 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 50, 0, 'zhTW', '終於出現了一場值得一看的戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 51 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 51, 0, 'zhTW', '把他撕碎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34995 AND `GroupID` = 52 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34995, 52, 0, 'zhTW', '感覺如何？哈！我很喜歡看著你們這些弱小的勇士是怎樣失敗的，人類。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 0, 0, 'zhTW', '歡迎，勇士們！你們聽到了銀白十字軍的號召，並勇敢地作出了響應！此時此地，就在十字軍演武場，你們將面對最強大的挑戰。能在這次選拔中活下來的人都將加入北伐的行列，共同進軍冰冠堡壘！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 1, 0, 'zhTW', '他來自風暴峭壁最幽深，最黑暗的洞穴，穿刺者戈莫克！準備戰鬥，英雄們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 2, 0, 'zhTW', '做好準備，英雄們，兩頭猛獸已經進入了競技場！它們是酸喉和恐鱗！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 3, 0, 'zhTW', '當下一名鬥士出場時，空氣都會為之凍結！它是冰吼，勝或是死，勇士們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 4, 0, 'zhTW', '這些恐怖的野獸終於被消滅了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 5, 0, 'zhTW', '悲劇……他們英勇奮戰，但還是沒有制服北裂境的猛獸。讓我們為這些死去的英雄默哀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 6, 0, 'zhTW', '高階術士威爾弗雷德·菲茲班將是你們的下一個對手。等待他的上場吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 7, 0, 'zhTW', '快，英雄們，消滅那隻惡魔，不要讓他開啟通向惡魔空間的傳送門！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 8, 0, 'zhTW', '很遺憾，我們失去了威爾弗雷德·菲茲班，但這也給那些膽敢研習黑暗魔法的人們敲響了警鐘。唉，你勝利了。準備面對下一個挑戰吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 9, 0, 'zhTW', '大家冷靜！不要慌亂！這並不是什麼陰謀！這名術士只是在按照自己的意願行事，並不是聯盟的授意。比賽必須繼續！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 10, 0, 'zhTW', '接下來你們將面對銀白十字軍最強的騎士！只有打敗他們，才能證明你的價值……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 11, 0, 'zhTW', '好吧，我同意了。為榮譽而戰吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 12, 0, 'zhTW', '膚淺且可悲的勝利。今天的內耗讓我們又一次被削弱了。這種愚蠢的行為只能讓巫妖王受益！偉大的戰士們就這樣白白犧牲，而真正的威脅卻步步逼近。巫妖王正計算著我們的死期。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 13, 0, 'zhTW', '你們只有團結才能戰勝最終的挑戰。來自於寒冰皇冠的深處，天災軍團最強的戰將：巫妖王的雙翼使者，恐怖的瓦格里！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 14, 0, 'zhTW', '讓遊戲開始吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 15, 0, 'zhTW', '這是對巫妖王的一次重創！你的實力絕不亞於銀白十字軍的勇士。很快，我們將攜手攻入冰冠堡壘，消滅天災軍團的殘餘！只要心齊，我們必將勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 16, 0, 'zhTW', '阿爾薩斯！你已經孤立無援了！放下霜之哀傷，我會讓你死個痛快。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 17, 0, 'zhTW', '現在去休息一下吧，辛苦了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 18, 0, 'zhTW', '現在去休息一下吧，辛苦了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 50 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 50, 0, 'zhTW', '歡迎，勇士們。今天，在你們的領袖與族人面前，你們將證明自己強大的實力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 51 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 51, 0, 'zhTW', '你首先會與這場錦標賽的三名總冠軍作戰。這些強大的戰士已經把他們的對手都一一擊敗了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 52 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 52, 0, 'zhTW', '開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 53 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 53, 0, 'zhTW', '幹得漂亮！你的下一個挑戰將來自於十字軍的騎士們。他們將以強大的實力對你進行測試。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 54 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 54, 0, 'zhTW', '可以開始了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 55 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 55, 0, 'zhTW', '幹得好，今天，你證明了自己的實力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 56 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 56, 0, 'zhTW', '這是怎麼回事？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 57 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 57, 0, 'zhTW', '勇士們，祝賀你們！經歷過一系列計劃之中和意料之外的試煉，你們終於取得了勝利。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 34996 AND `GroupID` = 58 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (34996, 58, 0, 'zhTW', '現在去休息一下吧，辛苦了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35003 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35003, 0, 0, 'zhTW', '全體登上飛行戰艦！做好開火準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 0, 0, 'zhTW', '正在走進競技場的是一位對於戰場和比武場都絕不陌生的聖騎士——銀色十字軍的總冠軍，純潔者耶德瑞克！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 1, 0, 'zhTW', '接下來出場的是聖光最忠實的追隨者！銀色神官帕爾崔絲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 2, 0, 'zhTW', '奪日者們自豪地介紹他們在這場競賽中的代表。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 3, 0, 'zhTW', '現在出場的是矮小卻極度致命的安布羅斯·雷釘，諾姆瑞根的總冠軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 4, 0, 'zhTW', '進入競技場的是達納蘇斯的總冠軍，戰技非凡的婭琳·永歌！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 5, 0, 'zhTW', '請向驕傲而強壯的暴風城總冠軍，雅克布·奧勒留斯元帥歡呼吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 6, 0, 'zhTW', '今天，矮人的力量將在鐵爐堡的總冠軍，拉娜·硬錘的身上得以展現！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 7, 0, 'zhTW', '從大門中走出來的是克羅索斯，艾克索達強大的總冠軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35004 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35004, 8, 0, 'zhTW', '那些椽子旁邊是什麼？');
