DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35005 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35005, 3, 0, 'zhTW', '從大門中走出來的是埃蕾希·晨歌，強大的法師！銀月城總冠軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35005 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35005, 4, 0, 'zhTW', '進入競技場的是削瘦卻極度危險的祖爾託，森金村的總冠軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35005 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35005, 5, 0, 'zhTW', '現在請注意，強大的奧格瑞姆總冠軍，碎顱者莫克拉出場！');
