INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35005, 6, 0, 'zhTW', '我們現在要介紹的是幽暗城的總冠軍，強韌的亡靈，死亡獵手維賽裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35005 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
