INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35119, 6, 0, 'zhTW', '我認輸！我投降。你做得很好。我可以走了吧？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35127 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35127, 0, 0, 'zhTW', '非常榮幸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35144 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35144, 0, 0, 'zhTW', '看到同伴的死亡，%s被激怒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35144 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35144, 1, 0, 'zhTW', '你已經被麻痺毒素感染了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35144 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35144, 2, 0, 'zhTW', '%s從地下鑽出來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35320 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35320, 0, 0, 'zhTW', '謝謝，這是我唯一能做的。我們需要同心協力。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35320 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35320, 1, 0, 'zhTW', '我相信索爾會管住他的部下……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35321 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35321, 0, 0, 'zhTW', '提里奧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35321 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35321, 1, 0, 'zhTW', '你說個不停，提里奧。要平心靜氣，要相信那些野人會管住自己。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35321 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35321, 2, 0, 'zhTW', '也許吧。我覺得這比賽沒什麼意義。我們現在就應該集結大軍發動總攻。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35321 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35321, 3, 0, 'zhTW', '但如果我出席這些比賽能換來你在戰爭中的協助。那我暫時，會留下來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 0, 0, 'zhTW', '歡迎你們，索爾酋長，地獄咆哮統帥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 1, 0, 'zhTW', '我希望你能明白現在的狀況，加爾魯什。如果再這樣互相爭鬥，就休想戰勝天災軍團。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 2, 0, 'zhTW', '在我這裡，各位，我相信你們不會亂來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 3, 0, 'zhTW', '那就請跟我來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 4, 0, 'zhTW', '瓦里安國王，珍娜女士，歡迎你們的到來。我們恭候多時了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 5, 0, 'zhTW', '我的人在這裡是為了確保比賽的井然有序。最好讓你的部下知道你在看著他們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 6, 0, 'zhTW', '%s點點頭，招手示意他的客人跟上。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 7, 0, 'zhTW', '參加聯盟和部落之間的戰鬥吧！歡迎你加入到銀色十字軍的麾下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 8, 0, 'zhTW', '我們的目標就在南方。我們將向那座要塞進軍，直搗天災軍團的心臟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 9, 0, 'zhTW', '這可不是一個輕鬆的任務。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 10, 0, 'zhTW', '一場動員所有人參加的大規模攻擊只會導致本可以避免的慘重傷亡。而每一名倒下的士兵都會變成敵人再爬起來。到那時候，艾澤拉斯將再沒有力量對抗亡靈怪物的威脅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 11, 0, 'zhTW', '實際上，我們需要組建一支小規模的精英力量，對敵人造成致命打擊。這才是我們的取勝之道。所以我們舉辦了銀色錦標賽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 12, 0, 'zhTW', '你將在這裡接受測試。你必須以自身的戰鬥實力來對抗北裂境最兇暴危險的力量。而你的領袖們將親眼見證你的戰鬥。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 13, 0, 'zhTW', '你們的勇敢、力量和機智都將受到萬眾矚目。這些競賽將決定誰才是艾澤拉斯最強的戰士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35361 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35361, 14, 0, 'zhTW', '勝利者將成為進攻冰冠堡壘大軍的先鋒。我們將並肩對抗邪惡。阿爾薩斯必將滅亡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35368 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35368, 0, 0, 'zhTW', '加爾魯什，我希望你能控制自己。我不想紫羅蘭城堡的一幕再發生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35368 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35368, 1, 0, 'zhTW', '我們是客人，加爾魯什，你要注意你的言行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35368 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35368, 2, 0, 'zhTW', '感謝您的邀請，弗丁大人。我們期待著精彩的比賽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35368 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35368, 3, 0, 'zhTW', '說的好。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35368 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35368, 4, 0, 'zhTW', '加爾魯什，夠了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35368 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35368, 5, 0, 'zhTW', '當然，提里奧，我為他的莽撞向你致歉，我保證下不為例。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35372 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35372, 0, 0, 'zhTW', '哼！那只是領袖在展示他的力量。我真後悔沒在那個法師插手前幹掉那個人類。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35372 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35372, 1, 0, 'zhTW', '揮舞粗頭棒子有什麼榮譽可言？這是在浪費時間。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35372 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35372, 2, 0, 'zhTW', '別算上我，索爾。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35372 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35372, 3, 0, 'zhTW', '一派胡言。部落殺死那隻亡靈易如反掌，不需要你，更別說那個傲慢的國王。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35372 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35372, 4, 0, 'zhTW', '呸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 0, 0, 'zhTW', '你搞砸了我的盛大登場，鼠輩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 1, 0, 'zhTW', '你們真以為，巫妖王的戰士會敗在你們那可憐的比武場上？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 2, 0, 'zhTW', '我是來做個了斷的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 3, 0, 'zhTW', '這場鬧劇該結束了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 4, 0, 'zhTW', '我的爛肉還真礙事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 5, 0, 'zhTW', '我可不需要用骨頭來打敗你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 6, 0, 'zhTW', '可憐。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 6 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 6, 1, 'zhTW', '真是對生命的浪費。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35451 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35451, 7, 0, 'zhTW', '不！我絕不能再……失敗了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35458 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35458, 0, 0, 'zhTW', '感謝你，大領主。挑戰者們，我將開始召喚儀式。當儀式完成時，一個恐怖的末日守衛就會出現！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35458 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35458, 1, 0, 'zhTW', '準備迎接末日吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35458 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35458, 2, 0, 'zhTW', '啊哈！我做到了！看看召喚大師威爾弗雷德·菲茲班強大的力量吧！為我效命吧，惡魔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35458 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35458, 3, 0, 'zhTW', '我才是主人……呦，哦……哦……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35476 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35476, 0, 0, 'zhTW', '為這些競技選手們召喚惡魔敵人的工作當然應該由我來完成。我是威爾弗雷德·菲茲班，召喚大師！在我鋼鐵般意志的控制下，即使是惡魔也會瑟瑟發抖！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35476 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35476, 0, 1, 'zhTW', '很快，全世界都將知道威爾弗雷德的名字！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35501 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35501, 0, 0, 'zhTW', '部落的酋長索爾和督軍加爾魯什·地獄咆哮已經來到比武場！讓路！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35501 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35501, 1, 0, 'zhTW', '大領主提里奧·弗丁已經來到臺上，要向聚集在比武場上的人們講話！來聽他的演講吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35501 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35501, 2, 0, 'zhTW', '瓦里安·烏瑞恩國王殿下和珍娜·普勞德摩爾女士已經蒞臨比武場！讓路！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35545 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35545, 0, 0, 'zhTW', '漂亮的爆頭射擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35545 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35545, 1, 0, 'zhTW', '誰能擋住這個食屍鬼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 35545 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
