INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (35642, 0, 0, 'zhTW', '請原諒，恐怕現在我還有別的事情必須去做。請以後再來找我。');
