INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 0, 0, 'zhTW', '怎麼，自詡正義的聖光終於來了？我是不是該丟下霜之哀傷，懇求您的寬恕呢，弗丁？');
