INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 1, 0, 'zhTW', '讓我來親自告訴你。當一切結束，你將跪求我的寬恕－－而我會拒絕你。你痛苦的哀號將是我狂野力量的最好證明……');
