INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 2, 0, 'zhTW', '我會讓你活著目睹這個末日，弗丁。這悲慘的世界將在我手中重鑄，我不想讓聖光最強大的勇士錯過這一切。');
