INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 13, 0, 'zhTW', '|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你受到了|cFFBC05FF死疽|r的傷害！|TInterface\\Icons\\ability_creature_disease_02.blp:16|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 14, 0, 'zhTW', '我不再有問題，也不再有疑問。你是艾澤拉斯最強大的勇士。我的阻撓都被你一一化解。我最悍勇的僕從也都倒在了你的無情怒火和利刃之下……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 15, 0, 'zhTW', '真的是正義在驅使你嗎？我很好奇……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 16, 0, 'zhTW', '你把他們訓練的很好，弗丁。你把世界上最強大的勇士都送到我的面前，這正合我意！你們的默默犧牲會得到我的褒獎。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 17, 0, 'zhTW', '親眼目睹吧，我會把他們從屍骸變為天災軍團的戰士。艾澤拉斯會在他們的手中陷入混亂，走向毀滅！而你，將是第一具屍體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 18, 0, 'zhTW', '我會享受這種諷刺。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 19, 0, 'zhTW', '這不可能……');
