INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 20, 0, 'zhTW', '我如同羊群前的雄獅，但它們不畏懼我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36597 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36597, 21, 0, 'zhTW', '也不敢畏懼。');
