INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36612, 0, 0, 'zhTW', '這就是你們的開始與終結之地，凡人們。休想進入主人的密室！');
