INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36642, 1, 0, 'zhTW', '這把劍的形制和銘文表明它是一把龍鑄之刃。終於，答案找到了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36642 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
