INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36642, 3, 0, 'zhTW', '見證奪日者奪回奎爾德拉是我們的使命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36656 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36656, 1, 0, 'zhTW', '巫妖王的爪牙，這裡不歡迎你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 0, 0, 'zhTW', '唉，勇敢的冒險者，你們的路已經到頭了。難道你們沒有聽到身後隧道里鋼鐵撞擊的聲音嗎？那就是末日降臨的樂章。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 1, 0, 'zhTW', '哈，一群不自量力的烏合之眾。等我殺了你們之後，主人的劍就能盡情享用你們的靈魂了。去死吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 2, 0, 'zhTW', '我不會讓巫妖王失望的。準備受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 3, 0, 'zhTW', '低劣的頑抗，死亡是對你的優待。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 3 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 3, 1, 'zhTW', '也許你早應該留在……群山裡！');
