INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 4, 0, 'zhTW', '不可能……霜牙……警報……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 5, 0, 'zhTW', '霜牙，幹掉那個蠢貨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 6, 0, 'zhTW', '冰霜巨龍霜牙凝視著$n，準備發動一次冰霜襲擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 7, 0, 'zhTW', '力量……無上的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36658 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36658, 8, 0, 'zhTW', '%s發出怒吼，在黑暗力量的作用下開始膨脹！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36669 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36669, 0, 0, 'zhTW', '總算盼到你來了，信使。克拉蘇斯將其餘的上古龍鑄之刃複製品中的一個交給了我們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36669 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36669, 1, 0, 'zhTW', '給你書。你要確保趕在奪日者發現這一切之前將書送到卡萊迪斯·亮矛那裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36669 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36669, 2, 0, 'zhTW', '快馬加鞭！奪日者發現我們有他們要的資訊時會抓緊一切時間對付我們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36670 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36670, 0, 0, 'zhTW', '你太遲了，信使。不，我不想聽你的藉口；這個任務極為重要。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36670 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36670, 1, 0, 'zhTW', '這是我們的使者從龍眠神殿帶回來的寶典。立刻將它帶給麥雷昂·陽炎。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36670 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36670, 2, 0, 'zhTW', '信使，你要小心。我無須向你解釋這本書的重要性，況且，銀色盟約的人會不惜一切代價把它從我們手裡奪走。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36678 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36678, 0, 0, 'zhTW', '這是普通的毒雲，但請千萬小心，這毒雲其實並不普通！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36678 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36678, 1, 0, 'zhTW', '哦爛腸，你是我的最愛，僅次於腐面。不過你的死給我留下了那麼多毒氣，我都快被燻死了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36678 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36678, 2, 0, 'zhTW', '重大喜訊！各位！軟泥又開始流動啦！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36678 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36678, 2, 1, 'zhTW', '好訊息！各位！我修好了毒性軟泥管道！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36678 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36678, 3, 0, 'zhTW', '驚天噩耗，我作的腐面，剛剛死了。但重大喜訊，他留下了，大量軟泥！哇，我居然還有這麼出眾的詩歌才華……雷死了！');
