DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36774 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36774, 0, 0, 'zhTW', '你們這些奪日者下人全都一個樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36774 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36774, 0, 1, 'zhTW', '我們不會讓你輕易逃脫的！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36776 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36776, 0, 0, 'zhTW', '你認為你能活著逃走嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36776 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36776, 0, 1, 'zhTW', '你們永遠別想把我們趕出城去，銀色盟約的混蛋！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 0, 0, 'zhTW', '英雄們，請快些幫助我，我……我快要抵擋不住他們了。請治療我的傷口！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 1, 0, 'zhTW', '我開啟了進入夢境的傳送門。英雄們，救贖就在其中……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 2, 0, 'zhTW', '我的力量回來了。堅持，英雄們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 3, 0, 'zhTW', '我……堅持不了多久了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 4, 0, 'zhTW', '原諒我所做的一切！我……無法做到……噩夢才是歸宿！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 5, 0, 'zhTW', '一場悲劇……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 6, 0, 'zhTW', '受死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36789 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36789, 7, 0, 'zhTW', '我獲得了新生！伊瑟拉的恩澤賜予我消滅邪惡的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 0, 0, 'zhTW', '沒用的蟲子！死亡正等待著你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 1, 0, 'zhTW', '不要以為我會那麼容易讓你進入主人的密室。有本事放馬過來吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 2, 0, 'zhTW', '你們的努力是徒勞的，入侵者。巫妖王讓我統率的可是一支亡靈大軍！小心了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 3, 0, 'zhTW', '固執的傢伙！你們根本到不了主人的密室！士兵們，消滅他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 4, 0, 'zhTW', '入侵者進入了主人的領地。拉響警報！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 5, 0, 'zhTW', '哼，廢物，就連在礦坑裡作苦力都不配。享受最後的時刻吧。很快你們就會變成行屍走肉了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 6, 0, 'zhTW', '你們最後的記憶將填滿痛苦。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36794 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36794, 7, 0, 'zhTW', '奴僕們，消滅那些闖入者！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36795 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36795, 0, 0, 'zhTW', '別人會取代他。你是在浪費時間。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36795 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36795, 1, 0, 'zhTW', '霜牙，把他們困在隧道里！統統給我埋了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36823 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36823, 0, 0, 'zhTW', '你是來審判阿爾薩斯的嗎？想要看到巫妖王的滅亡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36823 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36823, 1, 0, 'zhTW', '首先，你需要擺脫霜之哀傷的控制，否則就會像我一樣，永世成為這把邪劍的囚徒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36823 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36823, 2, 0, 'zhTW', '幫我摧毀這些痛苦的靈魂！我們合力就能弱化霜之哀傷的控制，從內部削弱巫妖王！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36838 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36838, 0, 0, 'zhTW', '|TInterface\\Icons\\Spell_開火_Flameshock.blp:20|t|cFFBC0000過熱|r|TInterface\\Icons\\Spell_開火_Flameshock.blp:20|t');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36839 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
