DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 0, 0, 'zhTW', '你們這些蠢貨膽敢闖入這裡。北裂境的冰風將捲走你們的靈魂！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 1, 0, 'zhTW', '痛苦吧，凡人，你們可憐的魔法背叛了你們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 2, 0, 'zhTW', '%s準備釋放一波嚴寒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 3, 0, 'zhTW', '你能感受到死神之手的那股寒意嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 4, 0, 'zhTW', '啊！強烈的灼痛！這是什麼魔法？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 5, 0, 'zhTW', '你們的入侵結束了！無人可以生還！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 6, 0, 'zhTW', '絕望吧，體會主人那無窮無盡的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 7, 0, 'zhTW', '%s向$n擲出一顆冰凍寶珠！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 8, 0, 'zhTW', '去死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 8 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 8, 1, 'zhTW', '軟弱的凡人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 9, 0, 'zhTW', '夠了！我厭倦了這些遊戲！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 10, 0, 'zhTW', '終於……自由了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 11, 0, 'zhTW', '%s變得狂暴不已！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36853 AND `GroupID` = 101 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36853, 101, 0, 'zhTW', '%s變得狂暴不已！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 0, 0, 'zhTW', '你們之所以在這裡，那是因為你們是少數幾個擁有特殊能力，能夠洞悉這詛咒世界的人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 1, 0, 'zhTW', '你們能夠看穿遮蔽世界的迷霧，掌握真正的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 2, 0, 'zhTW', '好好看看你粗陋的手：看看那肌腱、軟肉和其中的黑暗之血。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 3, 0, 'zhTW', '多麼的軟弱和不堪……這真是造物主的玩笑。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 4, 0, 'zhTW', '你只有承認自己必然的失敗，才有可能早日獲得更強的力量，重獲新生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 5, 0, 'zhTW', '我的主人是無所不能的，他有無比強大的力量，不可抗拒的意志。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 6, 0, 'zhTW', '反抗者必將被毀滅。而那些全身心的，堅定不移的，有虔誠的思想與靈魂的效忠者們，必將得到超乎你們想象範疇的強大的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 7, 0, 'zhTW', '是誰在打擾我？你們竟敢擅闖這神聖的地方？這裡將會是你們的埋骨之地！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 8, 0, 'zhTW', '夠了！看來需要我親自上陣了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 9, 0, 'zhTW', '%s的法力壁壘閃著微光並在逐漸消退！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 10, 0, 'zhTW', '軟弱的你抵擋不了我強大的意志！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 11, 0, 'zhTW', '來接受這祝福，讓入侵者嚐嚐主人偉大的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 12, 0, 'zhTW', '忠誠的追隨者，從血肉的詛咒中解脫吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 13, 0, 'zhTW', '來吧，為純粹的形態歡喜吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 14, 0, 'zhTW', '你還不明白自己的徒勞嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 14 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 14, 1, 'zhTW', '擁抱黑暗吧……永恆的黑暗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 15, 0, 'zhTW', '陪你們玩的夠久了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36855 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36855, 16, 0, 'zhTW', '這全是主人的計劃……你的結局是必然的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 0, 0, 'zhTW', '你很走運。我剛裝了些你需要的，正準備拿去洗。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 1, 0, 'zhTW', '看到大堆的衣服和那桶水了吧？我會大聲喊需要什麼，你就把需要的扔進盆裡。準備好了嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 1, 1, 'zhTW', '乾的真不賴！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 1, 2, 'zhTW', '阿誇諾斯要忙不過來了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 1, 3, 'zhTW', '幹得好。我不想知道那點汙跡究竟是什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 2, 0, 'zhTW', '快點兒，扔幾件襯衫到洗衣桶裡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 3, 0, 'zhTW', '加幾件兒噁心的…呃，我是說，“棘手的”！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 4, 0, 'zhTW', '桶裡需要加水！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 5, 0, 'zhTW', '朝桶裡扔幾條褲子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 6, 0, 'zhTW', '我應該留住你的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 7, 0, 'zhTW', '哦，不！不應該這樣的。現在我們不得不再弄些清潔劑重新開始了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36856 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36856, 8, 0, 'zhTW', '阿誇諾斯，別把衣服扔那麼高了！我知道你不用看艾薩斯·奪日者在噴泉找到自己褲子時的臉色！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36888 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36888, 0, 0, 'zhTW', '走這邊！我們就要對天災領主的領地發動襲擊了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36889 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36889, 0, 0, 'zhTW', '走這邊！我們就要對天災領主的領地發動襲擊了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36899 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36899, 4, 0, 'zhTW', '|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s開始釋放|cFFFF0000不穩定軟泥爆炸！|r');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 0, 'zhTW', '在痛苦中哭泣吧…讓你的痛消磨你的力量…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 1, 'zhTW', '讓你自己擺脫生命的輪迴…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 2, 'zhTW', '沒人能阻擋巫妖王的步伐…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 3, 'zhTW', '主人的意志不容侵犯…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 4, 'zhTW', '你無法逃脫主人的怒火……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 5 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 5, 'zhTW', '死亡將你吞噬…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36913 AND `GroupID` = 0 AND `ID` = 6 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36913, 0, 6, 'zhTW', '屈服吧…投入死亡冰冷的懷抱…');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 0, 0, 'zhTW', '來吧！部落忠誠勇敢的兒女們！今天是部落仇敵滅亡的日子！Lok\'tar Ogar！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 1, 0, 'zhTW', '庫卡隆，出發！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 2, 0, 'zhTW', '那是什麼？有東西正從遠方靠近！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 3, 0, 'zhTW', '聯盟的炮船！全體集合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 4, 0, 'zhTW', '在你面前的是薩魯法爾！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 5, 0, 'zhTW', '你很快就會明白了。庫卡隆，消滅他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 6, 0, 'zhTW', '這不是你的戰鬥，矮人。回去，否則我們就只能摧毀你們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 7, 0, 'zhTW', '你竟敢上我的船？你活不長了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 8, 0, 'zhTW', '將士們，給我進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 9, 0, 'zhTW', '飛斧手，加速擲斧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 10, 0, 'zhTW', '火箭手，裝彈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 11, 0, 'zhTW', '我們的船體受損了，趕快叫個戰鬥法師來轟掉那些大炮！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 12, 0, 'zhTW', '聯盟不行了。向巫妖王進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36939 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36939, 13, 0, 'zhTW', '把火撲滅，控制損傷！讓你們見識一下部落的堅強！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 0, 0, 'zhTW', '啟動引擎！小夥子們，向命運之戰前進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 1, 0, 'zhTW', '都給我抓緊了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 2, 0, 'zhTW', '那到底是什麼？來人，給我望遠鏡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 3, 0, 'zhTW', '以我的鬍子起誓！部落的速度真快啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 4, 0, 'zhTW', '規避動作！炮火準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 5, 0, 'zhTW', '卑鄙的傢伙！竟敢偷襲我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 6, 0, 'zhTW', '想擋住我？也不看看自己是誰？我現在就要去和阿爾薩斯算賬了，誰也別想攔著我！注意！全火力射擊！開火！開火！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 7, 0, 'zhTW', '獸人！挪開你的破飛艇，否則我就把它轟爛！這裡沒部落什麼事！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 8, 0, 'zhTW', '什麼？！別妄想能輕易就奪走我們鐵爐堡的船！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 9, 0, 'zhTW', '將士們，給我進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 10, 0, 'zhTW', '火槍手，加速射擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 11, 0, 'zhTW', '火炮小隊，裝彈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 12, 0, 'zhTW', '我們的船體受傷了，趕快叫個法師來幹掉那些大炮！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 13, 0, 'zhTW', '我早就警告過你，惡棍！兄弟姐妹們，前進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36948 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36948, 14, 0, 'zhTW', '指揮官巴雷特，離開這裡！我們受到重創，難以漂浮了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 0, 0, 'zhTW', '你的盟友到了，珍娜，你說的沒錯。全都變成效忠我的天災戰士吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 1, 0, 'zhTW', '我不會再犯同樣的錯誤，希爾瓦娜斯。這次你走不了了，你們死後都會成為我的奴僕！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 2, 0, 'zhTW', '你們無路可逃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 3, 0, 'zhTW', '屈服於死亡的嚴寒吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 4, 0, 'zhTW', '死路一條！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 5, 0, 'zhTW', '你們能抵擋多久？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 6, 0, 'zhTW', '甦醒吧，奴僕們。攔住他們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 7, 0, 'zhTW', '奴僕們，抓住他們！帶他們的屍體來見我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 8, 0, 'zhTW', '陰冷的死亡等待著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36954 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36954, 9, 0, 'zhTW', '窮途末路……變成我的奴僕吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 0, 0, 'zhTW', '太強大了。我們必須馬上離開！我的魔法只能暫時拖住他。快來，英雄們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 1, 0, 'zhTW', '我會摧毀這道屏障，但你必須擋住那些亡靈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 2, 0, 'zhTW', '又是一道冰牆！不要讓那些亡靈打斷我的法術，這樣我才能摧毀冰牆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 3, 0, 'zhTW', '我們就要到了……不要放棄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 4, 0, 'zhTW', '你的屏障擋不住我們，怪物！我會將它們全部粉碎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 5, 0, 'zhTW', '前面有個出口，趕快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 6, 0, 'zhTW', '這……這是死路！我們別無選擇，只能戰鬥。準備迎戰，英雄們，這是我們最後的陣地。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 7, 0, 'zhTW', '原諒我，英雄們。我應該聽烏瑟爾的。我……我只是希望能夠，能夠看他最後一眼。對不起。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36955 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36955, 8, 0, 'zhTW', '我們知道該怎麼做了。我會把這個訊息帶給瓦里安國王和弗丁大人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 0, 0, 'zhTW', '為什麼女妖之王要饒恕你的小命？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 1, 0, 'zhTW', '霜之哀傷？巫妖王從不離開他的佩劍。如果你撒謊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 2, 0, 'zhTW', '叛徒就是這種下場。來吧，我們必須解救那些奴隸，再看看巫妖王的密室中都有什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 3, 0, 'zhTW', '部落的戰士們，進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 4, 0, 'zhTW', '我以為他永遠都閉不上嘴。但辛達苟薩讓這個呱噪的傢伙安靜下來了。勇士們，向映像大廳前進！我能感覺到……目標已近。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 7, 0, 'zhTW', '可憐的傢伙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 11, 0, 'zhTW', '你只能靠自己衝過這個骯髒的地方了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 13, 0, 'zhTW', '解救你遇到的所有部落奴隸。我們需要他們的協助來對抗泰蘭努斯。我會集結援軍，並在礦坑對面與你匯合。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 37 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 37, 0, 'zhTW', '為什麼女妖之王要饒恕你的小命？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 40 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 40, 0, 'zhTW', '霜之哀傷？巫妖王從不離開他的佩劍。如果你撒謊……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36990 AND `GroupID` = 46 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36990, 46, 0, 'zhTW', '叛徒就是這種下場。來吧，我們必須解救那些奴隸，再看看巫妖王的密室中都有什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 0, 0, 'zhTW', '我不會因為你的可憐而手下留情，有話快說吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 1, 0, 'zhTW', '霜之哀傷無人守衛？不可能！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 2, 0, 'zhTW', '聯盟的英雄們，進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 3, 0, 'zhTW', '英雄們，到我這來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 4, 0, 'zhTW', '冰霜女王完了。我們……我們必須繼續前進——目標就在眼前。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 5, 0, 'zhTW', '我……我救不了他們……該死，阿爾薩斯！你這惡魔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 6, 0, 'zhTW', '不！你這怪物！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 9, 0, 'zhTW', '我別無選擇。請原諒我，高貴的戰士們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 10, 0, 'zhTW', '你只能靠自己衝過這個礦坑了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 12, 0, 'zhTW', '解救你遇到的所有聯盟奴隸。我們需要他們的協助來對抗泰蘭努斯。我會集結援軍，並在礦坑對面與你匯合。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 36 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 36, 0, 'zhTW', '我不會因為你的可憐而手下留情，有話快說吧。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 39 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 39, 0, 'zhTW', '霜之哀傷無人守衛？不可能！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 36993 AND `GroupID` = 45 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (36993, 45, 0, 'zhTW', '惡有惡報。來吧，英雄們。去看看那個地精說的是真是假。如果阿爾薩斯沒了霜之哀傷，我們也許有機會阻止他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37007 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37007, 0, 0, 'zhTW', '有人闖進了主人的房間！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37007 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37007, 0, 1, 'zhTW', '我醒了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37007 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37007, 0, 2, 'zhTW', '那裡是誰？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37038 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37038, 0, 0, 'zhTW', '快點，我們會在背後伏擊他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37038 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37038, 0, 1, 'zhTW', '這裡有活人？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37038 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37038, 0, 2, 'zhTW', '你逃不出我們的手心！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37119 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37119, 0, 0, 'zhTW', '這是我們最後的陣地。今天的一切都將千古流傳。無論是生是死，我們都是為了榮譽而戰。我們都是為了自由和人民而戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37119 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37119, 1, 0, 'zhTW', '記住，勇士們，在這邪惡之地，恐懼是你們最大的敵人。勇氣將讓你們的靈魂比千顆太陽還要明亮。敵人會在你們面前潰不成軍。正義的光芒將徹底摧毀他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37119 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37119, 2, 0, 'zhTW', '現在，我們向冰冠堡壘進軍！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37119 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37119, 3, 0, 'zhTW', '阿爾薩斯！我發誓會徹底消滅你和天災軍團！昔日的恩怨會在今天做個了斷！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37119 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37119, 4, 0, 'zhTW', '聖光的力量沒有止境，薩魯法爾。他的靈魂飽受壓抑，但他現在，還活著。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37119 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37119, 5, 0, 'zhTW', '聖光在上，勝利屬於我們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 0, 0, 'zhTW', '終於，開始了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 1, 0, 'zhTW', '看啊！神聖與墮落的結合，那就是影鋒，一把潛能無限的武器。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 2, 0, 'zhTW', '讓它服從你，你就能獲得無法想象的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 3, 0, 'zhTW', '如果失敗，你的靈魂就將永遠被奴役。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 4, 0, 'zhTW', '父親……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 5, 0, 'zhTW', '父親。你的聖潔……讓我，感到戰慄。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37120 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37120, 6, 0, 'zhTW', '父親……為了你，我萬死不辭。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37122 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37122, 0, 0, 'zhTW', '永遠……差那麼……一點兒……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37122 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37122, 1, 0, 'zhTW', '你們這些傻瓜永遠找不到一隻像樣的蝙蝠翅膀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37122 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37122, 2, 0, 'zhTW', '這是為了讓我得到變質的蜘蛛毒液！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37122 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37122, 3, 0, 'zhTW', '不要……讓芬克斯坦拿我……做藥……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37122 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37122, 4, 0, 'zhTW', '戰鬥難免犧牲，而我們的戰友無論生死，都會效忠銀白十字軍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37122 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37122, 5, 0, 'zhTW', '我寧願死在這裡，也不要為那個瘋子芬克斯坦收集材料。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37123 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37123, 0, 0, 'zhTW', '我已經救不活了。兄弟們，繼續戰鬥……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37123 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37123, 1, 0, 'zhTW', '什麼？這種力量是……？所有的痛苦都消失了！你……？難道我們都投入了永恆的死亡懷抱？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37123 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37123, 2, 0, 'zhTW', '一點都不疼了，是不是？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37123 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37123, 3, 0, 'zhTW', '很抱歉……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37123 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37123, 4, 0, 'zhTW', '你在與天災的戰爭中立下了大功。願聖光給你恩澤。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37124 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37124, 0, 0, 'zhTW', '請……將我火化。讓我在死後得到溫暖……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37124 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37124, 1, 0, 'zhTW', '不！不！為什麼我不能在火中死去？都燒成焦炭吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37124 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37124, 2, 0, 'zhTW', '能感到那灼熱嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37124 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37124, 3, 0, 'zhTW', '我……做了什麼？不！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37124 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37124, 4, 0, 'zhTW', '拯救這個邪惡之地非你莫屬，謝謝你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37125 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37125, 0, 0, 'zhTW', '我死的……很值得。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37125 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37125, 1, 0, 'zhTW', '巫妖王的意志不可逃避。準備好迎接一場爆炸吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37125 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37125, 2, 0, 'zhTW', '這就是你距離炸彈太近的結果！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37125 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37125, 3, 0, 'zhTW', '多麼……爆炸性的結局啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37125 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37125, 4, 0, 'zhTW', '小心前面潛伏的危險……就是死也要留個全屍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 0, 0, 'zhTW', '你也許曾和我並肩作戰，科羅克，但現在你只不過是一個叛徒。接受你的第二次死亡吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 1, 0, 'zhTW', '可憐的生物！死吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 2, 0, 'zhTW', '愚蠢的科羅克。你帶來了我的援軍。銀色勇士們，用你們的死來效忠巫妖王吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 3, 0, 'zhTW', '來吧，斬亡者。我會讓主人知道，我們誰才配得上“勇士”之名！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 4, 0, 'zhTW', '怎麼選這種低能的盟友，科羅克！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 5, 0, 'zhTW', '什麼？這就死了？這也不錯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 6, 0, 'zhTW', '也許……你是對的，科羅克。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 7, 0, 'zhTW', '%s刺穿了$n！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37126 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37126, 8, 0, 'zhTW', '%s的以太護盾已經被$n擊碎。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 0, 0, 'zhTW', '準備戰鬥，十字軍的弟兄們。維庫人會用他們的生命保護冰霜女王。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 1, 0, 'zhTW', '都給我嚴肅點！我們的勇士已經到了，我們要奮勇戰鬥，支援他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 2, 0, 'zhTW', '把他們引到這裡來。我們會支援你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 3, 0, 'zhTW', '快！推進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 4, 0, 'zhTW', '她的援兵就要到了！我們必須迅速消滅她！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 5, 0, 'zhTW', '我來擋住她。讓我的兄弟回到墳墓中去，然後幫我消滅她！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 6, 0, 'zhTW', '啊！我必須休息一下了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 7, 0, 'zhTW', '勇士們！我就要擋不住她了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37129 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37129, 8, 0, 'zhTW', '勇士們！我就要擋不住她了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37158 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37158, 0, 0, 'zhTW', '面對霜之哀傷，奎爾德拉很快復甦了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37158 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37158, 1, 0, 'zhTW', '%s準備攻擊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 0, 0, 'zhTW', '這是天災軍團的神聖土地。聖光在這裡毫無用處，聖騎士。你將孤立無援……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 1, 0, 'zhTW', '弗丁，你本應是我最強大的戰士，你的黑暗力量將清洗這個世界，開啟一個新的世代。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 2, 0, 'zhTW', '但這個榮耀不屬於你了。很快，我將有一名新的勇士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 3, 0, 'zhTW', '我為這個靈魂耗費了巨大的力量，讓他承受了無數痛苦……他抵抗了那麼長時間，但用不了多久就會屈服了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 4, 0, 'zhTW', '你們最終都要臣服於我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 20, 0, 'zhTW', '拿走它們吧，凡人，這些靈魂很快又將是我的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 21, 0, 'zhTW', '凡人，你很快也會成為劍中的囚徒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 22 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 22, 0, 'zhTW', '記住，英雄：我也曾尋找一件強大的武器……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 23 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 23, 0, 'zhTW', '我看到你也在收集著靈魂，就像我一樣。我們真的不同嗎，勇士？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 24 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 24, 0, 'zhTW', '沒錯！打造你的恐怖武器吧。它將隨著你的靈魂一同為我效命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 25 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 25, 0, 'zhTW', '帶上你的武器，勇士，它會嚐到自己主人靈魂的鮮美！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 26 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 26, 0, 'zhTW', '孩子，你想操縱靈魂嗎……你還無法理解我所掌握的力量！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 27 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 27, 0, 'zhTW', '狂妄之徒！來祭我的劍吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 28 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 28, 0, 'zhTW', '我的考驗讓你變得更強，你將更好地效忠我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 29 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 29, 0, 'zhTW', '你要知道，凡人，我並不後悔饒你一命，因為你總會給我帶來樂趣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 30 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 30, 0, 'zhTW', '你的大限將至，凡人。你將在新的艾澤拉斯永受折磨！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 31 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 31, 0, 'zhTW', '你會發現……對靈魂的渴求……是多麼的難以抗拒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 32 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 32, 0, 'zhTW', '你的武器感到了飢餓。這不算什麼。想要感受真的飢餓，真的力量嗎？繼續吧，英雄，我等著你們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 33 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 33, 0, 'zhTW', '你只能在黑暗中躊躇。那裡沒有光明，也沒有憐憫！冰冠堡壘吞噬過比你更加強大的靈魂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 34 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 34, 0, 'zhTW', '你不停跳動的心臟令我厭惡。我會讓它停止，就像我一樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37181 AND `GroupID` = 35 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37181, 35, 0, 'zhTW', '聖光會拋棄你，英雄，就像拋棄我那樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37183 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37183, 0, 0, 'zhTW', '絕不！我……絕不……服從你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37184 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37184, 0, 0, 'zhTW', '火箭揹包啟動！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37184 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37184, 1, 0, 'zhTW', '火箭揹包已關閉。移至扎福德·波姆布克斯旁邊以重新啟動。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 0, 0, 'zhTW', '庫卡隆，行動！勇士們，提高警惕。天災軍團已經……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 1, 0, 'zhTW', '我的兒子戰死在天譴之門。我來只是想帶走他的屍體。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 2, 0, 'zhTW', '我給他起名為德拉諾什，意思是“德拉諾之心”。我不會讓那些術士帶走他。我的孩子會安全地藏在加拉達爾長老那裡。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 3, 0, 'zhTW', '我在他的母親彌留時許下諾言。我會孤身穿過黑暗之門。無論我是生是死，我的兒子都不會有事，都會純淨如初……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 4, 0, 'zhTW', '今天，我兌現了諾言。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 5, 0, 'zhTW', '%s開始衝鋒！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 6, 0, 'zhTW', '躺在那裡的是我唯一的兒子。無論什麼也不能把我和他分離。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 7, 0, 'zhTW', '庫卡隆，為最後的衝鋒做好準備！勇士們，炮船將在那座堡壘的頂部著陸。我們在那裡匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 8, 0, 'zhTW', '庫卡隆，為最後的衝鋒做好準備！勇士們，炮船將在那座堡壘的頂部著陸。我們在那裡匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 9, 0, 'zhTW', '庫卡隆，為最後的衝鋒做好準備！勇士們，炮船將在那座堡壘的頂部著陸。我們在那裡匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 10, 0, 'zhTW', '我不會忘記您的……仁慈。感謝您，殿下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 11, 0, 'zhTW', '%s開始咳嗽。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 12, 0, 'zhTW', '%s對著自己兒子的屍體流下了眼淚。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 13, 0, 'zhTW', '你會在納格蘭有一個隆重的葬禮，安睡在你的母親與祖先身旁。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37187 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37187, 14, 0, 'zhTW', '年輕的英雄們……無論戰鬥多麼可怕……也不要忘記榮耀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37188 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37188, 0, 0, 'zhTW', '%s哭了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37188 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37188, 1, 0, 'zhTW', '沒什麼，陛下……我只是，為國王而自豪。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 0, 0, 'zhTW', '那我們要行動了，我們要……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 1, 0, 'zhTW', '區區一個獸人竟然膽敢與聯盟對抗？？？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 2, 0, 'zhTW', '衝鋒！！！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 3, 0, 'zhTW', '%s氣喘吁吁。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 4, 0, 'zhTW', '這就是薩魯法爾的兒子——部落在天譴之門的指揮官。真是個悲劇……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 5, 0, 'zhTW', '遠處那裡……那裡是什麼！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 6, 0, 'zhTW', '英雄們，你們必須儘快在冰冠堡壘內部奪取一個立足點。我們在城牆上匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 7, 0, 'zhTW', '士兵們，集合！看樣子部落馬上又要射擊了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 8, 0, 'zhTW', '英雄們，你們必須儘快在冰冠堡壘內部奪取一個立足點。我們在城牆上匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 9, 0, 'zhTW', '別逼我，獸人。我不能讓你過去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 10, 0, 'zhTW', '我，我不能這樣做。回到船上去，我就饒你一命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 11, 0, 'zhTW', '英雄們，你們必須儘快在冰冠堡壘內部奪取一個立足點。我們在城牆上匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37200 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37200, 12, 0, 'zhTW', '這就去，陛下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 0, 0, 'zhTW', '無論如何我們都要守住太陽之井。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 1, 0, 'zhTW', '我命令你們撤退回太陽之井，在那裡協助佈置防線。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 2, 0, 'zhTW', '我會守在這裡，儘量為你們爭取時間。記住，不要辜負我們的王子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 3, 0, 'zhTW', '能與你們攜手保衛家園和人民，是我的榮幸。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 4, 0, 'zhTW', '你……你，不是我的士兵。你願意留下來和我共同抗敵嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 5, 0, 'zhTW', '聽著，天災的渣滓們。只要我活著，你們就休想靠近太陽之井！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 6, 0, 'zhTW', '我……我沒有想過能生還。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 7, 0, 'zhTW', '為什麼會發生這種事？為什麼你會來？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 8, 0, 'zhTW', '這是奎爾德拉！你獲得了它！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37205 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37205, 9, 0, 'zhTW', '我說不清楚，但這把劍已經認定你是它的新主人。請帶上我的祝福，像我一樣去血戰天災軍團！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37217 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37217, 0, 0, 'zhTW', '%s大聲哭嚎起來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 0, 0, 'zhTW', '這種刺骨的寒冷……血液好像都要凝結了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 1, 0, 'zhTW', '看前面！那是什麼！難道是？英雄們，到我身邊來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 2, 0, 'zhTW', '霜之哀傷：正是它摧毀了我們的王國。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 3, 0, 'zhTW', '後退！如果碰到這把劍，你的靈魂就會受到永恆的創傷！我必須試著與封印在霜之哀傷中的靈魂交談。遠離我，請再後退一點。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 4, 0, 'zhTW', '烏瑟爾！親愛的烏瑟爾！我……很難過。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 5, 0, 'zhTW', '阿爾薩斯在這裡？也許我……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 6, 0, 'zhTW', '但是，烏瑟爾，哪怕有一絲見到他的可能，我……我也要去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 7, 0, 'zhTW', '告訴我，烏瑟爾，我該怎樣終結我的王子？我的……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 8, 0, 'zhTW', '你是對的，烏瑟爾。原諒我。我……我不知道自己是怎麼了。正在冰冠堡壘與天災軍團作戰的國王和騎士們很快就會得到我們的報告。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 9, 0, 'zhTW', '誰能扛起這樣的重擔？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 10, 0, 'zhTW', '也許還有希望……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37221 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37221, 11, 0, 'zhTW', '你不能拒絕我，阿爾薩斯！我必須知道……必須明白……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 0, 0, 'zhTW', '真是……不敢相信！霜之哀傷居然……無人看管，那個地精說的沒錯。來吧，英雄們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 1, 0, 'zhTW', '就是這把劍終結了我的生命……那種痛苦……揮之不去。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 2, 0, 'zhTW', '我不敢碰它。後退！後退，我要試著和這把劍交談！也許我們的救贖就在其中……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 3, 0, 'zhTW', '烏瑟爾……烏瑟爾·光明使者。怎麼……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 4, 0, 'zhTW', '巫妖王就在這裡？那今天就是我完成使命的日子！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 5, 0, 'zhTW', '一定有辦法……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 6, 0, 'zhTW', '誰能扛起這樣的重擔？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 7, 0, 'zhTW', '冰封王座……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37223 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37223, 8, 0, 'zhTW', '你別想輕易逃走，阿爾薩斯！我的仇一定要報！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 0, 0, 'zhTW', '珍娜！真的是你嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 1, 0, 'zhTW', '珍娜，你沒有時間了。巫妖王能看到劍旁的一切。他就要來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 2, 0, 'zhTW', '不，孩子。阿爾薩斯不在這裡。阿爾薩斯只是巫妖王意識中的一個存在。一個即將泯滅的存在……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 3, 0, 'zhTW', '珍娜，聽我說。你必須終結巫妖王。不要試圖說服他。他會把你們全殺掉，變成天災軍團的戰士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 4, 0, 'zhTW', '振作起來，女孩。你必須在巫妖王和耐奧祖融合的地方－－冰封王座，將他終結。這是唯一的辦法。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 5, 0, 'zhTW', '還有…還有一些事情你需要知道。天災軍團絕不能失去控制。即使你戰勝了這個巫妖王，也要有別人來取代他。沒有巫妖王的控制，天災軍團就會橫掃整個世界，摧毀一切生靈。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 6, 0, 'zhTW', '要有個崇高的靈魂作出犧牲……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 7, 0, 'zhTW', '我不知道，珍娜。我懷疑正是阿爾薩斯殘留在巫妖王體內的一縷靈魂阻止了天災軍團徹底毀滅艾澤拉斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 8, 0, 'zhTW', '不，珍娜！啊……他……他來了。你……你必須……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 9, 0, 'zhTW', '小心，女孩。我聽說這把被詛咒的劍救過我們。注意周圍，看看霜之哀傷都創造了些什麼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 10 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 10, 0, 'zhTW', '你沒有時間了。巫妖王能看到劍旁的一切。他就要來了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 11 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 11, 0, 'zhTW', '在這裡，你無法擊敗巫妖王。這種企圖是愚蠢的。他會打倒那些跟隨你的人，把他們變成強大的天災戰士。只有你除外，希爾瓦娜斯……他對你的“饋贈”要比上次更恐怖。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 12 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 12, 0, 'zhTW', '也許吧，但要記住：一定要有一位巫妖王。即使你終結了阿爾薩斯，也要有另一個人來取代他。沒有了巫妖王的控制，天災軍團就會像蝗災一樣橫掃世界，所到之處，寸草不生。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 13, 0, 'zhTW', '我不知道，女妖之王。我懷疑正是阿爾薩斯殘留在巫妖王體內的一縷靈魂阻止了天災軍團徹底毀滅艾澤拉斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 14, 0, 'zhTW', '唉，擊敗巫妖王的唯一方法就是在他的誕生地摧毀他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 15, 0, 'zhTW', '啊……他……他來了。你……你必須……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 16 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 16, 0, 'zhTW', '住手！你快把那劍放下！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 17 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 17, 0, 'zhTW', '你知道你在幹什麼嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 18 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 18, 0, 'zhTW', '你用上古之神的血，薩隆邪鐵重鑄了這把劍。巫妖王的力量會召喚它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 19 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 19, 0, 'zhTW', '只要你留在這裡，奎爾德拉就會汲取這裡的邪能。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 20 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 20, 0, 'zhTW', '只有一個辦法能淨化它。趕快到太陽之井去，將劍沉入井水之中。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37225 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37225, 21, 0, 'zhTW', '我抵抗不了霜之哀傷的召喚……巫妖王來了……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37226 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37226, 0, 0, 'zhTW', '閉嘴，聖騎士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37226 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37226, 1, 0, 'zhTW', '你真的想和死人交談？我會滿足你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37226 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37226, 2, 0, 'zhTW', '法瑞克，瑪維恩，殺掉他們，送到我的大殿來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37230 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37230, 0, 0, 'zhTW', '一聲尖叫直入雲霄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37230 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37230, 1, 0, 'zhTW', '一條護塔冰龍落在了奧格瑞姆之錘前。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37230 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37230, 2, 0, 'zhTW', '一條護塔冰龍落在了破天號前。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37491 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37491, 1, 0, 'zhTW', '你們這些傻瓜永遠找不到一隻像樣的蝙蝠翅膀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37491 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37491, 2, 0, 'zhTW', '這是為了讓我得到變質的蜘蛛毒液！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37491 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37491, 3, 0, 'zhTW', '不要……讓芬克斯坦拿我……做藥……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37493 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37493, 1, 0, 'zhTW', '什麼？這種力量是……？所有的痛苦都消失了！你……？難道我們都投入了永恆的死亡懷抱？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37493 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37493, 2, 0, 'zhTW', '一點都不疼了，是不是？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37493 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37493, 3, 0, 'zhTW', '很抱歉……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37494 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37494, 1, 0, 'zhTW', '不！不！為什麼我不能在火中死去？都燒成焦炭吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37494 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37494, 2, 0, 'zhTW', '能感到那灼熱嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37494 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37494, 3, 0, 'zhTW', '我……做了什麼？不！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37495 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37495, 1, 0, 'zhTW', '巫妖王的意志不可逃避。準備好迎接一場爆炸吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37495 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37495, 2, 0, 'zhTW', '這就是你距離炸彈太近的結果！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37495 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37495, 3, 0, 'zhTW', '多麼……爆炸性的結局啊！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37503 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37503, 0, 0, 'zhTW', '絕不能讓他們靠近冰霜女王。快，阻止他們！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37542 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37542, 0, 0, 'zhTW', '你會同你的家園和城池一樣遭受滅頂之災。我的主人會在這裡大獲全勝，你的名字將被人們遺忘。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37542 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37542, 1, 0, 'zhTW', '前進！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37542 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37542, 2, 0, 'zhTW', '食屍鬼們，殺掉這個可憐的高等精靈！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37542 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37542, 3, 0, 'zhTW', '你們都會被天災軍團的力量擊垮。地穴劫掠者，進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37542 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37542, 4, 0, 'zhTW', '我要親手殺了你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 0, 0, 'zhTW', '他……太強大了。英雄們，快，快過來！我們必須馬上離開！你們先走。我會盡全力擋住他。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 1, 0, 'zhTW', '沒有牆壁能阻擋女妖之王。擋住那些亡靈，英雄們。我會粉碎這道屏障！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 2, 0, 'zhTW', '又是一道！堅持住，勇士們。我會粉碎這面冰牆。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 3, 0, 'zhTW', '我厭倦了你的把戲，阿爾薩斯！你的冰牆阻擋不了我！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 4, 0, 'zhTW', '你們這些惡魔攔不住我們！擋住那些亡靈，我在努力摧毀冰牆！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 5, 0, 'zhTW', '前面有個出口，趕快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 6, 0, 'zhTW', '我們就要到了……不要放棄！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 7, 0, 'zhTW', '天殺的死路！看來真的無路可走了。準備戰鬥，英雄們，讓我們放手一搏！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37554 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37554, 8, 0, 'zhTW', '我們暫時……安全了。他的力量已經十倍於往昔。只有一支大軍才能戰勝巫妖王。單憑部落的力量毫無勝算。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37580 AND `GroupID` = 62 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37580, 62, 0, 'zhTW', '今天我們不僅見證了你們的勇猛，還見證了聯盟和部落拋開仇怨，精誠團結的力量。有了這種力量，即使是巫妖王也會敗倒在你們腳下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37580 AND `GroupID` = 68 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37580, 68, 0, 'zhTW', '勇士們，你們救了我們，還我們自由……這種大恩大德我們無以為報。但我發誓，從今往後所有人都會知道你們的事蹟，知道你們如何在這座黑暗的城堡中劈開一條光明之路。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37580 AND `GroupID` = 69 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37580, 69, 0, 'zhTW', '英雄們！我們就算拼了性命，也會擋住那些亡靈。去消滅天災領主吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37581 AND `GroupID` = 51 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37581, 51, 0, 'zhTW', '英雄們！我們就算拼了性命，也會擋住那些亡靈。去消滅天災領主吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37581 AND `GroupID` = 61 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37581, 61, 0, 'zhTW', '勇士們，你們救了我們，還我們自由……這種大恩大德我們無以為報。但我發誓，從今往後所有人都會知道你們的事蹟，知道你們如何在這座黑暗的城堡中劈開一條光明之路。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37581 AND `GroupID` = 62 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37581, 62, 0, 'zhTW', '今天我們不僅見證了你們的勇猛，還見證了聯盟和部落拋開仇怨，精誠團結的力量。有了這種力量，即使是巫妖王也會敗倒在你們腳下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37591 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37591, 21, 0, 'zhTW', '熔爐之主已經死了！抽刀亮劍，我們要幹掉天災領主。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37592 AND `GroupID` = 21 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37592, 21, 0, 'zhTW', '今天我們不僅見證了你們的勇猛，還見證了聯盟和部落拋開仇怨，精誠團結的力量。有了這種力量，即使是巫妖王也會敗倒在你們腳下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37596 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37596, 0, 0, 'zhTW', '銀白十字軍和黯刃騎士團已經攻入冰冠城堡大門，正準備向天災軍團發動總攻。我們的任務雖小，但同樣重要。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37596 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37596, 1, 0, 'zhTW', '當巫妖王的注意力被吸引到前門的時候，我們就從側翼潛入，尋找能幫助我們的重要情報，徹底除掉巫妖王。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37596 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37596, 2, 0, 'zhTW', '我們的偵察兵說巫妖王在冰封王座外有個私人密室，深藏在被稱作映像大廳的地方。那就是我們的目標，勇士們。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37596 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37596, 3, 0, 'zhTW', '我們會一路殺進這個被詛咒的地方，找到進入映像大廳的入口。那裡一定隱藏著某些極具價值的情報。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37596 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37596, 4, 0, 'zhTW', '你的首個任務是摧毀靈魂引擎中的死亡機器，為我們的士兵殺出一條路來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37596 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37596, 5, 0, 'zhTW', '黑暗女王正在看著你，加緊行動！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 0, 0, 'zhTW', '感謝聖光，你安然無恙！為了消滅巫妖王和天災軍團，我們還有很多事要做。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 1, 0, 'zhTW', '銀白十字軍和黯刃騎士團的盟軍已經打破冰冠堡壘的大門，他們正努力在城堡中安置一個前哨站。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 2, 0, 'zhTW', '我們在這些廳堂中的發現將決定他們的成敗。雖然任務危險重重，但我們必須堅持！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 3, 0, 'zhTW', '當巫妖王的注意力被吸引到前門的時候，我們就從側翼潛入，尋找有用的重要情報，從而一勞永逸地剷除天災軍團。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 4, 0, 'zhTW', '瓦里安國王的軍情七處得到情報，巫妖王的私人密室就深藏在一個被稱作映像大廳的地方。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 5, 0, 'zhTW', '我們要想辦法殺出一條通往映像大廳的血路。我感到那裡潛藏著強大的魔法。那將是摧毀天災軍團的關鍵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 6, 0, 'zhTW', '你的首個任務是摧毀靈魂引擎中的死亡機器，為我們的士兵殺出一條路來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37597 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37597, 7, 0, 'zhTW', '趕快，勇士們！我會讓部隊緊跟在你們身後。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37763 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37763, 0, 0, 'zhTW', '洛瑟瑪，看那。的確是奎爾德拉。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37763 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37763, 1, 0, 'zhTW', '攝政者說的對，$n。薩洛瑞安的犧牲無法阻止太陽之井的覆滅。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37763 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37763, 2, 0, 'zhTW', '當你找到那把劍時，那把劍已經是殘破不堪、無人問津了，更像是被凱爾薩斯出賣了的銀月城。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37763 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37763, 3, 0, 'zhTW', '讓奎爾德拉成為我們永不言棄的標誌，面對敵人我們將不再心存恐懼。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37763 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37763, 4, 0, 'zhTW', '拿回那把劍，$n，帶著它穿過傳送門前往達拉然。大法師艾薩斯·奪日者正等待著為你喝彩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37763 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37763, 5, 0, 'zhTW', '拿回那把劍，$n，帶著它穿過傳送門前往達拉然。溫蕾薩·風行者正等待著為你喝彩。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37764 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37764, 0, 0, 'zhTW', '我們會搞清楚的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37764 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37764, 1, 0, 'zhTW', '這的確是奎爾德拉。傳說中薩洛瑞安·尋晨者的寶劍又回到我們的手裡了，我從沒想過我會活著見到這一天。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37764 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37764, 2, 0, 'zhTW', '你是辛多雷的英雄，你鼓舞著我們，$n，在面對悲劇和背叛時一種堅韌的象徵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37765 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37765, 0, 0, 'zhTW', '不僅辛多雷的人十分看重奎爾德拉。它在銀月城所有孩子們的心中都佔據著一定的位置。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37765 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37765, 1, 0, 'zhTW', '出於某種原因，這把劍重新回到了我們手裡，我的主人。現在，是緊隨奎爾德拉持有者重整旗鼓的時候了，為銀月城和太陽之井的毀滅報仇。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37781 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37781, 0, 0, 'zhTW', '那真的會是奎爾德拉嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37813 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37813, 0, 0, 'zhTW', '你每消滅一名部落士兵，或是殺死一隻聯盟狗。巫妖王的軍力就會增長一分。瓦格里正在把你們的陣亡者變為天災戰士。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37813 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37813, 1, 0, 'zhTW', '你們就要大禍臨頭了。來吧，嚐嚐巫妖王賜予我的力量吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37813 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37813, 2, 0, 'zhTW', '矮人……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37813 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37813, 3, 0, 'zhTW', '%s禁錮了穆拉丁和他的士兵');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37813 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
