INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37976, 0, 1, 'zhTW', '別害怕，主人。看我怎麼將敵人撕個粉碎！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37976 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37976, 1, 0, 'zhTW', '主人……我……失敗了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 37976 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (37976, 2, 0, 'zhTW', '結束了，主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38004 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38004, 0, 0, 'zhTW', '愚蠢的凡人。你以為能輕易打敗我們？薩萊因是巫妖王永生的戰士！現在他們將合力撕碎你！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38004 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38004, 1, 0, 'zhTW', '站起來，兄弟們，消滅這些敵人！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38017 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38017, 0, 0, 'zhTW', '你確定你應該幫助那些凡人取得那把劍嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38017 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38017, 1, 0, 'zhTW', '這些武器，克拉蘇斯…它們製造於很久以前，那時候的一切…都不同。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38017 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38017, 2, 0, 'zhTW', '我們的敵人曾利用我們最強大的武器來對抗我們。是什麼讓你覺得這些古劍會有所不同？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38017 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38017, 3, 0, 'zhTW', '遵從您的意願，我的女王。我不會阻攔他們，但我會對他們緊密監視。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38056 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38056, 0, 0, 'zhTW', '我的主人和女王，請允許我向您們介紹$n，奎爾德拉的持有者。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 0, 0, 'zhTW', '男人，女人，還有孩子……沒人能逃過主人的怒火。你的死早已註定。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 1, 0, 'zhTW', '無能的傢伙！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 1, 1, 'zhTW', '斯坦索姆的小孩子都要比你們勇猛！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 2, 0, 'zhTW', '瑪維恩，幹掉他們……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 3, 0, 'zhTW', '絕望……如此甘甜……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 4, 0, 'zhTW', '恐懼……如此美好……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 5, 0, 'zhTW', '遵命，我的主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38112 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38112, 6, 0, 'zhTW', '洛丹倫的戰士們，服從主人的召喚！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 0, 0, 'zhTW', '你們只會尋得死亡！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 1, 0, 'zhTW', '我看到的是同樣的眼神。泰瑞納斯怎麼也想不到。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 1 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 1, 1, 'zhTW', '痛苦的窒息吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 2, 0, 'zhTW', '對，去吧……迎接你的命運吧……痛苦、冰冷的擁抱正等著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 3, 0, 'zhTW', '你的軀殼將在你的眼前朽化！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 4, 0, 'zhTW', '灰飛煙滅吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 5, 0, 'zhTW', '如您所願，我的主人。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 6, 0, 'zhTW', '靈魂們出現並圍在祭壇四周！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38113 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38113, 7, 0, 'zhTW', '主人審視他的王國，找到了它的……不足。他的決斷迅速而無情：生靈俱滅！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38153 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38153, 0, 0, 'zhTW', '入侵者闖入了內室。加緊毀掉那條綠龍！留下龍筋龍骨用來複生！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38160 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38160, 0, 0, 'zhTW', '幹得漂亮，勇士們！我們將在這些房間裡建立營地。我的人很快就能讓這架天災傳送器恢復工作。準備好就站進去。我和新的任務會在目的地等著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38161 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38161, 0, 0, 'zhTW', '幹得漂亮，勇士們！我們將在這些房間裡建立營地。我的人很快就能讓這架天災傳送器恢復工作。準備好就站進去。我和新的任務會在目的地等著你。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38172 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38172, 0, 0, 'zhTW', '死後仍為主人效命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38172 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38172, 0, 1, 'zhTW', '我們的靈魂將永無寧日。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38172 AND `GroupID` = 0 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38172, 0, 2, 'zhTW', '我們永遠無法擺脫折磨。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38172 AND `GroupID` = 0 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38172, 0, 3, 'zhTW', '這只不過是暫時的休息…。');
