DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38188 AND `GroupID` = 63 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38188, 63, 0, 'zhTW', '英雄們，到我這來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38188 AND `GroupID` = 65 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38188, 65, 0, 'zhTW', '冰霜女王完了。我們……我們必須繼續前進——目標就在眼前。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38188 AND `GroupID` = 66 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38188, 66, 0, 'zhTW', '我……我救不了他們……該死，阿爾薩斯！你這惡魔！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38189 AND `GroupID` = 64 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38189, 64, 0, 'zhTW', '躲到我後面來！快！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38189 AND `GroupID` = 67 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38189, 67, 0, 'zhTW', '我以為他永遠都閉不上嘴。但辛達苟薩讓這個呱噪的傢伙安靜下來了。勇士們，向映像大廳前進！我能感覺到……目標已近。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38294 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38294, 0, 0, 'zhTW', '卡魯耶克釣魚大賽將於5分鐘後開始！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38294 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38294, 1, 0, 'zhTW', '卡魯耶克釣魚大賽開始！如果你是第一個釣到黑鰭鯊並帶到達拉然給我的人，會成為第一名！黑鰭鯊可以在你捕捉小型亞口魚的地方釣到。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38294 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38294, 2, 0, 'zhTW', '$N獲得了卡魯耶克釣魚大賽的勝利！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38294 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38294, 3, 0, 'zhTW', '卡魯耶克釣魚大賽結束！如果你釣到了黑鰭鯊，請在規定時間內帶給我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38334 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38334, 0, 0, 'zhTW', '你在盯著看什麼？沒見過天才嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38334 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38334, 1, 0, 'zhTW', '這會讓你明白別管閒事的道理！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38335 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38335, 0, 0, 'zhTW', '沒錯，我會把那些“煙火”列一張表出來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38335 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38335, 1, 0, 'zhTW', '從南海回來後那些東西就能賣大價錢了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38335 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38335, 2, 0, 'zhTW', '你…別以為我看不到你。離我遠點！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38336 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38336, 0, 0, 'zhTW', '夥計，感謝你提供這麼棒的理髮、修面服務。');
