INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38336, 2, 0, 'zhTW', '我又想了想，整個袋子都拿走吧。我必須，嗯，走了。');
