DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38337 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38337, 0, 0, 'zhTW', '你在盯著看什麼？沒見過天才嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38337 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38337, 1, 0, 'zhTW', '這會讓你明白別管閒事的道理！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38338 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38338, 0, 0, 'zhTW', '沒錯，我會把那些“煙火”列一張表出來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38338 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38338, 1, 0, 'zhTW', '從南海回來後那些東西就能賣大價錢了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38338 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38338, 2, 0, 'zhTW', '你…別以為我看不到你。離我遠點！');
