DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38472 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38472, 0, 0, 'zhTW', '死吧，入侵者！沒人能干預教派的計劃！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38472 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38472, 1, 0, 'zhTW', '我…我在哪…？這真是場可怕的惡夢…不過沒時間細想了，還有很多事情在等著我彙報！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38485 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
