DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38490 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38490, 0, 0, 'zhTW', '$n感染了死亡疫病！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38494 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38494, 0, 0, 'zhTW', '$n感染了死亡疫病！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38579 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38579, 0, 0, 'zhTW', '終於自由了！結束了，我的兒子。清算的時候到了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38579 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38579, 1, 0, 'zhTW', '聖光的勇士們！集結起來！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38606 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38606, 0, 0, 'zhTW', '這是什麼？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38606 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38606, 1, 0, 'zhTW', '這……他還留著？一直以來，他還帶著它？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38606 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38606, 2, 0, 'zhTW', '我知道！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38606 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38606, 3, 0, 'zhTW', '我還能感覺到他！飽受摧殘……苦苦掙扎……啊，阿爾薩斯！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38606 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38606, 4, 0, 'zhTW', '也許……也許有一天，他會想起真正的自己。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38606 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38606, 5, 0, 'zhTW', '聖光啊，願他擺脫那把魔劍的寒冷束縛，魂歸故里。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 0, 0, 'zhTW', '哦，夥計……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 1, 0, 'zhTW', '我忘不了在洛丹倫的那些日子……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 2, 0, 'zhTW', '……用這把鈍劍訓練你的劍術……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 3, 0, 'zhTW', '……讓你成才，期待著你去完成偉大的使命。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 4, 0, 'zhTW', '呵呵……那些功夫沒有白費，不是嗎，夥計？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 5, 0, 'zhTW', '如果那天我能阻止你，也許一切都會不一樣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 6, 0, 'zhTW', '要是我從沒發現過那把被詛咒的劍……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 7, 0, 'zhTW', '再見了，阿爾薩斯……好兄弟。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 13 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 13, 0, 'zhTW', '弗丁領主，這是真的？如果伯瓦爾還活著，也許聯盟和部落之間還有和平的希望。我們必須衝到堡壘頂層，救出聖騎士！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 14 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 14, 0, 'zhTW', '讓破天號做好空襲城堡的準備！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38607 AND `GroupID` = 15 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38607, 15, 0, 'zhTW', '英雄們，你們必須儘快在冰冠堡壘內部奪取一個立足點。我們在城牆上匯合！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 0, 0, 'zhTW', '阿爾薩斯……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 1, 0, 'zhTW', '艾澤拉斯的英雄們，你們對我的恩澤遠超想象。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 2, 0, 'zhTW', '長久以來，我苦苦地想要寬恕王子的滔天罪行。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 3, 0, 'zhTW', '焦慮和痛苦撕扯著我的靈魂，邪惡的念頭……讓我遠離聖光。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 4, 0, 'zhTW', '我清晰地記得他眼中的光芒，那光芒帶著榮耀，帶著擊敗聖光之敵的熱切……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 5, 0, 'zhTW', '帶著寧死也要保護人民的決心……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 6, 0, 'zhTW', '這就是阿爾薩斯，我要永記於心的阿爾薩斯。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 7, 0, 'zhTW', '朋友，你們的恩情沒齒難忘。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38608 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38608, 8, 0, 'zhTW', '謝謝。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 0, 0, 'zhTW', '一切都結束了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 1, 0, 'zhTW', '我不敢相信這是真的——因為巫妖王已經愚弄我太多太多次了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 2, 0, 'zhTW', '他對我們犯下累累罪行，現在他終於付出了代價。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 3, 0, 'zhTW', '願艾澤拉斯不要忘記那曾因軟弱和傲慢所付出的沉重代價。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 4, 0, 'zhTW', '但現在呢，英雄？那些擺脫了他的束縛，卻無法擺脫凡塵俗世的人呢？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 5, 0, 'zhTW', '退下。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38609 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38609, 6, 0, 'zhTW', '我的思緒很亂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 0, 0, 'zhTW', '達里安，我的孩子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 1, 0, 'zhTW', '終於，我能夠重新見到你了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 2, 0, 'zhTW', '巫妖王一直在折磨我，達里安。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 3, 0, 'zhTW', '無休無止，他想要擊潰我的意志，讓我屈服，成為劍中的冤魂……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 4, 0, 'zhTW', '最後，戰爭讓他無暇分身，他才放棄了我。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 5, 0, 'zhTW', '有個回憶，是我的力量，達里安……是讓我不被奴役的力量……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38610 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38610, 6, 0, 'zhTW', '那就是你的犧牲，我的兒子，再度拯救我於萬劫不復。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38995 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38995, 0, 0, 'zhTW', '我們會讓你死個痛快，阿爾薩斯。對於犯下累累罪行的你，這是最大的仁慈了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38995 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38995, 1, 0, 'zhTW', '好吧，勇士們，進攻！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38995 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38995, 2, 0, 'zhTW', '無上的聖光啊！請祝福我！賜予我力量……幫助我衝破這些枷鎖！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 38995 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (38995, 3, 0, 'zhTW', '結束了，阿爾薩斯！你殘害生靈的日子今天結束了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 39217 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (39217, 0, 0, 'zhTW', '你是來審判阿爾薩斯的嗎？想要看到巫妖王的滅亡？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 39217 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (39217, 1, 0, 'zhTW', '首先，你需要擺脫霜之哀傷的控制，否則就會像我一樣，永世成為這把邪劍的囚徒。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 39368 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (39368, 0, 0, 'zhTW', '好啊，你真有讓機器起死回生的能力。讓我們開始工作吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 39368 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (39368, 1, 0, 'zhTW', '我要讓你們知道該如何成為一名真正的士兵！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 39368 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
