DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40264 AND `GroupID` = 1 AND `ID` = 2 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40264, 1, 2, 'zhTW', '準備同沃金並肩作戰！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40264 AND `GroupID` = 1 AND `ID` = 3 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40264, 1, 3, 'zhTW', '新巨魔報道！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40264 AND `GroupID` = 1 AND `ID` = 4 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40264, 1, 4, 'zhTW', '訓練什麼時候開始？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40301 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40301, 0, 0, 'zhTW', '猛虎女王出現了！在戰鬥中證明你自己吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40329 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40329, 0, 0, 'zhTW', '暫時夠了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40329 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40329, 1, 0, 'zhTW', '不要這麼驚訝。你的薩滿朋友有著明察秋毫的眼睛，或者說有著明察秋毫的青蛙。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40329 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40329, 2, 0, 'zhTW', '我們德魯伊一直潛伏在這裡，等待著，看沃金是不是會回來。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40329 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40329, 3, 0, 'zhTW', '看樣子，暗矛部族正在返回這些島嶼。也許我們現身的時候到了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40329 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40329, 4, 0, 'zhTW', '回到沃金那裡去，告訴他：岑塔布拉已經做好了和他並肩作戰的準備。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 0, 0, 'zhTW', '暗矛的成員們，我們要向先祖之靈尋求答案！鼓手，立刻就位！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 1, 0, 'zhTW', '偉大的英靈啊，我們聚集於此，尋求您的指引。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 2, 0, 'zhTW', '我們的領袖，森金之子沃金向全體暗矛部族的成員發起了號召：奪回回音群島。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 3, 0, 'zhTW', '偉大的英靈啊！我向您獻出自己的身軀。請透過我說話吧！現在是不是強大的沃金開始行動的時刻？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 4, 0, 'zhTW', '巫醫，祖先聽到你的話了！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 5, 0, 'zhTW', '你們的計劃讓我們喜悅，暗矛部族，森金之子的道路是正確的。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 6, 0, 'zhTW', '你們的任務相當艱鉅，但你們將得到我們的祝福。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 7, 0, 'zhTW', '你們離開回音群島，放棄了家園和祖先的光榮。祖先不喜歡你們如此冷漠沉寂。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 8, 0, 'zhTW', '如果你們想要擊敗扎拉贊恩，你們就必須向亡魂的守護者邦桑迪贖罪。把這件事告訴森金之子。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40352 AND `GroupID` = 9 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40352, 9, 0, 'zhTW', '先祖之靈祝福了我們！回音群島將再次成為我們的家園！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40391 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40391, 0, 0, 'zhTW', '謝謝你，哨兵。你還要繼續巡邏的工作。不過現在你應該去休息一下。解散。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40416 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40416, 0, 0, 'zhTW', '他有一支規模很大的軍隊，而且他正在策劃著一個陰謀。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40416 AND `GroupID` = 0 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40416, 0, 1, 'zhTW', '扎拉贊恩讓他的大多數巨魔妖術師藏在那座大島上的樹屋裡面。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40423 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40423, 0, 0, 'zhTW', '%s用一聲戰吼鼓舞起了其他戰士計程車氣。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 0, 0, 'zhTW', '謝謝你的幫助！我已經瀕臨崩潰了……這裡發生了可怕的事情。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 1, 0, 'zhTW', '我們相信聖殿是堅不可摧的，但我們沒想到會遭受這樣的攻擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 2, 0, 'zhTW', '黑龍人憑空出現，在我們反應過來之前就發動了攻擊。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 3, 0, 'zhTW', '我們全面潰敗。同胞們一個個死去。只有我撤退到這裡，並封住了入口。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 4, 0, 'zhTW', '他們冷酷無情地屠殺我們，但他們真正的目標似乎是聖殿裡的那些卵。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 5 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 5, 0, 'zhTW', '指揮他們的是一個名叫薩瑞瑟裡安的殘忍傢伙。但我擔心他背後還有更強大的力量。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 6 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 6, 0, 'zhTW', '剛受到攻擊時，我看見了他們真正的首領，一頭恐怖的暮光巨龍。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 7 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 7, 0, 'zhTW', '我還不知道他們的全盤計劃，但我知道，英雄們，絕不能讓他們得逞！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40429 AND `GroupID` = 8 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40429, 8, 0, 'zhTW', '救命！我被困在這棵樹裡了！我需要幫助！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40703 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40703, 0, 0, 'zhTW', '我們來玩吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40703 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40703, 1, 0, 'zhTW', '我太累了……我要休息一會……');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40703 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40703, 2, 0, 'zhTW', '好像不能這樣用力折它。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40703 AND `GroupID` = 2 AND `ID` = 1 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40703, 2, 1, 'zhTW', '我……好像把它弄壞了。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 40703 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (40703, 3, 0, 'zhTW', '新玩具？給我的嗎？');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 61021 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (61021, 0, 0, 'zhTW', '我們到這裡來是為了消滅你，迷失的兄弟。按照傳統，我們會在消滅你之前給你個懺悔的機會。按照納魯的律法，我們給你這個機會。');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 61021 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (61021, 1, 0, 'zhTW', '我們也許勢單力薄，索克雷薩，但是我們有著強大的信念。有些東西你是永遠都不會懂的。現在機會已經給過你了，準備迎接你的末日吧！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 61021 AND `GroupID` = 2 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (61021, 2, 0, 'zhTW', '怎麼……你怎麼能？！');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 61021 AND `GroupID` = 3 AND `ID` = 0 AND `Locale` = 'zhTW';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (61021, 3, 0, 'zhTW', '索克雷薩矇蔽了你的心靈，凱蘭恩！這些話不是你的本意！我還記得你孩提時我訓練你的情景。你的意志向來那麼堅強！');
